typedef struct {
    int id;
    time_t timestamp;
    char source_ip[INET6_ADDRSTRLEN];
    char destination_ip[INET6_ADDRSTRLEN];
    size_t payload_size;
} PacketMetadata;

struct packet_array {
    PacketMetadata* data;
    size_t capacity;
    size_t size;
};

void packet_array_init(struct packet_array* array, size_t initial_capacity) {
    array->data = malloc(initial_capacity * sizeof(PacketMetadata));
    array->capacity = initial_capacity;
    array->size = 0;
}

void packet_array_resize(struct packet_array* array, size_t new_capacity) {
    PacketMetadata* temp = malloc(new_capacity * sizeof(PacketMetadata));
    memcpy(temp, array->data, array->size * sizeof(PacketMetadata));

    free(array->data);
    array->data = temp;
    array->capacity = new_capacity;
}

size_t packet_array_find_by_ip(const struct packet_array* array, const char* ip) {
    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->data[i].source_ip, ip) == 0 || strcmp(array->data[i].destination_ip, ip) == 0) {
            return i;
        }
    }
    return SIZE_MAX;
}

void packet_array_add(struct packet_array* array, const PacketMetadata* metadata) {
    if (array->size == array->capacity) {
        packet_array_resize(array, array->capacity * 2);
    }

    array->data[array->size] = *metadata;
    ++array->size;
}

void packet_array_update(struct packet_array* array, size_t index, const PacketMetadata* metadata) {
    if (index >= array->size) {
        fprintf(stderr, "Invalid index provided.\n");
        return;
    }

    memcpy(&array->data[index], metadata, sizeof(PacketMetadata));
}
