typedef struct {
    int value;
    int *key;
} Record;

size_t const KEY_ARRAY_SIZE = 10000;
size_t const RECORDS_PER_KEY = 100;
size_t const OFFSET_ARRAY_SIZE = KEY_ARRAY_SIZE * RECORDS_PER_KEY;

int keys[KEY_ARRAY_SIZE]; // unique identifiers for records
long offsets[OFFSET_ARRAY_SIZE]; // memory offsets for record structures
Record *records;

void init() {
    srand(time(NULL));

    // Allocate and initialize key array
    keys = (int *) calloc(KEY_ARRAY_SIZE, sizeof(int));

    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate and initialize offset array
    offsets = (long *) calloc(OFFSET_ARRAY_SIZE, sizeof(long));

    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        free(keys);
        exit(EXIT_FAILURE);
    }

    // Allocate and initialize records array
    size_t totalSize = sizeof(Record) * (KEY_ARRAY_SIZE * RECORDS_PER_KEY);
    records = (Record *) calloc(1, totalSize);

    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        free(keys);
        free(offsets);
        exit(EXIT_FAILURE);
    }

    // Initialize record pointers in offset array
    long currentOffset = 0;
    for (size_t i = 0; i < KEY_ARRAY_SIZE; ++i) {
        keys[i] = i;
        offsets[i * RECORDS_PER_KEY + 0] = currentOffset;
        for (size_t j = 1; j < RECORDS_PER_KEY; ++j) {
            offsets[i * RECORDS_PER_KEY + j] = currentOffset + sizeof(Record);
            currentOffset += sizeof(Record);
        }
    }
}

void populateRecords() {
    for (size_t i = 0; i < KEY_ARRAY_SIZE * RECORDS_PER_KEY; ++i) {
        records[i].value = rand() % 100 + 1;
