struct Event {
    char* line;
    // Other event fields here
};

struct Metric {
    char key[256];
    long long value;
};

void parseEvent(struct Event*, struct Metric*, const char* filter);
void aggregateMetrics(struct Metric*, const char* aggRules, FILE* outFile);

int main(int argc, char** argv) {
    if (argc != 5) {
        printf("Usage: %s <input_log> <output_summary> <filter> <aggregation_rules>\n", argv[0]);
        return 1;
    }

    FILE* inFile = fopen(argv[1], "r");
    if (!inFile) {
        perror("Error opening input file");
        return 2;
    }

    FILE* outFile = fopen(argv[2], "w");
    if (!outFile) {
        perror("Error opening output file");
        fclose(inFile);
        return 3;
    }

    long long numEvents = 0;
    struct Event* events = NULL;

    char line[4096];
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, inFile)) != -1) {
        // Allocate memory for the new event and copy the line into it.
        struct Event* newEvent = malloc(sizeof(struct Event));
        if (!newEvent) {
            perror("Error allocating memory");
            fclose(inFile);
            fclose(outFile);
            return 4;
        }
        newEvent->line = strdup(line);
        events = realloc(events, ++numEvents * sizeof(struct Event));
        if (!events) {
            perror("Error allocating memory");
            free(newEvent->line);
            free(newEvent);
            fclose(inFile);
            fclose(outFile);
            return 4;
        }
        events[numEvents - 1] = newEvent;
    }
    fclose(inFile);

    struct Metric* metrics = calloc(256, sizeof(struct Metric));
    if (!metrics) {
        perror("Error allocating memory");
        free_events(events, numEvents);
        fclose(outFile);
        return 4;
    }

    for (size_t i = 0; i < numEvents; ++i) {
        parseEvent(&events[i], metrics, argv[3]);
    }
    aggregateMetrics(metrics, argv[4], outFile);

    free_events(events, numEvents);
    free(metrics);
    fclose(outFile);

    return 0;
}
```

