int dns_resolve(const char *hostname, ip_address *ip, pthread_mutex_t *mutex) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only for this example
    hints.ai_socktype = SOCK_STREAM;

    status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        perror("getaddrinfo");
        return -1;
    }

    // Filter out the IP addresses that are in restricted ranges or domains.
    for (struct addrinfo *ptr = res; ptr != NULL; ptr = ptr->ai_next) {
        u_char ip[16];
        memset(ip, 0, sizeof(ip));
        memcpy(ip, ((struct sockaddr_in *)ptr->ai_addr)->sin_addr.s_addr, sizeof(u_long));

        if (is_ip_in_range(ip) || is_domain_restricted(hostname)) {
            continue;
        }

        pthread_mutex_lock(mutex);
        memcpy((*ip).ip, ip, sizeof(ip));
        (*ip).ip_size = sizeof(u_char) * 4; // IPv4 size is 4 bytes per octet
        pthread_mutex_unlock(mutex);

        freeaddrinfo(res);
        return 0;
    }

    freeaddrinfo(res);

    if (time(NULL) - start_time > TIMEOUT_MS) {
        perror("DNS timeout");
