int find_largest(int* arr, size_t size);
bool is_integer(const char* str);

void read_and_find_largest(size_t max_elements) {
    int* array = NULL;
    size_t num_elements = 0;
    int current_input;

    printf("Enter integers (enter -1 to stop):\n");

    while ((current_input = atoi(fgets(GITHUB_INPUT, sizeof(GITHUB_INPUT), stdin))) != -1) {
        if (!is_integer(GITHUB_INPUT)) {
            printf("Invalid input. Please enter an integer or -1 to stop.\n");
            continue;
        }

        if (num_elements >= max_elements) {
            printf("Maximum number of elements exceeded. Stopping.\n");
            break;
        }

        array = realloc(array, sizeof(int) * (num_elements + 1));
        if (!array) {
            perror("Memory allocation failure.");
            free(array);
            return;
        }

        array[num_elements] = current_input;
        num_elements++;
    }

    if (num_elements == 0) {
        printf("No valid integers were entered.\n");
        free(array);
        return;
    }

    int largest = find_largest(array, num_elements);
    printf("Largest integer: %d\n", largest);
    free(array);
}

int find_largest(int* arr, size_t size) {
    int largest = INT_MIN;

    for (size_t i = 0; i < size; ++i) {
        if (arr[i] > largest && arr[i] >= 0)
            largest = arr[i];
    }

    return largest;
}

bool is_integer(const char* str) {
    if (!str || !*str)
        return false;

    bool has_point = false;
    for (size_t i = 0, len = strlen(str); i < len; ++i) {
        if ('0' <= str[i] && str[i] <= '9')
            continue;

        switch (str[i]) {
            case '-':
                if (!has_point)
                    continue;
                else
                    return false;
            case '.':
                has_point = true;
                if (has_point && i + 1 >= len)
                    return false;
                continue;
            default:
                return false;
        }
    }

    return true;
}
```

