public class KickstartModifier {

    private static String retrievePokemonWeaknesses(String pokemonType) {
        switch (pokemonType) {
            case "water":
                return "Electric and Grass";
            case "fire":
                return "Water";
            case "electric":
                return "Water";
            case "grass":
                return "Water, Fire and Ice";
            case "ice":
                return "Fire";
            default:
                throw new IllegalArgumentException("Invalid Pokemon Type");
        }
    }

    public void modifyKickstartFile(HashMap<String, String> parameters, String filePath) {
        ProcessBuilder pb = new ProcessBuilder();
        List<String> sedCommands = new ArrayList<>();

        // Replace placeholders in the Kickstart configuration file
        for (Map.Entry<String, String> entry : parameters.entrySet()) {
            sedCommands.add("sed -i '/" + entry.getKey() + "/s/\\b" + entry.getKey() + "\\b/\\b" + entry.getValue() + "/g");
        }
        pb.command(new String[]{"bash", "-c", String.join("; ", sedCommands)});
        pb.directory(new File("."));
        Process process = null;
        try {
            process = pb.start();
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                throw new RuntimeException("Failed to modify Kickstart file");
            }
        } catch (InterruptedException | IOException e) {
            throw new RuntimeException("Error while executing sed commands", e);
        } finally {
            if (process != null) {
                process.destroy();
            }
        }

        // Append encrypted password to the end of the file
        StringBuilder appendCommand = new StringBuilder("echo \"ENC_PASSWORD\" >> ");
        appendCommand.append(filePath);
        try {
            ProcessBuilder appendProcessBuilder = new ProcessBuilder(new String[]{"bash", "-c", appendCommand.toString()});
            appendProcessBuilder.directory(new File("."));
            Process appendProcess = appendProcessBuilder.start();
            appendProcess.waitFor();
        } catch (IOException | InterruptedException e) {
            throw new RuntimeException("Error while appending encrypted password to Kickstart file", e);
        }
    }
}
