#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>

typedef void* (*hash_func_t)(const char*, const unsigned char*, size_t);
typedef void* (*cipher_func_t)(const unsigned char*, size_t, const unsigned char*, size_t, unsigned char*);

struct algorithm {
    char name[128];
    union {
        hash_func_t hash;
        cipher_func_t cipher;
    } func;
    void* handle;
    char* init_params;
};

void load_config(const char* filename) {
    // Load configuration file and parse preferred algorithms.
}

struct algorithm* discover_algorithms() {
    struct algorithm* list = NULL;
    size_t count = 0, i;

    // Use dlopen to load the system-provided cryptography library.
    void* handle = dlopen("libcryptography", RTLD_LAZY);
    if (!handle) {
        perror("dlopen");
        return NULL;
    }

    // Iterate through exported symbols and discover available hash functions.
    char** sym = dl_symbols(handle);
    for (i = 0; sym[i]; i++) {
        void* func = dlsym(handle, sym[i]);
        if (dlerror() == NULL) {
            // Check if the symbol is a valid hash function constructor.
            if (strncmp("hash_", sym[i], 5)) continue;

            struct algorithm* alg = malloc(sizeof(struct algorithm));
            strcpy(alg->name, sym[i] + 5);
            alg->func.hash = (hash_func_t) func;
            alg->handle = handle;
            list = realloc(list, sizeof(struct algorithm) * ++count);
            list[count - 1] = alg;
        }
    }

    // Iterate through exported symbols and discover available block ciphers.
    for (i = 0; sym[i]; i++) {
        void* func = dlsym(handle, sym[i]);
        if (dlerror() == NULL) {
            // Check if the symbol is a valid block cipher constructor.
            if (strncmp("cipher_", sym[i], 7)) continue;

            struct algorithm* alg = malloc(sizeof(struct algorithm));
            strcpy(alg->name, sym[i] + 7);
            alg->func.cipher = (cipher_func_t) func;
            alg->handle = handle;
            list = realloc(list, sizeof(struct algorithm) * ++count);
            list[count - 1] = alg;
        }
    }

    // Free memory used for symbol lookup.
    free(sym);

    // Filter out preferred algorithms from the config file.
    load_config("preferences.conf");

    return count ? list : NULL;
}

void cleanup(struct algorithm* list) {
    for (size_t i = 0; list[i]; i++) {
        if (list[i]->init_params) free(list[i]->init_params);
        dlclose(list[i]->handle);
    }
    free(list);
}
