['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Resource {
    void* data;
    struct Resource* next;
} Resource;

typedef struct ResourcePool {
    Resource* head;
    int capacity;
    int size;
    pthread_mutex_t lock;
    sem_t not_full, not_empty;
} ResourcePool;

ResourcePool* createResourcePool(int capacity) {
    ResourcePool* pool = malloc(sizeof(ResourcePool));
    if (!pool) {
        perror("Failed to allocate memory");
        return NULL;
    }

    pool->head = NULL;
    pool->capacity = capacity;
    pool->size = 0;

    pthread_mutex_init(&pool->lock, NULL);
    sem_init(&pool->not_full, 0, capacity);
    sem_init(&pool->not_empty, 0, 0);

    return pool;
}

void* getResource(ResourcePool* pool) {
    void* data = NULL;
    Resource* resource;

    pthread_mutex_lock(&pool->lock);
    while (pool->size == pool->capacity && sem_trywait(&pool->not_full) < 0) {
        sem_wait(&pool->not_empty);
    }

    if (pool->size < pool->capacity) {
        resource = malloc(sizeof(Resource));
        if (!resource) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }

        resource->data = NULL;
        resource->next = pool->head;
        pool->head = resource;
        pool->size++;
    } else {
        resource = pool->head;
        pool->head = resource->next;
        pool->size--;
    }

    data = resource->data;
    pthread_mutex_unlock(&pool->lock);
    return data;
}

void freeResource(ResourcePool* pool, void* data) {
    pthread_mutex_lock(&pool->lock);
    Resource* resource = (Resource*)malloc(sizeof(Resource));
    if (!resource) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    resource->data = data;
    resource->next = pool->head;
    pool->head = resource;
    sem_post(&pool->not_empty);
    pthread_mutex_unlock(&pool->lock);
}
