#include <vector>
#include <algorithm>
#include <iterator>

void replaceConsecutiveDuplicates(std::vector<int>& v, int third, int second) {
    int count = 0;
    std::vector<int>::iterator it = v.begin();

    for (; it != --v.end(); ++it) {
        if (*it == third) {
            if (++count > 2) {
                *it = second;
                count = 0;
            }
        } else {
            count = 0;
        }
    }

    if (count == 0 && v.back() == third) {
        v.push_back(second);
    }
}
