namespace myapp {

class logger {
public:
    logger(const boost::filesystem::path& logFilePath, int maxSizeMB, int rotateIntervalSecs)
        : m_logSink(keywords::file_name = logFilePath.string(),
                   keywords::rotation_size = static_cast<unsigned>(maxSizeMB * 1048576),
                   keywords::time_based_rotation = boost::posix_time::seconds(rotateIntervalSecs)) {
        m_ioService.reset(new boost::asio::io_service);
        m_logSink.add_filter("debug") << boost::log::trivial::severity_level::debug;
        m_logSink.add_filter("info") << boost::log::trivial::severity_level::info;
        m_logSink.add_filter("warning") << boost::log::trivial::severity_level::warning;
        m_logSink.add_filter("error") << boost::log::trivial::severity_level::error;
        m_logger = boost::log::core::get()->get_sink(m_logSink);
    }

    ~logger() {
        m_ioService->stop();
        m_ioService->run();
    }

    template<typename T>
    void log(boost::log::trivial::severity_level sl, const T& tag, const char* msg) {
        m_logger->push_attributes([tag]() mutable { return boost::log::keywords::named_scope(tag); })
            ->operator()(sl)(msg);
    }

private:
    boost::log::sinks::async_frontend m_logSink;
    boost::shared_ptr<boost::asio::io_service> m_ioService;
    boost::log::sources::logger m_logger;
};

} // namespace myapp
