import express from 'express';
import { v4 as uuidv4 } from 'uuid';
import paginate from 'paginate-express';

const app = express();
app.use(express.json());

let templates = []; // In-memory storage for simplicity, replace with a database in production

// Generate unique UUID for new templates
function generateUUID() {
  return uuidv4();
}

// Validate template data size
function validateSize(data) {
  return data.length <= 1000; // Replace with your predefined size limit
}

// Create a new template
app.post('/templates', (req, res) => {
  const data = req.body;
  if (validateSize(data)) {
    const template = { id: generateUUID(), ...data };
    templates.push(template);
    res.status(201).send(template);
  } else {
    res.status(400).send({ error: 'Data exceeds size limit' });
  }
});

// Update an existing template by UUID
app.put('/templates/:id', (req, res) => {
  const id = req.params.id;
  const index = templates.findIndex(template => template.id === id);

  if (index !== -1) {
    const data = req.body;
    if (validateSize(data)) {
      templates[index] = { ...templates[index], ...data };
      res.send(templates[index]);
    } else {
      res.status(400).send({ error: 'Data exceeds size limit' });
    }
  } else {
    res.status(404).send({ error: 'Template not found' });
  }
});

// Delete a template by UUID
app.delete('/templates/:id', (req, res) => {
  const id = req.params.id;
  const index = templates.findIndex(template => template.id === id);

  if (index !== -1) {
    templates.splice(index, 1);
    res.sendStatus(204); // No Content status indicates successful deletion
  } else {
    res.status(404).send({ error: 'Template not found' });
  }
});

// Paginate templates
app.get('/templates', paginate.mongo(templates), (req, res) => {
  res.json(res.paginated);
});
