    public static String hash(String input, HashingAlgorithm algorithm) throws Exception {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input cannot be null or empty.");
        }

        MessageDigest md;
        switch (algorithm) {
            case MD5:
                md = MessageDigest.getInstance("MD5");
                break;
            case SHA_256:
                md = MessageDigest.getInstance("SHA-256");
                if (input.length() < 32) {
                    throw new InvalidInputLengthException(32, input.length());
                }
                break;
            default:
                throw new IllegalArgumentException("Invalid hashing algorithm.");
        }

        byte[] digest = md.digest(input.getBytes());
        BigInteger number = new BigInteger(1, digest);

        // Log detailed error messages to a specified logger if an exception occurs during hashing
        LOGGER.log(Level.FINEST, "Hash calculation for input: {0} with algorithm: {1}", new Object[]{input, algorithm});

        return number.toString(16);
    }

    // Custom exceptions for invalid input lengths when using the SHA-256 algorithm
    public static class InvalidInputLengthException extends Exception {
        private final int requiredLength;
        private final int inputLength;

        public InvalidInputLengthException(int requiredLength, int inputLength) {
            super("Input length must be at least " + requiredLength + " bytes (256 bits). Given input has " + inputLength + " bytes.");
            this.requiredLength = requiredLength;
            this.inputLength = inputLength;
        }
    }

    // Hashing algorithm enum
    public enum HashingAlgorithm {
        MD5,
        SHA_256
    }
}
```']

