using System.Linq;
using System.Net;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

namespace YourWebApplication.Controllers
{
    [Route("api/[controller]")]
    public class ElementController : ControllerBase
    {
        private readonly ILogger<ElementController> _logger;
        private readonly IUserService _userService;
        private readonly IElementService _elementService;

        public ElementController(ILogger<ElementController> logger, IUserService userService, IElementService elementService)
        {
            _logger = logger;
            _userService = userService;
            _elementService = elementService;
        }

        [HttpPost]
        public async Task<IActionResult> UpdateElement(int pageSectionId, int elementId, string content)
        {
            var user = await _userService.GetCurrentUser();

            if (user == null || !await _userService.IsAuthenticated(user))
                return Unauthorized();

            var permissions = await _userService.GetUserPermissions(user);

            if (!permissions.Any(p => p.PageSectionId == pageSectionId && p.ElementId == elementId))
                return Forbid();

            await _elementService.UpdateElement(pageSectionId, elementId, content);
            _logger.LogInformation($"User {user.Username} attempted to update element {elementId} in section {pageSectionId}.");
            Response.Headers.Add("Refresh", "0"); // Refresh the page
            return Ok();
        }
    }
}
