function runModuleTests({ timeout = 5, verbose = true } = {}) {
  // Load the module using try-catch block to handle case where the module might not be found
  const module = {};
  try {
    module = require(moduleName);
  } catch (err) {
    console.error(`Failed to load module "${moduleName}":`, err);
