  blueslip.reset();

  // Iterate through the provided tests and execute them, handling timeouts and exceptions
  for (const test of tests) {
    const startTime = Date.now();

    try {
      test.f(blueslip); // Call the test function with Blueslip as an argument
      const duration = Date.now() - startTime;

      if (duration > timeout * 1000) {
        console.error(`Test "${test.name}" exceeded the time limit of ${timeout} seconds. Skipped.`);
        continue;
      }

      if (verbose) {
        console.log(`Test "${test.name}" passed in ${duration}ms.`);
      } else {
        console.log(`Test "${test.name}" passed.`);
      }
    } catch (err) {
      const duration = Date.now() - startTime;
      console.error(`Test "${test.name}" failed:`, err);
      if (verbose) {
        console.log(`Test "${test.name}" took ${duration}ms to fail.`);
      }
    } finally {
      clearTimeout(currentTestTimeout); // Clear the current timeout before moving on to the next test
    }

    // Set a new timeout for the next test, if the user didn't provide a custom timeout value
    if (timeout !== undefined && typeof timeout === 'number') {
      currentTestTimeout = setTimeout(() => {
        console.error(`Test "${test.name}" timed out after ${timeout} seconds. Skipped.`);
      }, timeout * 1000);
    }
  }
}
