// Cache for regex patterns to avoid redundant processing
let otBooksPatternCache = new Map();

function getOTBooksPattern() {
  let pattern = otBooksPatternCache.get(this.text);

  if (!pattern) {
    // Construct and compile regular expressions using the text input
    const bookNames = ['Genesis', 'Exodus', 'Leviticus', ...]; // Add more books as needed
    const patterns = [];

    for (let book of bookNames) {
      patterns.push(new RegExp('\\b' + book + '\\b', 'gi'));
    }

    otBooksPatternCache.set(this.text, patterns);
    pattern = patterns;
  }

  return pattern;
}

function analyzeText(text) {
  this.text = text; // Set the input text for the function calls below

  const otBooksPattern = getOTBooksPattern.call({ text });
  const bookCounts = {};

  let match;
  while ((match = otBooksPattern.exec(text)) !== null) {
    const bookName = match[0].toLowerCase();
    if (!bookCounts[bookName]) bookCounts[bookName] = 0;
    bookCounts[bookName]++;
  }

  return countWords(bookCounts);
}

function countWords(counts) {
  const results = {};

  for (let book in counts) {
    if (counts[book] >= THRESHOLD) {
      const logEntry = logFrequencyAndLineNumbers(counts[book], this.text);
      results[book] = counts[book];
      results['total_mentions'] += counts[book];
      results['log_entries'].push(logEntry);
    }
  }

  const chapterCounts = countChapterMentions(results, this.text);

  return {
    ...results,
    'total_chapters': Object.values(chapterCounts).reduce((a, b) => a + b),
    'distribution': chapterCounts
  };
}

function logFrequencyAndLineNumbers(freq, text) {
  const logEntries = [];
  let lineNumber = 1;

  // Split the text into lines and filter for matches
  const lines = text.split('\n');
  for (let line of lines) {
    if ((match = /\b(\w+)\s*(:|:|,|;|\.)?\s*\b(?=(\b(?:$|^)|(?!\b(\w+):)))/.exec(line)) !== null) {
      const word = match[1];
      if (word.toLowerCase() === this.bookName) {
        logEntries.push({ freq, lineNumber });
      }
    }
    lineNumber++;
  }

  return { bookName: this.bookName, frequency: freq, logEntries };
}

function countChapterMentions(results, text) {
  const chapterCounts = {};

  // Assuming that you have a function to get the current chapter based on line numbers and split the text into chapters
  for (let chapter of this.getChapters(text)) {
    let mentionsInChapter = 0;

    for (let book in results) {
      if (results[book]['log_entries']) {
        mentionsInChapter += results[book]['log_entries'].filter(entry => entry.lineNumber >= chapter.startLine && entry.lineNumber <= chapter.endLine).length;
      }
    }

    chapterCounts[chapter.name] = mentionsInChapter;
  }

  return chapterCounts;
}

function getBooks(isOffline) {
  if (isOffline) {
    // Use a predefined local list of books as a fallback
    return [...]; // Add the list here
  } else {
    return axios.get(OT_BOOKS_API_URL).then(response => response.data).catch(error => {
      console.error('Error fetching Old Testament books from API:', error);
      return getBooks(true); // Recursively call with offline mode enabled if there's an error
    });
  }
}

function analyzeTextOffline() {
  this.books = getBooks(true).then(res => res); // Assuming that the function returns a promise
  return analyzeText.call({ text: this.text, books: this.books });
}

// Example usage
