function generateNavigation(configs) {
  const navList = document.createDocumentFragment();

  configs.forEach((config) => {
    const listItem = document.createElement('li');
    const link = document.createElement('a');
    const icon = config.icon ? `<span class="${config.icon}"></span>` : '';

    link.textContent = config.label;
    link.href = config.link;
    link.appendChild(Document.createTextNode("")); // empty text node for correct rendering of submenus

    if (config.children) {
      listItem.appendChild(icon);
      listItem.appendChild(link);
      navList.appendChild(listItem);
      generateSubmenu(navList, config.children);
    } else {
      link.insertAdjacentHTML('afterBegin', icon);
      listItem.appendChild(link);
    }
  });

  function generateSubmenu(parent, submenus) {
    const sublist = document.createElement('ul');

    submenus.forEach((subconfig) => {
      const subitem = document.createElement('li');
      const sublink = document.createElement('a');

      if (subconfig.icon) {
        sublink.insertAdjacentHTML('afterBegin', `<span class="${subconfig.icon}"></span>`);
      }

      sublink.textContent = subconfig.label;
      sublink.href = subconfig.link;

      subitem.appendChild(sublink);
      if (subconfig.children) generateSubmenu(subitem, subconfig.children);

      parent.appendChild(sublist);
      sublist.appendChild(subitem);
    });
  }

  return navList.innerHTML;
}
