function traverseDOM(callback, root = document) {
  const formElements = [];

  function collectFormsRecursive(node) {
    if (node.tagName === 'FORM' || node.matches('input[type="text"], input[type="email"], input[type="password"], select, textarea')) {
      const isValid = callback(node);
      if (isValid) formElements.push(node);
    }

    for (const child of node.children) {
      collectFormsRecursive(child);
    }
  }

  collectFormsRecursive(root);

  return formElements;
}
