import java.time.*;
import java.util.*;
import java.io.*;
import static java.lang.System.currentTimeMillis;

public class LogProcessor {
    private static final long MINUTE = 60000L;
    private static final int SLIDING_WINDOW = 5; // minutes

    public static void main(String[] args) throws IOException {
        long startTime = currentTimeMillis();
        int uniqueSessionIds = processLogFile("log.txt");
        long processingTime = currentTimeMillis() - startTime;
        System.out.printf("Processed %d lines, generated %d unique session IDs with average session length: %.2f seconds%n",
                totalLines, numSessions, avgSessionLength);
        System.out.printf("Processing time: %.2f milliseconds%n", processingTime);
    }

    private static long totalLines = 0;
    private static Map<Long, Session> sessions = new TreeMap<>();
    private static int numSessions = 0;
    private static double avgSessionLength;

    private static class Session {
        private final LocalDateTime startTime;
        private long endTime;

        public Session(LocalDateTime start) {
            this.startTime = start;
            this.endTime = start.toInstant(ZoneOffset.UTC).toEpochMilli();
        }
    }

    private static void processLine(String line) throws IOException {
        String[] parts = line.split(" ");
        LocalDateTime timestamp = LocalDateTime.parse(parts[0]);
        long eventId = Long.parseLong(parts[1]);

        totalLines++;

        Session currentSession = sessions.floorEntry(timestamp.toInstant(ZoneOffset.UTC).toEpochMilli());

        if (currentSession == null) {
            sessions.putIfAbsent(timestamp.toInstant(ZoneOffset.UTC).toEpochMilli(), new Session(timestamp));
            currentSession = sessions.floorEntry(timestamp.toInstant(ZoneOffset.UTC).toEpochMilli());
        }

        long sessionEndTime = currentSession.getValue().endTime;
        long diffInMinutes = (timestamp.minusMillis(sessionEndTime).toChronoUnit().get() + 1) / MINUTE;
        if (diffInMinutes > SLIDING_WINDOW) {
            Session sessionToRemove = sessions.remove(currentSession.getKey());
            numSessions--;
        }

        currentSession.getValue().endTime = timestamp.toInstant(ZoneOffset.UTC).toEpochMilli();
    }

    private static int processLogFile(String fileName) throws FileNotFoundException {
        Scanner scanner = new Scanner(new File(fileName));
        while (scanner.hasNextLine()) {
            String line = scanner.nextLine();
            processLine(line);
        }
        scanner.close();
        numSessions = sessions.size();
        avgSessionLength = ((double) sessions.values().stream().mapToLong(s -> s.endTime - s.startTime.toInstant(ZoneOffset.UTC).toEpochMilli()).sum()) / (double) numSessions;
        return numSessions;
    }
}
```']

['```java
import java.nio.channels.*;
import java.util.*;
import java.net.*;

public class ConnectionPool {
    private static final int MAX_CONNECTIONS = 100;
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private static final Map<Integer, SelectionKey> connectionMap = new WeakHashMap<>();

    public SelectionKey acquireConnection() {
        synchronized (connectionMap) {
            for (SelectionKey key : connectionMap.values()) {
                if (!key.isValid() || !key.isRegistered()) {
                    connectionMap.remove(key);
                }
            }

            for (SelectionKey key : connectionMap.values()) {
                if (!key.channel().isOpen()) {
                    key.cancel();
                    connectionMap.remove(key);
                }
            }

            SelectionKey availableConnection = null;
            if (connectionMap.size() < MAX_CONNECTIONS) {
                try {
                    SocketChannel socketChannel = SocketChannel.open();
                    socketChannel.configureBlocking(false);
                    Selector selector = Selector.open();
                    socketChannel.register(selector, SelectionKey.OP_CONNECT);
                    availableConnection = socketChannel.register(selector, SelectionKey.OP_READ);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }

            if (availableConnection != null && connectionMap.size() < MAX_CONNECTIONS) {
                return availableConnection;
            } else if (!connectionMap.isEmpty()) {
                return connectionMap.values().iterator().next();
            }
        }

        return null;
    }

    public void releaseConnection(SelectionKey key) {
        synchronized (connectionMap) {
            if (key != null && key.isValid() && !key.isRegistered()) {
                connectionMap.put(key.attach((short) System.identityHashCode(this)), key);
            }
        }
    }

    public void manageConnections() {
        while (true) {
            try {
                Selector selector = Selector.open();
                List<SelectionKey> selectedKeys = new ArrayList<>();

                for (SelectionKey key : connectionMap.values()) {
                    if (key != null && key.isValid() && !key.isRegistered()) {
                        key.attach((short) System.identityHashCode(this));
                        key.register(selector, SelectionKey.OP_CONNECT);
                        selectedKeys.add(key);
                    }
                }

                if (selectedKeys.size() > 0) {
                    selector.selectNow();
                    Iterator<SelectionKey> it = selectedKeys.iterator();
                    while (it.hasNext()) {
                        SelectionKey key = it.next();
                        if (!key.isValid() || !key.isRegistered()) {
                            connectionMap.remove(key);
                            it.remove();
                            continue;
                        }

                        SocketChannel socketChannel = (SocketChannel) key.channel();

                        if (key.isConnectable()) {
                            if (!socketChannel.finishConnect()) {
                                key.cancel();
                                connectionMap.remove(key);
                            } else {
                                key.interestOps(SelectionKey.OP_READ);
                            }
                        }

                        if (key.isReadable()) {
                            // Handle read operation here
                        }
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
            }

            scheduler.scheduleWithFixedDelay(() -> manageConnections(), 1, 100, TimeUnit.MILLISECONDS);
        }
    }
}
