// Define User schema and model
const UserSchema = new mongoose.Schema({
  username: String,
  password: String,
  sessionId: String
});
const User = mongoose.model('User', UserSchema);

// Function to generate a secure token for user sessions
function generateToken(user) {
  return jwt.sign({ id: user.id }, 'your_secret_key', { expiresIn: '1h' });
}

// Middleware to check for a valid session ID and update lastActivity
app.use((req, res, next) => {
  const token = req.cookies['sessionID'];
  if (token) {
    User.findOne({ sessionId: token }, (err, user) => {
      if (err || !user) {
        res.clearCookie('sessionID');
        return next();
      }
      user.lastActivity = Date.now();
      user.save((err) => {
        if (err) return next(err);
      });
      req.user = user;
      next();
    });
  } else {
    res.clearCookie('sessionID');
    next();
  }
});

// Login route that validates user credentials and generates a session ID
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  User.findOne({ username }, (err, user) => {
    if (err || !user || user.password !== password) {
      return res.status(401).send('Invalid credentials');
    }
    const token = generateToken(user);
    res.cookie('sessionID', token).json({ success: true, sessionId: token });
  });
});

// Set up inactivity timeout and session cleanup
const ONE_HOUR = 60 * 60 * 1000;
app.get('/', (req, res) => {
  if (req.user) req.user.lastActivity = Date.now();
  req.user.save((err) => {
    if (err) return next(err);
  });
  res.send('Welcome to our web application!');
});
setInterval(() => {
  User.deleteMany({ lastActivity: { $lt: Date.now() - ONE_HOUR } }, (err) => {
    if (err) console.error(err);
  });
}, ONE_HOUR);
```"]

