use reqwest::Client;
use reqwest::redirect::Policy;
use reqwest::header::{HeaderMap, HeaderValue};
use std::sync::{Arc, Mutex};
use serde_json::json;
use log::*;
use reqwest::RequestBuilder;
use arc-swap::Swap;

type ResponseCache = Arc<Mutex<std::collections::HashMap<String, reqwest::Response>>>;

struct MyClient {
    client: Client,
    cache: ResponseCache,
    log_fn: Box<Fn(&reqwest::Request, &reqwest::Response) + Send + Sync>,
}

impl MyClient {
    fn new(disable_cert_validation: bool, cache_size: usize, log_fn: Box<Fn(&reqwest::Request, &reqwest::Response) + Send + Sync>) -> Self {
        let client = Client::builder()
            .redirect(Policy::custom({
                |location| match location.url().host() {
                    Some(_) => Policy::supercharge(), // Handle redirections for all domains
                    None => Policy::no_new_tokens(), // Don't follow redirects for no host urls
                }
            }))
            .keep_alive(true) // Enable connection pooling
            .dangerously_disable_http1_native() // Required for automatic header handling
            .build().unwrap();

        let cache = Arc::new(Mutex::new(std::collections::HashMap::with_capacity(cache_size)));
        MyClient { client, cache, log_fn, }
    }

    async fn request_builder(&self, url: &str) -> RequestBuilder {
        let mut req = self.client.request(url).clone();

        // Handle authentication headers for certain domains
        if should_use_auth_headers(url) {
            let auth_header = HeaderValue::from_str(format!("Basic {}", base64::encode("username:password"))).unwrap();
            req = req.header("Authorization", auth_header);
        }

        // Disable certificate validation if required
        if !self.client.dangerous().ca().is_none() && disable_cert_validation {
            self.client.dangerous().ca(None);
        }

        req.before_send(|req| {
            log(&format!("{}", serde_json::to_string(&json!({"url": req.url(), "headers": req.headers()})).unwrap()));
            self.log_fn(req, &req)
        });

        // Cache responses based on request URLs
        let cached_response = self.cache.lock().await.get(url).cloned();
        if let Some(ref response) = cached_response {
            req.body(response.into_body())
        } else {
            req
        }
    }
}

fn should_use_auth_headers(url: &str) -> bool {
    // Add your logic to determine whether authentication headers should be used for a given URL here
}

fn log<T: serde::Serialize>(message: T) {
    let _ = info!("{:?}", message);
}
```

