            $error = curl_error($handle);
            break;
        } else {
            $response = json_decode(curl_getcontent($handle), true);
            curl_close($handle);
            break; // Exit the loop if we got a valid response
        }

        usleep(1000000 * ($i + 1)); // Increase sleep interval with each iteration
