<?php

class Password {
    private $charset;
    private $length;
    private $hashAlgorithm = 'argon2i';

    public function __construct($charset = null, $length = 32) {
        $this->charset = $charset ? str_replace("\r\n", '', trim($charset)) : '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
        $this->length = intval($length);
    }

    public function generateRandomString() {
        $randomString = '';
        for ($i = 0; $i < $this->length; $i++) {
            $randomString .= $this->charset[rand(0, strlen($this->charset) - 1)];
        }
        return $randomString;
    }

    public function hashPassword($password, $rounds = 2) {
        if (!extension_loaded('argon2')) {
            throw new Exception('Argon2 extension not loaded.');
        }

        $algorithmMap = [
            'bcrypt' => ['cost' => 10],
            'argon2i' => ['time', 'memory', 'threads' => $rounds],
            // Add more algorithms as needed
        ];

        if (!array_key_exists($this->hashAlgorithm, $algorithmMap)) {
            throw new Exception("Invalid hash algorithm: {$this->hashAlgorithm}");
        }

        $algorithm = $algorithmMap[$this->hashAlgorithm];
        $options = [];
        foreach ($algorithm as $option => $value) {
            if (is_int($value)) {
                $options[$option] = intval($value);
            } else {
                $options[$option] = $value;
            }
        }

        // Use password_hash for built-in algorithms and argon2 for custom algorithm.
        if (function_exists("password_hash")) {
            return password_hash($password, PASSWORD_DEFAULT, $options);
        } else {
            // Implement argon2 using external library or native functions based on the environment.
            // ...
        }
    }

    public function verifyPassword($hashedPassword, $plaintextPassword) {
        return password_verify($plaintextPassword, $hashedPassword);
    }
}

