#include <stdlib.h>
#include <stdbool.h>

struct ListNode {
    int stateIndex;
    struct ListNode *next;
};

FSANode* getReachableStates(int* states, int numStates, FSANode* fsa, int lastState) {
    if (!fsa || numStates <= 0)
        return NULL;

    struct ListNode *head = NULL, *current = NULL;

    bool visited[numStates] = {false};
    visited[lastState] = true;

    int queue[3];
    queue[0] = lastState;
    int front = 0, rear = 1;

    while (front != rear) {
        FSANode *node = &fsa[queue[front]];
        if (node->stateIndex == -1) continue; // Invalid state

        for (int i = 0; i < numStates; ++i) {
            if (!visited[i]) {
                if (node->next && node->next->stateIndex == i) {
                    visited[i] = true;
                    if (rear < sizeof(queue)/sizeof(int)) {
                        queue[rear++] = i;
                    } else {
                        struct ListNode *temp = (struct ListNode*)malloc(sizeof(struct ListNode));
                        if (!temp) return NULL;

                        temp->stateIndex = i;
                        temp->next = head;
                        head = temp;
                    }
                }
            }
        }

        ++front;
    }

    // Connect the last state in the current list with the newly created linked list.
    if (head)
        head->next = fsa[lastState].next;
    else
        fsa[lastState].next = head; // In case no new states were reachable.

    return head;
}
