#include <memory>
#include <vector>
#include <atomic>
#include <mutex>
#include <thread>
#include <future>

template<typename T>
class Node {
public:
    std::array<std::unique_ptr<Node<T>>, 8> children;
    T data;
    std::atomic<int> isLeaf{1};
    std::mutex mutex;

    Node() {}
    Node(const T& data) : data(data), isLeaf(0) {}
};

class Octree {
public:
    Octree(size_t featureSize, size_t initialLeafNodes, size_t dataCapacity)
        : m_featureSize(featureSize), m_initialLeafNodes(initialLeafNodes),
          m_dataCapacity(dataCapacity), m_root(std::make_unique<Node<T>>()),
          m_numLevels(0), m_mutex() {}

    std::unique_ptr<Node<T>>& getRoot() { return m_root; }
    size_t numLevels() const { return m_numLevels; }
    size_t featureSize() const { return m_featureSize; }

private:
    void expand(std::unique_ptr<Node<T>>& node) {
        for (auto& child : node->children) {
            if (!child) {
                child = std::make_unique<Node<T>>();
            }
        }
        ++m_numLevels;
    }

    size_t calculateIndex(size_t bitPosition, float coordinate) const {
        return static_cast<size_t>(coordinate * (1 << bitPosition) + 0.5);
    }

    void insert(const T& data, std::unique_ptr<Node<T>>& node, size_t currentLevel, size_t bitPosition) {
        if (currentLevel == m_numLevels) {
            node->data = data;
            node->isLeaf.store(1);
            return;
        }

        std::unique_lock lock(m_mutex);
        auto index = calculateIndex(bitPosition, data[bitPosition / 8]);
        if (!node->children[index]) {
            expand(node->children[index]);
        }

        node = node->children[index];
        bitPosition++;

        std::thread([this, data, node, currentLevel, bitPosition]() {
            insert(data, *node, currentLevel, bitPosition);
        }).detach();
    }

    T retrieveData(const std::unique_ptr<Node<T>>& node, size_t currentLevel, size_t bitPosition) const {
        if (currentLevel == 0) {
            return {};
        }

        auto index = calculateIndex(bitPosition, node->data[bitPosition / 8]);
        std::unique_ptr<const Node<T>> tempNode = node->children[index];

        if (!tempNode || tempNode->isLeaf.load() == 1) {
            return {};
        }

        std::thread t([this, tempNode, currentLevel, bitPosition]() {
            return retrieveData(tempNode, currentLevel - 1, bitPosition + 1);
        });

        T result = retrieveData(*tempNode, currentLevel - 1, bitPosition + 1);
        if (t.joinable()) {
            t.join();
        }
        return result;
    }

    std::unique_ptr<const Node<T>> m_root;
    size_t m_numLevels;
    mutable std::mutex m_mutex;
    size_t m_featureSize, m_initialLeafNodes, m_dataCapacity;
};
```

