#include <stdio.h>
#include <time.h>
#include <stdbool.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int id;
    double weights[4]; // Adjust the number and types of weighted attributes as needed
} Transaction;

struct sliding_window {
    Transaction transactions[10];
    double cumulative_weighted_sum;
    int count;
    pthread_mutex_t lock;
};

void init_sliding_window(struct sliding_window *win) {
    win->count = 0;
    win->cumulative_weighted_sum = 0.0;
    pthread_mutex_init(&win->lock, NULL);
}

int is_valid_transaction(const struct Transaction *t, const struct sliding_window *win) {
    time_t now = time(NULL);
    if (now - t->timestamp > 5) return false;
    int last_10s_count = win->count;
    pthread_mutex_lock(&win->lock);
    while ((now - t->timestamp <= 5) && (last_10s_count < 100)) {
        last_10s_count++;
        if (++win->count > 10) win->count = 0;
        else continue;
        pthread_mutex_unlock(&win->lock);
        return false;
    }
    pthread_mutex_unlock(&win->lock);
    return true;
}

double calculate_weighted_sum(const Transaction *t) {
    // Adjust this formula to fit your requirements
    double weighted_sum = 0.0;
    for (int i = 0; i < ARRAY_SIZE(t->weights); ++i) {
        weighted_sum += t->weights[i];
    }
    return weighted_sum;
}

void update_sliding_window(struct sliding_window *win, const Transaction *t) {
    pthread_mutex_lock(&win->lock);
    if (is_valid_transaction(t, win)) {
        win->transactions[win->count] = *t;
        win->cumulative_weighted_sum += calculate_weighted_sum(t);
        if (++win->count > 10) win->count = 0;
    }
    pthread_mutex_unlock(&win->lock);
}

void reset_sliding_window(struct sliding_window *win) {
    pthread_mutex_lock(&win->lock);
    if (win->count > 0) {
        win->cumulative_weighted_sum -= calculate_weighted_sum(&win->transactions[0]);
        memmove(win->transactions, &win->transactions[1], sizeof(Transaction) * (win->count - 1));
    }
    win->count = 0;
    win->cumulative_weighted_sum = 0.0;
    pthread_mutex_unlock(&win->lock);
}

void process_transaction(const Transaction *t, struct sliding_window *win, double *max_weighted_sum, int *max_id) {
    if (is_valid_transaction(t, win)) {
        double current_weighted_sum = calculate_weighted_sum(t);
        update_sliding_window(win, t);
        if (*max_weighted_sum < current_weighted_sum) {
            *max_weighted_sum = current_weighted_sum;
            *max_id = t->id;
        }
    }
}

void manage_transactions(struct sliding_window *win, Transaction transaction, double *max_weighted_sum, int *max_id) {
    process_transaction(&transaction, win, max_weighted_sum, max_id);
    if (time(NULL) - win->transactions[0].timestamp > 10) reset_sliding_window(win);
}
```

