        while (true) {
            // Check if it's time to select a new attack
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - attackTimer).count();
            if (elapsed >= cooldownDuration.count()) {
