            } else {
                // Wait for remaining cooldown time
                auto waitTime = cooldownDuration - (attackTimer - start);
                if (waitTime > 0) {
                    std::this_thread::sleep_for(std::chrono::milliseconds(waitTime));
                }
            }
        }
    }
