using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace RandomValueGenerator
{
    public class RandomValueGenerator
    {
        private readonly Random _random;
        private readonly (float min, float max) _floatRange;
        private readonly (int min, int max) _intRange;
        private readonly Dictionary<float, float> _probabilityDistribution;
        private int _seed;

        public RandomValueGenerator(int seed = 0)
        {
            _random = new Random(seed);
            _seed = seed;
            _floatRange = ((float)double.MinValue, (float)double.MaxValue);
            _intRange = (int.MinValue, int.MaxValue);
            _probabilityDistribution = new Dictionary<float, float>();
        }

        public RandomValueGenerator(float floatMin, float floatMax, bool isInclusive = true, int intMin = int.MinValue, int intMax = int.MaxValue, bool isIntInclusive = true)
        {
            _random = new Random();
            _seed = _random.Next();
            SetFloatRange(floatMin, floatMax, isInclusive);
            SetIntRange(intMin, intMax, isIntInclusive);
            _probabilityDistribution = new Dictionary<float, float>();
        }

        public void SetFloatRange(float min, float max, bool isInclusive)
        {
            if (min > max) throw new ArgumentException("The provided range for floating-point numbers is invalid.");
            _floatRange = (isInclusive ? (min, max) : (Math.Min(min, max), Math.Max(min, max)));
        }

        public void SetIntRange(int min, int max, bool isInclusive)
        {
            if (min > max) throw new ArgumentException("The provided range for integer numbers is invalid.");
            _intRange = (isInclusive ? (min, max) : (Math.Min(min, max), Math.Max(min, max)));
        }

        public void AddProbability(float value, float weight)
        {
            if (weight <= 0) throw new ArgumentException("The provided probability weight must be greater than zero.");
            _probabilityDistribution[value] = weight;
        }

        public T Generate<T>(Func<Random, T> generator) where T : struct
        {
            if (!typeof(T).IsAssignableFrom(typeof(float)) && !typeof(T).IsAssignableFrom(typeof(int)))
                throw new ArgumentException("The generated type must be either float or int.");

            var numberType = Nullable.GetUnderlyingType(typeof(T)) ?? typeof(T);

            if (numberType == typeof(float))
            {
                if (_probabilityDistribution.Count > 0)
                {
                    var totalWeight = _probabilityDistribution.Sum(weight => weight.Value);
                    var randomFloat = _random.NextDouble() * totalWeight;
                    var cumulativeWeight = 0.0f;

                    foreach (var kv in _probabilityDistribution)
                    {
                        cumulativeWeight += kv.Value;
                        if (cumulativeWeight > randomFloat)
                        {
                            return (T)(object)kv.Key;
                        }
                    }
                }
                else
                {
                    return (T)_floatRange.Item1 + (_random.NextDouble() * (_floatRange.Item2 - _floatRange.Item1));
                }
            }
            else if (numberType == typeof(int))
            {
                if (_probabilityDistribution.Count > 0)
                {
                    var totalWeight = _probabilityDistribution.Sum(weight => weight.Value);
                    var randomFloat = _random.NextDouble() * totalWeight;
                    var cumulativeWeight = 0.0f;

                    foreach (var kv in _probabilityDistribution)
                    {
                        cumulativeWeight += kv.Value;
                        if (cumulativeWeight > randomFloat)
                        {
                            return (T)(object)Math.Round(kv.Key);
                        }
                    }
                }
                else
                {
                    return (T)_intRange.Item1 + _random.Next(_intRange.Item2 - _intRange.Item1);
                }
            }

            throw new NotSupportedException("The provided type is not supported.");
        }

        public override string ToString()
        {
            var floatRangeText = _probabilityDistribution.Count > 0 ? "Probability distribution" : $"({_floatRange.Item1}, {_floatRange.Item2})";
            var intRangeText = _probabilityDistribution.Count > 0 ? "Probability distribution" : $"({_intRange.Item1}, {_intRange.Item2})";
            return $"RandomValueGenerator: Seed={_seed}\nFloat range:{floatRangeText}\nInteger range:{intRangeText}";
        }

        public void Reset()
        {
            _random = new Random(_seed);
        }
    }
}
