const asyncReduce = (arr, initialValue, callback, concurrency = 5) => {
  const queue = Array(concurrency).fill().map(() => Promise.resolve());
  let accumulator = initialValue;
  let processedIndex = 0;

  const processNextItem = () => {
    if (processedIndex >= arr.length) return;

    const currentItemIndex = processedIndex;
    const itemPromise = Promise.resolve(arr[currentItemIndex]);

    queue.shift().then(() => {
      return itemPromise.then(item => callback(accumulator, item, currentItemIndex))
        .catch(error => {
          console.error(`Error processing item ${currentItemIndex}:`, error);
          accumulator = initialValue; // Reset the accumulator on error to avoid propagating incorrect results
        });
    })
      .then(() => queue.push(processNextItem()))
      .catch(error => console.error('AsyncReduce error:', error));
  };

  processNextItem();
  return Promise.all(queue).then(() => accumulator);
};
```

