#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>
#include <stdbool.h>

struct resource_item {
    char* key;
    char* value;
};

typedef struct resource_bundle {
    int size;
    int capacity;
    struct resource_item* items;
    pthread_mutex_t lock;
} ResourceBundle;

ResourceBundle* load_resource_bundle(const char* file_path) {
    FILE* fp = fopen(file_path, "r");
    if (!fp) {
        perror("Failed to open file");
        return NULL;
    }

    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        fprintf(stderr, "Out of memory\n");
        fclose(fp);
        return NULL;
    }

    memset(bundle, 0, sizeof(ResourceBundle));
    pthread_mutex_init(&bundle->lock, NULL);

    bool error = false;
    char line[4096];
    int item_count = 0;
    while (fgets(line, sizeof(line), fp)) {
        size_t key_len = strlen(strchr(line, '='));
        if (key_len > sizeof(line) - 1 || line[0] == '\n' || line[key_len + 1] != '\n') {
            fprintf(stderr, "Invalid resource bundle format\n");
            error = true;
            break;
        }

        char* key = malloc(key_len + 2); // +1 for '=' and \0
        char* value = malloc(sizeof(line) - key_len - 1);
        if (!key || !value) {
            fprintf(stderr, "Out of memory\n");
            error = true;
            break;
        }

        strncpy(key, line, key_len + 1);
        key[key_len] = '\0';
        strncpy(value, line + key_len + 1, sizeof(line) - key_len - 2);
        value[sizeof(line) - key_len - 2] = '\0';

        pthread_mutex_lock(&bundle->lock);
        if (item_count >= bundle->capacity) {
            if (bundle->size != bundle->capacity) {
                bundle->capacity *= 2;
                bundle->items = realloc(bundle->items, sizeof(struct resource_item) * bundle->capacity);
            }
        }
        struct resource_item* item = &bundle->items[item_count];
        item->key = key;
        item->value = value;
        bundle->size++;
        pthread_mutex_unlock(&bundle->lock);

        item_count++;
    }

    fclose(fp);

    if (error) {
        destroy_resource_bundle(bundle);
        return NULL;
    }

    return bundle;
}

void destroy_resource_bundle(ResourceBundle* bundle) {
    pthread_mutex_destroy(&bundle->lock);

    for (int i = 0; i < bundle->size; ++i) {
        free(bundle->items[i].key);
        free(bundle->items[i].value);
    }

    free(bundle->items);
    free(bundle);
}
```

This code provides the basic implementation for the requested function, `load_resource_bundle`. It uses a thread-safe approach using a mutex lock to ensure safety when modifying the resource bundle. The function dynamically allocates memory for the bundle and its items and handles file I/O errors gracefully. However, it does not include logging or performance optimizations.']

