char* trim_or_truncate(const char *input, size_t limit, bool trim) {
    if (!input || limit == 0)
        return NULL;

    size_t input_len = strlen(input);
    if (input_len > limit) {
        if (trim)
            input_len = limit - 1; // Truncate the string without trailing slash
        else
            return NULL; // Exceeded limit and not allowed to trim, so return NULL
    }

    char *result = malloc(input_len + 2); // Allocate space for the input and a trailing slash
    if (!result)
        return NULL; // Failed allocation, no memory available

    strncpy(result, input, input_len); // Copy the input without extra characters
    result[input_len] = '/'; // Append the trailing slash
    result[input_len + 1] = '\0'; // Null-terminate the string

    return result;
}

int main() {
    char *small_string = trim_or_truncate("small_string", 8, true);
    printf("%s\n", small_string); // Expected output: "smal_" (truncated due to size limit and trim parameter)

    char *large_string = trim_or_truncate("very_long_string", 6, false);
    if (large_string)
