static void* process_file(void *arg) {
    int fd = *(int *) arg;
    char buffer[4096];
    ssize_t read_bytes;
    LineData data;

    while ((read_bytes = read(fd, buffer, sizeof(buffer))) > 0) {
        if (!(data.line = realloc(data.line, data.line_len + read_bytes))) {
            syslog(LOG_ERR, "Memory allocation error");
            goto close_and_exit;
        }
        memcpy(data.line + data.line_len, buffer, read_bytes);
        data.line_len += read_bytes;
        data.line[data.line_len] = '\0';

        char *token = strtok(data.line, "\n");
        while (token) {
            // Process each line here, calculating the average of last two fields and adjusting output formatting as needed
            // ...

            token = strtok(NULL, "\n");
        }
    }

close_and_exit:
    if (fd >= 0) close(fd);
    free(data.line);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s FILE [FILE...]\n", argv[0]);
        return 1;
    }

    pthread_t threads[argc - 1];
    struct timespec start, end;

    clock_gettime(CLOCK_MONOTONIC, &start);

    for (int i = 1; i < argc; ++i) {
        int fd = open(argv[i], O_RDONLY);
        if (fd == -1) {
            syslog(LOG_ERR, "Error opening file %s", argv[i]);
            continue;
        }

        pthread_create(&threads[i - 1], NULL, process_file, &fd);
    }

    for (int i = 0; i < argc - 1; ++i) {
        pthread_join(threads[i], NULL);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    syslog(LOG_INFO, "Processed %d lines in %.3fs", total_lines, (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1_000_000_000);

