TiffInfo* parseTIFF(const char* file_path) {
    TIFF* tif = TIFFOpen(file_path, "r");
    if (!tif) return NULL;

    TIFFGetFieldDefault(tif, TIFFTAG_BITSPERSAMPLE);
    int bits_per_sample = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
    int sample_per_pixel = TIFFGetFieldDefault(tif, TIFFTAG_SAMPLESPERPIXEL);
    int photometric_interpretation = TIFFGetFieldDefault(tif, TIFFTAG_PHOTOMETRICINTERPRETATION);

    TiffInfo* info = malloc(sizeof(TiffInfo));
    if (!info) {
        fprintf(stderr, "Error: Failed to allocate memory for TiffInfo\n");
        tiffClose(tif);
        return NULL;
    }

    info->bits_per_sample = bits_per_sample;
    info->sample_per_pixel = sample_per_pixel;
    info->photometric_interpretation = photometric_interpretation;

    tiffClose(tif);
    return info;
}

AES_KEY* initializeCipher(const char* encryption_method) {
    AES_KEY cipher;

    if (strlen(encryption_method) != 32) {
        ERR_load_crypto_strings();
        fprintf(stderr, "Error: Invalid encryption method length\n");
        return NULL;
    }

    if (AES_set_encrypt_key((const unsigned char*) encryption_method, 128, &cipher) <= 0) {
        ERR_load_crypto_strings();
        fprintf(stderr, "Error: Failed to initialize cipher\n");
        return NULL;
    }

    return &cipher;
}
