enum { MAX_FILENAME_LENGTH = 255 };

int rename_with_unique_id(const char *original_filename, char *new_filename) {
    if (!original_filename || strlen(original_filename) > MAX_FILENAME_LENGTH) {
        return -1; // Error: Filename too long
    }

    time_t current_time = time(NULL);
    struct tm *tm_ptr = localtime(&current_time);
    char timestamp[9];
    strftime(timestamp, 9, "%Y%m%d%H%M%S", tm_ptr);

    size_t filename_length = strlen(original_filename);
    if (filename_length + strlen(timestamp) > MAX_FILENAME_LENGTH) {
        return -1; // Error: Resulting name too long
    }

    sprintf(new_filename, "%s%zu%.*s_%s", original_filename, filename_length, 3, original_filename + (filename_length - 3), timestamp);

    return 0; // Success
}
