typedef struct {
    AES_KEY key;
    uint8_t iv[AES_BLOCK_SIZE];
} aes_context;

aes_context* aes_init(const char *password, size_t password_len) {
    unsigned char derived_key[AES_BLOCK_SIZE], iv[AES_BLOCK_SIZE];
    EVP_pbkdf2((const EVP_CIPHER *)EVPaes_256_cbc(),
               (const uint8_t*)password, password_len,
               "my-salt", 32, 20000, derived_key, sizeof(derived_key));
    RAND_bytes(iv, AES_BLOCK_SIZE);

    aes_context *ctx = malloc(sizeof(aes_context));
    if (!ctx) {
        fprintf(stderr, "Out of memory.\n");
        return NULL;
    }

    AES_set_encrypt_key((const unsigned char*)derived_key, 256, &ctx->key);
    memcpy(ctx->iv, iv, sizeof(ctx->iv));

    return ctx;
}

int aes_encrypt(aes_context *ctx, uint8_t *input, size_t input_len, uint8_t *output) {
    AES_cbc_encrypt((unsigned char*)input, (unsigned char*)output, input_len, &ctx->key, ctx->iv, AES_ENCRYPT);
    return 0;
}

int aes_decrypt(aes_context *ctx, uint8_t *input, size_t input_len, uint8_t *output) {
    AES_cbc_encrypt((unsigned char*)input, (unsigned char*)output, input_len, &ctx->key, ctx->iv, AES_DECRYPT);
    return 0;
}
