int process_video(const char* video_file, const char* output_dir, const char* log_file) {
    FILE *log = fopen(log_file, "w");
    if (!log) return 1;

    // Create output directory if it doesn't exist
    mkdir(output_dir, 0755);

    cv::VideoCapture cap(video_file);
    if(!cap.isOpened()) {
        fprintf(log, "Error: Unable to open video file.\n");
        return 1;
    }

    int frame_count = 0;
    cv::Mat frame;
    while (true) {
        cap >> frame;
        if (frame.empty()) break;

        ++frame_count;
        fprintf(log, "Processing frame %d...\n", frame_count);

        // Resize the frame to specified resolution
        cv::resize(frame, frame, cv::Size(320, 240));

        // Save the processed frame as a JPEG image in the output directory
        std::stringstream ss;
        ss << output_dir << "/frame_" << frame_count << ".jpg";
        imwrite(ss.str(), frame);
    }

    cap.release();
    fclose(log);
    return 0;
}
