    if (!root) {
        fprintf(stderr, "Error: Invalid JSON\n");
        return false;
    }

    bool valid = true;
    const char *access_token, *token_type, *expires_in_str, *refresh_token;
    json_object *access_token_obj, *expires_in_obj, *refresh_token_obj;

    access_token_obj = json_object_get(root, "access_token");
    token_type_obj = json_object_get(root, "token_type");
    expires_in_obj = json_object_get(root, "expires_in");
    refresh_token_obj = json_object_get(root, "refresh_token");

    if (!access_token_obj || !token_type_obj || !expires_in_obj) {
        fprintf(stderr, "Error: Mandatory fields 'access_token', 'token_type', and 'expires_in' are missing\n");
        valid = false;
    } else {
        access_token = json_object_get_string(access_token_obj);
        token_type = json_object_get_string(token_type_obj);
        expires_in_str = json_object_get_string(expires_in_obj);

        if (!access_token || strlen(access_token) == 0 ||
            strcmp(token_type, "Bearer") != 0 ||
            atoi(expires_in_str) <= 0) {
            valid = false;
        } else {
            int expires_in = atoi(expires_in_str);
            if (expires_in > INT_MAX) {
                fprintf(stderr, "Error: 'expires_in' value is too large\n");
                valid = false;
            }
        }
    }

    if (refresh_token_obj && !isValidUuidV4(json_object_get_string(refresh_token_obj))) {
        fprintf(stderr, "Error: 'refresh_token' is not a valid UUID v4\n");
        valid = false;
    }

    json_object_put(root);
    return valid;
}

