using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
using Amazon.S3;
using Amazon.S3.Model;
using SixLabors.ImageShapers;
using SevenZip;

namespace DocumentCompressionAndUpload
{
    public class CompressAndUploadService
    {
        private readonly IAmazonS3 _s3Client;
        private readonly string _bucketName;

        public CompressAndUploadService(IAmazonS3 s3Client, string bucketName)
        {
            _s3Client = s3Client;
            _bucketName = bucketName;
        }

        public async Task<Dictionary<string, (UploadStatus status, long size)>> ProcessDocumentsAsync(IEnumerable<string> documentPaths)
        {
            var results = new Dictionary<string, (UploadStatus, long)>();

            using (var archiveWriter = new ArchiveWriter())
            {
                var compressedDocumentNames = await Task.WhenAll(documentPaths.Select(async path =>
                {
                    var compressedPath = $"{Guid.NewGuid()}.7z";
                    var compressResult = await CompressFileAsync(path, archiveWriter, compressedPath);
                    if (!compressResult.Success) return (UploadStatus.Failed, default);
                    results[path] = (UploadStatus.Compressed, compressResult.Size);
                    return (UploadStatus.ReadyForUpload, compressResult.Size);
                }));

                var metadataJson = JsonSerializer.Serialize(compressedDocumentNames.Where(x => x.Item1 == UploadStatus.ReadyForUpload).ToDictionary(x => x.Key, x => new { Status = x.Item2.Item1, Size = x.Item2.Item2 }));
                await UploadFileAsync($"metadata.json", metadataJson, _bucketName);
            }

            var uploadTasks = compressedDocumentNames.Where(x => x.Item1 == UploadStatus.ReadyForUpload).Select(async x => await UploadFileAsync(x.Key, x.Value, _bucketName));
            var uploadResults = await Task.WhenAll(uploadTasks);
            foreach (var (path, result) in compressedDocumentNames)
                results[path] = (result ? UploadStatus.Uploaded : UploadStatus.Failed, results[path].Item2);

            return results;
        }

        private struct CompressResult
        {
            public bool Success { get; set; }
            public long Size { get; set; }
        }

        private async Task<CompressResult> CompressFileAsync(string filePath, ArchiveWriter archiveWriter, string outputFilePath)
        {
            try
            {
                using var inputFileStream = File.OpenRead(filePath);
                using var outputFileStream = new FileStream(outputFilePath, FileMode.CreateNew);
                await archiveWriter.WriteFileAsync(inputFileStream, outputFileStream, null);
                return new CompressResult { Success = true, Size = new FileInfo(filePath).Length };
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error while compressing file: {ex}");
                return new CompressResult { Success = false };
            }
        }

        private async Task UploadFileAsync(string fileName, byte[] content, string bucketName)
        {
            var uploadRequest = new PutObjectRequest
            {
                BucketName = bucketName,
                Key = fileName,
                ContentBody = content,
                ContentType = MimeMapping.GetMimeType(fileName)
            };
            try
            {
                await _s3Client.PutObjectAsync(uploadRequest);
            }
            catch (AmazonS3Exception ex) when (ex.ErrorCode == S3Error.NoSuchBucket)
            {
                Console.WriteLine($"The bucket specified does not exist.");
            }
        }
    }
}
```

