namespace FileProcessingLibrary
{
    public class DecryptAndHashFile
    {
        private const int BufferSize = 64 * 1024; // 64KB buffer size for efficient I/O operations
        private readonly TripleDESCryptoServiceProvider _tripleDES;
        private readonly MD5 _md5Hasher;
        private readonly byte[] _key;
        private readonly byte[] _iv;
        private Stream _loggingStream;

        public DecryptAndHashFile(byte[] key, byte[] iv)
        {
            _tripleDES = new TripleDESCryptoServiceProvider();
            _md5Hasher = MD5.Create();
            _key = key;
            _iv = iv;
        }

        public async Task<(string DecryptedMessage, string Md5Hash)> DecryptAndHashFileAsync(string base64EncodedMessage, string filePath)
        {
            var decryptedMessage = DecryptBase64(base64EncodedMessage);
            var md5Hash = await ComputeMd5HashAsync(filePath);

            if (_loggingStream != null)
            {
                await WriteToLoggingStreamAsync($"DecryptedMessage: {decryptedMessage}\nMD5Hash: {md5Hash}");
            }

            return (decryptedMessage, md5Hash);
        }

        private byte[] DecryptBase64(string base64Encoded) => Convert.FromBase64String(base64Encoded);

        private async Task<string> ComputeMd5HashAsync(string filePath)
        {
            using var fileStream = File.OpenRead(filePath);
            var md5HashBuilder = new StringBuilder();
            byte[] buffer = new byte[BufferSize];

            while (true)
            {
                var readBytes = await fileStream.ReadAsync(buffer, 0, buffer.Length);
                if (readBytes == 0) break;
                _md5Hasher.TransformBlock(buffer, 0, readBytes, _);
            }

            _md5Hasher.TransformFinalBlock(_md5Hasher.HashValue.Take(16).ToArray(), 0, 16);
            md5HashBuilder.Append(BitConverter.ToString(_md5Hasher.HashValue).Replace("-", ""));
            return md5HashBuilder.ToString();
        }

        public void SetLoggingStream(Stream loggingStream) => _loggingStream = loggingStream;
    }
}
