public class MD5Hasher
{
    private readonly Dictionary<string, byte[]> _cache = new ConcurrentDictionary<string, byte[]>();
    private readonly HttpClient _httpClient;
    private readonly Stopwatch _stopwatch = new Stopwatch();

    public MD5Hasher()
    {
        _httpClient = new HttpClient();
    }

    public async Task<byte[]> ComputeHashAsync(string input)
    {
        if (_cache.TryGetValue(input, out var cachedHash))
            return cachedHash;

        _stopwatch.Start();
        byte[] hash = CalculateMD5Hash(input);
        _stopwatch.Stop();

        await SendLogAsync(input.Length, _stopwatch.ElapsedMilliseconds);

        _cache[input] = hash;

        return hash;
    }

    private byte[] CalculateMD5Hash(string input)
    {
        using var md5 = MD5.Create();
        return md5.ComputeHash(Encoding.ASCII.GetBytes(input));
    }

    private async Task SendLogAsync(int inputLength, int processingDuration)
    {
        try
        {
            var logPayload = new
            {
                Timestamp = DateTimeOffset.Now,
                InputLength = inputLength,
                ProcessingDuration = processingDuration
            };
            var json = JsonConvert.SerializeObject(logPayload);

            await _httpClient.PostAsJsonAsync("https://your-logging-service-url", logPayload);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error sending log: {ex.Message}");
        }
    }
}
