using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace AesDecryption
{
    public static class AesDecryptor
    {
        private const string PaddingScheme = "PKCS7";

        public static async Task<byte[]> DecryptAsync(byte[] cipherText, byte[] key, byte[] iv, PadMode paddingMode = PadMode.PKCS7)
        {
            try
            {
                using (var aes = Aes.Create())
                {
                    aes.Key = key;
                    aes.IV = iv;

                    if (aes.KeySize != 128 && aes.KeySize != 256)
                        throw new ArgumentException("Invalid AES key size.");

                    var cryptoTransform = aes.CreateDecryptor(aes.Key, aes.IV);
                    using (var ms = new MemoryStream(cipherText))
                    {
                        using (var cs = new CryptoStream(ms, cryptoTransform, CryptoStreamMode.Read))
                        {
                            var decryptedBytes = await cs.ToArrayAsync();
                            return DecryptPaddedData(decryptedBytes, paddingMode);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Decryption failed: {ex.Message}");
                throw;
            }
        }

        private static byte[] DecryptPaddedData(byte[] encrypted, PadMode padding)
        {
            if (!EncryptDecryptHelper.IsValidPadding(encrypted, padding))
                throw new ArgumentException($"Invalid padding mode for the provided data.");

            var paddingSize = EncryptDecryptHelper.GetPaddingSizeFromBytes(encrypted, padding);
            return encrypted.Take(encrypted.Length - paddingSize).ToArray();
        }
    }

    public static class EncryptDecryptHelper
    {
        public static bool IsValidPadding(byte[] data, PadMode mode)
        {
            if (data.Last() != GetPaddingValue(mode))
                return false;

            var unpaddedData = data[..^1];
            return (unpaddedData.Length % GetBlockSize(mode)) == 0;
        }

        public static int GetPaddingSizeFromBytes(byte[] data, PadMode mode) => GetPaddingValue(mode) - data[data.Length - 1];

        private static int GetBlockSize(PadMode mode)
            => mode switch
            {
                PadMode.PKCS7 => 8,
                _ => throw new NotSupportedException($"Unsupported padding scheme: {mode}")
            };

        private static byte GetPaddingValue(PadMode mode) => (byte)(GetBlockSize(mode) - 1);
    }
}
```

This code provides an `AesDecryptor.DecryptAsync` function that takes a ciphertext, encryption key, and IV as parameters. It returns the decrypted plaintext as a byte array. The function handles different block sizes and padding schemes effectively by using PKCS7 padding and checks for its validity before decrypting the data.

The function supports decryption of messages that were encrypted using both 128-bit and 256-bit keys, as indicated by the key size check in the `Aes.Create()` method. If an invalid key size is provided, it will throw an exception with a detailed error message.

The function also logs error messages if any decryption fails, specifying the exact nature of the failure (e.g., invalid key size, incorrect padding). Lastly, it handles large ciphertexts efficiently by using MemoryStream and CryptoStream to minimize memory allocation issues.']

