        // Initialize Node.js server with proper arguments, such as the script execution port
        ProcessBuilder builder = new ProcessBuilder("node", "-e", "executeJavaScript('path/to/script1.js', 'path/to/script2.js')");
        Process process = builder.start();

        // Wait for the Node.js server to finish its execution and collect the output
        int exitValue = process.waitFor();
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
