const { exec } = require('child_process');
const log = console.log;

function executeShellCommand(cmd, callback) {
  if (!cmd || typeof cmd !== 'string') {
    throw new Error('Invalid command. Command must be a non-empty string.');
  }

  exec(cmd, (error, stdout, stderr) => {
    if (error) {
      log(`Error executing command: ${error.message}`);
      callback(new Error(`Error executing command: ${error.message}`));
    } else {
      log(`Command output:\n${stdout}`);
      log(`Command error:\n${stderr}`);
      if (stderr) {
        callback(new Error(`Command error: ${stderr}`));
      } else {
        callback(null, stdout); // If no error, pass the command's output as second argument to callback
      }
    }
  });
}
