import java.util.*;
import com.example.GraphDatabase;
import com.example.Vertex;
import com.example.Edge;
import com.example.RetryPolicy;
import com.example.LoadPatternAnalyzer;

public class GraphWriter {
    private final GraphDatabase db;
    private final RetryPolicy retryPolicy;
    private final LoadPatternAnalyzer loadPatternAnalyzer;

    public GraphWriter(GraphDatabase db, RetryPolicy retryPolicy, LoadPatternAnalyzer loadPatternAnalyzer) {
        this.db = db;
        this.retryPolicy = retryPolicy;
        this.loadPatternAnalyzer = loadPatternAnalyzer;
    }

    public void addVertex(String id, String label, Map<String, Object> properties) {
        Vertex vertex = new Vertex(id, label, properties);
        int retriesLeft = retryPolicy.getRetries();

        while (retriesLeft > 0 && db.isOperationFailed(vertex.save())) {
            logEvent("Vertex save failed, retrying...");
            --retriesLeft;
            try {
                Thread.sleep(retryPolicy.getSleepInterval());
            } catch (InterruptedException e) {
                logEvent("Interrupted while waiting for retries.");
                throw new RuntimeException(e);
            }
        }

        if (retriesLeft == 0 && db.isOperationFailed(vertex.save())) {
            logEvent("Vertex save failed after all retries, giving up.");
            throw new RuntimeException("Vertex save failed after all retries");
        }
    }

    public void addEdge(String fromId, String toId, String label, Map<String, Object> properties) {
        Vertex from = db.getVertexById(fromId);
        Vertex to = db.getVertexById(toId);

        Edge edge = new Edge(from, to, label, properties);
        int retriesLeft = retryPolicy.getRetries();

        while (retriesLeft > 0 && db.isOperationFailed(edge.save())) {
            logEvent("Edge save failed, retrying...");
            --retriesLeft;
            try {
                Thread.sleep(retryPolicy.getSleepInterval());
            } catch (InterruptedException e) {
                logEvent("Interrupted while waiting for retries.");
                throw new RuntimeException(e);
            }
        }

        if (retriesLeft == 0 && db.isOperationFailed(edge.save())) {
            logEvent("Edge save failed after all retries, giving up.");
            throw new RuntimeException("Edge save failed after all retries");
        }
    }

    public void adjustVertexCount(int threshold) {
        int currentCount = db.getVertexCount();
        if (currentCount > threshold) {
            int verticesToRemove = currentCount - threshold;
            List<Vertex> verticesToDelete = new ArrayList<>(verticesToRemove);
            for (int i = 0; i < verticesToRemove; ++i) {
                Vertex vertexToDelete = db.randomVertex();
                vertexToDelete.delete();
            }
        } else if (currentCount < threshold) {
            int verticesToAdd = threshold - currentCount;
            for (int i = 0; i < verticesToAdd; ++i) {
                String id = UUID.randomUUID().toString();
                addVertex(id, "default", new HashMap<>());
            }
        }
    }

    public void adjustEdgeCount(int threshold) {
        int currentCount = db.getEdgeCount();
        if (currentCount > threshold) {
            int edgesToRemove = currentCount - threshold;
            List<Edge> edgesToDelete = new ArrayList<>(edgesToRemove);
            for (int i = 0; i < edgesToRemove; ++i) {
                Edge edgeToDelete = db.randomEdge();
                edgeToDelete.delete();
            }
        } else if (currentCount < threshold) {
            int edgesToAdd = threshold - currentCount;
            for (int i = 0; i < edgesToAdd; ++i) {
                String fromId = db.getRandomVertex().getId();
                String toId = db.getRandomVertex().getId();
                addEdge(fromId, toId, "default", new HashMap<>());
            }
        }
    }

