[' Here is a simple structure for your Rust program using Tokio and structuring tasks as modules. I will provide the skeleton code for Task1, Task2, Task3, and the main function. Note that this code does not include error handling and debug logging, which you can implement according to your needs.

```rust
// Cargo.toml
[dependencies]
tokio = { version = "1", features = ["full"] }
tokio-util = { version = "0.7", features = ["threadpool"] }
thiserror = "1"

// main.rs
use std::env;
use tokio::task::spawn;
use tokio::sync::RwLock;
use tokio_util::sync::CancellationToken;
use thiserror::Error;

mod task1;
mod task2;
mod task3;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <task_id>", args[0]);
        return Ok(());
    }

    let mut task_pool = tokio::sync::RwLock::new(Vec::new());
    let mut cancellations = Vec::with_capacity(10);
    let token_manager = CancellationToken::new().unwrap();

    for i in 0..10 {
        if i == args[1].parse::<usize>().unwrap() {
            spawn_task(i, &mut *task_pool.write().await, &token_manager).await?;
        }
    }

    loop {
        tokio::select! {
            res = task_pool.read().await.pop() => {
                match res {
                    Some(task) => spawn_task(task.id, &mut *task_pool.write().await, &token_manager).await?,
                    None => break,
                }
            },
            _ = token_manager.cancelled() => break,
        }
    }

    Ok(())
}

async fn spawn_task(id: usize, task_pool: &mut Vec<Box<dyn Task + Send + Sync>, token: &CancellationToken) {
    let mut task = match id {
        1 => Box::new(task1::Task{}),
        2 => Box::new(task2::Task{}),
        3 => Box::new(task3::Task{}),
        _ => return,
    };

    if !task.validate_input().await? {
        eprintln!("Error in task {}: {}", id, task.error_message());
        return;
    }

    let handle = tokio::spawn(async move { task.run().await });
    task_pool.push(handle);
}
```

The individual tasks (Task1, Task2, and Task3) should implement the `Task` trait as follows:

```rust
pub trait Task: Send + Sync {
    async fn validate_input(&self) -> Result<(), Error>;
    async fn run(&self) -> Result<(), Error>;
    fn error_message(&self) -> &'static str;
}
```']

