["```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>
#include <netinet/in.h>

// Custom PacketMetadata structure
typedef struct {
    uint64_t id;
    time_t timestamp;
    struct sockaddr_in source, destination;
    size_t payload_size;
} PacketMetadata;

// Global variables for concurrent access synchronization
pthread_mutex_t metadata_lock = PTHREAD_MUTEX_INITIALIZER;
struct LinkedList *metadata_list = NULL; // Doubly-linked list of packet metadata
extern Logger *logger; // External logging service pointer (assume it's defined elsewhere)

// Function to initialize a new PacketMetadata structure and add it to the linked list
void enqueue_packet(PacketMetadata pkt) {
    PacketMetadata *new_node = malloc(sizeof(PacketMetadata));
    if (!new_node) return; // Exit gracefully if we can't allocate memory

    memcpy(new_node, &pkt, sizeof(PacketMetadata));
    new_node->next = metadata_list;
    new_node->prev = NULL;

    if (metadata_list) {
        metadata_list->prev = new_node;
        metadata_list = new_node;
    } else {
        metadata_list = new_node;
    }
}

// Function to safely dequeue and free a packet metadata node from the linked list
void dequeue_packet(PacketMetadata *pkt) {
    pthread_mutex_lock(&metadata_lock);

    if (!metadata_list) {
        pthread_mutex_unlock(&metadata_lock);
        return;
    }

    if (metadata_list == pkt) { // If we're removing the head of the list
        metadata_list = metadata_list->next;
        if (metadata_list) metadata_list->prev = NULL;
    } else { // Otherwise, find and remove a specific node
        PacketMetadata *current = metadata_list;
        while (current && current != pkt) {
            current = current->next;
        }

        if (!current) {
            pthread_mutex_unlock(&metadata_lock);
            return;
        }

        if (current == metadata_list) { // If we're removing the head of the list
            metadata_list = metadata_list->next;
            metadata_list->prev = NULL;
        } else {
            current->prev->next = current->next;
            if (current->next) current->next->prev = current->prev;
        }
    }

    free(pkt);
    pthread_mutex_unlock(&metadata_lock);
}

// Function to log a packet metadata entry
void log_packet(PacketMetadata pkt) {
    if (logger) logger->log_packet(pkt); // Delegate logging to the external service
}
```

Note that this code is a basic implementation of a concurrent, high-performance packet metadata management system using a doubly-linked list and mutex for synchronization. To optimize for memory usage, consider using a pack struct or an array of packed fields. For handling network anomalies, you could use input validation functions to filter out invalid packets. Lastly, ensure your external logging service can handle high concurrency during peak network traffic periods."]

