typedef struct Record {
    int value;
    const int *key;
    const char *label;
} Record;

struct Storage {
    long *offsets;
    int *keys;
    char *labels;
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

void initStorage(struct Storage *storage, size_t capacity) {
    storage->offsets = calloc(capacity + 1, sizeof(long));
    storage->keys = malloc(capacity * sizeof(int));
    storage->labels = malloc((capacity + 1) * sizeof(char));
    storage->records = malloc(capacity * sizeof(Record));
    storage->capacity = capacity;
    storage->count = 0;
    pthread_mutex_init(&storage->mutex, NULL);
}

void destroyStorage(struct Storage *storage) {
    free(storage->offsets);
    free(storage->keys);
    free(storage->labels);
    free(storage->records);
    pthread_mutex_destroy(&storage->mutex);
}

void addRecord(struct Storage *storage, int key, const char *label) {
    pthread_mutex_lock(&storage->mutex);

    if (storage->count >= storage->capacity) {
        fprintf(stderr, "Out of memory\n");
        pthread_mutex_unlock(&storage->mutex);
        return;
    }

    long *offset = storage->offsets + storage->count;
    int *recordKey = storage->keys + storage->count;
    char *recordLabel = storage->labels + storage->count;

    *offset = *storage->offsets++;
    *recordKey = key;
    *recordLabel = *label;
    storage->records[storage->count].value = rand() % 1000000;
    storage->records[storage->count++].key = recordKey;
    storage->records[storage->count - 1].label = recordLabel;

    pthread_mutex_unlock(&storage->mutex);
}

// Replace this with the actual interaction function with the external data source
void updateRecords(struct Storage *storage) { /* ... */ }

int main() {
    struct Storage storage;
    initStorage(&storage, 10000000);

    // Seed random number generator with current time for reproducible results
    srand((unsigned int)time(NULL));

    // Add records concurrently using threads
    pthread_t threads[10];
    for (size_t i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, (void*(*)(void*))&addRecord, &storage);
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    updateRecords(&storage);

    destroyStorage(&storage);

    return 0;
}
