[' Here's a Java implementation of the requested method using Apache Commons Codec for hashing and Log4j2 for logging:

```java
import org.apache.commons.codec.digest.DigestUtils;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import java.security.NoSuchAlgorithmException;
import java.util.Objects;

public class HashingUtil {
    private static final Logger LOGGER = LogManager.getLogger(HashingUtil.class);

    public static String hash(String input, AlgorithmType algorithmType) throws InvalidInputLengthException {
        if (Objects.isNull(input) || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty");
        }

        int minLength = algorithmType == AlgorithmType.SHA_256 ? 32 : DigestUtils.getMd5HashLength();
        if (input.length() < minLength) {
            throw new InvalidInputLengthException("Invalid input length: " + input.length());
        }

        try {
            switch (algorithmType) {
                case MD5:
                    return DigestUtils.md5Hex(input);
                case SHA_256:
                    return DigestUtils.sha256Hex(input);
                default:
                    throw new IllegalArgumentException("Unsupported algorithm type");
            }
        } catch (NoSuchAlgorithmException e) {
            LOGGER.error("Error occurred while hashing input: {}", e.getMessage());
            throw new RuntimeException(e);
        }
    }

    private enum AlgorithmType {
        MD5, SHA_256
    }

    public static class InvalidInputLengthException extends Exception {
        public InvalidInputLengthException(String message) {
            super(message);
        }
    }
}
