typedef enum { AES, CAMELLIA, MD5, SHA256, RSA_SHA256 } Algorithm;

typedef struct CryptoContext {
    Algorithm algorithm;
    void* ctx; // Context-specific data
} CryptoContext;

CryptoContext* create_crypto_context(Algorithm algorithm) {
    switch (algorithm) {
        case AES:
            return aes_create_context();
        case CAMELLIA:
            return camellia_create_context();
        // Add more algorithms as needed
        default:
            fprintf(stderr, "Unsupported algorithm.\n");
            return NULL;
    }
}

void free_crypto_context(CryptoContext* ctx) {
    if (ctx == NULL) return;

    switch (ctx->algorithm) {
        case AES:
            aes_free_ctx((AES_KEY*)ctx->ctx);
            break;
        case CAMELLIA:
            camellia_free_key((Camellia_KEY *) ctx->ctx);
            break;
        // Add more algorithms as needed
        default:
            break;
    }
    free(ctx);
}

int crypto_encrypt(const unsigned char* key, const unsigned char* iv,
                   const unsigned char* data, size_t length,
                   CryptoContext* ctx, unsigned char* encrypted) {
