public class DynamicValueSimulator
{
    private readonly ObjectCache _cache = MemoryCache.Default;
    private Random _random;
    private string _seed;
    private bool _isInclusive;
    private double _minValue, _maxValue;
    private Dictionary<string, List<(double value, double weight)>> _weightConfigurations;

    public DynamicValueSimulator(double minValue, double maxValue, bool isInclusive = true, string seed = null)
    {
        _minValue = minValue;
        _maxValue = maxValue;
        _isInclusive = isInclusive;
