            _cache.Add(key, _weightConfigurations, CacheItemPolicy.RefreshOnRemove);
        }
    }

    public T GenerateValue<T>(Func<double, T> convertFunction) where T : struct
    {
        ValidateBounds();

        if (_isInclusive)
        {
            var range = _maxValue - _minValue;
            return convertFunction((_random.NextDouble() * range) + _minValue);
        }
        else
        {
            var range = _maxValue - _minValue + 1;
            return convertFunction((_random.NextDouble() * range) + _minValue + 1);
        }
    }

    public T GenerateWeightedValue<T>(Func<double, T> convertFunction, string key = null) where T : struct
    {
        ValidateBounds();

        if (_weightConfigurations.TryGetValue(key, out var values))
        {
            var totalWeight = values.Sum(v => v.weight);
            var randomWeight = _random.NextDouble() * totalWeight;

            foreach (var valueAndWeight in values)
            {
                if (randomWeight <= valueAndWeight.weight)
                    return convertFunction(valueAndWeight.value);

                randomWeight -= valueAndWeight.weight;
            }
        }

        throw new InvalidOperationException("No valid weight configurations found for the specified key.");
    }

    private void ValidateBounds()
    {
        if (_minValue > _maxValue) throw new ArgumentOutOfRangeException(nameof(_minValue), "Minimum value must be smaller than maximum value.");
    }

    public void ResetGeneratorState()
    {
        _random = new Random(GenerateSeed(_seed));
    }

    public override string ToString()
    {
        return $"DynamicValueSimulator{{ Range={_minValue}-{_maxValue}, Seed={_seed} }}";
    }
}
```']

