            LOGGER.addHandler(handler);

            // Hash processing and logging
            for (int i = 0; i < hashBytes.length; ++i) {
                int value = hashBytes[i] & 0xFF;
                if (value < 16) {
                    LOGGER.log(Level.INFO, "Value: {0}, Hexadecimal: {1}", new Object[]{value, Integer.toHexString(value)});
                } else {
                    LOGGER.log(Level.FINE, "Value: {0}, Hexadecimal: {1}", new Object[]{value, Integer.toHexString(value)});
                }
            }

            return bytesToHex(hashBytes);
        } catch (NoSuchAlgorithmException e) {
            LOGGER.log(Level.SEVERE, "Error during hashing: {0}", e.getMessage());
            throw e;
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; ++i) {
            sb.append(String.format("%02x", bytes[i]));
        }
        return sb.toString();
    }

    static class InvalidInputLengthException extends Exception {
        public InvalidInputLengthException(String message) {
            super(message);
        }
    }

    // Octree implementation omitted for brevity
}
