import re
import time
from typing import Dict, Any, List
import concurrent.futures
import gzip

class MemoryChunk:
    def __init__(self, size):
        self.data = {}
        self.size_limit = size
        self.chunk_size = 0

    def add(self, key: str, value: Any) -> None:
        if len(self.data[key]) + len(str(value)) > self.size_limit - self.chunk_size:
            self._trim()
        self.data[key] += str(value) + " "
        self.chunk_size += len(str(value)) + 1

    def _trim(self):
        for key, value in self.data.items():
            if value[:self.size_limit] == value:
                self.data[key] = value[:self.size_limit]
                break
        self.data = {k: v for k, v in self.data.items() if v and len(v) > self.size_limit}

class LogProcessor:
    def __init__(self, buffer_size=1024 * 16):
        self.buffer = MemoryChunk(buffer_size)
        self.metrics = {}
        self.log_formats = {
            "format1": re.compile(r"^(\[.*\]) (?P<metric>[a-zA-Z0-9_]+): (?P<value>\d+(\.\d+)?|[a-zA-Z0-9_]+)$"),
            "format2": re.compile(r"^(?P<level>.*) (?P<timestamp>[\w:- ]+) (?P<message>.*)$")
        }

    def process_log(self, log_data: str) -> None:
        for format in self.log_formats:
            match = self.log_formats[format].finditer(log_data)
            if match:
                for group in match:
                    if group.lastgroup == "message":
                        self.buffer.add("message", group.group("message"))
                    elif group.lastgroup == "metric":
                        self._parse_metric(group.group("metric"), group.group("value"))
                break

    def _parse_metric(self, metric: str, value: str) -> None:
        if metric not in self.metrics:
            self.metrics[metric] = MemoryChunk(1024 * 4)
        self.metrics[metric].add(value)

    def aggregate(self) -> Dict[str, List[Any]]:
        aggregated_metrics = {}
        for metric, chunk in self.metrics.items():
            aggregated_metrics[metric] = [float(v.split()[0]) for v in chunk.data.split()]
        return aggregated_metrics

    def analyze(self) -> None:
        start_time = time.monotonic()
        chunks = concurrent.futures.ThreadPoolExecutor().map(self.process_log, self.read_logs())
        for _ in chunks:
            pass
        aggregated_metrics = self.aggregate()
        elapsed_time = time.monotonic() - start_time
        print(f"Elapsed time: {elapsed_time} seconds")
        print("Aggregated metrics:", aggregated_metrics)

    def read_logs(self) -> List[str]:
        log_files = ["log1.txt", "log2.gz"]  # Add your list of log files here
        for file in log_files:
            if file.endswith(".gz"):
                with gzip.open(file, "rt") as f:
                    for line in f:
                        yield line
            else:
                with open(file, "r") as f:
                    for line in f:
                        yield line
```

This code defines a `LogProcessor` class that processes log files containing different data schemas and log levels. It handles large files by processing data in memory-efficient chunks. The `process_log()` method is responsible for parsing the logs based on predefined formats, and the `aggregate()` method aggregates the metrics for performance analysis.

The provided code reads both compressed (gzip) and uncompressed log files, processes them concurrently using threading, and optimizes for memory efficiency. It balances real-time processing needs with long-term storage requirements by implementing a chunked buffer approach. The `analyze()` method demonstrates how to call the necessary functions to process the logs and aggregate the metrics.']

