import org.apache.commons.io.FileUtils;
import java.io.File;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ConcurrentMap;
import java.util.concurrent.ConcurrentHashMap;

public class MD5Hasher {
    private static final ConcurrentMap<String, BigInteger> cache = new ConcurrentHashMap<>();

    public static BigInteger hashFile(String filePath) throws NoSuchAlgorithmException, IOException {
        File file = new File(filePath);
        byte[] data = FileUtils.readFileToByteArray(file);

        MessageDigest digest = MessageDigest.getInstance("MD5");
        digest.update(data);
        BigInteger hash = new BigInteger(1, digest.digest());

        if (cache.containsKey(hash.toString())) {
            return cache.get(hash.toString());
        } else {
            cache.putIfAbsent(hash.toString(), hash);
            return hash;
        }
    }
}
```

