```java
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Collections;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class IdentifierGenerator {
    private final MessageDigest digest;
    private final ConcurrentHashMap<String, String> cache;

    public IdentifierGenerator() throws NoSuchAlgorithmException {
        this.digest = MessageDigest.getInstance("SHA-256");
        this.cache = new ConcurrentHashMap<>();
    }

    public String generateIdentifier(String metadata) {
        if (cache.containsKey(metadata)) {
            return cache.get(metadata);
        }

        byte[] hash = digest.digest(metadata.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hash) {
            sb.append(String.format("%02x", b));
        }

        String id = sb.toString();
        cache.putIfAbsent(metadata, id);

        return id;
    }

    // Load metadata from an external data source (e.g., CSV file)
    public void loadMetadata() {
        Executors.newSingleThreadExecutor().submit(() -> {
            try {
                String metadata = new String(Files.readAllBytes(Paths.get("/path/to/metadata.csv")));
                generateIdentifier(metadata);
            } catch (IOException e) {
                System.err.println("Error while loading metadata: " + e.getMessage());
            }
        });
    }
}
```

The `generateIdentifier()` method takes a string as input, generates an SHA-256 hash of the given metadata, and stores it in a concurrent cache to avoid redundant generation for duplicate inputs. The caching mechanism ensures thread safety when used concurrently by multiple users.

The `loadMetadata()` method reads data from an external source (CSV file in this case) asynchronously, allowing high-throughput applications to handle thousands of requests per second without degradation in performance.']

