typedef struct {
    uint64_t id;
    time_t timestamp;
    char src_ip[INET6_ADDRSTRLEN];
    char dst_ip[INET6_ADDRSTRLEN];
    size_t payload_size;
    enum { LOW, MEDIUM, HIGH } priority;
} PacketMetadata;

struct LoggingService {
    void* logging_data;
    void (*log)(void*, const PacketMetadata*);
    char* log_url; // for remote logging
};

typedef struct ThreadSafeQueue {
    PacketMetadata** data;
    size_t capacity;
    size_t head;
    size_t tail;
    pthread_mutex_t mutex;
} ThreadSafeQueue;

void tsq_init(ThreadSafeQueue* q, size_t capacity) {
    q->data = malloc(capacity * sizeof(PacketMetadata*));
    q->capacity = capacity;
    q->head = q->tail = 0;
    pthread_mutex_init(&q->mutex, NULL);
}

void tsq_push(ThreadSafeQueue* q, PacketMetadata* item) {
    pthread_mutex_lock(&q->mutex);
    while (q->head == (q->tail + 1) % q->capacity)
        pthread_cond_wait(&q->mutex, &q->mutex);
    q->data[q->tail] = item;
    q->tail = (q->tail + 1) % q->capacity;
    pthread_mutex_unlock(&q->mutex);
}

PacketMetadata* tsq_pop(ThreadSafeQueue* q) {
    PacketMetadata* res;
    pthread_mutex_lock(&q->mutex);
    while (q->head == q->tail)
        pthread_cond_wait(&q->mutex, &q->mutex);
    res = q->data[q->head];
    q->head = (q->head + 1) % q->capacity;
    pthread_mutex_unlock(&q->mutex);
    return res;
}

// External logging service interface functions
