        db_(dbPath), queue_(queueName), archiveThreshold_(archiveThreshold), server_(io_, tcp::endpoint(tcp::v4(), port)) {
        doAccept();
    }

    void enqueue(const LogEntry& entry) {
        new (&queue_.push_back()) LogEntry(entry);
    }

    void query(const std::string& key, std::function<void(const LogEntry&)> callback) {
        auto it = db_.find(key);
        if (it != db_.end())
            callback(*it->second);
    }

    void archive() {
        auto now = std::chrono::system_clock::now().time_since_epoch().count();
        for (auto it = db_.begin(); it != db_.end(); ) {
            if (it->second->timestamp + archiveThreshold_ < now) {
                it = db_.erase(it);
                // Archive the log entry to a secondary storage system here.
            } else {
                ++it;
            }
        }
    }

private:
    void doAccept() {
        acceptor_.async_accept([this](boost::system::error_code ec, tcp::socket socket) {
            if (!ec) {
                std::make_shared<LogEntryHandler>(std::move(socket), this->queue_, this->db_)->start();
                doAccept();
            }
        });
    }

    boost::asio::io_context io_;
    tcp::acceptor acceptor_;
    boost::lockfree::queue<LogEntry, boost::lockfree::capacity_policy<>> queue_;
    std::unordered_map<std::string, std::unique_ptr<LogEntry>> db_;
    const size_t archiveThreshold_;
    int port_;
};

class LogEntryHandler : public std::enable_shared_from_this<LogEntryHandler> {
public:
    LogEntryHandler(tcp::socket socket, boost::lockfree::queue<LogEntry, boost::lockfree::capacity_policy<>>& queue, std::unordered_map<std::string, std::unique_ptr<LogEntry>>& db) :
        socket_(std::move(socket)), queue_(queue), db_(db) {}

    void start() {
        boost::asio::async_read(*this->socket_, buffer_, [this](boost::system::error_code ec, std::size_t /*length*/) {
            if (!ec) {
                auto entry = LogEntry::Deserialize(buffer_.data());
                queue_.push_back(entry);
                processRequest();
            }
        });
    }

    void processRequest() {
        // Send a response back to the client, and query/aggregate metrics here.
    }

private:
    tcp::socket socket_;
    boost::lockfree::queue<LogEntry, boost::lockfree::capacity_policy<>>& queue_;
    std::unordered_map<std::string, std::unique_ptr<LogEntry>>& db_;
};
```

