public class HashUtil {
    private static final Logger LOGGER = Logger.getLogger(HashUtil.class.getName());
    private static final int SHA_256_MIN_LENGTH = 32;

    public static String hash(String input, String algorithm, Logger logger) throws Exception {
        if (input == null || input.isEmpty()) {
            throw new InvalidInputException("Input cannot be null or empty.");
        }

        MessageDigest md;
        Cipher cipher;
        SecretKeySpec key;

        switch (algorithm.toLowerCase()) {
            case "md5":
                md = MessageDigest.getInstance("MD5");
                break;
            case "sha-256":
                if (input.length() < SHA_256_MIN_LENGTH) {
                    throw new InvalidInputException("Input length must be at least " + SHA_256_MIN_LENGTH + " bytes for SHA-256.");
                }
                md = MessageDigest.getInstance("SHA-256");
                break;
            default:
                throw new UnsupportedAlgorithmException("Unsupported algorithm: " + algorithm);
        }

        md.update(input.getBytes());
        byte[] digest = md.digest();

        if (algorithm.equalsIgnoreCase("sha-256")) {
            // Convert the byte array to a hexadecimal string for easier handling
            StringBuilder hashedHex = new StringBuilder(2 * digest.length);
            for (byte b : digest) {
                hashedHex.append(String.format("%02x", b));
            }
            digest = hashedHex.toString().getBytes();
        }

        // Integrate with an external authentication service (assuming a custom Authenticator class exists)
        String authenticatedHash = Authenticator.hashWithAuthentication(digest);

        return authenticatedHash;
    }

