['```java
import java.io.File;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.List;
import java.util.concurrent.*;

public class HashCalculator {
    private final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public List<String> calculateSha256Hashes(List<String> filePaths) throws InterruptedException, ExecutionException {
        List<Future<String>> futures = executor.invokeAll(createCallableTasks(filePaths));
        return futures.stream().map(future -> future.get()).collect(Collectors.toList());
    }

    private List<Callable<String>> createCallableTasks(List<String> filePaths) {
        return filePaths.stream()
                .map(this::createCallableTask)
                .collect(Collectors.toList());
    }

    private Callable<String> createCallableTask(String filePath) {
        return () -> {
            try {
                File file = new File(filePath);
                byte[] fileHash = MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(file.toPath()));
                return Base64.getEncoder().encodeToString(fileHash);
            } catch (Exception e) {
                e.printStackTrace();
                throw new RuntimeException(e);
            }
        };
    }
}
