#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct PortStatus {
    int PORT_NUMBER;
    char STATE; // 'O' for open, 'C' for closed
    time_t LAST_CONNECTION_TIME;
} PortStatus;

typedef struct NetworkInterfaceStatus {
    char IP_ADDRESS[INET_ADDRSTRLEN];
    char SUBNET_MASK[INET_ADDRSTRLEN];
    char DEFAULT_GATEWAY[INET_ADDRSTRLEN];
    List* PORTS; // List of PortStatus structures
} NetworkInterfaceStatus;

typedef struct ListNode {
    PortStatus data;
    struct ListNode *next;
} ListNode;

struct List {
    int size;
    ListNode* head;
    pthread_mutex_t mutex;
};

List* create_list() {
    List* list = malloc(sizeof(List));
    list->size = 0;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void add_to_list(List* list, PortStatus data) {
    ListNode* new_node = malloc(sizeof(ListNode));
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        ListNode* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

PortStatus* remove_from_list(List* list, int port_number) {
    PortStatus* data = NULL;
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        if (current->data.PORT_NUMBER == port_number) {
            data = &current->data;
            if (current->next == NULL) {
                list->head = NULL;
            } else {
                ListNode* temp = current;
                current = current->next;
                free(temp);
            }
            list->size--;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return data;
}

void update_port_status(List* list, int port_number, PortStatus new_state) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        if (current->data.PORT_NUMBER == port_number) {
            current->data = new_state;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

NetworkInterfaceStatus* create_network_interface(char* ip_address, char* subnet_mask, char* default_gateway) {
    NetworkInterfaceStatus* network_interface = malloc(sizeof(NetworkInterfaceStatus));
    strcpy(network_interface->IP_ADDRESS, ip_address);
    strcpy(network_interface->SUBNET_MASK, subnet_mask);
    strcpy(network_interface->DEFAULT_GATEWAY, default_gateway);
    network_interface->PORTS = create_list();
    return network_interface;
}
