import re
import sys
from typing import List

def sortFileAndExtractSequence(file_path: str) -> int or None:
    try:
        with open(file_path, 'r') as f:
            lines = sorted(f.readlines(), key=lambda line: line.split()[0])

        sequence = re.search(r'Sequence\s+(\d+)', lines[-1]).group(1)
        return int(sequence) if sequence else None
    except IOError as e:
        print(f"Error reading file: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error occurred: {e}")
