typedef struct {
    EVP_CIPHER *cipher;
    int mode;
} CipherStruct;

CipherStruct select_cipher(const char *alg, const char *mode) {
    CipherStruct cipher;

    if (!strcmp(alg, "DES")) {
        switch (mode[0]) {
            case 'E':
                if (!strcmp(&mode[1], "CBF")) {
                    cipher.mode = EVP_CFB_MODE;
                } else if (!strcmp(&mode[1], "ECB")) {
                    cipher.mode = EVP_ECB_MODE;
                } else if (!strcmp(&mode[1], "EDE")) {
                    if (strlen(mode) >= 4 && mode[2] == '3') {
                        cipher.mode = EVP_CIPHER_ID_des_ede3();
                    } else {
                        cipher.mode = EVP_EDE_MODE;
                    }
                } else {
                    // Handle invalid mode error
                }
                break;
            default:
                // Handle invalid algorithm error
        }

        cipher.cipher = EVP_des_cipher();
    } else {
        // Handle unsupported algorithm error
    }

    return cipher;
}

JSON_Object *parse_token(const char *json, size_t len) {
    JSON_Object *obj = json_tokener_parse(json, len);

    if (!obj || json_object_get_type(obj) != json_object_t::jot_object) {
        // Handle parsing error
        return NULL;
    }

    const char *access_token, *token_type, *expires_in_str;
    int expires_in;
    JSON_Object *refresh_token_obj = NULL;
    json_object_object_foreach(obj, key, value) {
        if (!strcmp(key, "access_token")) {
            access_token = json_object_get_string(value);
        } else if (!strcmp(key, "expires_in")) {
            expires_in_str = json_object_get_string(value);
            expires_in = atoi(expires_in_str);
        } else if (!strcmp(key, "token_type")) {
            token_type = json_object_get_string(value);
        } else if (!strcmp(key, "refresh_token")) {
            refresh_token_obj = value;
        } else {
            // Ignore other fields
        }
    }

    if (!access_token || !strcmp(token_type, "Bearer") || expires_in <= 0) {
        // Handle missing or invalid field errors
        return NULL;
    }

    // Allocated memory is managed by json-c library
    return obj;
}

EVP_CIPHER *parse_and_select_cipher(const char *json, size_t len) {
    JSON_Object *obj = parse_token(json, len);

    if (!obj) {
        // Return default cipher and failure flag
        return NULL;
    }

    const char *alg, *mode;
    json_object_object_foreach(obj, key, value) {
        if (!strcmp(key, "alg")) {
            alg = json_object_get_string(value);
        } else if (!strcmp(key, "mode")) {
            mode = json_object_get_string(value);
        }
    }

    if (!alg || !mode) {
        // Return default cipher and failure flag
        return NULL;
    }

    CipherStruct cipher = select_cipher(alg, mode);

    if (!cipher.cipher) {
        // Return default cipher and failure flag
        return NULL;
    }

    return cipher.cipher;
}
