```cpp
#include <iostream>
#include <vector>
#include <condition_variable>
#include <mutex>
#include <queue>
#include <thread>
#include <chrono>
#include <atomic>

class ResourcePool {
public:
    explicit ResourcePool(size_t capacity) : pool_(capacity), not_full_(pool_.get_sync_wait()), not_empty_(not_full_) {}

    void addResource() {
        std::unique_lock<std::mutex> lock(m_);
        pool_.push_back(new Resource());
        not_full_.notify_one();
    }

    void removeResource() {
        std::unique_lock<std::mutex> lock(m_);
        while (pool_.empty()) {
            not_empty_.wait(lock);
        }
        pool_.pop_back();
        not_empty_.notify_one();
    }

    void loadBalanceToPool(ResourcePool& other) {
        std::unique_lock<std::mutex> lock(m_);
        while (pool_.size() > other.getSize() * 0.8f && pool_.size() != 0) {
            other.addResource();
            removeResource();
        }
    }

private:
    std::vector<Resource*> pool_;
    std::queue<std::unique_lock<std::mutex>> not_full_;
    std::queue<std::unique_lock<std::mutex>> not_empty_;
    std::mutex m_;
};

class Resource {
