        private readonly bool _enableLogging, _enableTransaction;

        public DatabaseExecutor(IConfiguration configuration)
        {
            _configuration = configuration;
            _enableLogging = _configuration.GetValue<bool>("Database:EnableLogging");
            _enableTransaction = _configuration.GetValue<bool>("Database:EnableTransaction");
        }

        public void ExecuteCommand(List<object> parameters, string commandText, int timeout, SqlConnection connection)
        {
            if (connection == null || connection.State != ConnectionState.Open)
                throw new ArgumentException("Invalid or closed database connection.");

            var command = new SqlCommand(commandText, connection);
            command.CommandTimeout = timeout;

            if (_enableLogging)
                Stopwatch stopWatch = Stopwatch.StartNew();

            int maxLength = _configuration.GetValue<int>("Database:MaxCommandLength");
            if (commandText.Length > maxLength)
                throw new ArgumentException($"SQL command length exceeds the maximum allowed value ({maxLength})");

            var parametersToExecute = PrepareParameters(parameters, command);

            try
            {
                if (_enableTransaction)
                    connection.Open();
                command.ExecuteNonQuery();
                if (_enableTransaction)
                    connection.Close();

                if (_enableLogging)
                {
                    stopWatch.Stop();
                    TimeSpan duration = stopWatch.Elapsed;
                    LogExecution(stopWatch, commandText);
                }
            }
            catch (Exception ex)
            {
                if (_enableLogging)
                {
                    stopWatch.Stop();
                    TimeSpan duration = stopWatch.Elapsed;
                    LogError(stopWatch, commandText, ex);
                }
                throw;
            }
        }

        private void LogExecution(Stopwatch stopWatch, string commandText)
        {
            // Implement logging using an established logging library or framework
        }

        private void LogError(Stopwatch stopWatch, string commandText, Exception ex)
        {
            // Implement detailed error logging, including exception message and stack trace
        }

        private SqlParameter[] PrepareParameters(List<object> parameters, SqlCommand command)
        {
            var parameterNames = new List<string>();
            var parameterValues = new List<SqlParameter>();

            int i = 0;
            foreach (var parameter in parameters)
            {
                if (parameter == null)
                    throw new ArgumentException("SQL command contains null parameter.");

                string name = $"@{i++}";
                parameterNames.Add(name);
                parameterValues.Add(new SqlParameter(name, parameter));
            }

            foreach (var (name, value) in command.Parameters)
            {
                if (!parameterNames.Contains(value.ParameterName))
                    command.Parameters.Remove(value);
            }

            foreach (var sqlParameter in parameterValues)
                command.Parameters.Add(sqlParameter);

            return command.Parameters;
        }
    }
}
