            var aesParameters = new ParametersWithIV(AES.Create(new Rfc2898DeriveBytes(weatherData.Temperature, Encoding.ASCII.GetBytes(weatherData.CityName))));
            var camelliaParameters = new CamelliaEngineParameters(new KeyParameter(Encoding.ASCII.GetBytes(weatherData.Humidity)), 128); // or 256 for 256-bit key size

