import express from 'express';
import mongoose from 'mongoose';
import Order from './orderModel'; // Assuming you have an Order model set up

const api = express.Router();
let pageSize = 20; // Number of items per page for pagination

api.post('/orders', async (req, res) => {
    const newOrder = new Order(req.body);
    try {
        await newOrder.save();
        res.status(201).json(newOrder);
    } catch (error) {
        res.status(400).json({ message: error.message });
    }
});

api.put('/orders/:id', async (req, res) => {
    try {
        const order = await Order.findById(req.params.id);
        if (!order) return res.status(404).json({ message: 'Order not found' });

        // Validation and business rules here

        order.set(req.body);
        await order.save();
        res.json(order);
    } catch (error) {
        res.status(400).json({ message: error.message });
    }
});

api.delete('/orders/:id', async (req, res) => {
    try {
        const order = await Order.findById(req.params.id);
        if (!order) return res.status(404).json({ message: 'Order not found' });

        // Check for canceled orders here

        await order.remove();
        res.json({ message: 'Order deleted successfully' });
    } catch (error) {
        res.status(500).json({ message: error.message });
    }
});

api.get('/orders', async (req, res) => {
    const { status, sortBy, page = 1 } = req.query;
    const query = {};

    if (status) query.status = status;

    try {
        const totalCount = await Order.countDocuments(query);
        const orders = await Order.find(query)
            .sort({ [sortBy || 'createdAt']: -1 })
            .skip((page - 1) * pageSize)
            .limit(pageSize);
        res.json({ totalCount, page, orders });
    } catch (error) {
        res.status(500).json({ message: error.message });
    }
});
```

