using System;
using System.Collections.Generic;
using System.Xml;
using System.Xml.Linq;
using System.Xml.XPath;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.CommandLine;
using System.Threading;
using System.Reflection;

public class XmlElementFinder
{
    private readonly Dictionary<string, XDocument> _cache = new Dictionary<string, XDocument>();
    private readonly object _lock = new object();

    public static RootCommand Create()
    {
        var root = new RootCommand("XmlElementFinder")
        {
            new Option<string>("-i", "--input", "The XML input file path."),
            new Option<string>("-n", "--name", "The name of the element to match."),
            new Option<string>("--manpage", "Display this help text and exit."),
            new Option<string>("-cs", "Output as command script for easy execution."),
            new Option<string>("-o", "--output", "Output file path."),
        };

        root.SetHandler((Input, Name, Manpage, Cs, Output) =>
        {
            if (Manpage != null)
                Console.Write(root.GetHelpMarkdown());
            else if (!string.IsNullOrEmpty(Input))
            {
                var finder = new XmlElementFinder();
                List<XElement> elements;

                try
                {
                    elements = finder.FindElements(Input, Name);
                }
                catch (Exception ex)
                {
                    Console.WriteLine(ex.Message);
                    return;
                }

                if (!elements.Any())
                {
                    Console.WriteLine("No elements found.");
                    return;
                }

                if (Cs != null)
                {
                    var script = CreateScript(elements);
                    Console.WriteLine(script);
                }
                else if (!string.IsNullOrEmpty(Output))
                {
                    File.WriteAllText(Output, string.Join("\n", elements.Select(e => e.ToString())));
                    Console.WriteLine($"Elements written to '{Output}'.");
                }
                else
                {
                    foreach (var element in elements.OrderBy(e => e.Value<string>()))
                        Console.WriteLine(element);
                }
            }
            else
            {
                root.ShowHelp();
            }
        });

        return root;
    }

    private List<XElement> FindElements(string inputFile, string elementName)
    {
        lock (_lock)
        {
            if (_cache.TryGetValue(inputFile, out var doc))
                return doc.Root.Elements(elementName).OrderBy(e => e.Value<string>()).ToList();
        }

        using var reader = XmlReader.Create(inputFile);
        var cacheKey = inputFile + "_" + elementName;

        lock (_lock)
        {
            if (!_cache.TryGetValue(cacheKey, out doc))
            {
                doc = XDocument.Load(reader);
                _cache[cacheKey] = doc;
            }
        }

        return doc.Root.Elements(elementName).OrderBy(e => e.Value<string>()).ToList();
    }

    private static string CreateScript(List<XElement> elements)
    {
        var script = new StringBuilder("echo ");
        for (var i = 0; i < elements.Count; i++)
        {
            if (i > 0) script.AppendLine();
            script.Append($"{elements[i]} ");
        }
        return script.ToString();
    }
}
```

This code provides a console application with command-line options for finding elements in an XML document using XPath, caching parsed documents, sorting the results by text content and handling thread safety, errors, memory leaks, and usage information display.']

