import java.io.*;
import java.util.logging.Logger;
import java.util.Optional;
import java.io.Serializable;

public class FileLoader {
    private static final Logger LOGGER = Logger.getLogger(FileLoader.class.getName());

    public static <T extends Serializable & Versionable> T loadStateFromFile(String filePath, Class<T> clazz) {
        T loadedObject = null;
        FileInputStream fileInputStream = null;
        ObjectInputStream objectInputStream = null;

        try {
            fileInputStream = new FileInputStream(filePath);
            objectInputStream = new ObjectInputStream(fileInputStream);

            // Read the first line to check for version compatibility
            String versionLine = objectInputStream.readLine();
            if (versionLine == null || !VersionUtil.isCompatibleWithCurrentVersion(versionLine)) {
                LOGGER.warning("File format or structure has changed, returning a default instance of MoSTState.");
                loadedObject = clazz.newInstance();
            } else {
                loadedObject = objectInputStream.readObject();
            }
        } catch (IOException | ClassNotFoundException | VersionMismatchException e) {
            LOGGER.severe("Error loading state from file: " + e.getMessage());
            // Handle exceptions and log detailed information
        } finally {
            if (objectInputStream != null) {
                try {
                    objectInputStream.close();
                } catch (IOException e) {
                    LOGGER.warning("Error closing ObjectInputStream: " + e.getMessage());
                }
            }
            if (fileInputStream != null) {
                try {
                    fileInputStream.close();
                } catch (IOException e) {
                    LOGGER.warning("Error closing FileInputStream: " + e.getMessage());
                }
            }
        }

        return Optional.ofNullable(loadedObject).orElse(clazz.newInstance());
    }
}

@FunctionalInterface
interface Versionable extends Serializable {
    String getVersion();
}

abstract class VersionableObject implements Versionable, Serializable {
    private static final long serialVersionUID = 1L;
    protected abstract String getVersion();
}

public class MoSTState extends VersionableObject {
    // Implement the MoSTState class here...
}

class VersionUtil {
    public static boolean isCompatibleWithCurrentVersion(String versionLine) {
        // Implement compatibility checking logic based on the file version line here...
    }
}
