import aiohttp
import json
import re
import os
from typing import List, Dict, Any
import asyncio
from dotenv import load_dotenv
load_dotenv()
MAX_RETRIES = 5
CONCURRENT_DOWNLOADS = int(os.getenv("CONCURRENT_DOWNLOADS", 4))
CACHE_SIZE = int(os.getenv("CACHE_SIZE", 1024*1024*16))

class InMemoryCache:
    def __init__(self, max_size):
        self.max_size = max_size
        self.cache = {}

    async def get(self, key):
        if key in self.cache:
            value = self.cache[key]
            del self.cache[key]
            if len(self.cache) > self.max_size // 2:
                for item in list(self.cache.items())[:len(self.cache)//2]:
                    del self.cache[item[0]]
            return value
        return None

    async def set(self, key, value):
        if len(self.cache) > self.max_size:
            for item in list(self.cache.items())[:len(self.cache)//2]:
                del self.cache[item[0]]
        self.cache[key] = value

async def download_and_cache(url: str, cache: InMemoryCache):
    async with aiohttp.ClientSession() as session:
        try:
            async with session.get(url) as response:
                if response.status == 302 or response.status == 301:
                    location = response.headers["location"]
                    return await download_and_cache(location, cache)
                content = await response.content.read()
                content_type = response.content_type
                if content_type == "application/json":
                    data = json.loads(content)
                    await cache.set(url, data)
                elif content_type == "text/html":
                    # Implement parsing and storing HTML as desired
                    pass
                else:
                    await cache.set(url, content)
                return content
        except aiohttp.ClientError as e:
            if MAX_RETRIES > 0:
                await asyncio.sleep(1)
                return await download_and_cache(url, cache)
            else:
                print(f"Failed to download {url}: {e}")
                return None

async def process_urls(urls: List[str]):
    cache = InMemoryCache(CACHE_SIZE)
    tasks = []
    for url in urls:
