const navigation = (config, library) => {
  const cryptos = [];
  let html = '<ul id="nav">';

  const generateMenu = (items, parentId = null) => {
    items.forEach(item => {
      if (Array.isArray(item)) {
        html += `<li id="${item[0].id}-parent">${item[0].label}<ul></ul></li>`;
        generateMenu(item, item[0].id);
      } else {
