      }
    });
  };

  // Enumerate supported cryptographic algorithms
  library.forEachAlgorithm((name, func, params) => {
    if (func && !cryptos.find(c => c.name === name)) {
      cryptos.push({ name, func, params });
    }
  });

  // Merge user-provided configuration with default behavior
