function manageUserAccount($request) {
    if (!isset($request['name']) || !isset($request['email']) || !isset($request['password'])) return json_encode(array('error' => 'Missing data.'));

    $validate = new Validate();
    if (!$validate->isValidEmail($request['email'])) return json_encode(array('error' => 'Invalid email.'));
    if ($request['id']) {
        $userData = $save->getUserById($request['id']);
        if (!$userData) return json_encode(array('error' => 'User not found.'));
    } else {
        $userData = array();
    }
    if (!$validate->isValidPassword($request['password'])) return json_encode(array('error' => 'Invalid password.'));

    if (isset($request['id']) && $request['sub_action'] == 'delete') {
        $save->deleteUserById($request['id']);
        return json_encode(array('success' => true));
    }

    $userData['name'] = $request['name'];
    $userData['email'] = $request['email'];
    $userData['password'] = $save->hashPassword($request['password']);
