    @staticmethod
    def _update_k8s_resources(resources):
        config.load_kube_config()
        v1 = client.CoreV1Api()
        for resource, scale in resources.items():
            meta = kubernetes.client.V1ObjectMeta(name=resource)
            container = kubernetes.client.V1Container(name='data-processing', image='<image-with-scaling-logic>', resources={"cpu": f"{scale['cpu']}", "memory": f"{scale['memory']}"})
            container.set_metadata(meta)
            pod = kubernetes.client.V1Pod(spec=kubernetes.client.V1PodSpec(containers=[container]))
            v1.replace_namespaced_pod(resource, 'default', body=pod)

    def run(self):
        while True:
            time.sleep(1)
            self.consumer.poll(timeout_ms=1000)
            for msg in self.consumer:
                self.process_data(msg.value)

class Scaler:
