import os
import json
import requests
from datetime import timedelta
import oauthlib.oauth2 as oauth2
from graphviz import Digraph
from random import randint

class Graph:
    def __init__(self, config_file):
        self.graph = Digraph()
        self.config = json.load(open(config_file))
        self.api_key, self.api_secret = self._get_oauth_credentials()
        self.timeout = int(self.config['timeout'])

    def _get_oauth_credentials(self):
        try:
            client_id, client_secret, access_token, refresh_token = {}, {}, {}, {}
            with open(os.path.join(os.path.dirname(__file__), 'oauth_credentials.json')) as f:
                credentials = json.load(f)
            for key in ['client_id', 'client_secret', 'access_token', 'refresh_token']:
                client_id[key] = credentials[key]

            token_url, authorize_url = self.config['authorization_url'], self.config['token_url']
            token = oauth2.AccessToken(client_secret=client_secret, resource_owner_key=access_token)
            if not token.expires < time.time():
                return client_id, token.to_dict()

            authorization_response = requests.get(authorize_url + '?response_type=code&client_id={}&redirect_uri={}'.format(client_id['client_id'], self.config['redirect_uri'])).json()
            code = authorization_response['code']
            token.fetch_token(token_url, client_id=client_id['client_id'], client_secret=client_id['client_secret'], code=code)

            refresh_token = token.refresh()
            return client_id, refresh_token
        except Exception as e:
            print('Error fetching OAuth credentials:', str(e))
            raise e

    def _fetch_vertices_and_edges(self):
        try:
            vertices = []
            edges = []
            for i in range(randint(1, 10000)):
                vertex = self._create_vertex()
                vertices.append(vertex)
                if len(vertices) < randint(1, len(vertices)):
                    continue

                for j in range(randint(1, min(len(vertices), 50000))):
                    weight = randint(1, 100)
                    u, v = vertices[randint(0, len(vertices))], vertices[randint(0, len(vertices))]
                    if u != v:
                        edges.append((u, v, weight))

            return vertices, edges
        except requests.exceptions.RequestException as e:
            print('Error fetching data from remote server:', str(e))
            raise e

    def _create_vertex(self):
        try:
            vertex = {'id': len(self.graph.nodes), 'property': randint(0, 100)}
            self.graph.node(vertex['id'], label=str(vertex))
            return vertex
        except Exception as e:
            print('Error creating vertex:', str(e))
            raise e

    def add_vertices_and_edges(self):
        vertices, edges = self._fetch_vertices_and_edges()
        for v in vertices:
            self.graph.node(v['id'], label=str(v), **v)
        for u, v, weight in edges:
            self.graph.edge(u, v, weight=weight)

def main():
    graph = Graph('config.json')
    graph.add_vertices_and_edges()
    graph.view()

if __name__ == '__main__':
    main()
