#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    unsigned int rxiit;
    uint32_t rnti;
    uint8_t crcflag;
    uint8_t crc_indication_rel8_tag[15];
} NFAPI_CRC_INDICATION_PDU_T;

#define RNTI_DATA_SOURCE "/path/to/unique_rnti.txt"
pthread_mutex_t rnti_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(unsigned int n) {
    NFAPI_CRC_INDICATION_PDU_T *list, *current;

    list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Memory allocation failed");
        return NULL;
    }

    current = list;

    pthread_t rnti_reader;
    if (pthread_create(&rnti_reader, NULL, read_unique_rntis, list)) {
        perror("Thread creation failed");
        free(list);
        return NULL;
    }

    for (unsigned int i = 0; i < n; ++i) {
        current->crcflag = rand() % 2;
        current->rxiit = i + 1; // 1-based index
        current->rnti = read_next_rnti();
        memcpy(current->crc_indication_rel8_tag, "\x00\x00\x00\x00\x00\x00\x00\x00"
               "\x00\x00\x00\x00\x00\x00", 15);
        current++;
    }

    // Wait for the RNTI reader thread to finish before returning
    pthread_join(rnti_reader, NULL);

    return list;
}

unsigned int read_next_rnti() {
    FILE *file = fopen(RNTI_DATA_SOURCE, "r");
    if (!file) {
        perror("Unable to open RNTI data source");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&rnti_mutex);

    unsigned int rnti;
    fscanf(file, "%u", &rnti);
    fseek(file, -sizeof(unsigned int), SEEK_CUR); // Move the file pointer back to the beginning of the read line

    pthread_mutex_unlock(&rnti_mutex);

    return rnti;
}

void* read_unique_rntis(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *list = arg;
    char line[256];
    FILE *file = fopen(RNTI_DATA_SOURCE, "r");

    if (!file) {
        perror("Unable to open RNTI data source");
        exit(EXIT_FAILURE);
    }

    while (fgets(line, sizeof(line), file)) {
        unsigned int rnti;
        sscanf(line, "%u", &rnti);

        pthread_mutex_lock(&rnti_mutex);
        list->rnti = rnti;
        pthread_mutex_unlock(&rnti_mutex);

        // Move to the next element in the list and increment the pointer
        NFAPI_CRC_INDICATION_PDU_T *current = list++;
    }

