// Database interface for unique RNTI generation
typedef struct {
    pthread_mutex_t lock;
    unsigned long next_rnti;
} RNTIDataBase;

RNTIDataBase *rnti_db = NULL;

void rnti_db_init(RNTIDataBase **db) {
    *db = malloc(sizeof(RNTIDataBase));
    if (*db == NULL) {
        fprintf(stderr, "Failed to allocate RNTI database.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&((*db)->lock), NULL);
    (*db)->next_rnti = 1; // First RNTI is always 1
}

unsigned long rnti_get() {
    unsigned long rnti;

    pthread_mutex_lock(&rnti_db->lock);
    rnti = rnti_db->next_rnti++;
    pthread_mutex_unlock(&rnti_db->lock);

    return rnti;
}

typedef struct {
