    if (*pdus == NULL) {
        fprintf(stderr, "Failed to allocate PDUs array pointers.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < n; ++i) {
        create_pdu_array(&((*pdus)[i]), 1); // Create and populate a single PDU for each pointer in the array
    }
}
