        exit(EXIT_FAILURE);
    }
    regex_t regex;
    int rc = regcomp(&regex, *(const char **)arg, REG_EXTENDED | REG_NEWLINE);
    if (rc) {
        log("process_file", "Failed to compile regular expression");
        exit(EXIT_FAILURE);
    }
    size_t lines = 0;
    char line[4096];
