        }
        NFAPI_CRCI_PDU_T *pdu = alloc_pdu();
        pdu->RX_UE_INFORMATION_TAG = rand() % 0xFFFFFFFF;
        pdu->RNTI = get_rnti();
        pdu->CRC_INDICATION_REL8_TAG = rand() % 0xFFFF;
        pdu->CRCFLAG = rand() % 2 == 0 ? true : false;
        // Add the new PDU to your data structure here...
        lines++;
    }
    regfree(&regex);
    fclose(fp);
    log("process_file", "Processed file, read %ld lines.", lines);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [options] input_files...\n"
                        "\nOptions:\n"
                        "  --manpage         Print this message.\n"
                        "  -cs               Compile and save the regular expression in a variable.\n"
                        "  -o output_file    Save the log messages to output_file instead of stderr.\n", argv[0]);
        return EXIT_SUCCESS;
    }

    int c;
    const char *log_file = NULL;
    regex_t regex;
    while ((c = getopt(argc, argv, "m:cs:o:")) != -1) {
        switch (c) {
            case 'm':
                // Compile the regular expression from the option argument here...
                break;
            case 'c':
                // Save the regular expression in a variable as discussed earlier...
                break;
            case 'o':
                log_file = optarg;
                break;
        }
    }

    if (log_file) {
        freopen(log_file, "a", stderr);
    }

    db = db_open("database.db", DB_OPEN_NEW | DB_CREATE, 0644);
    if (!db) {
        log("main", "Failed to open or create database");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[argc - optind];
    for (int i = optind; i < argc; ++i) {
        pthread_create(&threads[i - optind], NULL, process_file, argv[i]);
    }

    for (int i = 0; i < argc - optind; ++i) {
        pthread_join(threads[i], NULL);
    }

    db_close(db);
    return EXIT_SUCCESS;
}
