int get_order_id(struct inventory_api *inventory) {
    pthread_mutex_lock(&inventory->mutex);

    CURLcode res;
    CURL *curl = inventory->curl;

    if (curl) {
        curl_easy_reset(curl);
        curl_easy_setopt(curl, CURLOPT_URL, "https://your-inventory-api.com/order-id");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, order_id_callback);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error during ORDER_ID retrieval: %s\n", curl_easy_strerror(res));
            curl_easy_cleanup(curl);
            inventory->curl = NULL;
        }
    } else {
        if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
            fprintf(stderr, "Failed to initialize libcurl\n");
            return -1;
        }

        inventory->curl = curl_easy_init();
        if (!inventory->curl) {
            fprintf(stderr, "Failed to create a new libcurl session\n");
            return -1;
        }

        curl_easy_setopt(inventory->curl, CURLOPT_URL, "https://your-inventory-api.com/order-id");
        curl_easy_setopt(inventory->curl, CURLOPT_WRITEFUNCTION, order_id_callback);
    }

    pthread_mutex_unlock(&inventory->mutex);

    return inventory->curl ? (int) curl_easy_getinfo(inventory->curl, CURLINFO_RECV_DATA_SEARCH_END) : -1;
}

// Function to get a random product quantity within a given range
int get_random_product_quantity() {
    return rand() % 100 + 1;
}

// Helper function to initialize the inventory API struct
void init_inventory_api(struct inventory_api *inventory) {
    inventory->curl = NULL;
    pthread_mutex_init(&inventory->mutex, NULL);
}

// Function to clean up the inventory API resources on program termination
void cleanup_inventory_api(struct inventory_api *inventory) {
    if (inventory->curl) {
        curl_easy_cleanup(inventory->curl);
        inventory->curl = NULL;
    }
    pthread_mutex_destroy(&inventory->mutex);
}
