std::ofstream log_file("attack_log.txt", std::ios::app);

void Attack() {
    static std::map<int, int64_t> lastAttacks = {{0, 0}, {1, 0}, {2, 0}};
    auto currentTime = std::chrono::steady_clock::now().time_since_epoch().count();
    double healthPercentage = (double)currentTime / 60.0; // assuming currentTime is in seconds and game time is in minutes
    int cooldownSeconds = static_cast<int>(5 + (10 * (healthPercentage - 0.5)));
    std::this_thread::sleep_for(std::chrono::seconds(cooldownSeconds));

    auto randomAttackIndex = distribution(generator);
    while (lastAttacks[randomAttackIndex] + cooldownSeconds > currentTime) {
        randomAttackIndex = (randomAttackIndex + 1) % 3; // cycle through attacks if one is on cooldown
    }
    lastAttacks[randomAttackIndex] = currentTime;

    std::cout << "Selected attack: " << randomAttackIndex << "\n";

    {
        std::lock_guard<std::mutex> lock(log_mutex);
        log_file << "Selected attack: " << randomAttackIndex << " at time: " << currentTime << "\n";
    }
}

int main() {
    generator = std::mt19937(std::random_device{}());
    while (true) {
        Attack();
    }
    return 0;
}
