```javascript
const Reducer = (callback, config) => {
  let pendingRequests = 0; // Tracks number of active requests
  const maxConcurrency = config.maxConcurrency || 10; // Maximum concurrent operations
  const queue = []; // Request queue
  const results = []; // Results storage

  // Check input and configure error handling strategies
  if (!Array.isArray(callback) && !callback.length === 2) {
    throw new Error('Invalid callback function');
  }

  // Resource management system
  const resourceManager = new ResourceManager({
    maxConcurrency,
    onExhausted: config.onExhausted || defaultOnExhausted,
    onRecovered: config.onRecovered || defaultOnRecovered,
    onError: config.onError || defaultOnError,
  });

  // Asynchronous reduction function
  const reduce = (arr, initialValue) => {
    if (!Array.isArray(arr)) throw new Error('Invalid array input');

    // Initialize results and queue
    results.length = 0;
    queue.length = 0;

    // Set initial value and process first chunk of data (up to maxConcurrency)
    resourceManager.acquire(() => {
      let start = 0;
      let end = Math.min(maxConcurrency, arr.length);

      for (let i = start; i < end; i++) {
        processData(arr[i], initialValue, callback);
        start++;
        if (start === end) break; // Reset loop for next chunk
      }
    });
  };

  // Process data asynchronously and handle potential failures gracefully
  const processData = (data, accumulator, callback) => {
    pendingRequests++;

    resourceManager.execute(() => {
      try {
        const result = callback(accumulator, data);
        results.push(result);
      } catch (error) {
        console.error(`Error processing data ${data}:`, error);
        results.push(undefined); // Mark failed request as undefined
      } finally {
        pendingRequests--;
        processNextRequest();
      }
    });
  };

  // Process next request from the queue or start a new one if needed
  const processNextRequest = () => {
    if (queue.length) {
      resourceManager.acquire(() => processData(queue.shift(), results[results.length - 1], callback));
    } else if (pendingRequests < maxConcurrency && arr.length > results.length) {
      let start = Math.max(results.length - maxConcurrency, 0);
      let end = Math.min(arr.length, results.length + maxConcurrency);

      for (let i = start; i < end; i++) {
        queue.push(arr[i]);
      }

      resourceManager.acquire(() => processData(queue.shift(), results[results.length - 1], callback));
    }
  };

  // Default error handling functions
  const defaultOnExhausted = () => console.warn('Reached maximum concurrency limit');
  const defaultOnRecovered = () => console.log('Recovered from resource exhaustion');
  const defaultOnError = (error) => console.error(error);
};
```

