typedef struct Bundle {
    int type;
    char** pairs;
    size_t num_pairs;
    pthread_mutex_t mutex;
} Bundle;

typedef struct BundleState {
    int num_bundles;
    int max_bundles;
    Bundle* bundles;
    pthread_mutex_t lock;
} BundleState;

int load_resource_bundle(const char** paths, int bundle_type, BundleState** state) {
    size_t num_paths = sizeof(paths)/sizeof(char*);
    bool* file_exists = malloc(num_paths * sizeof(bool));
    struct stat file_stat;

    for (size_t i = 0; i < num_paths; ++i) {
        if (stat(paths[i], &file_stat) == -1 || S_ISDIR(file_stat.st_mode)) {
            file_exists[i] = false;
            continue;
        }
        file_exists[i] = true;
    }

    int num_duplicate_types = 0;
    BundleState* new_state = malloc(sizeof(BundleState));
    new_state->num_bundles = 0;
    new_state->max_bundles = 16;
    new_state->bundles = malloc(new_state->max_bundles * sizeof(Bundle));
    new_state->lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < num_paths; ++i) {
        if (!file_exists[i]) continue;

        Bundle* current_bundle = NULL;
        int found = false;
        pthread_mutex_lock(&new_state->lock);
        for (int j = 0; j < new_state->num_bundles; ++j) {
            if (new_state->bundles[j].type == bundle_type) {
                current_bundle = &new_state->bundles[j];
                found = true;
                break;
            }
        }
        pthread_mutex_unlock(&new_state->lock);

        if (current_bundle && current_bundle->type == bundle_type) {
            num_duplicate_types++;
            continue;
        }

        FILE* file = fopen(paths[i], "r");
        if (!file) continue;

        char line[4096];
        ssize_t read_len;
        Bundle new_bundle = {bundle_type};
        new_bundle.pairs = malloc(1 * sizeof(char*));
        new_bundle.num_pairs = 0;
        new_bundle.mutex = PTHREAD_MUTEX_INITIALIZER;

        while ((read_len = getline(&line, sizeof(line), file)) != -1) {
            if (new_bundle.num_pairs == new_bundle.max_bundles) {
                new_bundle.max_bundles *= 2;
                new_bundle.pairs = realloc(new_bundle.pairs, new_bundle.max_bundles * sizeof(char*));
            }
            new_bundle.pairs[new_bundle.num_pairs] = strdup(line);
            ++new_bundle.num_pairs;
        }
        fclose(file);

        if (current_bundle) {
            // Merge the new bundle with the existing one
            for (int j = 0; j < new_bundle.num_pairs; ++j) {
                char* pair = new_bundle.pairs[j];
                int key_index = -1, value_index = -1;
                for (int k = 0; k < current_bundle->num_pairs; ++k) {
                    if (strncmp(current_bundle->pairs[k], pair, strcspn(pair, "=")) == 0) {
                        key_index = k;
                        value_index = j;
                        break;
                    }
                }
                if (key_index != -1 && value_index != -1) {
                    free(current_bundle->pairs[key_index]);
                    current_bundle->pairs[key_index] = new_bundle.pairs[value_index];
                    continue;
                }
            }
        } else {
            pthread_mutex_lock(&new_state->lock);
            if (new_state->num_bundles < new_state->max_bundles) {
                new_state->bundles[new_state->num_bundles] = new_bundle;
                ++new_state->num_bundles;
            } else {
                realloc(new_state->bundles, (new_state->max_bundles *= 2) * sizeof(Bundle));
                new_state->bundles[new_state->num_bundles - 1] = new_bundle;
                ++new_state->num_bundles;
            }
            pthread_mutex_unlock(&new_state->lock);
        }
    }

    free(file_exists);
    if (num_duplicate_types > 1) {
        free(new_state);
        return BUNDLE_ERROR_DUPLICATE_TYPES;
    }

    // Handle potential I/O errors and memory leaks here.

    *state = new_state;
    return BUNDLE_SUCCESS;
}
