void init_rnti_cache(struct rtni_cache *cache, int cache_size) {
    cache->size = cache_size;
    cache->rntis = calloc(cache_size, sizeof(uint32_t));
    cache->lock = PTHREAD_MUTEX_INITIALIZER;
}

void free_rnti_cache(struct rtni_cache *cache) {
    free(cache->rntis);
}

uint32_t get_unique_rnti(struct rtni_cache *cache) {
    pthread_mutex_lock(&cache->lock);
    uint32_t rnti = cache->rntis[0];
    memmove(&cache->rntis[0], &cache->rntis[1], sizeof(uint32_t) * (cache->size - 1));
    cache->rntis[cache->size - 1] = rnti;
    pthread_mutex_unlock(&cache->lock);
    return rnti;
}

void generate_crc_indication(NFAPI_CRCI_PDU_T *crc_pdu) {
