class PacketProcessor {
private:
    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> dataList;
    RNTI_Generator rntiGen;
    size_t capacity = 0;

public:
    void addDataPacket(const NFAPI_CRC_INDICATION_PDU_T& packet) {
        if (dataList.size() >= capacity) {
            resize();
        }
        dataList[dataList.size() - 1] = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(packet);
    }

    void resize() {
        capacity *= 2;
        auto newDataList = std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>>(capacity);
        newDataList.swap(dataList);
    }

    NFAPI_CRC_INDICATION_PDU_T* getNextPacket() {
        if (dataList.empty()) {
            throw std::runtime_error("No data packets available");
        }

        auto packet = dataList[0].get();
        dataList.erase(dataList.begin());
        return packet;
    }

    void start() {
        std::thread worker([this]() {
            while (true) {
                try {
                    auto packet = getNextPacket();
                    // process the packet...
                } catch (const std::exception& e) {
                    std::cerr << "Error processing data packet: " << e.what() << std::endl;
                }
            }
        });
        worker.detach();
    }
