int add_header(char *name, char *value) {
    if (!private_key) {
        return -1; // No private key provided
    }

    HTTP_RESPONSE_HEADERS* new_header = malloc(sizeof(HTTP_RESPONSE_HEADERS));
    generate_unique_header();
    new_header->HEADER_NAME = strdup(name);
    new_header->HEADER_VALUE = strdup(value);
    new_header->LAST_MODIFIED_TIME = time(NULL);

    pthread_mutex_lock(&headers_lock);
    headers[num_headers] = new_header;
    num_headers++;
    pthread_mutex_unlock(&headers_lock);

    return 0;
}

bool validate_signature(char *data, size_t data_len, char *public_key) {
    if (!private_key || !public_key) {
        return false; // No private or public key provided
    }

    BIGNUM *sha256 = NULL;
    SHA256_CTX ctx;
    unsigned char hash[SHA256_DIGEST_LENGTH];

    // Hash the data using SHA-256
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, data, data_len);
    SHA256_Final(hash, &ctx);

    // Generate RSA-PSS signature with SHA-256
    const EVP_MD *md = EVP_sha256();
    if (!EVP_DigestSignInit(&private_key->pkey, NULL, md, NULL, private_key)) {
        return false; // Error during signature generation
    }
    EVP_DigestSignUpdate(&private_key->pkey, hash, SHA256_DIGEST_LENGTH);
    if (!EVP_DigestSignFinal(&private_key->pkey, NULL, NULL)) {
        return false; // Error during signature generation
    }

    unsigned char sig[i2d_RSAPSS_SIGNATURE(private_key->pkey)->length];
    i2d_RSAPSS_SIGNATURE(private_key->pkey, &sig);

    // Verify the signature with the provided public key
    if (!EVP_DigestVerifyInit(&ctx, NULL, md, NULL, public_key)) {
        return false; // Error during signature verification
    }
    EVP_DigestVerifyUpdate(&ctx, hash, SHA256_DIGEST_LENGTH);
    EVP_DigestVerifyFinal(&ctx, sig, i2d_RSAPSS_SIGNATURE(private_key->pkey, NULL));

    return true; // Signature is valid
}

void init_headers() {
    pthread_mutex_init(&headers_lock, NULL);
    headers = calloc(1, sizeof(HTTP_RESPONSE_HEADERS*));
}
