#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <openssl/sha.h>
#include <openssl/md5.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    const char* path;
    bundle_type type;
    uint8_t hash[SHA256_DIGEST_LENGTH]; // or MD5_DIGEST_LENGTH for MD5
    size_t length;
    time_t last_modified;
} bundle_state;

struct resource_hasher {
    sem_t mutex;
    size_t capacity;
    bundle_state** data;
};

void destroy(bundle_state* state) {
    free(state->path);
    free(state->hash);
    free(state);
}

bundle_state* load_bundle(const char* path, bundle_type type) {
    FILE* file = fopen(path, "rb");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    struct stat file_stat;
    if (fstat(fileno(file), &file_stat) < 0) {
        perror("Error getting file status");
        fclose(file);
        return NULL;
    }

    // Handle invalid input lengths for SHA-256 here

    uint8_t* buffer = malloc(file_stat.st_size);
    size_t read_bytes = fread(buffer, 1, file_stat.st_size, file);
    if (read_bytes != file_stat.st_size) {
        perror("Error reading file");
        free(buffer);
        fclose(file);
        return NULL;
    }

    bundle_state* state = malloc(sizeof(bundle_state));
    state->path = strdup(path);
    state->type = type;
    state->hash = SHA256(buffer, file_stat.st_size, state->hash) // or MD5(buffer, file_stat.st_size, state->hash) for MD5
                  + SHA256_DIGEST_LENGTH * '\0'; // or MD5_DIGEST_LENGTH * '\0' for MD5
    state->length = file_stat.st_size;
    state->last_modified = file_stat.st_mtime;

    free(buffer);
    fclose(file);
    return state;
}

resource_hasher* resource_hasher_init(size_t capacity) {
    resource_hasher* hasher = malloc(sizeof(resource_hasher));
    hasher->mutex = sem_init(0, 1, 1);
    hasher->capacity = capacity;
    hasher->data = calloc(capacity, sizeof(bundle_state*));
    return hasher;
}

void resource_hasher_destroy(resource_hasher* hasher) {
    for (size_t i = 0; i < hasher->capacity; ++i) {
        bundle_state* state = hasher->data[i];
        if (state) destroy(state);
    }

    sem_destroy(hasher->mutex);
    free(hasher->data);
    free(hasher);
}

void resource_hasher_add(resource_hasher* hasher, const char* path, bundle_type type) {
    sem_wait(&hasher->mutex);

    size_t i;
    for (i = 0; i < hasher->capacity; ++i) {
        if (!hasher->data[i]) {
            hasher->data[i] = load_bundle(path, type);
            if (hasher->data[i]) break;
        }

        // Check for duplicate bundle types here
    }

    sem_post(&hasher->mutex);
}

bundle_state* resource_hasher_get(resource_hasher* hasher, const char* path, bundle_type type) {
    sem_wait(&hasher->mutex);

    size_t i;
    for (i = 0; i < hasher->capacity; ++i) {
        if (!hasher->data[i]) continue;

        if (strcmp(hasher->data[i]->path, path) == 0 && hasher->data[i]->type == type) {
            bundle_state* state = hasher->data[i];
            void* temp = hasher->data[i];
            hasher->data[i] = NULL;
            sem_post(&hasher->mutex);
            return state;
        }
    }

    sem_post(&hasher->mutex);
    return NULL;
}

// Implement stream-loading functionality, error handling, and logging here
