import com.google.protobuf.InvalidProtocolBufferException;

public class ConnectionManager {
    private SocketChannel channel;
    private List<NFAPI_CRC_INDICATION_PDU_T> dataList = new ArrayList<>();

    public void establishAndManageConnection(String remoteAddress, int port) throws IOException {
        this.channel = SocketChannel.open();
        this.channel.connect(new InetSocketAddress(remoteAddress, port));

        // Check connection state and handle exceptions
        while (!this.channel.finishConnect()) {
            Thread.sleep(100);
        }

        // Generate a unique RNTI for each data structure in the list
        Set<Integer> rntiSet = new HashSet<>();
        Random random = new Random();

        while (dataList.size() < 10) { // Adjust size as per your requirements
            int rnti = Math.abs(random.nextInt());
            if (!rntiSet.contains(rnti)) {
                rntiSet.add(rnti);
                dataList.add(new NFAPI_CRC_INDICATION_PDU_T(RX_UE_INFORMATION_TAG, rnti, CRC_INDICATION_REL8_TAG, random.nextBoolean()));
            }
        }

        // Serialize the list using Protobuf or any other efficient serialization technique
        ByteBuffer byteBuffer = ByteBuffer.allocate(1024);
        for (NFAPI_CRC_INDICATION_PDU_T data : dataList) {
            try {
                byte[] dataBytes = data.toByteArray();
                int length = dataBytes.length;
                if (byteBuffer.remaining() < length) {
                    byteBuffer.flip();
                    this.channel.write(byteBuffer);
                    byteBuffer.clear();
                }
                byteBuffer.put(dataBytes);
            } catch (InvalidProtocolBufferException e) {
                System.err.println("Invalid Protobuf data: " + e.getMessage());
            }
        }
        byteBuffer.flip();
        this.channel.write(byteBuffer);

        // Deserialize the received data back into a list of NFAPI_CRC_INDICATION_PDU_T structures
        ByteBuffer receiveBuffer = ByteBuffer.allocate(1024);
        while (this.channel.read(receiveBuffer) > 0) {
            receiveBuffer.flip();
            while (receiveBuffer.hasRemaining()) {
                try {
                    NFAPI_CRC_INDICATION_PDU_T deserializedData = NFAPI_CRC_INDICATION_PDU_T.parseFrom(receiveBuffer);
                    dataList.add(deserializedData);
                } catch (InvalidProtocolBufferException e) {
                    System.err.println("Invalid Protobuf data: " + e.getMessage());
                }
            }
            receiveBuffer.clear();
        }
    }
}
