/* Define maximum size for the input string and MD5 hash */
#define MAX_INPUT_SIZE 65536
#define MD5_HASH_LENGTH 32

char* stringToMD5WithSizeLimit(const char* input, size_t limit, bool trim) {
    /* Check for invalid parameters */
    if (!input || strlen(input) >= MAX_INPUT_SIZE || limit > MAX_INPUT_SIZE) {
        return NULL;
    }

    /* Calculate the required length of the final string (including the trailing slash and hash) */
    size_t md5_hash_len = strlen(input) + MD5_HASH_LENGTH + 1;
    if (md5_hash_len > limit && trim) {
        /* Truncate the input string to fit within the specified limit */
        char* truncated_input = calloc(limit, sizeof(char));
        if (!truncated_input) {
            return NULL;
        }
        strncpy(truncated_input, input, limit);
        truncated_input[limit - 1] = '\0';

        /* Hash the truncated string and allocate memory for the resulting MD5 hash */
        unsigned char md5[MD5_DIGEST_LENGTH];
        if (MD5((unsigned char*)truncated_input, strlen(truncated_input), md5) != 0) {
            free(truncated_input);
            return NULL;
        }

        /* Combine the truncated string and the MD5 hash into a single string with a trailing slash */
        char* result = calloc(md5_hash_len, sizeof(char));
        if (!result) {
            free(truncated_input);
            return NULL;
        }
        strncpy(result, truncated_input, limit - 1);
        strcat(result, md5_to_hex(md5));
        strcat(result, "/");

        /* Free the temporary variables and return the result */
        free(truncated_input);
        return result;
    } else if (md5_hash_len > limit && !trim) {
        /* The input string exceeds the size limit without trimming. Return NULL to indicate failure. */
        return NULL;
    } else {
        /* Hash the input string and allocate memory for the resulting MD5 hash */
        unsigned char md5[MD5_DIGEST_LENGTH];
        if (MD5((unsigned char*)input, strlen(input), md5) != 0) {
            return NULL;
        }

        /* Combine the input string and the MD5 hash into a single string with a trailing slash */
        char* result = calloc(md5_hash_len, sizeof(char));
        if (!result) {
            return NULL;
        }
        strcpy(result, input);
        strcat(result, md5_to_hex(md5));
        strcat(result, "/");

        /* Return the result */
        return result;
    }
}

char* md5_to_hex(const unsigned char* data) {
    static const char* HEX_CHARSET = "0123456789ABCDEF";
    char hex[MD5_HASH_LENGTH * 2 + 1];
    int index;

    for (index = 0; index < MD5_DIGEST_LENGTH; ++index) {
        uint8_t byte = data[index];
        hex[(index * 2)] = HEX_CHARSET[byte >> 4];
        hex[(index * 2) + 1] = HEX_CHARSET[byte & 0xF];
    }

    /* Null-terminate the resulting string */
    hex[MD5_HASH_LENGTH * 2] = '\0';
    return hex;
}

int main() {
    const char* test_strings[] = {"", "abc", "1234567890", "0123456789012345678901234567890", "a"};
    size_t size_limits[] = {1, 10, 20, 16, 1};
    bool trim[] = {false, true, false, true, false};

    for (size_t i = 0; i < sizeof(test_strings) / sizeof(char*); ++i) {
        char* result = stringToMD5WithSizeLimit(test_strings[i], size_limits[i], trim[i]);
        if (!result) {
            printf("Error: Failed to generate the MD5 hash for the given input string.\n");
        } else {
            printf("Input String: %s\n", test_strings[i]);
            printf("Size Limit:  %zu\n", size_limits[i]);
            printf("Trim:       %s\n", trim[i] ? "True" : "False");
            printf("MD5 Hash:   %s\n\n", result);
            free(result);
        }
    }

    return 0;
}
