#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    size_t capacity;
    size_t length;
    char* data;
} Line;

Line* line_new() {
    Line* line = (Line*) malloc(sizeof(Line));
    line->capacity = 16;
    line->length = 0;
    line->data = (char*) malloc(line->capacity * sizeof(char));
    return line;
}

void line_resize(Line* line) {
    if (line->length >= line->capacity) {
        line->capacity *= 2;
        line->data = realloc(line->data, line->capacity * sizeof(char));
    }
}

void line_append(Line* line, const char* str) {
    size_t len = strlen(str);
    line_resize(line);
    memcpy(&(line->data[line->length]), str, len + 1);
    line->length += len + 1;
}

void process_line(Line* line) {
    char* token = strtok(line->data, " \t");
    size_t count = 0;
    double total = 0.0;

    while (token != NULL) {
        total += atof(token);
        count++;

        if (count >= 3) { // Skip the first two numerical fields
            token = strtok(NULL, " \t");
            if (token != NULL) {
                double avg = total - atof(token);
                line_append(line, ",");
                char avg_str[32];
                sprintf(avg_str, "%.16f", avg); // Prevent overflow by using a large buffer
                line_append(line, avg_str);
            }
        }

        token = strtok(NULL, " \t");
    }
}

int main() {
    FILE* file = fopen("largefile.txt", "r");

    if (file == NULL) {
        fprintf(stderr, "Error: Unable to open the file.\n");
        return 1;
    }

    Line* current_line = line_new();

    char buffer[4096]; // Larger buffer for efficient reading of large lines

    while (fgets(buffer, sizeof(buffer), file)) {
        Line* new_line = line_new();
        memcpy(new_line->data, buffer, strlen(buffer));
        process_line(current_line);
        free(current_line);
        current_line = new_line;
    }

    process_line(current_line);
    fclose(file);
    free(current_line->data);
    free(current_line);

    return 0;
}
```

This program reads a large text file and processes each line efficiently. It dynamically allocates memory for each line and appends the calculated average value at the end of the line. The program handles varying line lengths and ensures robust error handling for potential file I/O issues. Memory is managed carefully to prevent leaks, and resources are freed promptly when they are no longer needed.']

