JSAMPARRAY optimize_jpeg(j_decompress_struct *cinfo, JSAMPROW *buffer, int optimization);

ImageInfo* processJPEGAndOptimize(const char *filePath, int optimization) {
    FILE *fp = fopen(filePath, "rb");
    if (!fp) {
        perror("Error opening file");
        return NULL;
    }

    jpeg_decompress_struct cinfo;
    jpeg_error_mgr jerr;

    j peg_init_source(&cinfo, fp);
    jpeg_create_err(jpeg_std_error(&jerr), &cinfo);
    jpeg_parse_header(&cinfo, &jerr);

    if (jpeg_read_scanlines(&cinfo, NULL, 1) < 0) {
        perror("Error reading JPEG data");
        fclose(fp);
        return NULL;
    }

    int width = cinfo.image_width;
    int height = cinfo.image_height;
    jpeg_color_space cs = cinfo.colorspace;
    int compression = cinfo.comps_in_sample[0];

    if (optimization < 1 || optimization > 3) {
        printf("Invalid optimization level\n");
        fclose(fp);
        return NULL;
    }

    JSAMPROW *buffer = (*jpeg_malloc_sensor)(width * height, JPOOL_IMAGE);
    jpeg_read_scanlines(&cinfo, buffer, height);

    ImageInfo *imageInfo = malloc(sizeof(ImageInfo));
    imageInfo->width = width;
    imageInfo->height = height;
    imageInfo->cs = cs;
    imageInfo->compression = compression;

    jpeg_compress_struct cinfo2;
    jpeg_error_mgr jerr2;
    jpeg_copy_cinfo(&cinfo2, &cinfo);

    jpeg_create_compress(&cinfo2);
    jpeg_mem_dest(&cinfo2);

    cinfo2.image_width = width;
    cinfo2.image_height = height;

    jpeg_set_defaults(&cinfo2);
    jpeg_set_quality(&cinfo2, optimization * 10, TRUE);

    jpeg_start_compress(&cinfo2, &jerr2);

    JSAMPROW row[1];
    while (cinfo2.next_scanline < cinfo2.image_height) {
        row[0] = buffer[cinfo2.next_scanline];
        jpeg_write_scanlines(&cinfo2, row, 1);
    }

    jpeg_finish_compress(&cinfo2);

    JSAMPARRAY optimized_buffer = optimize_jpeg(&cinfo2, buffer, optimization);
    ImageInfo *optimizedImage = malloc(sizeof(ImageInfo));
    memcpy(optimizedImage, imageInfo, sizeof(ImageInfo));

    jpeg_destroy_compress(&cinfo2);
    fclose(fp);

    return optimizedImage;
}

