    localPartEnd = localPartBegin + strlen(localPartBegin);
    if (strlen(localPartBegin) > maxUsernameLength || strlen(localPartBegin) == 0) return MALFORMED_EMAIL;

    size_t maxDomainLength = 19;
    const char *domainBegin = strchr(inputEmail, '@');
    const char *domainEnd = domainBegin + strlen(domainBegin);
    if (strlen(domainBegin) > maxDomainLength || strlen(domainBegin) == 0) return MALFORMED_EMAIL;

