    iconv(cd, &const char*[&inputBuffer, NULL], &size_t[&inputSize, NULL], &const char*[&outputBuffer, NULL], &size_t[&outputSize, NULL]);
    iconv_close(cd);

    // Construct the new email address with the updated identifier
    sprintf(outputEmail, "%c%.*s%ld%06d@%s",
            localPartBegin[0], (int)strlen(localPartBegin), localPartBegin,
            static_cast<long>(std::time(nullptr)), static_cast<int>(std::time(nullptr) % 1000000));
    strncpy(outputEmail + strlen(outputEmail), outputBuffer, maxDomainLength);
    free(inputBuffer);
    free(outputBuffer);

    return NO_ERROR;
}
