public class ConnectionManager {
    private static final int MAX_CONCURRENT_CONNECTIONS = 10;
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static SortedSet<Connection> activeConnections = new TreeSet<>(Comparator.comparingLong(c -> c.getId()));

    public static void establishAndManageConnection(List<NFAPI_CRC_INDICATION_PDU_T> data) throws IOException {
        if (data == null || data.isEmpty()) return;

        Random rntiGenerator = new Random();
        SortedSet<Long> usedRNTIValues = ConcurrentSkipListSet.newKeySet();

        for (NFAPI_CRC_INDICATION_PDU_T pdu : data) {
            long rnti;
            do {
                rnti = rntiGenerator.nextLong();
            } while (usedRNTIValues.contains(rnti));
            usedRNTIValues.add(rnti);
            pdu.setRnti(rnti);
        }

        Connection connection;
        synchronized (activeConnections) {
            if (activeConnections.size() < MAX_CONCURRENT_CONNECTIONS) {
                connection = newConnection();
            } else {
                connection = activeConnections.pollFirst();
            }
        }

        DataOutputStream outputStream;
        DataInputStream inputStream;
        try (ByteArrayOutputStream serializedDataStream = new ByteArrayOutputStream()) {
            objectMapper.setDefaultSerializer(new JsonSerializer<NFAPI_CRC_INDICATION_PDU_T>() {
                @Override
                public void serialize(NFAPI_CRC_INDICATION_PDU_T pdu, JsonGenerator jsonGenerator, SerializerProvider serializers) throws IOException {
                    jsonGenerator.writeStartObject();
                    jsonGenerator.writeNumberField("RX_UE_INFORMATION_TAG", pdu.getRxUEInformationTag());
                    jsonGenerator.writeNumberField("RNTI", pdu.getRnti());
                    jsonGenerator.writeNumberField("CRC_INDICATION_REL8_TAG", pdu.getCrcIndicationRel8Tag());
                    jsonGenerator.writeBooleanField("CRCFLAG", pdu.getCrcflag());
                    jsonGenerator.writeEndObject();
                }
            });

            objectMapper.writeValue(serializedDataStream, data);
            byte[] serializedData = serializedDataStream.toByteArray();

            connection.setOutputSteam(new DataOutputStream(connection.getOutputStream()));
            outputStream = connection.getOutputSteam();
            outputStream.writeInt(serializedData.length);
            outputStream.write(serializedData);
            outputStream.flush();

            inputStream = new DataInputStream(connection.getInputStream());
            int responseLength = inputStream.readInt();
            byte[] responseData = new byte[responseLength];
            inputStream.readFully(responseData);

            // Handle the response and update the state accordingly
            // ...
        } catch (IOException e) {
            if (!connection.isClosed()) {
                connection.close();
                activeConnections.remove(connection);
            }
            if (data.size() > 1) {
                establishAndManageConnection(Arrays.copyOfRange(data, 1, data.size()));
            }
        }
    }

    private static Connection newConnection(String remoteAddress, int remotePort) throws IOException {
        Socket socket = new Socket(remoteAddress, remotePort);
        return new Connection(socket);
    }

    private static class Connection implements Comparable<Connection> {
        private final Socket socket;
        private DataOutputStream outputStream;
        private DataInputStream inputStream;
        private long id;

        private Connection(Socket socket) {
            this.socket = socket;
            this.id = System.currentTimeMillis();
        }

        public void setOutputSteam(DataOutputStream outputStream) {
            this.outputStream = outputStream;
        }

        public DataOutputStream getOutputSteam() {
            return outputStream;
        }

        public DataInputStream getInputSteam() {
            if (inputStream == null) {
                inputStream = new DataInputStream(socket.getInputStream());
            }
            return inputStream;
        }

        @Override
        public int hashCode() {
            return (int) id;
        }

        @Override
        public boolean equals(Object obj) {
            if (obj instanceof Connection) {
                return this.id == ((Connection) obj).getId();
            }
            return false;
        }

        @Override
        public int compareTo(Connection o) {
            return Long.compare(this.id, o.id);
        }
    }
}
