#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <inttypes.h>
#include <idn2/idna.h>
#include <uuid/uuid.h>

typedef struct {
    char local_part[3]; // maximum of 2 characters
    char domain[11];    // maximum of 10 characters, plus the \0 terminator
} email_parts;

email_parts parse_email(const char* email) {
    email_parts parts = {};
    size_t i, len;

    if (!email || strlen(email) > 256)
        return parts; // invalid email or too long

    for (i = 0; i < sizeof(parts.local_part); ++i) {
        if (email[i] == '\0')
            break;
        if (i < sizeof(parts.local_part) - 1 && isalnum(email[i]))
            parts.local_part[i] = tolower(email[i]);
    }

    len = strlen(email);
    if (len > sizeof(parts.domain))
        return parts; // invalid email or too long

    memset(parts.domain, 0, sizeof(parts.domain));
    strncpy(parts.domain, &email[i], len - i);

    idna_context ctx = {0};
    uint32_t status;
    idn_toascii(&ctx, parts.domain, strlen(parts.domain), parts.domain, sizeof(parts.domain), &status);

    return parts;
}

char* generate_unique_email(const email_parts* parts) {
    uuid_t uuid;
    char timestamp[14]; // YYYYMMDDHHMMSS format

    uuid_time_t now = time(NULL);
    snprintf(timestamp, sizeof(timestamp), "%" PRIu64, now);

    UNUSED(uuid_generate_time(uuid)); // ensure entropy with current time

    char unique_id[17]; // first character + domain + timestamp + random string
    unique_id[0] = toupper(parts->local_part[0]);
    strncpy(&unique_id[1], parts->domain, sizeof(parts->domain));
    strncpy(&unique_id[11], timestamp, sizeof(timestamp));

    // Generate a 4-character alphanumeric string for uniqueness.
    uuid_bytes_t bytes;
    uuid_to_bytes_time(uuid, bytes);
    uint32_t random = (bytes[3] << 24) | (bytes[2] << 16) | (bytes[1] << 8) | bytes[0];
    snprintf(&unique_id[15], sizeof(unique_id) - 16, "%04" PRIx32, random);

    return unique_id;
}

int main() {
    char email[] = "john.doe@example.com";
    email_parts parts = parse_email(email);
    if (!parts.local_part[0] || !parts.domain[0])
        printf("Invalid email.\n");
    else
        printf("%s\n", generate_unique_email(&parts));

    return 0;
}
