typedef struct Session_t {
    SSL_CTX *ctx;
    SSL *ssl;
    EVP_CIPHER_CTX *sym_ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
    // Additional fields for connection pooling and error handling
} Session;

Session* create_session(const char* pass) {
    SSL_CTX *ctx = SSL_CTX_new(TLSv1_3_client_method());
    const EVP_CIPHER *cipher = EVP_aes_256_gcm();

    // Derive key and IV from password using PBKDF2 with 50,000 iterations and SHA-256 hashing.
    unsigned char key_derived[EVP_MAX_KEY_LENGTH];
    derive_key(pass, EVP_MAX_KEY_LENGTH, key_derived);

    // Generate random IV for each session initiation
    RAND_bytes(iv, sizeof(iv));

    // Set up cipher context with derived key and IV
    EVP_CIPHER_CTX_init(&sym_ctx);
    EVP_EncryptInit_ex(sym_ctx, cipher, NULL, key_derived, iv, 0);

    Session* session = malloc(sizeof(Session));
    session->key = key_derived;
    session->iv = iv;
    session->sym_ctx = sym_ctx;
    // Initialize SSL context
    session->ctx = ctx;
    return session;
}

SSL* acquire_session(Session* session) {
    if (!session->ssl) {
        session->ssl = SSL_new(session->ctx);
    }
    return session->ssl;
}

void release_session(Session* session) {
    SSL_free(session->ssl);
    EVP_CIPHER_CTX_cleanup(session->sym_ctx);
    free(session);
}
