    // Initialize dynamic array with provided capacity
    data_list = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data_list) {
        perror("Error allocating memory for data list");
        exit(EXIT_FAILURE);
    }

    // Initialize semaphores and mutex for synchronization
    sem_init(&sem_read, 0, capacity);
    sem_init(&sem_write, 0, 1);
    pthread_mutex_init(&mtx, NULL);

    this->capacity = capacity;
    this->size = 0;
}

// Function to add a new element to the data list with a random CRC_INDICATION_REL8_TAG
void add(void) {
    if (size == capacity) { // If list is full, dynamically resize it
        size_t new_capacity = capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(data_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            perror("Error resizing data list");
            exit(EXIT_FAILURE);
        }
        data_list = new_list;
        capacity = new_capacity;
    }

    sem_wait(&sem_write);  // Acquire write lock

    NFAPI_CRC_INDICATION_PDU_T *element = &data_list[size];
    element->tag = SOME_VALID_TAG;  // Set tag value here
    element->rnti = generate_rnti();  // Generate RNTI value using external data source
    element->crc_indication.crcflag = (rand() % 2) ? true : false;  // Set CRC flag randomly

    size++;

    sem_post(&sem_write);   // Release write lock
}

// Implement the main function for processing incoming data packets, leveraging multi-threading and load balancing
void process(void) {
    pthread_t threads[NUM_THREADS];
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, process_worker, &data_list)) {
