        }
    }

    // Wait for all threads to finish processing data packets
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Error joining thread");
            exit(EXIT_FAILURE);
        }
    }
}

// Worker function for each processing thread, leveraging the data list and synchronization mechanisms
void* process_worker(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *data_list = (NFAPI_CRC_INDICATION_PDU_T *)arg;

    while (true) {
        sem_wait(&sem_read);  // Acquire read lock

        // Process incoming data packets here, ensuring thread-safety
        NFAPI_CRC_INDICATION_PDU_T *element = &data_list[0];

        if (size == 0) {
            sem_post(&sem_read);   // Release read lock and continue looping
            continue;
        }

        // Process the first element and move it to the end of the list
        process_packet(element);
        memmove(&data_list[0], &data_list[1], (size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        size--;

