#include <arpa/inet.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    char device_name[17]; // 16 characters for device name + null terminator
    struct in_addr ip;
    unsigned short port;
    void* security_profile;
    void (*event_handler)(void);
    pthread_mutex_t mutex;
} NetworkInterfaceConfig;

#define NETWORK_INTERFACE_CONFIG_ERROR_INVALID_NAME 1
#define NETWORK_INTERFACE_CONFIG_ERROR_IP_INVALID 2
#define NETWORK_INTERFACE_CONFIG_ERROR_PORT_MISSING 3
#define NETWORK_INTERFACE_CONFIG_ERROR_SECURITY_PROFILE 4
#define NETWORK_INTERFACE_CONFIG_ERROR_EVENT_HANDLER 5
#define NETWORK_INTERFACE_CONFIG_ERROR_RESOURCE_LIMIT 6

int init_network_interface_config(NetworkInterfaceConfig* config, const char* device_name, const struct in_addr ip, unsigned short port, void* security_profile, void (*event_handler)(void)) {
    if (device_name == NULL || strlen(device_name) > 16) {
        return NETWORK_INTERFACE_CONFIG_ERROR_INVALID_NAME;
    }

    if (ip.s_addr == 0) {
        return NETWORK_INTERFACE_CONFIG_ERROR_IP_INVALID;
    }

    if (port == 0 || port > USHRT_MAX) {
        return NETWORK_INTERFACE_CONFIG_ERROR_PORT_MISSING;
    }

    if (security_profile == NULL) {
        return NETWORK_INTERFACE_CONFIG_ERROR_SECURITY_PROFILE;
    }

    if (event_handler == NULL) {
        return NETWORK_INTERFACE_CONFIG_ERROR_EVENT_HANDLER;
    }

    pthread_mutex_init(&config->mutex, NULL);
    strcpy(config->device_name, device_name);
    config->ip = ip;
    config->port = port;
    config->security_profile = security_profile;
    config->event_handler = event_handler;

    return 0;
}
