#define MAX_JSON_SIZE (1048576) // 1 MB

namespace js = nlohmann;

bool isValidAccessToken(const std::string& jsonStr) {
    uintmax_t jsonSize = jsonStr.size();

    if (jsonSize > MAX_JSON_SIZE) {
        throw std::runtime_error("Input too large, exceeds maximum allowed JSON size.");
    }

    js::Json json;

    try {
        json = js::Json::parse(jsonStr);
    } catch (const js::parse_error& ex) {
        std::cerr << "JSON parsing error: " << ex.what() << std::endl;
        return false;
    }

    if (!json.contains("access_token") || !json["access_token"].is_string()) {
        std::cerr << "Missing or invalid 'access_token' field." << std::endl;
        return false;
    }

    if (json["access_token"].get<std::string>().empty()) {
        std::cerr << "Empty 'access_token' value." << std::endl;
        return false;
    }

    if (!json.contains("expires_in") || !json["expires_in"].is_number() || json["expires_in"].get<int>() <= 0) {
        std::cerr << "Invalid or missing 'expires_in' field." << std::endl;
        return false;
    }

    if (!json.contains("token_type") || !js::serialize(json["token_type"]) == "\"Bearer\"") {
        std::cerr << "Invalid or missing 'token_type' field." << std::endl;
        return false;
    }

    if (json.contains("refresh_token")) {
        try {
            uuid_t temp_uuid;
            std::stringstream ss(json["refresh_token"].get<std::string>());
            uint8_t bytes[16];

            if (ss >> std::hex >> std::setw(2) >> std::setfill('0') >> bytes[0]
                >> std::setw(2) >> bytes[1]
                >> std::setw(2) >> bytes[2]
                >> std::setw(2) >> bytes[3]
                >> std::setw(4) >> bytes[4]
                >> std::setw(4) >> bytes[5]
                >> std::setw(4) >> bytes[6]
                >> std::setw(4) >> bytes[7]
                >> std::setw(12) >> uuid_parse(bytes, temp_uuid)) {
                if (memcmp(json["refresh_token"].get<std::string>().c_str(), uuid_unparse(temp_uuid), 36) != 0) {
                    std::cerr << "Invalid 'refresh_token' value." << std::endl;
                    return false;
                }
            } else {
                std::cerr << "Invalid UUID format in 'refresh_token' field." << std::endl;
                return false;
            }
        } catch (const std::exception& ex) {
            std::cerr << "Error while parsing 'refresh_token': " << ex.what() << std::endl;
            return false;
        }
    }

    return true;
}
