using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

public class EmailValidator
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, bool> _cache;

    public EmailValidator()
    {
        _httpClient = new HttpClient();
        _cache = new ConcurrentDictionary<string, bool>();
    }

    public async Task<bool[]> ValidateEmails(string[] emailAddresses)
    {
        var tasks = new List<Task<bool>>();

        foreach (var email in emailAddresses)
        {
            tasks.Add(ValidateEmailAsync(email));
        }

        var results = await Task.WhenAll(tasks);

        // Cache the validation results for future use
        Parallel.ForEach(results, result => CacheResult(emailAddresses, result));

        return results;
    }

    private async Task<bool> ValidateEmailAsync(string email)
    {
        var request = new HttpRequestMessage
        {
            Method = HttpMethod.Post,
            RequestUri = new Uri("YOUR_VALIDATION_SERVICE_URL"),
            Content = new StringContent(JsonSerializer.Serialize(new
            {
                timestamp = DateTimeOffset.Now.ToUnixTimeSeconds(),
                inputListSize = emailAddresses.Length,
                validationStatus = _cache.ContainsKey(email) ? _cache[email] : false
            }), System.Text.Encoding.UTF8, "application/json")
        };

        try
        {
            var response = await _httpClient.SendAsync(request);
            if (response.IsSuccessStatusCode)
            {
                var responseContent = await response.Content.ReadAsStringAsync();
                return JsonSerializer.Deserialize<bool>(responseContent);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error validating email: {ex.Message}");
        }

        // Default to false in case of network failure or invalid response from the service
        return false;
    }

    private void CacheResult(string[] emailAddresses, bool result)
    {
        foreach (var email in emailAddresses)
        {
            if (_cache.GetOrAdd(email, result))
            {
                _cache[email] = true;
                break;
            }
        }
    }
}
