using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

namespace SecureMessageProcessor
{
    public class SecureMessageProcessor
    {
        private readonly ILogger<SecureMessageProcessor> _logger;
        private readonly ICryptoTransform _encryptor;
        private readonly ICryptoTransform _decryptor;
        private readonly int _maxRetries;
        private readonly TimeSpan _retryDelay;
        private readonly string _metadataServiceUrl;

        public SecureMessageProcessor(ILogger<SecureMessageProcessor> logger, Rfc2898DeriveBytes keyGenerator, CryptoConfig cryptoConfig, ConfigManager config)
        {
            _logger = logger;
            var aesProvider = cryptoConfig.GetAesProvider();
            using (var symmetricKey = keyGenerator.GenerateKey(aesProvider.KeySize))
            {
                _encryptor = aesProvider.CreateEncryptor(symmetricKey, cryptoConfig.GetIV());
                _decryptor = aesProvider.CreateDecryptor(symmetricKey, cryptoConfig.GetIV());
            }
            _maxRetries = config.GetInt("MaxRetries");
            _retryDelay = TimeSpan.FromSeconds(config.GetFloat("RetryDelay"));
            _metadataServiceUrl = config.GetString("MetadataServiceUrl");
        }

        public byte[] ProcessMessage(byte[] ciphertext, string key, string iv, PaddingMode padding)
        {
            try
            {
                using (var ms = new MemoryStream(ciphertext))
                {
                    using (var transform = _decryptor.CreateTransform(padding))
                    {
                        var plainTextBytes = new byte[ms.Length];
                        transform.TransformBlock(ms.ToArray(), 0, ms.Length, plainTextBytes, 0);
                        return plainTextBytes;
                    }
                }
            }
            catch (CryptographicException ex)
            {
                _logger.LogError(ex, "Decryption failed: {Reason}", ex.Message);
                if (!RetryDecryption(ciphertext))
                {
                    return null;
                }
            }
        }

        private bool RetryDecryption(byte[] ciphertext)
        {
            var retriesLeft = _maxRetries;
            while (retriesLeft > 0 && !SuccessfulDecryptionAttempt(ciphertext))
            {
                _logger.LogInformation("Decryption failed, retrying in {Delay}", _retryDelay.TotalSeconds);
                System.Threading.Thread.Sleep(_retryDelay);
                retriesLeft--;
            }
            return retriesLeft > 0;
        }

        private bool SuccessfulDecryptionAttempt(byte[] ciphertext)
        {
            var validationResult = ValidateMetadata(ciphertext);
            if (validationResult.Success)
            {
                try
                {
                    using (var ms = new MemoryStream(ciphertext))
                    {
                        using (var transform = _decryptor.CreateTransform(CryptoConfig.GetPadding(_padding)))
                        {
                            var plainTextBytes = new byte[ms.Length];
                            transform.TransformBlock(ms.ToArray(), 0, ms.Length, plainTextBytes, 0);
                            return true;
                        }
                    }
                }
                catch (CryptographicException ex)
                {
                    _logger.LogError(ex, "Decryption failed: {Reason}", ex.Message);
                    return false;
                }
            }
            else
            {
                _logger.LogError("Validation failed due to metadata error: {ErrorMessage}", validationResult.ErrorMessage);
                return false;
            }
        }

        private JObject ValidateMetadata(byte[] ciphertext)
        {
            var client = new HttpClient();
            var request = new HttpRequestMessage
            {
                Method = HttpMethod.Get,
                RequestUri = new Uri(_metadataServiceUrl),
                Headers =
                {
                    { "Content-Type", "application/json" },
                    { "Ciphertext", Convert.ToBase64String(ciphertext) }
                }
            };

            var response = client.SendAsync(request).Result;
            if (!response.IsSuccessStatusCode)
            {
                return new JObject
                {
                    {"Success", false},
                    {"ErrorMessage", response.ReasonPhrase}
                };
            }

            var content = response.Content.ReadAsStringAsync().Result;
            return JObject.Parse(content);
        }
    }
}
