using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Collections.Concurrent;
using System.Text;

public class CustomData
{
    public int Id { get; set; }
    public string Name { get; set; }
    // Add other properties as needed
}

public class DataLoader
{
    private readonly string _filePath;
    private readonly ConcurrentDictionary<Guid, CustomData> _cache = new ConcurrentDictionary<Guid, CustomData>();

    public DataLoader(string filePath)
    {
        _filePath = filePath;
    }

    public CustomData LoadData()
    {
        if (!File.Exists(_filePath)) return null;

        BinaryFormatter formatter = new BinaryFormatter();
        using (FileStream stream = File.OpenRead(_filePath))
        {
            try
            {
                lock (_cache)
                {
                    CustomData data;
                    if (_cache.TryGetValue(stream.Position, out data)) return data;
                }

                data = (CustomData)formatter.Deserialize(stream);
                Guid cacheKey = stream.Position.GetHashCode().ToString("N").ToLower();
                _cache[cacheKey] = data;
                return data;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error loading data: {ex.Message}");
                return null;
            }
        }
    }

    public void ClearCache()
    {
        _cache.Clear();
    }
}
