    std::atomic<uint64_t> peak_memory{0};
    pthread_cond_t cond;
};

void* memory_manager_worker(void* arg) {
    struct memory_manager* mm = static_cast<struct memory_manager*>(arg);
    // Implement the multi-threading and load balancing strategy here.
}

void enqueue_frame(struct memory_manager* mm, LTE_PHY_RX_FRAME_PDU_T frame) {
    pthread_mutex_lock(&mm->lock);
    if (mm->size == mm->capacity) {
        mm->capacity *= 2;
        mm->data = static_cast<LTE_PHY_RX_FRAME_PDU_T**>(realloc(mm->data, sizeof(LTE_PHY_RX_FRAME_PDU_T*) * mm->capacity));
    }
    LTE_PHY_RX_FRAME_PDU_T* new_frame = static_cast<LTE_PHY_RX_FRAME_PDU_T*>(realloc(mm->data[mm->size], sizeof(LTE_PHY_RX_FRAME_PDU_T)));
    if (!new_frame) {
        mm->failed_allocs++;
    } else {
        memcpy(new_frame, &frame, sizeof(LTE_PHY_RX_FRAME_PDU_T));
        new_frame->crc_indication.CRCFLAG = (rand() % 2) == 0;
        mm->size++;
        mm->successful_allocs++;
    }
    pthread_mutex_unlock(&mm->lock);
}

void diagnostics(struct memory_manager* mm) {
    // Implement self-diagnostic tool here.
}

void start_memory_manager(struct memory_manager* mm, size_t num_threads) {
    pthread_t* threads = new pthread_t[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(threads + i, NULL, memory_manager_worker, mm)) {
            fprintf(stderr, "Failed to create thread\n");
            exit(1);
        }
    }
}

void stop_memory_manager(struct memory_manager* mm) {
    mm->running = false;
    pthread_mutex_lock(&mm->lock);
    if (mm->size > 0) {
        free(mm->data[0]);
        memmove(mm->data, mm->data + 1, (mm->size - 1) * sizeof(LTE_PHY_RX_FRAME_PDU_T*));
        free(mm->data[mm->size - 1]);
        mm->size--;
    }
    free(mm->data);
    pthread_mutex_unlock(&mm->lock);
    pthread_cond_destroy(&mm->cond);
}
