public class KickstartModifier {
    private static final String LOG_FILE = "kickstart_log.txt";
    private static final int MAX_RETRIES = 3;
    private static final long BACKOFF_SCALING_FACTOR = 2L;
    private static final int TIMEOUT_DEFAULT = 5000;
    private static final int RATE_LIMIT_PER_MINUTE = 5;

