    public void modifyKickstartFile(Map<String, String> placeholders, String filePath) throws ModificationFailedException {
        try (BufferedWriter logWriter = Files.newBufferedWriter(this.logPath, StandardOpenOption.APPEND)) {
            long startTime = Instant.now().toEpochMilli();
            ProcessBuilder pb = new ProcessBuilder("sed", "-i", "", filePath);
            AtomicBoolean success = new AtomicBoolean(false);
            pb.redirectOutput(ProcessBuilder.Redirect.APPEND, logPath.resolveSibling("modification_log.txt"));
