                pb.command().add("-e", String.format("s/%s/%s/g", entry.getKey(), entry.getValue()));
            }
            pb.redirectErrorStream(true);
            Process process = pb.start();
            long timeout = TIMEOUT_DEFAULT;
            process.waitFor(timeout, TimeUnit.MILLISECONDS);
            if (!process.exitValue() == 0) {
                throw new ModificationFailedException("Modification failed!");
            }
            success.set(true);
            logWriter.write(String.format("Modified kickstart file at %s in %.2f seconds%n", filePath, (Instant.now().toEpochMilli() - startTime) / 1000.0));
        } catch (IOException | InterruptedException | ExecutionException e) {
            throw new ModificationFailedException("Modification failed!", e);
