import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.ClassNotFoundException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class Deserializer {
    private static final String CHECKSUM_KEY = "checksum";
    private static final String VERSION_KEY = "version";

    public Object deserialize(byte[] data) throws IOException, ClassNotFoundException, NoSuchAlgorithmException, InstantiationException, IllegalAccessException, InvocationTargetException {
        if (!isValidData(data)) {
            throw new RuntimeException("Invalid or corrupted data");
        }

        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data));
        String checksum = (String) ois.readObject();
        int version = ois.readInt();

        if (!checkDataIntegrity(checksum, version)) {
            throw new RuntimeException("Data has incorrect metadata");
        }

        return ois.readObject();
    }

