    if args.len() < 2 {
        eprintln!("Usage: {} [task_id] [config_file]", args[0]);
        std::process::exit(1);
    }

    let task_id = &args[1];
    let config_path = PathBuf::from(&args[2]);

    let config: Config = serde_json::from_reader(File::open(config_path)?).unwrap();

    let mut runtime = Runtime::new().unwrap();

    let mut tasks = vec![];

    match task_id.as_str() {
        "task1" => tasks.push(async move { /* Implement task1 here */ }),
        "task2" => tasks.push(async move { /* Implement task2 here */ }),
        "task3" => tasks.push(async move { /* Implement task3 here */ }),
        "task4" => tasks.push(async move { /* Implement task4 here */ }),
        _ => eprintln!("Invalid task_id: {}", task_id),
    }

    let max_concurrent = runtime.current_thread_count().saturating_sub(1);
    let mut active_tasks = vec![];

    loop {
        let available_slots = max_concurrent - active_tasks.len();
        if available_slots > 0 && !tasks.is_empty() {
            match tasks.pop() {
                Some(task) => active_tasks.push(runtime.spawn(task)),
                None => break,
            }
        }

        let mut completed_tasks = vec![];

        while let Some(completed_task) = active_tasks.drain(..) {
            if let Err(e) = completed_task.await {
                eprintln!("Error in task: {}", e);
            } else {
                completed_tasks.push(());
            }
        }

        active_tasks.extend(completed_tasks);

        tokio::time::sleep(std::time::Duration::from_secs(1)).await;
    }

    // Implement health check endpoint here.

    Ok(())
}
```

