fn setup_logging(file: Option<&Path>) -> Result<(), Box<dyn std::error::Error> > {
    let mut log_file = LOG_FILE.with(|| {
        match file {
            Some(path) => Some(Mutex::new(BufWriter::new(File::create(path)?))),
            None => None,
        }
    });

    if let Some(ref mut log) = *log_file {
        log.lock().unwrap().flush()?;
    }

