            Ok::<RgbImage<u8>, Box<dyn std::error::Error>>(resized_frame)
        })
        .collect::<Result<Vec<RgbImage<u8>>, _>>()?;

    for (i, frame) in resized_frames.iter().enumerate() {
        save_jpeg(format!("{}.jpeg", i), frame)?;
        debug!(target: "frame_{}", i, "Saving frame");
    }

    Ok(())
}

