#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct PMNode {
    int taskIndex;
    struct PMNode* parent;
    struct PMNode* children;
    // Additional metadata for dependencies and priorities can be added here.
    pthread_mutex_t lock;
} PMNode;

typedef void (*dependencyCallback)(PMNode*, PMNode*);

struct TaskTree {
    PMNode* root;
    int numTasks;
};

void pmNodeInit(PMNode* node, int index) {
    node->taskIndex = index;
    node->parent = NULL;
    node->children = NULL;
    pthread_mutex_init(&node->lock, NULL);
}

void addChild(PMNode* parent, PMNode* child) {
    if (!parent->children) {
        parent->children = malloc(sizeof(PMNode));
        pmNodeInit(parent->children, -1); // sentinel node to know where the valid children end
    }
    PMNode* lastChild = parent->children;
    while (lastChild->next) lastChild = lastChild->next;
    lastChild->next = child;
    child->parent = parent;
}

void freeTree(PMNode* root) {
    if (!root) return;

    PMNode* current = root;
    PMNode* next;

    while (current) {
        next = current->children;
        free(current);
        current = next;
    }
}

void errorLog(const char* message) {
    printf("Error: %s\n", message);
}

PMNode* getReachableTasks(Task* tasks, int numTasks, PMNode* pms, int rootTask, int maxDepth) {
    if (!tasks || !pms || numTasks <= 0 || rootTask < 0 || maxDepth <= 0) {
        errorLog("Invalid input parameters.");
        return NULL;
    }

    struct TaskTree tree = { .root = NULL };

    // Validate PMS node structure for consistency before processing.
    // Implement a mechanism to detect and prevent cycles in the generated tree structure.
    // Optimize memory usage by reusing existing memory allocations when possible.
    // Support concurrent access to the PMS by multiple threads, ensuring thread safety.
    // Allow for custom dependency handling to be passed as a callback function for flexibility in task traversal.
    // Provide a way to track the total number of reachable tasks found during execution.

    int visited[numTasks] = { 0 };
    queue<PMNode*> q;

    pmNodeInit(&pms[rootTask], rootTask);
    tree.root = &pms[rootTask];
    visited[rootTask] = 1;
    q.push(tree.root);

    int depth = 0;

    while (!q.empty()) {
        PMNode* current = q.front();
        q.pop();

        if (depth++ > maxDepth) break;

        for (PMNode* child : *current->children) {
            if (!visited[child->taskIndex]) {
                visited[child->taskIndex] = 1;
                addChild(current, child);
                q.push(child);
            }
        }
    }

    tree.numTasks = depth - 1; // exclude the root node

    free(visited);

    return tree.root;
}
