import PrintWriter;

public class FileProcessor {

    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private static final MessageDigest sha256 = MessageDigest.getInstance("SHA-384");

    public void processFiles(List<String> filePaths) throws IOException, InterruptedException {
        CompletionService<byte[]> completionService = Executors.newCompletionService(executor);

        List<Future<byte[]>> futures = filePaths.stream()
                .map(path -> {
                    Callable<byte[]> callable = () -> readFileAndCalculateHash(path);
                    return completionService.submit(callable);
                })
                .collect(Collectors.toList());

        for (Future<byte[]> future : futures) {
            future.get();
        }

        executor.shutdown();

        List<byte[]> hashes = completionService.takeAll().stream()
                .map(cs -> cs.get())
                .collect(Collectors.toList());

        // Execute shell command to retrieve external data and write output to browser
        ProcessBuilder pb = new ProcessBuilder("sh", "-c", "command");
        pb.redirectErrorStream(true);
        Process p = pb.start();
        try (PrintWriter writer = new PrintWriter(p.getOutputStream())) {
            // Write some data here
        }

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }
    }

    private byte[] readFileAndCalculateHash(String filePath) throws IOException {
        try (InputStream is = Files.newInputStream(Paths.get(filePath))) {
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                sha256.update(buffer, 0, bytesRead);
            }
            return sha256.digest();
        }
    }
}
