use std::env;
use std::fs::File;
use std::io::{BufReader, Error as IoError};
use serde::{Deserialize, Serialize};
use serde_derive::Deserialize;
use serde_json::from_reader;
use tokio::fs::File as AsyncFile;
use tokio::prelude::*;
use tokio::sync::RwLock;
use md5;
use log::{error, info};
use structopt::StructOpt;

#[derive(Serialize, Deserialize, Debug)]
struct Data {
    // Define your custom data structure here
}

#[derive(StructOpt)]
struct Opt {
    /// Path to the binary file
    input: String,
    #[structopt(long = "cache")]
    cache: bool,
    #[structopt(flatten)]
    verbose: bool,
}

async fn load_data(path: &str) -> Result<Data, IoError> {
    let file = AsyncFile::open(path).await?;
    let reader = BufReader::new(file);
    from_reader::<_, Data>(reader).unwrap()
}

struct Cache {
    cache: RwLock<Option<Data>>,
}

impl Cache {
    async fn get(&self, path: &str) -> Option<&Data> {
        self.cache.read().await.clone()
    }

    async fn put(&mut self, path: &str, data: Data) {
        *self.cache.write().await = Some(data)
    }
}

async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let opt = Opt::from_args();
    let cache = Cache { cache: RwLock::new(None) };

    let data = match cache.get(&opt.input).await {
        Some(data) if !opt.cache => None,
        _ => data,
    };

    if let Err(e) = data.map_or_else(|| load_data(&opt.input).await, |cached| Ok(cached)) {
        error!("Error loading data: {}", e);
        return Ok(());
    }

    let md5 = md5::compute(data.as_ref().unwrap().serialize());
    info!("MD5 hash of data: {}...", hex::encode(md5));

    if opt.verbose {
        // You can print additional debug information here
    }

    if opt.input != env::args().nth(1).unwrap() {
        cache.put(&opt.input, data.unwrap()).await;
    }

    Ok(())
}

#[tokio::main]
async fn run() -> Result<(), Box<dyn std::error::Error>> {
    let _ = env_logger::init();
    main().await
}
