NFAPI_CRC_INDICATION_PDU_T* initStructures(size_t N) {
    if (N > MAX_STRUCTURES || N == 0) {
        log("Error: Invalid input value for number of structures.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *structures = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        log("Error: Out of memory.");
        return NULL;
    }

