    float decimal_value;
    time_t timestamp;
    enum measurement_type type;
};

typedef struct sensor_data_container {
    size_t capacity;
    size_t size;
    struct sensor_data* data;
} sensor_data_container;

sensor_data_container* init_sensor_data_container(size_t max_entries) {
    sensor_data_container* container = malloc(sizeof(sensor_data_container));
    container->capacity = max_entries;
    container->size = 0;
    container->data = calloc(max_entries, sizeof(struct sensor_data));
    return container;
}

void destroy_sensor_data_container(sensor_data_container* container) {
    free(container->data);
    free(container);
}

int add_sensor_data(sensor_data_container* container, struct sensor_data data) {
    if (container->size >= container->capacity) {
        return 0; // Reached capacity limit.
    }

    container->data[container->size] = data;
    ++container->size;
    return 1;
}

// Generates a random timestamp for testing purposes only.
time_t generate_timestamp() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return tv.tv_sec * 1000 + tv.tv_usec / 1000;
}

// A simple aggregation function for demonstration purposes only.
void aggregate(sensor_data_container* container) {
    struct sensor_data temp;
    float total = 0, avg;
    size_t count = 0;

    // Iterate through the container and filter by measurement type.
    for (size_t i = 0; i < container->size; ++i) {
        if (container->data[i].type == TEMPERATURE || container->data[i].type == HUMIDITY) {
            total += container->data[i].decimal_value;
            ++count;
        }
    }

    avg = total / count;

    // Initialize the aggregate data structure.
    temp.type = TEMPERATURE;
    temp.decimal_value = avg;
    temp.timestamp = generate_timestamp();

    printf("Aggregated data: %.2f at timestamp %ld\n", temp.decimal_value, temp.timestamp);
}

int main() {
    sensor_data_container* container = init_sensor_data_container(100); // Initialize a container with 100 entries.

    // Simulate data from the sensor network.
    struct sensor_data sensor_data_1;
    sensor_data_1.value = 25;
    sensor_data_1.decimal_value = 37.5;
    sensor_data_1.timestamp = generate_timestamp();
    sensor_data_1.type = TEMPERATURE;

    if (add_sensor_data(container, sensor_data_1)) {
        printf("Added sensor data with value %.2f at timestamp %ld\n", sensor_data_1.decimal_value, sensor_data_1.timestamp);
    } else {
        fprintf(stderr, "Failed to add sensor data due to capacity limit.\n");
    }

    // Aggregate the sensor data.
    aggregate(container);

    destroy_sensor_data_container(container);

    return 0;
}
