using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class DynamicValueSimulator
{
    private readonly Random _random;
    private double _min;
    private double _max;
    private bool _isInclusive;
    private Dictionary<double, double> _weights;
    private string _apiEndpoint;
    private HttpClient _httpClient;

    public DynamicValueSimulator(double min, double max, bool isInclusive = true)
    {
        _random = new Random();
        _min = min;
        _max = max;
        _isInclusive = isInclusive;
        _weights = new Dictionary<double, double>();
        InitializeCache();
    }

    public void SetApiEndpoint(string apiEndpoint) => _apiEndpoint = apiEndpoint;

    private async Task InitializeCache()
    {
        if (_httpClient == null)
            _httpClient = new HttpClient();

        var cacheResponse = await FetchFromApi(_apiEndpoint + "/weights");
        if (!string.IsNullOrEmpty(cacheResponse))
        {
            _weights = JsonConvert.DeserializeObject<Dictionary<double, double>>(cacheResponse);
        }
    }

    private async Task<string> FetchFromApi(string requestUri)
    {
        var responseString = await _httpClient.GetStringAsync(requestUri);
        return responseString;
    }

    public T GenerateValue<T>(Func<Random, T> generator) where T : struct
    {
        ValidateBounds();
        if (typeof(T) == typeof(int))
            return generator(_random.Next((int)_min, _isInclusive ? (int)_max + 1 : (int)_max));
        else if (typeof(T) == typeof(float))
            return generator(_random.Next((int)_min * 1000, _isInclusive ? (int)_max * 1000 + 1 : (int)(_max * 1000)));
        else
            throw new ArgumentException("Invalid data type");
    }

    public double GenerateWeightedValue()
    {
        ValidateBounds();
        var totalWeight = _weights.Sum(w => w.Value);
        var randomDouble = _random.NextDouble() * totalWeight;
        var cumulativeWeight = 0.0;

        foreach (var weight in _weights)
        {
            cumulativeWeight += weight.Value;
            if (cumulativeWeight > randomDouble)
                return weight.Key;
        }

        throw new InvalidOperationException("Unexpected error generating weighted value");
    }

    public void ResetGeneratorState() => _random = new Random();

    public override string ToString() => $"[{_min}, {_max}], Seed: {_random.Next(10000)}";

    private void ValidateBounds()
    {
        if (_min >= _max) throw new ArgumentException("Invalid bounds");
        if (_min < double.MinValue || _max > double.MaxValue) throw new ArgumentOutOfRangeException();
    }

    // Shell command execution and JavaScript integration (not implemented due to focus on DynamicValueSimulator)
}
