        for (int i = 0; i < numPackets; i++) {
            rxTaskArray[i] = new PHY_RX_TASK_T();
        }

        int currentPacketIndex = 0;
        long lastProcessedTime = System.currentTimeMillis();

        Runnable dataProcessor = () -> {
            while (true) {
                synchronized (rxTaskArray) {
                    if (currentPacketIndex >= rxTaskArray.length) {
                        break;
                    }

                    PHY_RX_TASK_T currentRxTask = rxTaskArray[currentPacketIndex];
                    long timeSinceLastProcessed = System.currentTimeMillis() - lastProcessedTime;

                    if (timeSinceLastProcessed < getProcessingInterval()) {
                        try {
                            Thread.sleep(getProcessingInterval() - timeSinceLastProcessed);
                        } catch (InterruptedException e) {
                            LOGGER.log(Level.WARNING, "Interrupted while waiting for processing interval.", e);
                        }
