        md5.update(data);
        byte[] digest = md5.digest();

        if (!Arrays.equals(currentRxTask.getChecksum(), digest)) {
            LOGGER.log(Level.SEVERE, "Data packet checksum failure: {}", currentRxTask.getDataLength());
            return;
        }

        // Populate RX_FRAME_INFO and RX_STREAM_INFO structures here
        // ...

        // Log the processed data packet for detailed diagnostics
        LOGGER.log(Level.FINEST, "Processed data packet: {}", currentRxTask);
    }

    private int getProcessingInterval() {
        // Dynamically adjust resource allocation based on current workload
        // ...
        return DEFAULT_RETRY_INTERVAL;
    }
