#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RX_RFI_INFORMATION_TAG;
    uint16_t RFI_ID;
    uint64_t timestamp; // Timestamp in nanoseconds
    bool status_flag;
} NFAPI_PHY_RX_INDICATION_PDU_T;

typedef struct __node {
    NFAPI_PHY_RX_INDICATION_PDU_T data;
    struct __node *next;
    pthread_mutex_t lock;
} Node;

struct dynamic_list {
    int num_interfaces;
    Node** list;
    pthread_mutex_t lock;
};

struct dynamic_list* create_dynamic_list(int num_interfaces) {
    struct dynamic_list* dl = (struct dynamic_list*)malloc(sizeof(struct dynamic_list));
    dl->num_interfaces = num_interfaces;
    dl->list = (Node**)calloc(num_interfaces, sizeof(Node*));
    dl->lock = PTHREAD_MUTEX_INITIALIZER;
    return dl;
}

void add_to_list(struct dynamic_list* dl, int rfi_id, NFAPI_PHY_RX_INDICATION_PDU_T data) {
    pthread_mutex_lock(&dl->lock);
    if (dl->list[rfi_id] == NULL) {
        dl->list[rfi_id] = (Node*)malloc(sizeof(Node));
        dl->list[rfi_id]->data = data;
        dl->list[rfi_id]->next = NULL;
    } else {
        Node* current = dl->list[rfi_id];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = (Node*)malloc(sizeof(Node));
        current = current->next;
        current->data = data;
        current->next = NULL;
    }
    pthread_mutex_unlock(&dl->lock);
}

int get_total_elements(struct dynamic_list* dl) {
    int total = 0;
    for (int i = 0; i < dl->num_interfaces; ++i) {
        Node* current = dl->list[i];
        while (current != NULL) {
            ++total;
            current = current->next;
        }
    }
    return total;
}

void destroy_dynamic_list(struct dynamic_list* dl) {
    for (int i = 0; i < dl->num_interfaces; ++i) {
        Node* current = dl->list[i];
        Node* temp;
        while (current != NULL) {
            temp = current;
            current = current->next;
            free(temp);
        }
        dl->list[i] = NULL;
    }
    free(dl->list);
    free(dl);
}
