    }

    private void processDataQueue(List<PHY_RX_TASK_T> taskArray) {
        while (!dataQueue.isEmpty()) {
            byte[] data = dataQueue.poll();
            try {
                handlePacket(taskArray, data);
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Failed to process packet.", e);
            }
        }
    }

    private void handlePacket(List<PHY_RX_TASK_T> taskArray, byte[] data) {
        RX_FRAME_INFO rxFrameInfo = new RX_FRAME_INFO();
        RX_STREAM_INFO rxStreamInfo = new RX_STREAM_INFO();

        try {
            // Calculate checksum and set other fields in RX_FRAME_INFO
            // Parse data format and packet type in RX_STREAM_INFO
            // Integrate with existing hardware and software components to process the data

            // If data length is incorrect, handle it gracefully (buffer overflow prevention)
            if (data.length > MAX_PACKET_LENGTH) {
                throw new IllegalArgumentException("Incorrect packet length.");
            }
        } catch (Exception e) {
            LOGGER.log(Level.WARN, "Invalid data packet encountered.", e);
            if (isDataLossThresholdExceeded()) {
                LOGGER.log(Level.ERROR, "Packet loss threshold exceeded. Aborting operation.");
                shutdownExecutor();
            } else {
                retryProcessPacket(data);
            }
            return;
        }

        // Set RX_FRAME_INFO and RX_STREAM_INFO fields in the corresponding PHY_RX_TASK_T instances
        for (int i = 0; i < taskArray.size(); i++) {
            if (i >= data.length) break;

            PHY_RX_TASK_T task = taskArray.get(i);
            task.setRxFrameInfo(rxFrameInfo);
            task.setRxStreamInfo(rxStreamInfo);
        }
    }

    private void shutdownExecutor() {
        executor.shutdownNow();
        try {
            executor.awaitTermination(60, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private boolean isDataLossThresholdExceeded() {
        return dataQueue.size() > packetLossThreshold;
    }

    private void retryProcessPacket(byte[] data) {
        try {
            Thread.sleep(retryInterval);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        dataQueue.add(data);
    }

