#define RING_BUFFER_SIZE (64 * 1024) // Adjust as needed for your use case
typedef struct {
    unsigned int rx_rfi_information_tag;
    uint8_t rfi_id;
    union {
        struct {
            time_t timestamp;
            uint32_t status_flag;
            uint16_t additional_indicator_type1;
            uint16_t additional_indicator_type2;
            // Add more indicator types as needed
        } phy_rx_indication;
        void *data;
    };
} NFAPI_PHY_RX_INDICATION_PDU_T;

typedef struct node {
    NFAPI_PHY_RX_INDICATION_PDU_T data;
    struct node* next;
} Node;

struct ring_buffer {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
};

void rb_init(struct ring_buffer *rb, size_t num_interfaces) {
    if (num_interfaces > RING_BUFFER_SIZE / sizeof(Node)) {
        fprintf(stderr, "Insufficient memory for requested number of interfaces.\n");
        return;
    }

    rb->head = NULL;
    rb->tail = NULL;
    rb->size = num_interfaces * 2; // Allocate extra space for backpressure
    pthread_mutex_init(&rb->lock, NULL);
}

void rb_push(struct ring_buffer *rb, const NFAPI_PHY_RX_INDICATION_PDU_T *data) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Memory allocation failure.\n");
        return;
    }

    pthread_mutex_lock(&rb->lock);
    node->data = *data;
    node->next = NULL;

    if (rb->head == NULL) {
        rb->head = node;
        rb->tail = node;
    } else {
        rb->tail->next = node;
        rb->tail = node;
    }

    if (rb->size == rb->head - &rb->head[0]) { // Backpressure: ring buffer full
        fprintf(stderr, "Ring buffer full. Implement backpressure mechanism.\n");
    }

    pthread_mutex_unlock(&rb->lock);
}

const NFAPI_PHY_RX_INDICATION_PDU_T* rb_pop(struct ring_buffer *rb) {
    if (pthread_mutex_trylock(&rb->lock)) {
        return NULL; // Returning NULL signifies busy or locked state, allowing callers to handle this gracefully
    }

    Node* temp = rb->head;
    if (!temp) {
        pthread_mutex_unlock(&rb->lock);
        return NULL;
    }

    rb->head = temp->next;
    if (rb->head == NULL) {
        rb->tail = NULL;
    }

    pthread_mutex_unlock(&rb->lock);

    return &temp->data;
}
```

