typedef struct {
    uint8_t L2_RX_PACKET_INFO[4];
    uint8_t MAC_HEADER[6];
    uint8_t MAC_PAYLOAD[];
} NFAPI_L2_RX_PDU_T;

struct mac_addr_generator {
    pthread_mutex_t mutex;
    unsigned long last_id;
};

struct performance_logger {
    FILE *log_file;
    uint64_t packet_count;
    double total_time;
};

void *generate_mac_addr(void *arg) {
    struct mac_addr_generator *gen = arg;
    gen->last_id++;
    return malloc(sizeof(NFAPI_L2_RX_PDU_T) + 6 + (gen->last_id & 0xFF));
}

void log_performance(struct performance_logger *log) {
    log->total_time += chrono::steady_clock::now().time_since_epoch().count();
    fprintf(log->log_file, "Time: %.3fs, Packets processed: %llu\n", log->total_time / log->packet_count, log->packet_count);
}

NFAPI_L2_RX_PDU_T* create_data_buffer(struct mac_addr_generator *gen) {
    void *buf = mmap(NULL, sizeof(NFAPI_L2_RX_PDU_T) + 6 + (gen->last_id & 0xFF), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (buf == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    NFAPI_L2_RX_PDU_T *data = buf;
    data->L2_RX_PACKET_INFO[0] = 0x01; // Example L2_RX_PACKET_INFO
    memcpy(data->MAC_HEADER, gen->last_id >> 8, 2); // Extract high-order bytes for MAC address
    memcpy(data->MAC_HEADER + 4, gen->last_id & 0xFFFF, 2);
    data->MAC_PAYLOAD[0] = 0x5A; // Example MAC payload data

    return data;
}

void resize_buffer(NFAPI_L2_RX_PDU_T **buf, size_t new_size) {
    NFAPI_L2_RX_PDU_T *new_buf = realloc(*buf, new_size * sizeof(NFAPI_L2_RX_PDU_T));
    if (!new_buf) {
        perror("realloc failed");
        exit(EXIT_FAILURE);
    }
    *buf = new_buf;
}

void process_data(NFAPI_L2_RX_PDU_T *data, struct performance_logger *log) {
    // Process data here...
    log->packet_count++;
}

int main() {
    int fd = open("mac_addrs.bin", O_RDONLY);
    if (fd == -1) {
        perror("open failed");
        exit(EXIT_FAILURE);
    }

    struct stat st;
    fstat(fd, &st);
    void *map = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (map == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    struct mac_addr_generator gen = { .last_id = 0 };
    pthread_mutex_init(&gen.mutex, NULL);

    struct performance_logger log = { .log_file = fopen("performance.log", "w"), .packet_count = 0, .total_time = 0.0 };

    size_t buffer_size = st.st_size / (sizeof(NFAPI_L2_RX_PDU_T) + 6);
    NFAPI_L2_RX_PDU_T *buffer = malloc(buffer_size * sizeof(NFAPI_L2_RX_PDU_T));
    if (!buffer) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, generate_mac_addr, &gen);
    }

    sem_t resize_sem;
    sem_init(&resize_sem, 0, buffer_size);

    while (1) {
        void *data = mmap(NULL, sizeof(NFAPI_L2_RX_PDU_T) + 6, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
        if (data == MAP_FAILED) {
            perror("mmap failed");
            exit(EXIT_FAILURE);
        }

        NFAPI_L2_RX_PDU_T *data_ptr = data;

        pthread_t thread;
        pthread_create(&thread, NULL, generate_mac_addr, &gen);

        sem_wait(&resize_sem);
        if (buffer_size == count) {
            resize_buffer(&buffer, buffer_size * 2);
        }

        memcpy(buffer[count], data, sizeof(NFAPI_L2_RX_PDU_T) + 6);
        count++;

        process_data(buffer[count - 1], &log);

        munmap(data, sizeof(NFAPI_L2_RX_PDU_T) + 6);
    }

    pthread_join(threads[i], NULL);
    free(threads);

    fclose(log.log_file);

    // Cleanup and exit...
}
