        std::unordered_map<uint64_t, bool> rntiMap; // Use external data source to generate unique RNTI values
        std::mt19937 rng; // Mersenne Twister pseudo-random number engine
        std::uniform_int_distribution<> crcflagDist(0, 1);

        auto generator = [&]() -> NFAPI_CRC_INDICATION_PDU_T {
            NFAPI_CRC_INDICATION_PDU_T pdu;
