    time_t last_modified_time;
};

class HeaderManager {
public:
    // Constructor initializes cache and thread-safe queue
    HeaderManager(size_t cacheSize) : _cache(cacheSize), _queue(_numThreads) {}

    // Function to add a header, handling concurrent access using the queue
    std::unique_ptr<HTTP_RESPONSE_HEADERS_T> addHeader(const std::string& name, const std::string& value) {
        auto header = createHeader(name, value);
        _queue.push(header.get()); // Push new header to the queue for processing by worker threads
        return header;
    }

    // Function to get a header from cache or retrieve it using external API
    std::unique_ptr<HTTP_RESPONSE_HEADERS_T> getHeader(const std::string& name) {
        auto iter = _headers.find(name);
        if (iter != _headers.end()) return std::move(iter->second); // Return from cache if found

        // Retrieve header using external API and store in cache for future access
        auto newHeader = createHeaderFromAPI(name);
        _headers[name] = std::move(newHeader);
        return std::move(_headers[name]);
    }

private:
    std::unique_ptr<HTTP_RESPONSE_HEADERS_T> createHeader(const std::string& name, const std::string& value) {
        auto header = std::make_unique<HTTP_RESPONSE_HEADERS_T>();
        header->header_name = generateUniqueName(); // Call external API for generating unique header names
        header->header_value = value;
        header->last_modified_time = time(0);
        return header;
    }

    HTTP_RESPONSE_HEADERS_T createHeaderFromAPI(const std::string& name) {
        // Call external API to retrieve the header data
        // ...
    }

    boost::lockfree::spsc_queue<HTTP_RESPONSE_HEADERS_T*> _queue; // Thread-safe queue for new headers
    boost::circular_buffer<std::unique_ptr<HTTP_RESPONSE_HEADERS_T>> _cache; // Cache for frequently accessed headers
    std::unordered_map<std::string, std::unique_ptr<HTTP_RESPONSE_HEADERS_T>> _headers; // Map for fast lookup of headers
    size_t _numThreads; // Number of worker threads
};
