void add_context(LTE_UE_CONTEXT* ctx) {
    pthread_mutex_lock(&contexts_mutex);
    if (num_contexts == 0) {
        contexts = malloc(sizeof(LTE_UE_CONTEXT*) * 16);
    } else if (num_contexts >= 8192) {
        LTE_UE_CONTEXT** new_contexts = realloc(contexts, sizeof(LTE_UE_CONTEXT*) * (num_contexts << 3));
        if (!new_contexts) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        contexts = new_contexts;
    }

    contexts[num_contexts++] = ctx;
    pthread_mutex_unlock(&contexts_mutex);
}

void remove_context(uint64_t ue_id) {
    size_t i;
    pthread_mutex_lock(&contexts_mutex);
    for (i = 0; i < num_contexts; ++i) {
        if (contexts[i]->ue_id == ue_id) {
            memmove(contexts + i, contexts + (i + 1), (num_contexts - (i + 1)) * sizeof(LTE_UE_CONTEXT*));
            --num_contexts;
            break;
        }
    }
    pthread_mutex_unlock(&contexts_mutex);

    free(contexts[i]->traffic_stats);
    free(contexts[i]);
}

LTE_UE_CONTEXT* find_context_by_ue_id(uint64_t ue_id) {
    size_t i;
    pthread_mutex_lock(&contexts_mutex);
    for (i = 0; i < num_contexts; ++i) {
        if (contexts[i]->ue_id == ue_id) {
            pthread_mutex_unlock(&contexts_mutex);
            return contexts[i];
        }
    }
    pthread_mutex_unlock(&contexts_mutex);
    return NULL;
}
