    double NoisePower;
    double SNR;
} FrameInfo;

sem_t lock; // Semaphore for synchronizing concurrent access to shared resources

void initializeFrames(FrameInfo** frames, size_t initialCapacity, const char* tag) {
    if (!frames || *frames || initialCapacity <= 0) {
        syslog(LOG_ERR, "%s: invalid input parameters", tag);
        return;
    }

    *frames = (FrameInfo*) calloc(initialCapacity, sizeof(FrameInfo));
    if (*frames == NULL) {
        syslog(LOG_ERR, "%s: memory allocation failure", tag);
        return;
    }

    sem_init(&lock, 0, 1); // Initialize semaphore

    for (size_t i = 0; i < initialCapacity; ++i) {
        FrameInfo* frame = &((*frames)[i]);

        frame->Timestamp = time(NULL);
        if (frame->NoisePower <= 0.0) {
            frame->NoisePower = DEFAULT_NOISE_POWER;
        }
        if (frame->SignalStrength < 0) {
            frame->SignalStrength = DEFAULT_SIGNAL_STRENGTH;
        }

        // Compute SNR using logarithmic scaling
        frame->SNR = frame->SignalStrength - frame->NoisePower * DB_TO_LINEAR_SCALE;
    }
}

double DB_TO_LINEAR_SCALE = 10.0;
double DEFAULT_NOISE_POWER = 0.0;
double DEFAULT_SIGNAL_STRENGTH = 0.0;
