public class FileProcessor {
    private static final Logger logger = Logger.getLogger(FileProcessor.class);
    private static final int MAX_CONCURRENT_THREADS = 10;
    private static final int MAX_API_REQUESTS = 5;
    private static final long SKIP_THRESHOLD = 10485760; // 10 MB
    private String apiKey;
    private ExecutorService threadPool;

    public FileProcessor(String apiKey) {
        this.apiKey = apiKey;
        this.threadPool = Executors.newFixedThreadPool(MAX_CONCURRENT_THREADS);
    }

    public void processFiles(List<File> files) throws IOException, InterruptedException, ExecutionException {
        List<Future<String>> futures = new ArrayList<>();

        for (File file : files) {
            if (file.length() > SKIP_THRESHOLD) {
                logger.info("Skipping large file: " + file.getName());
                continue;
            }

            Callable<String> callable = () -> processSingleFile(file);
            Future<String> future = threadPool.submit(callable);
            futures.add(future);
        }

        for (Future<String> future : futures) {
            future.get();
        }
        threadPool.shutdown();
        awaitTermination(threadPool, 1, TimeUnit.MINUTES);
    }

    private String processSingleFile(File file) throws IOException {
        byte[] sha256Hash = DigestUtils.getSHA-256Hex(new BufferedInputStream(new FileInputStream(file)));

        HttpURLConnection apiConnection = null;
        try {
            URL url = new URL("<API_SERVICE_URL>");
            apiConnection = (HttpURLConnection) url.openConnection();
            apiConnection.setRequestMethod("GET");
            apiConnection.setRequestProperty("Authorization", "Bearer " + apiKey);

            StringBuilder responseContent = new StringBuilder();
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(apiConnection.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    responseContent.append(line);
                }
            }

            // Process the metadata, execute shell command, and log results here...

        } catch (IOException e) {
            logger.error("Error processing file " + file.getName() + ": ", e);
            throw e;
        } finally {
            if (apiConnection != null) {
                apiConnection.disconnect();
            }
        }

        return sha256Hash;
    }

    private static boolean awaitTermination(ExecutorService executor, long timeout, TimeUnit unit) throws InterruptedException {
        return executor.awaitTermination(timeout, unit);
    }
}
