    uint16_t crc_flag;
    char data[128]; // Assuming each text embedded in the structures is less than or equal to 128 bytes
} NFAPI_CRC_INDICATION_PDU_T;

// Define regular expressions for Old Testament book names
regex_t books_reg[20]; // Array to store all regex objects
char books_patterns[][128] = {
    "([JJj][Oo][Ss][Ee])",
    "([Ee][Xx][Oo][Dd])",
    "([Ll][Ee][Vv][Ii][Tt])",
    // Add more book names here...
};

// Cache for storing processed texts to avoid redundant processing
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
int cache[1024][256] = {{0}}; // 2D array to store hashes and frequencies of processed texts, with a maximum size of 1024 unique hashes and 256 occurrences each

void init_regex() {
    int i;
    regcomp(&books_reg[0], books_patterns[0], REG_EXTENDED | REG_ICASE);
    for (i = 1; i < sizeof(books_patterns) / sizeof(books_patterns[0]); ++i)
        regcomp(&books_reg[i], books_patterns[i], REG_EXTENDED | REG_ICASE);
}

int is_cached(const char* text, size_t len) {
    unsigned long hash = murmurhash3_x64_final(text, len, 0);
    pthread_mutex_lock(&cache_mutex);
    int x = cache[hash % sizeof(cache)][hash];
    if (x == hash) {
        pthread_mutex_unlock(&cache_mutex);
        return 1;
    }
    pthread_mutex_unlock(&cache_mutex);
    return 0;
}

void update_cache(const char* text, size_t len, int frequency) {
    unsigned long hash = murmurhash3_x64_final(text, len, 0);
    pthread_mutex_lock(&cache_mutex);
    cache[hash % sizeof(cache)][hash] = hash;
    if (frequency < cache[hash % sizeof(cache)][hash + 1]) {
        cache[hash % sizeof(cache)][hash + 1] = frequency;
    }
    pthread_mutex_unlock(&cache_mutex);
}

int find_book_matches(const char* text, size_t len) {
    int matches[20] = { 0 };
    regmatch_t pmatch[20];
    int i;
    for (i = 0; i < sizeof(books_patterns) / sizeof(books_patterns[0]); ++i) {
        if (regexec(&books_reg[i], text, 2, pmatch, 0) == 0) {
            int start = pmatch[1].rm_so;
            int end = pmatch[1].rm_eo;
            matches[i] = 1;
            printf("Book '%s' found at line %d, position %d\n", books_patterns[i], __LINE__, start);
        }
    }
    return *max_element(matches, sizeof(matches) / sizeof(matches[0]));
}

size_t murmurhash3_x64_final(const void* key, size_t len, uint32_t seed) {
    // Adapted from https://en.wikipedia.org/wiki/MurmurHash
    const uint32_t m = 0x5bd1e995;
    const int r = 24;
    const uint64_t n = len * m;
    uint64_t h = seed ^ n;
    const uint8_t* data = (const uint8_t*)key;

    while (len >= 8) {
        uint64_t k = ((uint64_t)*(data++)) << 32 | ((uint64_t)*(data++));
        k *= m;
        k ^= k >> r;
        k *= m;
        h ^= k;
        len -= 8;
    }

    while (len >= 4) {
        uint64_t k = ((uint64_t)*(data++)) << 32 | ((uint64_t)*(data++));
        k *= m;
        k ^= k >> r;
        k *= m;
        h ^= (k >> ((len + 1) * r)) << (64 - (len + 1) * r);
        len -= 4;
    }

    while (len >= 1) {
        uint64_t k = ((uint8_t)*(data++)) << 32 | ((uint8_t)*(data++));
        k *= m;
        k ^= k >> r;
        k *= m;
        h ^= (k << (len * r)) | (k >> (64 - len * r));
        --len;
    }

    h ^= h >> 13;
    h *= m;
    h ^= h >> 15;

    return h;
}

// Function to generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_pdus(int n, FILE* output_file) {
    CURL *curl;
    struct curl_slist *headers = NULL;
    char *response;
    size_t length;

    init_regex();

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; ++i) {
        if (!(curl = curl_easy_init())) {
            fprintf(stderr, "Failed to initialize cURL\n");
            exit(-1);
        }

        headers = curl_slist_append(headers, "Accept: application/json");

        CURLcode res;
        res = curl_easy_setopt(curl, CURLOPT_URL, "http://api.example.com/verses/random"); // Replace with the actual API endpoint
        res = curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error in cURL request: %s\n", curl_easy_strerror(res));
            continue;
        }

        response = curl_easy_getinfo(curl, CURLINFO_RESPONSE_DATA);
        length = curl_easy_getinfo(curl, CURLINFO_RESPONSE_LEN);

        if (is_cached(response, length)) {
            continue;
        }

        update_cache(response, length, 1);

        int book_match = find_book_matches(response, length);
        if (book_match > 2) { // Set the threshold here
            int j;
            char verse[6]; // Assuming verses are 1-6 digits
            sscanf(response, "%*[^0-9]%s", verse);

            for (j = 0; j < i; ++j) {
                if (!strcmp(pdus[j].data, response)) {
                    break;
                }
            }

            if (j == i) {
                strncpy(pdus[i].data, response, sizeof(pdus[i].data));
                pdus[i].rnti = i + 12345; // Set the RNTI here
                pdus[i].crc_flag = rand() % 2; // Set the CRCFLAG randomly
            }
        }

        curl_easy_cleanup(curl);
    }

    fwrite(pdus, n * sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, output_file);

    free(pdus);
}
