static gsl_cache_hash _book_regex_cache;
static GSL_CACHE_HASH_FUNCTION(_book_regex_cache_hash) {
    uintptr_t hash = 5381;
    int c;
    for (c = 0; *regex_patterns[c]; c++)
        hash = ((hash << 5) + hash) + *regex_patterns[c]; /* hash * 33 + c */
    return hash % GSL_CACHE_MAX_SIZE;
}

static gsl_cache_value_t _book_regex_cache_lookup(const size_t key, void *data) {
    regex_t *regex = (regex_t *) data;
    regmatch_t match[1];
    int errcode;

