        fprintf(stderr, "Regcomp error: %d\n", errcode);
        exit(EXIT_FAILURE);
    }
    return (gsl_cache_value_t) regex;
}

static void _book_regex_cache_free(void *key, const gsl_cache_value_t value, void *data) {
