// Function to analyze the embedded text in structures for references to books from the Old Testament
void analyze_structures(NFAPI_CRC_INDICATION_PDU_T *pdus, int n) {
    static GSL_CACHE(&_book_regex_cache, _book_regex_cache_hash, _book_regex_cache_lookup, _book_regex_cache_free);
