            }
        }
    }

    for (size_t i = 0, count = 0; i < GSL_CACHE_MAX_SIZE; ++i) {
        struct book_count *book = books + i;
        if (book->frequency >= threshold && strcmp(book->book, "")) {
            printf("%s (%d chap., %d line): %d mentions\n", book->book, book->chapter, book->line_number, book->frequency);
            count++;
        }
    }

    if (count > 0) {
        // Generate a report summarizing the total number of book mentions and the distribution of mentions across different chapters
        printf("\nTotal: %d mentions across %d books\n", count, GSL_CACHE_MAX_SIZE / 2);
    }
}

// Function to update a database table with a new status, last modified IP address, and last modified date for a given clinic ID
int update_database(sqlite3 *db, const char *clinic_id) {
    sqlite3_stmt *stmt;
    const char *update_query = "UPDATE clinics SET status='active', last_modified_ip=?, last_modified=? WHERE id=?";
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    if (sqlite3_prepare_v2(db, update_query, -1, &stmt, 0) != SQLITE_OK) {
        fprintf(stderr, "Cannot prepare statement: %s\n", sqlite3_errmsg(db));
        return 0;
    }

    if (sqlite3_bind_text(stmt, 1, getenv("REMOTE_ADDR"), -1, SQLITE_STATIC) != SQLITE_OK ||
        sqlite3_bind_text(stmt, 2, timestamp, -1, SQLITE_STATIC) != SQLITE_OK ||
        sqlite3_bind_int(stmt, 3, atoi(clinic_id)) != SQLITE_OK) {
        fprintf(stderr, "Cannot bind parameter: %s\n", sqlite3_errmsg(db));
        return 0;
    }

    if (sqlite3_step(stmt) != SQLITE_DONE) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
        return 0;
    }

    if (sqlite3_finalize(stmt) != SQLITE_OK) {
        fprintf(stderr, "Cannot finalize statement: %s\n", sqlite3_errmsg(db));
        return 0;
    }

    printf("Database update successful.\n");
    return 1;
}
