    sqlite3_bind_int(stmt, 1, 0);
    sqlite3_bind_text(stmt, 2, "127.0.0.1", -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(stmt, 3, timestamp, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int(stmt, 4, clinic_id);

    if (sqlite3_step(stmt) != SQLITE_DONE) {
        fprintf(stderr, "Error executing update statement: %s\n", sqlite3_errmsg(db));

        // Retry on failed database operations with backoff logic
        usleep(1000 * pow(2, attempt));
        if (attempt < max_attempts - 1) {
            update_database(db, clinic_id);
        }
    } else {
        sqlite3_finalize(stmt);
    }
}

