    int success_count = manager->num_success;
    int error_count = manager->num_error;
    pthread_mutex_unlock(&manager->lock);

    // Process your PHY RX indication PDU here.
    // If validation succeeds, increment the success count and add the structure to the list.
    // If validation fails, increment the error count but do not add the structure to the list.

    pthread_mutex_lock(&manager->lock);
    manager->num_success = ++success_count;
    manager->num_error = error_count;
    if (manager->count < manager->capacity) {
        manager->list[manager->count++] = pdus; // pdus is your PHY_RX_INDICATION_PDU_T pointer.
    } else {
        size_t new_capacity = manager->capacity * 2;
        PHY_RX_INDICATION_PDU_T** new_list = realloc(manager->list, new_capacity * sizeof(PHY_RX_INDICATION_PDU_T*));
        if (new_list != NULL) {
            manager->list = new_list;
            manager->capacity = new_capacity;
            manager->list[manager->count++] = pdus; // pdus is your PHY_RX_INDICATION_PDU_T pointer.
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

PHY_RX_INDICATION_PDU_RESULT_T phy_rx_indication_pdu_process(PHY_RX_INDICATION_PDU_MANAGER_T* manager, PHY_RX_INDICATION_PDU_T** pdus, size_t num_pdus) {
