    result.num_success = manager->num_success - num_pdus; // Subtract the number of PDUs passed to the function.
    result.num_error = manager->num_error;
    result.list = realloc(manager->list, result.num_success * sizeof(PHY_RX_INDICATION_PDU_T));
    memcpy(result.list, manager->list, result.num_success * sizeof(PHY_RX_INDICATION_PDU_T));
    phy_rx_indication_pdu_manager_destroy(manager);
    return result;
}
