        weights[i] = rand() % VALUE_RANGE / 10.0f;

        if (!keys[i].key || weights[i] > THRESHOLD) {
            for (size_t j = i + 1; j < MAX_RECORDS; ++j) {
                free(keys[j - 1].key);
                keys[j - 1].key = NULL;
