    *records = (Record**) malloc(num_records * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        return 1; // Allocation failure
    }

    // Iterate through the array of pointers to Records and dynamically allocate memory for each Record structure
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i] = (Record*) malloc(sizeof(Record));
        if (!(*records)[i]) {
            fprintf(stderr, "Failed to allocate memory for record #%zu\n", i);
            free(*records);       // Free previously allocated memory up to the current index
            *records = NULL;       // Set the array of pointers to null to indicate failure
            return 2; // Allocation failure within an individual Record
