        // Initialize each record's key with a unique random value and calculate the corresponding offset based on the predefined factor
        (*(*records)[i]).key = rand() % key_range + 1;
        (*(*records)[i]).offset = ((*(*records)[i]).key * (MAX_OFFSET / key_range));
