    public class TileBasedWorld
    {
        private const int MinRecords = 10_000;
        private const int MaxRecordsPerTile = 1_000;
        private const int MaxOffsetFactor = 9_223_372_036_854_775_807; // Long.MaxValue / MaxRecordsPerTile

        private readonly Dictionary<int, Record[]> _tiles;
        private readonly int _worldWidth;
        private readonly int _worldHeight;
        private readonly double _cameraSpeed;
        private readonly Random _random;

        public TileBasedWorld(string configFilePath)
        {
            LoadConfiguration(configFilePath);
            _tiles = new Dictionary<int, Record[]>();
            AllocateAndInitializeTiles();
        }

        private void LoadConfiguration(string configFilePath)
        {
            var configXml = XDocument.Load(configFilePath);
            _worldWidth = int.Parse(configXml.Element("World").Element("Width"));
            _worldHeight = int.Parse(configXml.Element("World").Element("Height"));
            _cameraSpeed = double.Parse(configXml.Element("Camera").Element("Speed"));
        }

        private void AllocateAndInitializeTiles()
        {
            for (int x = 0; x < _worldWidth; x++)
            {
                for (int y = 0; y < _worldHeight; y++)
                {
                    var tileRecords = new Record[MaxRecordsPerTile];
                    for (int i = 0; i < tileRecords.Length; i++)
                    {
                        int key = GetRandomKey(_random);
                        tileRecords[i].Key = key;
                        tileRecords[i].Offset = key * MaxOffsetFactor;
                    }
                    _tiles.Add(Hash(x, y), tileRecords);
                }
            }
        }

        private int Hash(int x, int y)
        {
            return (x * 31 + y) % MinRecords;
        }

        private int GetRandomKey(Random random)
        {
            const int MaxKey = int.MaxValue - 1;
            return Math.Min(random.Next(MaxKey), MaxKey);
        }
    }
}
