            const int factor = 10;
            return (long)(key * factor + index * Math.Pow(factor, LayerIndex));
        }
    }

    public class WorldManager
    {
        private readonly ConcurrentDictionary<int, Layer> layers;
        private readonly int maxOffsetValue;
        private readonly int recordsPerLayer;
        private readonly int threadPoolSize;
        private readonly Random random;

        public WorldManager(XElement config)
        {
            maxOffsetValue = int.Parse(config.Element("MaxOffsetValue").Value);
            recordsPerLayer = int.Parse(config.Element("RecordsPerLayer").Value);
            threadPoolSize = int.Parse(config.Element("ThreadPoolSize").Value);
            random = new Random();
            layers = new ConcurrentDictionary<int, Layer>();
            LoadLayers(config);
        }

        private void LoadLayers(XElement config)
        {
            // Load additional layers from the XML file if necessary.
            int currentLayerIndex = 0;
            while (true)
            {
                var layerConfig = config.Element($"Layer{currentLayerIndex}");
                if (layerConfig == null) break;
                layers[currentLayerIndex] = new Layer(recordsPerLayer);
                currentLayerIndex++;
            }
        }

        public bool AddRecordToRandomLayer(int key)
        {
            // Attempt to add a record to a random layer, handle allocation failures gracefully.
            int layerIndex;
            if (!layers.TryAdd(layerIndex = random.Next(layers.Count), new Layer(recordsPerLayer)))
                return false; // Failed to allocate memory for the new layer.

            var layer = layers[layerIndex];
            if (layer.Records.Count >= recordsPerLayer)
                return false; // The layer is already full.

            var record = new Record { Key = key, Offset = layer.CalculateOffset(layer.Records.Count) };
            if (!layer.Records.TryAdd(record))
                return false; // Failed to allocate memory for the new record within the layer.

            return true;
        }

        public ConcurrentBag<Record> GetRecordsFromLayer(int layerIndex)
        {
            // Retrieve records from a specific layer safely, handling concurrent access.
            if (!layers.TryGetValue(layerIndex, out var layer))
                throw new KeyNotFoundException($"Layer with index '{layerIndex}' not found.");

            return new ConcurrentBag<Record>(layer.Records);
        }
    }

    public static async Task Main()
    {
