        WorldManager manager = new WorldManager(config);

        var tasks = Enumerable.Range(0, threadPoolSize)
            .Select(_ => Task.Run(() =>
            {
                for (int i = 0; i < 10000; i++)
                    manager.AddRecordToRandomLayer(i);
            }));
        await Task.WhenAll(tasks);
    }
}
