    {
        var process = new Process
        {
            StartInfo = new ProcessStartInfo
            {
                FileName = command,
                WorkingDirectory = workingDirectory,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true,
                Arguments = string.Empty,
            },
        };

        if (workingFile != null)
        {
            process.StartInfo.Arguments += " < " + workingFile.Name;
            process.StartInfo.RedirectStandardInput = true;
        }

        using (var readerOutput = new StreamReader(process.StandardOutput))
        using (var readerError = new StreamReader(process.StandardError))
        {
            process.Start();

            if (!process.StandardInput.BaseStream.CanWrite)
            {
                process.StartInfo.RedirectStandardInput = true;
                process.Start();
            }

            // Read the streams as needed
        }
    }
}
