bool add_pdu(struct list *list, NFAPI_CRC_INDICATION_PDU* pdu) {
    if (list->current_size >= list->max_size) {
        log_info("List is full, dropping PDUs");
        return false;
    }

    // Ensure integrity of the structure before adding it to the list
    // ...

    pthread_mutex_lock(&(list->mutex));
    if (!list->head) {
        list->head = (struct list_elem*) malloc(sizeof(struct list_elem));
        if (!list->head) {
            log_info("Failed to allocate memory for head element");
            free(pdu);
            pthread_mutex_unlock(&(list->mutex));
            return false;
        }
        list->head->data = pdu;
        list->head->next = NULL;
    } else {
        struct list_elem *current = list->head;
        while (current->next != NULL) current = current->next;
        current->next = (struct list_elem*) malloc(sizeof(struct list_elem));
        if (!current->next) {
            log_info("Failed to allocate memory for new element");
            free(pdu);
            pthread_mutex_unlock(&(list->mutex));
            return false;
        }
        current->next->data = pdu;
        current->next->next = NULL;
    }
    list->current_size++;
    pthread_mutex_unlock(&(list->mutex));

    // Enqueue the PDU for asynchronous processing, if applicable
    enqueue_struct(pdu);

    return true;
}
