struct lte_phytimer_pool {
    size_t capacity;
    size_t count;
    LTEPHYTIMER *array;
    pthread_mutex_t mutex;
};

void lte_phytimer_init(struct lte_phytimer_pool **pool, size_t initial_capacity) {
    *pool = malloc(sizeof(struct lte_phytimer_pool));
    if (!*pool) {
        perror("Failed to allocate memory for pool");
        return;
    }

    (*pool)->capacity = initial_capacity;
    (*pool)->count = 0;
    (*pool)->array = malloc(initial_capacity * sizeof(LTEPHYTIMER));
    if (!(*pool)->array) {
        perror("Failed to allocate memory for array");
        free(*pool);
        return;
    }

    pthread_mutex_init(&(*pool)->mutex, NULL);
}

void lte_phytimer_destroy(struct lte_phytimer_pool **pool) {
    if (*pool) {
        free((*pool)->array);
        pthread_mutex_destroy(&(*pool)->mutex);
        free(*pool);
        *pool = NULL;
    }
}

LTEPHYTIMER *lte_phytimer_get(struct lte_phytimer_pool *pool) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->count < pool->capacity) {
        LTEPHYTIMER *lte_phytimer = &pool->array[pool->count];
        pool->count++;
        pthread_mutex_unlock(&pool->mutex);
        return lte_phytimer;
    }

    pthread_mutex_unlock(&pool->mutex);

    // Double the capacity if it's full, reallocate memory and repeat the process
    size_t new_capacity = pool->capacity * 2;
    LTEPHYTIMER *new_array = realloc(pool->array, new_capacity * sizeof(LTEPHYTIMER));
    if (!new_array) {
        perror("Failed to allocate memory for expanded array");
        return NULL;
    }

    pool->array = new_array;
    pool->capacity = new_capacity;

    pthread_mutex_lock(&pool->mutex);
    LTEPHYTIMER *lte_phytimer = &pool->array[pool->count - 1];
    pool->count++;
    pthread_mutex_unlock(&pool->mutex);

    return lte_phytimer;
}
