    private static final Logger LOGGER = Logger.getLogger(StateLoader.class.getName());

    // Load configuration properties and get the path for state file
    private static String STATE_FILE_PATH;
    static {
        try {
            PropertiesLoaderUtils.setPropertiesLoadedFromClasspathLocation(true);
            Properties props = PropertiesLoaderUtils.loadAllProperties("application.properties");
            STATE_FILE_PATH = URLDecoder.decode(props.getProperty("stateFile"), "UTF-8");
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error loading configuration properties: {}", e.getMessage());
            throw new RuntimeException("Unable to load configuration properties", e);
        }
    }

    private ObjectMapper objectMapper = new ObjectMapper();

    @Override
    public MostState loadState() {
        Path path = Paths.get(STATE_FILE_PATH);

        if (!Files.exists(path)) {
            LOGGER.log(Level.WARNING, "Invalid file path: {}", STATE_FILE_PATH);
            return null;
        }

        try (FileInputStream fis = new FileInputStream(STATE_FILE_PATH);
             ObjectInputStream ois = new ObjectInputStream(fis)) {

            try {
                Object object = ois.readObject();
                if (object instanceof MostState) {
                    return (MostState) object;
                }
            } catch (ClassNotFoundException e) {
                LOGGER.log(Level.WARNING, "Deserialization error: {}", e.getMessage());
            }
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "File IO error: {}", e.getMessage());
        } finally {
            // Ensure proper closing of resources
        }

        return null;
    }
}
