from configparser import ConfigParser
import logging
import functools
from cachetools import TTLCache

CACHE_SIZE = 100  # Cache size limit
cache = TTLCache(maxsize=CACHE_SIZE, ttl=60)  # Cache configuration for 60 seconds

def parse_config(filename):
    try:
        ext = filename.lower().split('.')[-1]
        config = cache.get(filename, default={})  # Fetch from cache if available

        if not config:
            with open(filename, 'r') as fh:
                if ext == 'json':
                    config = json.load(fh)
                elif ext == 'yaml' or ext == 'yml':
                    config = yaml.safe_load(fh)
                elif ext == 'ini':
                    cp = ConfigParser()
                    cp.read(filename)
                    config = {cp.sections()[0]: dict(cp.items(cp.sections()[0]))}

            # Cache the parsed configuration for future requests
            cache[filename] = config
        return config
    except Exception as e:
        logging.error(f"Error parsing configuration file '{filename}': {e}")
        return {}

def with_logging(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        logging.info(f"Parsed configuration from file: {args[0]}")
        return result
    return wrapper

parse_config = with_logging(parse_config)  # Apply logging decorator to the function
```
