#include <arpa/inet.include>
#include <netdb.h>
#include <stdexcept>
#include <unordered_map>
#include <memory>
#include <sys/socket.h>
#include <netinet/in.h>
#include <fcntl.h>
#include <ifaddrs.h>
#include <cstring>
#include <iostream>

class DNSResolver : public ConfigurableComponent {
private:
    std::unordered_map<std::string, u_char*> cache;
    int timeout = 5;
    std::unique_ptr<IFAddrInfo, decltype(&freeifaddrinfo)> current_interface;
    std::unique_ptr<void, decltype(&freeaddrinfo)> res;

public:
    void load(const YAML::Node& node) override {
        timeout = node["timeout"].as<int>();
        // Load other configuration options if needed
    }

    int resolve(const std::string& hostname, u_char*& ip_address) {
        auto it = cache.find(hostname);
        if (it != cache.end()) {
            ip_address = it->second;
            return 0;
        }

        int err = getaddrinfo(const_cast<char*>(hostname.c_str()), nullptr, res.get(), &current_interface.get());
        if (err != 0) {
            std::cerr << "getaddrinfo: " << gai_strerror(err) << std::endl;
            return err;
        }

        // Iterate through the results and find a suitable IP address, e.g., with an IPv4 address family
        u_char ip[INET6_ADDRSTRLEN];
        u_char ipv4[INET_ADDRSTRLEN];
        while (current_interface != nullptr) {
            ifaddrinfo* cur = current_interface.get();
            current_interface = current_interface->ai_next;

            if (cur->ai_family == AF_INET6) {
                inet_ntop(AF_INET6, &((struct sockaddr_in6*)cur->ai_addr)->sin6_addr, ip, sizeof(ip));
                // Check if the IP is suitable for your use case and handle errors appropriately
            } else if (cur->ai_family == AF_INET) {
                inet_ntop(AF_INET, &((struct sockaddr_in*)cur->ai_addr)->sin_addr, ipv4, sizeof(ipv4));
                // Check if the IP is suitable for your use case and handle errors appropriately
            }
        }

        if (ip != nullptr) {
            // Cache the resolved IP address with a timeout mechanism
            cache[hostname] = new u_char[strlen(ip) + 1];
            strcpy((char*)cache[hostname], ip);
            ip_address = cache[hostname];
            return 0;
        }

        freeaddrinfo(res.get());
        if (current_interface != nullptr) {
            current_interface->ai_next = nullptr;
            freeifaddrinfo(current_interface.release());
        }
        return EAI_FAIL;
    }

    ~DNSResolver() {
        // Close any open resources and clean up the cache
        for (auto& entry : cache) {
            delete[] entry.second;
        }
        cache.clear();
    }
};
```

