import os
import json
import yaml
import configparser
from functools import lru_cache
from threading import Lock
from typing import Any, Dict, IO
import logging

class ConfigManager:
    def __init__(self, root_dir: str = ".", cache_dir: str = ".cache"):
        self.root_dir = root_dir
        self.cache_dir = cache_dir
        self.lock = Lock()
        self.configs: Dict[str, Any] = {}
        self._initialize_caches()

    def _format_match(self, filename: str) -> str:
        _, ext = os.path.splitext(filename)
        if ext == ".ini":
            return "ini"
        elif ext in (".json", ".yaml", ".yml"):
            return "json"
        else:
            return None

    @lru_cache(maxsize=None)
    def _load_from_disk(self, filename: str) -> Any:
        with open(filename, "r") as f:
            format_ = self._format_match(filename)
            if format_ == "ini":
                return configparser.ConfigParser().read_file(f)
            elif format_ == "json":
                return json.load(f)
            else:
                return yaml.safe_load(f)

    @lru_cache(maxsize=None)
    def _save_to_disk(self, filename: str, data: Any):
        with open(filename, "w") as f:
            format_ = self._format_match(filename)
            if format_ == "ini":
                configparser.ConfigParser(interpolation=None).write_file(f, data)
            elif format_ == "json":
                json.dump(data, f)
            else:
                yaml.dump(data, f)

    @lru_cache(maxsize=None)
    def _get_cached_config(self, filename: str) -> Any:
        cache_filename = os.path.join(self.cache_dir, filename)
        if not os.path.exists(cache_filename):
            self._save_to_disk(cache_filename, self._load_from_disk(filename))
        with open(cache_filename, "r") as f:
            return json.load(f)

    def get_config(self, filename: str, fallback: Dict[str, Any] = None) -> Any:
        with self.lock:
            cached_config = self._get_cached_config(filename)
            try:
                return self._load_from_disk(filename)
            except Exception as e:
                logging.error(f"Error while loading config file {filename}: {e}")
                if fallback is not None:
                    return fallback
                return cached_config

    def save_config(self, filename: str, data: Any):
        self._save_to_disk(filename, data)
        self._get_cached_config(filename)

def main():
    config = ConfigManager()
    json_config = config.get_config("app1.json")
    yaml_config = config.get_config("app2.yaml", fallback={"key": "value"})
    # ... other uses of the configuration object

if __name__ == "__main__":
    main()
```
