```java
import java.io.*;
import java.net.URL;
import java.nio.file.Paths;
import java.security.SecureRandom;
import java.util.Collections;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MoSTStateLoader {
    private static final String CONFIG_FILE = "config.properties";
    private static ConcurrentHashMap<String, Class<?>> implementationMap;
    private static ExecutorService executorService;

    static {
        try (PropertyResourceBundle bundle = new PropertyResourceBundle(new InputStreamReader(new URL("file:" + CONFIG_FILE).openStream()))){
            implementationMap = new ConcurrentHashMap<>();
            for (String key : bundle.getKeys()) {
                implementationMap.put(key, Class.forName(bundle.getString(key)));
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public static Object loadState(String filePath) throws IOException, ClassNotFoundException {
        if (!Paths.get(filePath).isAbsolute()) {
            throw new IllegalArgumentException("Invalid file path");
        }
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            Object object = ois.readObject();
            if (implementationMap.containsKey(object.getClass().getName())) {
                return object;
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }
}
