        return 1;
    }

    if (output_filename) { // Redirect output to specified file
        output_file = fopen(output_filename, "w");
        if (!output_file) { // Handle errors when opening output file
            perror("Error: Unable to open output_file.");
            return 1;
        }
    }

    size_t line_count = 0;
    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), input_file)) { // Read file line by line
        if (!only_count_nonempty || strlen(buffer) > 1) { // Count only non-empty lines
            ++line_count;
        }
    }

    if (output_file) { // Write line count to output file
        fprintf(output_file, "%zu\n", line_count);
    } else { // Print line count to stdout
        printf("%zu\n", line_count);
    }

    fclose(input_file);
    if (output_file) {
        fclose(output_file);
    }

    return 0;
}
