public class DistributedLoggingSystem {

    private static final int BATCH_SIZE = Integer.getInteger("BATCH_SIZE", 10000);
    private static final int THREAD_POOL_SIZE = Integer.getInteger("THREAD_POOL_SIZE", Runtime.getRuntime().availableProcessors() * 2);

    private Path dataCenterBasePath;
    private ExecutorService threadPool;

    public DistributedLoggingSystem(String dataCenterBasePath) {
        this.dataCenterBasePath = Paths.get(dataCenterBasePath);
        this.threadPool = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
    }

    public void log(String timestamp, String id, String message) {
        LogEntry entry = new LogEntry(timestamp, id, message);
        Queue<LogEntry> batch = new LinkedBlockingQueue<>(BATCH_SIZE);
        Runnable writerTask = () -> writeBatchToDisk(batch);

        synchronized (batch) {
            batch.add(entry);
            if (batch.size() == BATCH_SIZE) {
                threadPool.execute(writerTask);
                batch.clear();
            }
        }
    }

    private void writeBatchToDisk(Queue<LogEntry> batch) {
        List<Path> files = new ArrayList<>();
        Path file;

        for (int dcIndex = 0; dcIndex < dataCenterBasePath.getNameCount(); dcIndex++) {
            file = dataCenterBasePath.resolve(String.valueOf(dcIndex));
            if (!Files.exists(file)) {
                try {
                    Files.createDirectories(file);
                } catch (IOException e) {
                    // Handle I/O errors gracefully, log and continue
                }
            }
            files.add(file.resolve("log_" + dcIndex));
        }

        List<Callable<Void>> tasks = new ArrayList<>();
        for (Path file : files) {
            tasks.add(() -> writeToFile(batch, file));
        }

        try {
            Future<?>[] futures = threadPool.invokeAll(tasks).toArray(new Future[files.size()]);
            // Handle completion of tasks gracefully, log any errors and continue
        } catch (InterruptedException | ExecutionException e) {
            // Handle exceptions gracefully, log and continue
        }
    }

    private void writeToFile(Queue<LogEntry> batch, Path file) {
        try (BufferedWriter writer = Files.newBufferedWriter(file)) {
            for (LogEntry entry : batch) {
                writer.write(entry.toString());
            }
        } catch (IOException e) {
            // Handle I/O errors gracefully, log and continue
        }
    }

    public void sendToExternalService(String hostname, int port, Queue<LogEntry> batch) {
        try (Socket socket = new Socket(hostname, port)) {
            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            PrintWriter out = new PrintWriter(socket.getOutputStream());

            for (LogEntry entry : batch) {
                out.println(entry);
            }

            out.flush();
            String response = in.readLine();
            // Handle response from external service gracefully, log any errors and continue
        } catch (IOException e) {
            // Handle network issues gracefully, log and continue
        }
    }

    public void stop() {
        threadPool.shutdownNow();
    }

    static class LogEntry {
        private final Instant timestamp;
        private final String id;
        private final String message;

        public LogEntry(Instant timestamp, String id, String message) {
            this.timestamp = timestamp;
            this.id = id;
            this.message = message;
        }

        @Override
        public String toString() {
            return timestamp + "|" + id + "|" + message + "\n";
        }
    }
}
