struct Record {
    int value;
};

void modifyVectorWithRandomRecords(std::vector<int>& vec, int target, int replacement, int num_records, int max_random_value) {
    std::vector<long> offsets(vec.size());
    std::vector<int> keys(vec.size());
    std::vector<Record> records(num_records);

    auto it = vec.begin();
    long currentOffset = 0;
    int currentKey = -1;

    for (std::size_t i = 0; i < vec.size(); ++i) {
        if (it != vec.end() && *it == target) {
            keys[currentOffset] = i;
            offsets[i] = currentOffset++;
            currentKey = i;
        } else {
            if (currentKey >= 0) {
                keys[currentOffset] = i - 1;
                offsets[i - 1] = currentOffset++;
                currentKey = -1;
            }
            ++it;
        }
    }

    if (currentKey >= 0) {
        keys[currentOffset] = vec.size() - 1;
        offsets[vec.size() - 1] = currentOffset++;
    }

    std::default_random_engine generator;
    std::uniform_int_distribution<int> distribution(0, max_random_value);

    for (auto& record : records) {
        record.value = distribution(generator);
    }

    int consecutiveOccurrences = 0;
    it = vec.begin();
    currentKey = -1;

    for (std::size_t i = 0; i < vec.size(); ++i) {
        if (it != vec.end() && *it == target) {
            if (consecutiveOccurrences > 2) {
                std::copy(it, std::next(it), it + 1);
                for (std::size_t j = i; j < vec.size(); ++j) {
                    vec[keys[offsets[j]]] = replacement;
                }
                consecutiveOccurrences = 0;
            } else {
                consecutiveOccurrences++;
            }
        } else if (currentKey >= 0) {
            if (consecutiveOccurrences > 2) {
                std::copy(it, vec.end(), it + 1);
                for (std::size_t j = i; j < vec.size(); ++j) {
                    vec[keys[offsets[j]]] = replacement;
                }
                consecutiveOccurrences = 0;
            } else {
                consecutiveOccurrences = 0;
                currentKey = -1;
            }
            it = vec.begin();
        }

        if (currentKey >= 0 && *it == target) {
            currentKey = i;
        }
    }
}
