} NFAPI_CRC_INDICATION_PDU_T;

void createNFACRCIndicationListWithAdvancedOptions(int N, size_t limit, bool trim, bool log, NFAPI_CRC_INDICATION_PDU_T** list) {
    *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        if (log)
            printf("Error: Failed to allocate memory\n");
        return;
    }

    for (int i = 0; i < N; ++i) {
        (*list)[i].rx_ue_information.tag = RX_UE_INFORMATION_TAG__RX_UE_ID;
        (*list)[i].rnti.rntiValue = i % 65536;
        (*list)[i].crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG__CRC_INDICATION;
        (*list)[i].crc_indication_rel8.crcFlag = (unsigned char)rand() % 2;
    }

    size_t listSize = N;
    if (trim && listSize > limit) {
        listSize = limit;
        *list = realloc(*list, listSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!*list) {
            if (log)
                printf("Error: Failed to trim and reallocate memory\n");
            free(*list);
            *list = NULL;
            return;
        }
    }

    if (log && listSize > limit && !trim) {
        printf("Warning: List exceeds size limit but not trimmed\n");
    }

    if (log) {
        char md5_hash[SHA256_DIGEST_LENGTH * 2 + 1];
        unsigned char digest[SHA256_DIGEST_LENGTH];

        SHA256((unsigned char*)*list, listSize * sizeof(NFAPI_CRC_INDICATION_PDU_T), digest, NULL);
        for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            sprintf(&md5_hash[i * 2], "%02x", digest[i]);
        }
        printf("MD5 Hash: %s\n", md5_hash);
    }

    if (listSize < N) {
        (*list)[listSize] = *(*list + listSize - 1); // Append a trailing slash and the last element to avoid data loss
        (*list)[listSize].crc_indication_rel8.tag |= CRC_INDICATION_REL8_TAG__TRAILING_SLASH;
    }
}

int main() {
    int N = 10;
    size_t limit = 5;
    bool trim = true;
    bool log = true;
    NFAPI_CRC_INDICATION_PDU_T* list;
    createNFACRCIndicationListWithAdvancedOptions(N, limit, trim, log, &list);

    if (list) {
        for (int i = 0; i < limit; ++i) {
            printf("%s %d %d\n",
                list[i].rx_ue_information.tag == RX_UE_INFORMATION_TAG__RX_UE_ID ? "Rx UE ID" : "Unknown tag",
                list[i].rnti.rntiValue,
                list[i].crc_indication_rel8.crcFlag);
