public List<NFAPI_CRC_INDICATION_PDU_T> DecryptAndCreateNFACRCIndicationList(string encryptedMessage, int N, int sizeLimit, bool trim, bool log, int maxRetryCount)
{
    // Validate input parameters
    if (string.IsNullOrEmpty(encryptedMessage))
        throw new ArgumentException("Encrypted message cannot be null or empty.");
    if (N <= 0)
        throw new ArgumentOutOfRangeException(nameof(N), "Value of N must be greater than zero.");
