    if (maxRetryCount <= 0)
        throw new ArgumentOutOfRangeException(nameof(maxRetryCount), "Value of maxRetryCount must be greater than zero.");

    var decryptedMessage = Decrypt(encryptedMessage, maxRetryCount);
    if (decryptedMessage == null)
        return null;

    var list = new List<NFAPI_CRC_INDICATION_PDU_T>();

    // Attempt to create the specified number of indications within the size limit.
    for (int i = 0; i < N && list.Count < sizeLimit; ++i)
    {
        var indication = new NFAPI_CRC_INDICATION_PDU_T();
        indication.RX_UE_INFORMATION_TAG = (ushort)(Guid.NewGuid().GetHashCode() & 0xFFFF);
        indication.RNTI = (ushort)RandomNumberGenerator.GetInt32(1, int.MaxValue);
        indication.CRC_INDICATION_REL8_TAG.CRCFLAG = RandomNumberGenerator.GetInt32(0, 1) == 0 ? (byte)1 : (byte)0;
        list.Add(indication);
    }

    // Trim the list if required
    if (trim && list.Count > sizeLimit)
        list = list.Take(sizeLimit).ToList();

    // Return a dynamically allocated list with additional information
    return new List<NFAPI_CRC_INDICATION_PDU_T>(list) { new NFAPI_CRC_INDICATION_PDU_T() { CRC_INDICATION_REL8_TAG = new CRC_INDICATION_REL8_TAG_T { MD5HASH = ComputeMD5Hash(list.Select(indication => indication.ToByteArray()).Aggregate((a, b) => a.Concat(b)).ToArray()) } } };
}

private byte[] Decrypt(string encryptedMessage, int maxRetryCount)
{
    try
    {
        var tripleDES = TripleDESCryptoServiceProvider.Create();
        // Assuming you have the key and IV already set up as bytes or strings. Replace them with your own values.
        tripleDES.Key = new byte[tripleDES.KeySize / 8];
        tripleDES.IV = new byte[tripleDES.IVSize / 8];

        var decryptedMessageBytes = Encoding.UTF8.GetBytes(encryptedMessage);
        using (var msDecrypt = new MemoryStream(decryptedMessageBytes))
        {
            using (var cs = new CryptoStream(msDecrypt, tripleDES.CreateDecryptor(), CryptoStreamMode.Read))
            {
                var buffer = new byte[decryptedMessageBytes.Length];
                int read;
                while ((read = cs.Read(buffer, 0, buffer.Length)) > 0)
                    Array.Copy(buffer, 0, decryptedMessageBytes, 0, read);
            }
        }
        return decryptedMessageBytes;
    }
    catch (Exception ex) when (maxRetryCount-- > 0)
    {
        Debug.Write($"Decryption attempt failed: {ex.Message} - Retrying...");
        return Decrypt(encryptedMessage, maxRetryCount);
    }
    Debug.WriteLine("Decryption failed after maximum number of attempts.");
    return null;
}

private byte[] ToByteArray(this NFAPI_CRC_INDICATION_PDU_T indication)
{
    using var ms = new MemoryStream();
    using (var bw = new BinaryWriter(ms))
        bw.Write(indication);
    return ms.ToArray();
}

private static byte[] ComputeMD5Hash(byte[] data)
{
    using var md5 = MD5.Create();
    var hashBytes = md5.ComputeHash(data);
    return hashBytes;
}
