#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

typedef enum { SUMMARY, DETAILED } aggregation_mode;
typedef struct log_summary {
    aggregation_mode mode;
    int num_logs;
    int total_entries;
    int* entry_counts;
    char** latest_entries;
} log_summary;

struct log_entry {
    time_t timestamp;
    int level;
    char message[1024]; // Minimum 100 characters to avoid detailed mode invalid input
};

log_summary* log_aggregator(const char** file_paths, int num_files, int log_level, aggregation_mode mode) {
    log_summary* summary = malloc(sizeof(log_summary));
    summary->mode = mode;
    summary->num_logs = 0;
    summary->total_entries = 0;
    if (mode == DETAILED && num_files > 0) {
        summary->entry_counts = malloc(num_files * sizeof(int));
        summary->latest_entries = malloc(num_files * sizeof(char*));
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_files; ++i) {
        if (!file_paths[i] || strlen(file_paths[i]) == 0) continue;

        FILE* file = fopen(file_paths[i], "r");
        if (!file) {
            fprintf(stderr, "Error opening file: %s\n", file_paths[i]);
            continue;
        }

        log_entry entry;
        while (fscanf(file, "%ld%d: %[^\n]\n", &entry.timestamp, &entry.level, entry.message) == 3 &&
               !feof(file)) {
            if (entry.level > log_level) continue; // Filter by log level

            pthread_mutex_lock(&mutex);
            if (mode == DETAILED && summary->num_logs >= num_files) {
                fprintf(stderr, "Too many logs of the same level\n");
                pthread_mutex_unlock(&mutex);
                break; // Abort loading this log file
            }

            if (mode == SUMMARY) {
                summary->total_entries++;
            } else {
                summary->entry_counts[summary->num_logs] = 0;
                summary->latest_entries[summary->num_logs] = malloc(strlen(entry.message) + 1);
                strcpy(summary->latest_entries[summary->num_logs], entry.message);
            }

            pthread_mutex_unlock(&mutex);
            summary->num_logs++;
        }

