#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>

#define BUFFER_SIZE 65536 // Adjust buffer size according to typical file sizes and performance requirements
#define MAX_THREADS 10 // Number of threads for parallel processing

struct arg {
    char *filename;
    FILE *file;
    int cs, o, l;
    pthread_t tid;
};

void usage() {
    printf("Usage: ./program [--manpage|-cs|-o <output>] <input>\n");
}

void* process_file(void *arg) {
    struct arg *args = (struct arg *) arg;
    long lines = 0;
    char buffer[BUFFER_SIZE];

    while ((fgets(buffer, BUFFER_SIZE, args->file)) != NULL) {
        lines++;
    }

    fclose(args->file);
    pthread_detach(args->tid); // Detach thread to free resources when it terminates
    printf("Processed file '%s'. Total lines: %ld\n", args->filename, lines);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 2) usage();

    int c;
    char *output_file = NULL;
    char *log_file = "error.log";
    while ((c = getopt(argc, argv, ":h?m::cs:o:l:")) != -1) {
        switch (c) {
            case 'h':
            case '?':
                usage();
                break;
            case 'm':
                printf("Program details\n");
                exit(0);
            case 'c':
                // Set case-sensitive parsing flag (implicitly set in process_file)
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'l':
                log_file = optarg;
                break;
        }
    }

    if (argc - optind < 1) usage();
    char *input_file = argv[optind];

    int file_fd = open(input_file, O_RDONLY);
    struct stat st;
    fstat(file_fd, &st);

    if (file_fd == -1 || S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Error opening file '%s'\n", input_file);
        return 1;
    }

    FILE *input_stream = fdopen(file_fd, "r");
    if (!input_stream) {
        fprintf(stderr, "Failed to create input stream for file '%s'\n", input_file);
        return 1;
    }

    struct arg args[MAX_THREADS];
    int thread_idx = 0;
    while (thread_idx < MAX_THREADS && ftell(input_stream) < st.st_size) {
        struct arg *arg = &args[thread_idx++];
        char buffer[PATH_MAX];
        ssize_t read = readline(buffer, sizeof(buffer), input_stream);
        if (read <= 0) break; // EOF or error

        memset(arg, 0, sizeof(*arg));
        arg->filename = malloc(strlen(buffer) + 1);
        strcpy(arg->filename, buffer);
        arg->file = fopen(arg->filename, "r");
        if (!arg->file) {
            fprintf(stderr, "Failed to open file '%s'\n", arg->filename);
            free(arg->filename);
            continue;
        }
        arg->cs = 1; // Set case-sensitive parsing flag (implicitly set in process_file)
        arg->o = output_file;
        arg->l = log_file;
        arg->tid = pthread_create(&arg->tid, NULL, &process_file, arg);
    }

    if (thread_idx < MAX_THREADS) { // Cleanup any remaining threads
        for (int i = 0; i < thread_idx; ++i) {
            struct arg *arg = &args[i];
            pthread_join(arg->tid, NULL);
        }
    }

    if (output_file && freopen(output_file, "w", stdout)) {
        // Print total line count to output file if specified
    }

    return 0;
}
