import argparse
import hashlib
import os
from io import BytesIO

def md5_hash(file_path):
    hasher = hashlib.md5()
    buffer = BytesIO()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(8192)
            if not data:
                break
            hasher.update(data)
        hasher.digest_update(buffer)
        buffer.seek(0)
    return hasher.hexdigest()

def load_config(default_file, override):
    config = {}
    try:
        with open(default_file, 'r') as f:
            for line in f:
