    except Exception as e:
        print(f"Error loading default configuration: {e}")
        return {}

    for key, value in override.items():
        if key in config:
            config[key] = value

    return config

def save_config(file_path, config):
    with open(file_path, 'w') as f:
        for key, value in config.items():
