struct config_data {
    char dns_primary[256];
    char dns_secondary[256];
    RedisConfig redis;
};

void *redis_connect(void *arg) {
    ConfigurableComponent *config = arg;
    struct config_data *data = (struct config_data *)config->get_component_data();
    redisContext *context = redisConnect(data->redis.host, data->redis.port);
    if (context == NULL || context->err) {
        perror("Redis connect error");
        return NULL;
    }
    pthread_mutex_lock(&redis_lock);
    redis_conn = context;
    pthread_mutex_unlock(&redis_lock);
    return context;
}

int dns_resolve(const char *hostname, u_char *ip_addr) {
    ConfigurableComponent *config = ConfigurationLoader::get_instance()->load_config("dns.conf");
    struct config_data *data = (struct config_data *)config->get_component_data();

    redisContext *context;
    pthread_t redis_thread;

    if (!redis_conn) {
        pthread_create(&redis_thread, NULL, redis_connect, config);
        while (!redis_conn && pthread_join(redis_thread, NULL));
    }

    context = redis_conn;

    if (context == NULL) {
        // Handle error: DNS resolver not connected, use fallback mechanism
        // ...
        struct hostent *result = gethostbyname(hostname);
        if (result == NULL) {
            perror("gethostbyname");
            return -1;
        }
        memcpy(ip_addr, result->h_addr_list[0], sizeof(u_char)*result->h_length);
    } else {
        // Cache handling using Redis
        char cache_key[256];
        snprintf(cache_key, sizeof(cache_key), "dns:%s", hostname);
        u_char *cached_ip = (u_char *)redisGet(context, cache_key);

        if (cached_ip) {
            memcpy(ip_addr, cached_ip, sizeof(u_char)*4);
        } else {
            struct hostent *result = gethostbyname(hostname);
            if (result == NULL) {
                perror("gethostbyname");
                return -1;
            }
