        if (len <= 0) break; // Connection closed or error

        // Parse and validate UE information here

        sem_post(&service_mutex);
    }
}

void service_disconnect() {
    if (connected) {
        close(socket_fd);
        connected = false;
    }
}

sem_t pdu_mutex;
int pdu_count = 0;

NFAPI_CRC_INDICATION_PDU_T *generate_pdus(size_t count) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
