    pthread_t service_thread;
    if (socket_fd < 0) {
        service_connect();
    }
    pthread_create(&service_thread, NULL, service_read_ue_info, NULL);

    // Generate and populate PDUs concurrently
    for (size_t i = 0; i < count; ++i) {
        sem_wait(&service_mutex);
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pdus[pdu_count++];

        pdu->tag = (uint16_t)(rand() % 0xffff); // Use a smaller range if necessary for tag validation
        pdu->rnti = rand();
        pdu->crc_ind.cflag = rand() % 2;
    }

    sem_wait(&pdu_mutex);
    sem_destroy(&pdu_mutex);
    sem_destroy(&service_mutex);

    service_disconnect();

    return pdus;
}
