Pool* create_pool(size_t initial_capacity) {
    Pool* pool = malloc(sizeof(Pool));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->data = calloc(initial_capacity, sizeof(NFAPI_L1_RX_MSG_T));
    if (!pool->data) {
        free(pool);
        return NULL;
    }

    sem_init(&pool->sem_count, 0, initial_capacity);
    sem_init(&pool->sem_mutex, 0, 1);
    return pool;
}

NFAPI_L1_RX_MSG_T* acquire(Pool* pool) {
    sem_wait(&pool->sem_count);
    sem_wait(&pool->sem_mutex);

    if (pool->count >= pool->capacity) {
        sem_post(&pool->sem_mutex);
        return NULL;
    }

    NFAPI_L1_RX_MSG_T* msg = &pool->data[pool->count];
    memset(msg, 0, sizeof(*msg)); // Set default values and fill with random data for testing purposes
    pool->count++;
    sem_post(&pool->sem_mutex);

    return msg;
}

void release(Pool* pool, NFAPI_L1_RX_MSG_T* msg) {
    sem_wait(&pool->sem_mutex);
    pool->count--;
