#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/chacha.h>
#include <openssl/threefish.h>
#include <openssl/err.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <sys/mman.h>

typedef enum { AES, ChaCha20, Threefish } Algorithm;
typedef enum { CBC, GCM, CTR } Mode;

struct key_context {
    unsigned char keys[48]; // Key + IV for symmetric algorithms
    size_t key_len;
    void* deriver;
};

struct cipher_context {
    EVP_CIPHER_CTX *ctx;
    struct key_context *key;
    pthread_mutex_t mutex;
};

struct cipher_context *encrypt(const char *algorithm, const char *mode,
                                const unsigned char *key, size_t key_len,
                                const unsigned char *iv, EVP_CIPHER_KEYBIT key_bits) {
    struct cipher_context *ctx = mmap(NULL, sizeof(*ctx), PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);
    if (ctx == MAP_FAILED) {
        fprintf(stderr, "Memory mapping error\n");
        return NULL;
    }

    EVP_CIPHER *cipher = NULL;
    const EVP_CIPHER_ID id = EVP_get_cipherbyname(algorithm);
    if (id == EVP_aes_128_cbc() || id == EVP_chacha20poly1305_128() || id == EVP_threefish_256()) {
        cipher = EVP_CIPHER_new();
        EVP_CIPHER_set_cipher(cipher, id);
    } else {
        ERR_print_errors_fp(stderr);
        munmap(ctx, sizeof(*ctx));
        return NULL;
    }

    pthread_mutex_init(&ctx->mutex, NULL);
    ctx->key = calloc(1, sizeof(*ctx->key) + key_len);
    if (!ctx->key) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_free(cipher);
        munmap(ctx, sizeof(*ctx));
        return NULL;
    }
    memcpy(ctx->key->keys, key, key_len);
    ctx->key->key_len = key_len;

    const EVP_CIPHER_MODE mode_val = (mode == "CBC") ? EVP_CIPH_CFB : ((mode == "GCM") ? EVP_CIPH_GCM : EVP_CIPH_CTR);
    if (!EVP_CIPHER_set_mode(cipher, mode_val)) {
        ERR_print_errors_fp(stderr);
        free(ctx->key);
        EVP_CIPHER_free(cipher);
        munmap(ctx, sizeof(*ctx));
        return NULL;
    }
    if (mode == "GCM" && iv) {
        ctx->key->iv = iv;
        ctx->key->key_len += 16;
    } else {
        ctx->key->iv = ctx->key->keys + key_len;
    }

    const EVP_CIPHER_IVLEN cipher_iv_len = EVP_CIPHER_iv_length(cipher);
    if (cipher_iv_len > 16) {
        ctx->key->iv += cipher_iv_len - 16;
        ctx->key->key_len += cipher_iv_len - 16;
    }

    if (!EVP_CIPHER_set_key_length(cipher, key_bits)) {
        ERR_print_errors_fp(stderr);
        free(ctx->key);
        EVP_CIPHER_free(cipher);
        munmap(ctx, sizeof(*ctx));
        return NULL;
    }

    if (!EVP_CIPHER_CTX_init(ctx->ctx)) {
        ERR_print_errors_fp(stderr);
        free(ctx->key);
        EVP_CIPHER_free(cipher);
        munmap(ctx, sizeof(*ctx));
        return NULL;
    }
    ctx->ctx->cipher = cipher;

    return ctx;
}
```

