void generate_unique_rnti(NFAPI_CRC_INDICATION_PDU_T *pdu, size_t start_index) {
    pthread_mutex_lock(&mutex); // Assuming a global mutex for thread safety
    do {
        pdu->RNTI = (start_index + pthread_self()->id % MAX_ENTRIES);
    } while (bin_search(pdu, MAX_ENTRIES) != -1);
    pthread_mutex_unlock(&mutex);
}

bool bin_search(const NFAPI_CRC_INDICATION_PDU_T *key, size_t n, size_t low, size_t high) {
    if (high <= low) return false;
    const size_t mid = (low + high) / 2;
    return key->RNTI == entries[mid].RNTI ? true : (key->RNTI < entries[mid].RNTI ? bin_search(key, n, low, mid) : bin_search(key, n, mid + 1, high));
}

void* serialize(struct list *list, void *dest, size_t dest_size) {
