// Custom memory pool allocator
typedef struct Pool {
    void* freeList;
    size_t size;
} Pool;

Pool* create_pool(size_t size, size_t alignment) {
    Pool* pool = malloc(sizeof(Pool));
    if (!pool) return NULL;

    pool->freeList = calloc(size / alignment, sizeof(void*));
    if (!pool->freeList) {
        free(pool);
        return NULL;
    }

    pool->size = size;
    return pool;
}

void* pool_alloc(Pool* pool, size_t size, size_t alignment) {
    if (alignment > pool->size) alignment = pool->size;

    void** list = pool->freeList;
    void* ptr = list[0];

    if (!ptr) return NULL;

    // Update free list
    for (int i = 1; i < alignment && list[i]; ++i) {
        void* temp = list[i];
        list[i] = list[i + 1];
        list[++alignment - 1] = temp;
    }

    return ptr;
}

void pool_free(Pool* pool, void* ptr) {
    size_t alignment = sizeof(ptr);

    if (!pool->freeList) pool->freeList = malloc(alignment * pool->size);

    void** list = pool->freeList;
    int index = (int)((uintptr_t)ptr - (uintptr_t)(list[0])) / alignment;

    for (int i = alignment; i--; ) {
        if (!list[i + index]) list[i + index] = ptr;
        else break;
    }
}

