```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct _TCP_CONNECTION_RECORD {
    uint32_t id;
    char source_ip[32];
    char destination_ip[32];
    uint16_t source_port, destination_port;
    uint8_t status_flags; // custom flags
    struct _TCP_CONNECTION_RECORD *next;
    pthread_mutex_t lock;
} TCP_CONNECTION_RECORD;

typedef struct _MEMORY_POOL {
    void* start, *end;
    size_t block_size;
    struct _MEMORY_POOL* next;
} MEMORY_POOL;

TCP_CONNECTION_RECORD* tcp_connection_record_create(const char* source_ip, const char* destination_ip, uint16_t source_port, uint16_t destination_port, uint8_t status_flags) {
    TCP_CONNECTION_RECORD* record = (TCP_CONNECTION_RECORD*) pool_alloc(sizeof(TCP_CONNECTION_RECORD));
    if (!record) return NULL;

    strncpy(record->source_ip, source_ip, sizeof(record->source_ip));
    strncpy(record->destination_ip, destination_ip, sizeof(record->destination_ip));
    record->source_port = source_port;
    record->destination_port = destination_port;
    record->status_flags = status_flags;

    pthread_mutex_init(&record->lock, NULL);
    return record;
}

void tcp_connection_record_destroy(TCP_CONNECTION_RECORD* record) {
    if (!record) return;
    pthread_mutex_destroy(&record->lock);
    pool_free(record);
}

void* pool_alloc(size_t size) {
    MEMORY_POOL *pool = list, *prev, *new_pool;
    if (size <= 0 || !pool) return NULL;

    new_pool = malloc(sizeof(MEMORY_POOL));
    if (!new_pool) return NULL;

    new_pool->start = NULL;
    new_pool->end = NULL;
    new_pool->block_size = size;
    new_pool->next = NULL;

    if (list == NULL) { // first allocation
        list = new_pool;
        return list->start = malloc(new_pool->block_size);
    }

    prev = pool;
    while (pool != NULL && (prev->end + prev->block_size) <= pool->start)
        prev = pool, pool = pool->next; // advance to next available block

    if (!pool) { // create a new memory pool if none is available
        pool = malloc(sizeof(MEMORY_POOL));
        if (!pool) return NULL;

        pool->start = malloc(size);
        if (!pool->start) {
            free(pool);
            return NULL;
        }

        pool->end = pool->start + size - 1;
        pool->block_size = size;
        pool->next = list;
        list = pool;
    }

    void* result = pool->start;
    pool->start = (char*)pool->start + size;
    if (pool->start == pool->end) { // no space left in this block, so we need a new one
        pool->end = NULL;
        pool->next = new_pool;
        new_pool->start = result;
    }
    return result;
}
```

