#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>

typedef struct {
    sockaddr_in src, dest;
    uint16_t source_port, destination_port;
    int connection_status; // Connection flags
    pthread_mutex_t id_lock;
    uint32_t connection_id;
} TCP_CONNECTION_RECORD;

typedef struct NODE {
    TCP_CONNECTION_RECORD *record;
    struct NODE *next;
    _Atomic(int) ref_count;
} NODE;

NODE* node_new(TCP_CONNECTION_RECORD* rec) {
    NODE* new_node = malloc(sizeof(NODE));
    if (!new_node) return NULL;

    new_node->record = rec;
    new_node->next = NULL;
    atomic_init(&new_node->ref_count, 1);
    pthread_mutex_init(&new_node->id_lock, NULL);

    return new_node;
}

void node_ref(NODE* node) {
    if (node && ++(node->ref_count)) return;
}

void node_unref(NODE* node) {
    if (!--(node->ref_count)) {
        pthread_mutex_destroy(&node->id_lock);
        free(node);
    }
}

void list_insert(TCP_CONNECTION_RECORD** head, TCP_CONNECTION_RECORD* rec) {
    NODE* new_node = node_new(rec);
    if (!new_node) return;

    pthread_mutex_lock(&new_node->id_lock);
    rec->connection_id = generate_id(); // Use an external ID generation service
    pthread_mutex_unlock(&new_node->id_lock);

    NODE* traverse = *head;
    if (!traverse) {
        *head = new_node;
        return;
    }

    while (traverse->next) traverse = traverse->next;
    traverse->next = new_node;
}

TCP_CONNECTION_RECORD* list_remove(TCP_CONNECTION_RECORD** head, uint32_t connection_id) {
    NODE* traverse = *head;

    while (traverse) {
        if (traverse->record->connection_id == connection_id) {
            TCP_CONNECTION_RECORD* rec = traverse->record;

            node_unref(traverse);
            *head = traverse->next;
            return rec;
        }

        traverse = traverse->next;
    }

    return NULL;
}

