#include <set>
#include <boost/filesystem.hpp>
#include <nlohmann/json.hpp>
#include <boost/thread/thread_pool.hpp>
#include <boost/asio/streambuf.hpp>
#include <boost/iostreams/filtering_streambuf.hpp>
#include <boost/iostreams/filter/gzip.hpp>
#include <boost/program_options.hpp>

namespace fs = boost::filesystem;
using json = nlohmann::json;
using namespace std;
using namespace boost::asio;
using namespace boost::iostreams;

struct Processor {
    map<string, string> keysValues;
    set<string> uniqueKeys;

    void operator()(const json &j) {
        for (auto &pair : j.items()) {
            keysValues[pair.key()] = pair.value().dump();
            uniqueKeys.insert(pair.key());
        }
        uniqueKeys.insert("count");
        keysValues["count"] = to_string(uniqueKeys.size());
    }

    void clear() {
        keysValues.clear();
        uniqueKeys.clear();
    }
};

void processFile(const string &filename) {
    ifstream file(filename);
    if (!file.is_open()) {
        cerr << "Error opening file: " << filename << endl;
        return;
    }

    streambuf<char> input;
    filtering_streambuf<input> gzipInput;
    if (fs::exists(filename + ".gz")) {
        ifstream gzFile(filename + ".gz");
        gzipInput.push(gzip::decompressor());
        gzipInput.push(gzFile);
    } else {
        gzipInput.push(istreambuf_iterator<char>());
        gzipInput.push(file);
    }

    json j;
    try {
        j = json::parse(gzipInput, static_cast<charconst*>(gzipInput.data()), gzipInput.size());
    } catch (json::parse_error &e) {
        cerr << "Error parsing JSON in file: " << filename << ", error: " << e.what() << endl;
        return;
    }

    Processor processor;
    for (auto &obj : j.items()) {
        processor(obj.value());
    }

    // Store processed data and clear memory for next file
    auto it = uniqueKeys.begin();
    cout << *it++;
    for (const auto &kv : processor.keysValues) {
        cout << '\t' << kv.first << ':' << kv.second;
    }
    cout << '\t' << *(it) << endl;
    processor.clear();
}

int main(int argc, char *argv[]) {
    namespace po = boost::program_options;
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "Print help")
        ("filter", po::value<string>()->default_value(""), "Filter files by name or extension")
        ("size", po::value<uint64_t>()->default_value(0), "Filter files by size (in bytes)")
        ("threads,t", po::value<int>()->default_value(thread::hardware_concurrency()), "Number of threads to use")
        ("format,f", po::value<string>()->default_value("keys\tvalues"), "Output format")
        ("config,c", "Path to configuration file");

    po::variables_map vm;
    store(parse_command_line(argc, argv, desc), vm);
    notify(vm);

    if (vm.count("help")) {
        cout << desc << endl;
        return 0;
    }

    string configFile = vm["config"].as<string>();
    // Load configuration here

    boost::thread_pool pool(vm["threads"].as<int>());
    fs::path path(".");
    if (!vm["filter"].as<string>().empty()) {
        path /= vm["filter"].as<string>();
    }
    for (const auto &entry : fs::recursive_directory_iterator(path)) {
        string filename = entry.path().filename().string();
        uint64_t size = entry.file_size();

        if (vm["filter"].as<string>() != "" && (fs::extension(filename) != vm["filter"].as<string>() || size < vm["size"].as<uint64_t>())) {
            continue;
        }

        pool.enqueue(&processFile, filename);
    }

    return 0;
}
