using System;
using System.Collections.Generic;
using System.Numerics;
using System.Runtime.InteropServices;
using System.Text;

public class RandomValueGenerator
{
    private readonly Random _random;
    private readonly BigInteger _seed;
    private readonly float _minFloat;
    private readonly float _maxFloat;
    private readonly int _minInt;
    private readonly int _maxInt;

    [ThreadStatic]
    private static readonly Dictionary<ulong, (float minFloat, float maxFloat, int minInt, int maxInt)> ThreadData = new();

    public RandomValueGenerator(BigInteger seed = 0, float minFloat = 0f, float maxFloat = 1f, int minInt = int.MinValue, int maxInt = int.MaxValue)
    {
        _seed = seed;
        _minFloat = ValidateRange(minFloat, maxFloat);
        _maxFloat = ValidateRange(minFloat, maxFloat);
        _minInt = ValidateRange(minInt, maxInt);
        _maxInt = ValidateRange(minInt, maxInt);

        _random = new Random((int)_seed);
        if (ThreadData.TryGetValue(Convert.ToUInt64(_seed), out var threadData))
            throw new ArgumentException("Specified seed has already been used in this thread.");

        ThreadData[Convert.ToUInt64(_seed)] = (_minFloat, _maxFloat, _minInt, _maxInt);
    }

    private static float ValidateRange(float value, float limit) => value < limit ? value : throw new ArgumentOutOfRangeException(nameof(value), "Invalid range configuration: Bound should be less than the limit.");

    public float NextFloat()
    {
        if (_maxFloat - _minFloat <= 0f)
            throw new InvalidOperationException("Cannot generate random values within this range as it is empty or degenerate.");

        LogErrorIfNecessary("Generated a random float");
        return (float)_random.NextDouble() * (_maxFloat - _minFloat) + _minFloat;
    }

    public int NextInt()
    {
        if (_maxInt - _minInt < 1)
            throw new InvalidOperationException("Cannot generate random values within this range as it contains only one value.");

        LogErrorIfNecessary("Generated a random integer");
        return (int)_random.Next(_minInt, _maxInt + 1);
    }

    public void NextProbable(IDictionary<int, float> probabilities)
    {
        if (probabilities is null || probabilities.Count == 0)
            throw new ArgumentException("Invalid probability distribution configuration.");

        float sum = 0f;
        foreach (var pair in probabilities)
        {
            if (pair.Key < _minInt || _maxInt < pair.Key)
                throw new ArgumentOutOfRangeException(nameof(pair.Key), "Invalid probability distribution configuration: Index should be within the configured range.");

            sum += pair.Value;
        }

        if (sum <= 0f)
            throw new ArgumentException("Probabilities must add up to a positive value.");

        LogErrorIfNecessary("Generated a random integer using probability distribution");
        var cumulativeSum = new List<float>();
        foreach (var pair in probabilities)
        {
            cumulativeSum.Add(cumulativeSum.Count > 0 ? cumulativeSum[^1] + pair.Value : pair.Value);
        }

        float randomFloat = _random.NextDouble() * sum;
        int index = Array.BinarySearch(cumulativeSum.ToArray(), randomFloat);
        if (index < 0)
            index = ~index;

        return probabilities.ElementAt(index).Key;
    }

    private void LogErrorIfNecessary(string message)
    {
        if (_random.Next(100) == 0)
        {
            var bufferSize = 4096;
            var buffer = stackalloc char[bufferSize];
            var formatString = "RandomValueGenerator: {0}\n";
            va_list args;
            va_start(args, message);
            snprintf(buffer, buffer.Length, formatString, message, args);
            va_end(args);

            Console.Error.Write(buffer);
        }
    }

    public override string ToString()
    {
        var seedStr = _seed == 0 ? "" : $", Seed: {_seed}";
        return $"Range: [{_minInt}, {_maxInt}) for integers, ({_minFloat}, {_maxFloat}) for floats{seedStr}";
    }

    public void Reset()
    {
        _random = new Random((int)_seed);
        ThreadData.Remove(Convert.ToUInt64(_seed));
    }
}
