    public void AddRange<T>(Range<T> range)
    {
        if (range.Min > range.Max)
            throw new ArgumentOutOfRangeException(nameof(range), "Inclusive and exclusive bounds must not cross.");

        if (!typeof(T).Equals(typeof(float)) && !typeof(T).Equals(typeof(int)))
            throw new NotSupportedException("Only integers and floats are supported.");

        if (typeof(T) == typeof(float))
            _floats.Add(range);
        else
            _integers.Add(range);
    }

    public T Generate<T>(Range<T> range)
    {
        if (!_floats.Any(r => r.Type == typeof(T)) && !_integers.Any(r => r.Type == typeof(T)))
            throw new KeyNotFoundException($"No ranges of type {typeof(T).Name} found.");

        Range<T> matchingRange = _floats.FirstOrDefault(r => r.Type == typeof(T)) ?? _integers.FirstOrDefault(r => r.Type == typeof(T));

        if (matchingRange == null)
            throw new KeyNotFoundException($"No ranges of type {typeof(T).Name} found.");

        if (!IsWithinBounds(matchingRange, _random.Next()))
            Generate(matchingRange);

        return matchingRange.Generate(_random);
    }

    public void Generate<T>(Range<T> range)
    {
        T value;
        do
        {
            value = (T)(range.Min + _random.NextDouble() * (range.Max - range.Min));
        } while (!IsWithinBounds(range, value));

        if (_totalWeight == 0)
            SetProbabilityWeights(_floats, _integers);

        double probability = GetProbability(value, range);
        _random.AddSample(value, probability / _totalWeight);
    }

    private void SetProbabilityWeights(List<Range<float>> floats, List<Range<int>> integers)
    {
