    }

    private double GetProbability<T>(T value, Range<T> range)
    {
        if (typeof(T) == typeof(float))
            return _floats.FirstOrDefault(r => r.Type == typeof(T)).GetProbability(value);
        else
            return _integers.FirstOrDefault(r => r.Type == typeof(T)).GetProbability(value);
    }

    private bool IsWithinBounds<T>(Range<T> range, T value)
    {
        if (typeof(T) == typeof(float))
            return range.Min <= value && value <= range.Max;
        else
            return range.Min <= value && value < range.Max;
    }

    private void LogError(string format, params object[] args)
    {
