                sb.AppendLine();

            if (range.Type == typeof(float))
                sb.Append($"Float Range ({range.Min} - {range.Max})");
            else
                sb.Append($"Int Range ({range.Min} - {range.Max})");
        }

        if (_seed > 0)
            sb.AppendFormat(" (Seed: {0})", _seed);

        return sb.ToString();
    }

    public void Reset()
    {
        _random = new Random(_seed);
    }
}

public struct Range<T> where T : struct
{
    public Type Type { get; set; }
    public T Min { get; set; }
    public T Max { get; set; }

    public Range(T min, T max)
    {
        Type = typeof(T);
        Min = min;
        Max = max;
    }

    public T Generate(Random random) => (T)(Min + random.NextDouble() * (Max - Min));

    public double GetProbability(T value)
    {
        if (Type == typeof(float))
            return 0; // Implement probability calculation for integers here

        if (Min <= value && value < Max)
            return 1.0 / (Max - Min);

        return 0;
    }
}
