import os
import sys
import re
import glob
from functools import lru_cache, wraps
import threading
import gc
import zlib
import codecs
import time

class ConcurrentFileProcessor:
    def __init__(self, base_dir, delimiter='\n', custom_delimiter=None, field=0, max_lines=sys.maxsize, max_output_size=1073741824, regex_pattern=r'', compression=zlib.compressobj(wbits=9)):
        self.base_dir = base_dir
        self.delimiter = delimiter
        self.custom_delimiter = custom_delimiter or delimiter
        self.field = field
        self.max_lines = max_lines
        self.max_output_size = max_output_size
        self.regex_pattern = re.compile(regex_pattern)
        self.compression = compression
        self.lock = threading.Lock()
        self.workers = []
        self.log_file = None

    def _resolve_path(self, path):
        if os.path.islink(path):
            return os.readlink(path)
        return path

    @lru_cache(maxsize=64)
    def _walk(self, dirpath, depth=0):
        for root, dirs, files in os.walk(dirpath):
            for file in files:
                full_file = os.path.join(root, file)
                resolved_path = self._resolve_path(full_file)
                if os.path.isfile(resolved_path) and resolved_path.endswith('.txt'):
                    yield from (resolved_path,)

    @wraps(_walk)
    def walk(self):
        for path in self._walk(self.base_dir):
            yield path

    def _process_file(self, file_path):
        with self.lock:
            with open(file_path, encoding='utf-8') as f:
                lines = (line for line in f)
                if self.custom_delimiter:
                    lines = filter(lambda x: self.custom_delimiter in x, lines)
                if self.regex_pattern:
                    lines = filter(self.regex_pattern.match, lines)
                lines = itertools.islice(lines, self.max_lines)
                total_lines = sum(1 for _ in lines)
                output = [next(lines)[self.field] for _ in range(total_lines)]
                if len(output) > self.max_output_size:
                    output = self.compression.compress(b''.join(output))
            if self.log_file:
                with open(self.log_file, 'a') as log:
                    log.write(f"{time.asctime()}: processed {file_path}, lines={total_lines}, output_size={len(output)}\n")
            gc.collect()

    def process(self):
        for file_path in self.walk():
            thread = threading.Thread(target=self._process_file, args=(file_path,))
            self.workers.append(thread)
            thread.start()
        for thread in self.workers:
            thread.join()

    def log(self, log_file):
        self.log_file = log_file

if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('-d', '--directories', nargs='+', required=True, help='Comma-separated list of directories to process')
    parser.add_argument('-l', '--logfile', help='Path for the log file')
    args = parser.parse_args()

    processor = ConcurrentFileProcessor(*args.directories)
    if args.logfile:
        processor.log(args.logfile)
    processor.process()
