import concurrent.futures
from hashlib import md5
from zipfile import ZipFile, ZIP_DEFLATED
from contextlib import suppress

def is_text_file(path):
    return path.endswith(('.txt', '.csv', '.log'))

def get_real_path(path):
    if os.path.islink(path):
        return get_real_path(os.readlink(path))
    return path

def readlines(file, delimiter=None, regex=None):
    lines = []
    chunk = 1024

    with open(file, 'r', encoding='utf-8') as f:
        while True:
            data = f.read(chunk)
            if not data:
                break
            lines.extend(data.splitlines())

    if delimiter:
        lines = [line.split(delimiter) for line in lines]

    if regex:
        lines = [line for line in lines if re.match(regex, line)]

    return lines

def validate_checksum(file, checksum):
    with open(file, 'rb') as f:
        calculated_checksum = md5(f.read()).hexdigest()

    return calculated_checksum == checksum

def process_directory(root, output_log=None):
    processed_files = 0
    total_lines = 0
    errors = []

    for path, dirs, files in os.walk(root):
        for file in files:
            real_path = get_real_path(os.path.join(path, file))
            if not is_text_file(real_path) or validate_checksum(real_path, checksum(real_path)):
                continue

            try:
                lines = readlines(real_path)
                total_lines += len(lines)
                processed_files += 1

                if output_log:
                    output_log.write(f'{os.path.relpath(real_path, root)}\n')
            except Exception as e:
                errors.append((real_path, str(e)))

    return processed_files, total_lines, errors

def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('root', help='Root directory to process')
    parser.add_argument('--checksum', required=True, help='Checksum of the data files')
    parser.add_argument('--output-log', help='Path to output log file')
    parser.add_argument('--regex', help='Regular expression pattern for filtering lines')
    args = parser.parse_args()

    processed_files, total_lines, errors = process_directory(args.root, args.output_log)

    print(f'Processed {processed_files} files with {total_lines} lines')
    if errors:
        print('Encountered errors:')
        for error in errors:
            print(f'\t{error[0]}: {error[1]}')

if __name__ == '__main__':
    main()
