```cpp
#include <boost/asio/ip/address.hpp>
#include <boost/asio/ip/tcp.hpp>
#include <boost/cryptography/sha256.hpp>
#include <boost/circular_buffer.hpp>
#include <iostream>
#include <vector>
#include <memory>

#define DATA_PACKET_RECORD_SIZE 1024 // Size of the struct in bytes
#define MAX_NUM_PACKETS 100000      // Max number of packets to initialize

struct DATA_PACKET_RECORD_T {
    boost::asio::ip::address source_ip;
    uint16_t destination_port;
    std::array<uint8_t, 32> payload_digest; // SHA-256 digest
};

struct MemPool final {
    std::vector<char> buffer; // Buffer for struct instances
    size_t capacity = 0;       // Current buffer capacity
    size_t head = 0;           // Index of the next available slot in the buffer

    DATA_PACKET_RECORD_T* alloc() {
        if (head == capacity) {
            size_t newCapacity = std::max(capacity * 2, DATA_PACKET_RECORD_SIZE * 10);
            buffer.resize(newCapacity);
            capacity = newCapacity;
        }
        return reinterpret_cast<DATA_PACKET_RECORD_T*>(&buffer[head]);
    }

    void free(DATA_PACKET_RECORD_T* packet) {
        head += DATA_PACKET_RECORD_SIZE;
    }
};

MemPool memPool; // Custom memory pool instance

// Thread-safe SHA-256 digest computation using boost::cryptography and a circular buffer
void computeSHA256(const char* payload, std::array<uint8_t, 32>& digest) {
    static boost::circular_buffer<boost::cryptography::sha256::hash> cb(1);
    boost::cryptography::sha256::hash h;
    auto data = reinterpret_cast<const uint8_t*>(payload);
    h.process_bytes(data, sizeof(payload));
    digest = h.finalize();
}

void logPacketProcessingStats(const DATA_PACKET_RECORD_T& packet, bool success) {
    std::cout << "Packet processing stats: " << std::endl;
    std::cout << "Source IP:       " << packet.source_ip << std::endl;
    std::cout << "Destination Port: " << packet.destination_port << std::endl;
    if (success) {
        std::cout << "SHA-256 digest valid" << std::endl;
    } else {
        std::cout << "SHA-256 digest invalid" << std::endl;
    }
}

void initPackets() {
    DATA_PACKET_RECORD_T* packets = new DATA_PACKET_RECORD_T[MAX_NUM_PACKETS];

    for (size_t i = 0; i < MAX_NUM_PACKETS; ++i) {
        auto packet = memPool.alloc();
        packet->source_ip = boost::asio::ip::make_address(boost::asio::ip::address_v4::loopback()); // Use local IP for simplicity
        packet->destination_port = 80 + (i % 65536);

        // Assume a payload string is provided externally and validated before passing to this function
        const char* payload = "...";
        computeSHA256(payload, packet->payload_digest);
    }

    delete[] packets;
}

int main() {
    initPackets();

    // Process packets from different scenarios including boundary conditions and performance implications
    const char* payload1 = "...";
    logPacketProcessingStats(*memPool.alloc(), computeSHA256(payload1, std::array<uint8_t, 32>()));

    // Edge case: Exact size limit
    DATA_PACKET_RECORD_T packet;
    const char* payload2 = "...";
    if (payload2[DATA_PACKET_RECORD_SIZE - 1] != '\0') {
        std::cout << "Payload too large" << std::endl;
    } else {
        computeSHA256(payload2, packet.payload_digest);
        logPacketProcessingStats(packet, computeSHA256(payload2, packet.payload_digest));
    }
}
