['```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <map>
#include <filesystem>
#include <system_error>
#include <fmt/core.h> // Optional formatted output library (https://github.com/fmtlib/fmt)

namespace fs = std::filesystem;

struct FileStat {
    size_t lines = 0;
    size_t longestLineLength = 0;
};

std::map<fs::path, FileStat> processFiles(int argc, char* argv[]) {
    std::map<fs::path, FileStat> fileStats;
    for (int i = 1; i < argc; ++i) {
        fs::path path(argv[i]);
        if (!fs::exists(path)) {
            fmt::print("Error: {} does not exist\n", path);
            continue;
        }

        FileStat fileStat{};
        size_t longestLineLength = 0;
        std::ifstream file(path, std::ios::ate | std::ios::in);
        if (!file) {
            fmt::print("Error: Unable to open {} for reading\n", path);
            continue;
        }
        auto size = file.tellg();
        file.seekg(0, std::ios::beg);

        std::string line;
        while (std::getline(file, line)) {
            ++fileStat.lines;
            if (line.length() > longestLineLength) {
                longestLineLength = line.length();
            }
        }
        fileStat.longestLineLength = std::max(fileStat.longestLineLength, longestLineLength);
        fileStats[path] = fileStat;
    }
    return fileStats;
}

void displayUsageInformation() {
    fmt::print("Usage: {} [--help] [-d] [-o output_file] [file ...]\n" R"(Options:
  --help                 Show this help message.
  -d                     Display statistics for each individual file.
  -o output_file         Redirect summary output to a specified file.)", argv[0]);
}

void displayStatsForEachFile(const std::map<fs::path, FileStat>& fileStats) {
    if (fileStats.empty()) {
        fmt::print("No files provided or invalid file paths.\n");
        return;
    }

    for (const auto& [path, stat] : fileStats) {
        fmt::print("{}: Lines: {}, Longest line length: {}\n", path.string(), stat.lines, stat.longestLineLength);
    }
}

void writeSummaryToFile(const std::map<fs::path, FileStat>& fileStats, const fs::path& outputPath) {
    if (!outputPath) return;

    std::ofstream summary(outputPath, std::ios::trunc | std::ios::out);
    if (summary.is_open()) {
        for (const auto& [path, stat] : fileStats) {
            summary << path.string() << ": Lines: " << stat.lines << ", Longest line length: " << stat.longestLineLength << "\n";
        }
    } else {
        fmt::print("Error: Unable to open output file for writing.\n");
    }
}

int main(int argc, char* argv[]) {
    bool displayHelp = false;
    bool displayStatsForEachFile = false;
    fs::path outputPath;

    for (int i = 1; i < argc; ++i) {
        if (argv[i][0] == '-' && argv[i][1] != '-') { // Short option
            if (outputPath && displayHelp) {
                displayUsageInformation();
                return EXIT_FAILURE;
            }

            switch (argv[i][1]) {
                case 'h':
                    displayHelp = true;
                    break;
                case 'd':
                    displayStatsForEachFile = true;
                    break;
                case 'o':
                    if (++i == argc) {
                        displayUsageInformation();
                        return EXIT_FAILURE;
                    }
                    outputPath = fs::path(argv[i]);
                    break;
            }
        } else { // File path
            processFiles(argc, argv);
        }
    }

    if (displayHelp) {
        displayUsageInformation();
        return EXIT_SUCCESS;
    }

    auto fileStats = processFiles(argc, argv);

    if (displayStatsForEachFile) {
        displayStatsForEachFile(fileStats);
    } else {
        size_t totalLines = 0;
        size_t longestLineLength = 0;
        for (const auto& [_, stat] : fileStats) {
            totalLines += stat.lines;
            longestLineLength = std::max(longestLineLength, stat.longestLineLength);
        }

        fmt::print("Total lines: {}, Longest line length: {}\n", totalLines, longestLineLength);
    }

    if (outputPath) writeSummaryToFile(fileStats, outputPath);

    return EXIT_SUCCESS;
}
```

This code uses the modern C++ libraries to read files, including `<filesystem>` for handling paths and `<fstream>` for reading files. The program takes command line arguments, performs the required operations, and provides error messages when necessary. It supports options such as `--help`, `-d`, and `-o output_file`.']

