#include <mutex>
#include <cstdint>
#include <random>
#include <gsl/gsl_simd>
#include <gsl/gsl_check_range.h>
#include <boost/asio/io_service.hpp>
#include <spdlog/spdlog.h>
#include <pthread.h>

typedef struct {
    gsl_simd128_uint64_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    bool CRCFLAG;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> generate_structures(size_t n) {
    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> structures;
    std::mt19937 rng(std::random_device{}());
    std::uniform_int_distribution<> distrib(0, 0xFFFFFFFF);

    std::mutex mtx;
    size_t success_count = 0;
    spdlog::get("logger")->info("Starting structure generation...");

    for (size_t i = 0; i < n; ++i) {
        auto pdu = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>();
        pdu->RX_UE_INFORMATION_TAG = gsl_simd128_uint64_get(gsl_simd128_shuffle_even(gsl_simd128_set32(i)));
        pdu->RNTI = distrib(rng);
        pdu->CRCFLAG = distrib(rng) & 1;
        pdu->CRC_INDICATION_REL8_TAG = calculate_crc(pdu.get());

        if (GSL_CHECK_RANGE((size_t)pdu->CRC_INDICATION_REL8_TAG, 0, 0xFFFFFFFF)) {
            structures.push_back(std::move(pdu));
            ++success_count;
        } else {
            std::unique_lock<std::mutex> lock(mtx);
            spdlog::get("logger")->error("Failed to generate valid structure #{}", i);
            lock.unlock();
        }
    }

    spdlog::get("logger")->info("Structure generation complete: {}", success_count);
    return structures;
}

uint32_t calculate_crc(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    constexpr uint32_t POLYNOMIAL = 0xEDB88320;
    constexpr size_t BITS_PER_WORD = sizeof(uint32_t) * CHAR_BIT;

    uint32_t crc = ~0u;
    for (size_t i = 0, byte_index = 0; i < sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i, byte_index += BITS_PER_WORD) {
        const uint32_t word = reinterpret_cast<const uint32_t*>(&pdu[i])[byte_index / BITS_PER_WORD];
        for (size_t j = 0; j < BITS_PER_WORD; ++j) {
            if ((word >> (BITS_PER_WORD - j - 1)) & 1) {
                crc = (crc << 1) ^ (crc & POLYNOMIAL ? POLYNOMIAL : 0);
            } else {
                crc = crc >> 1;
            }
        }
    }
    return ~crc;
}
```

