int allocate_crc_indications(size_t N, const char *input, bool use_md5) {
    if (!input || strlen(input) <= 0) {
        log("Error: Input string cannot be null or empty.");
        return -1;
    }

    size_t input_length = strlen(input);
    if (use_md5 && input_length < 16) { // MD5 requires a minimum of 16 bytes
        throw InvalidInputLengthException();
    }

    NFAPI_CRC_INDICATION_PDU_T *data = nullptr;
    size_t retries = 0;

    while (true) {
        data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (data != nullptr) {
            break;
        }
        log("Error: Memory allocation failed. Retrying...");
        retries++;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (size_t i = 0; i < N; ++i) {
        data[i].rx_ue_information.tag = RX_UE_INFORMATION_TAG_random();
        data[i].rnti.value = RNTI_random(use_md5 ? RNTI_FORMAT_SHA256 : RNTI_FORMAT_MD5);

        // Parallelize the CRCFLAG calculation for each element
        pthread_t thread;
        pthread_create(&thread, NULL, [i, use_md5] (void*) {
            data[i].crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG_random();
            data[i].crc_indication_rel8.crcflag = use_md5 ? md5(input).md[3] & 0xFF : SHA256(input).digest[3];
        });
        pthread_join(thread, NULL);
    }

    // Lock the data array to validate RNTI uniqueness and handle retries if necessary
    pthread_mutex_lock(&mutex);
    for (size_t i = 1; i < N; ++i) {
        for (size_t j = 0; j < i; ++j) {
            if (data[i].rnti.value == data[j].rnti.value) {
                free(data);
                data = nullptr;
                retries++;
                break;
            }
        }
        if (!data) {
            log("Error: Failed to allocate memory after %lu retries.", retries);
            return -1;
        }
    }
    pthread_mutex_unlock(&mutex);

    // Release the mutex and return the allocated data
    pthread_mutex_destroy(&mutex);
    log("Allocated %zu CRCI indications successfully.", N);
    return retries > 0 ? retries : 0;
}
