class CustomException : public std::exception {
public:
    const char* what() const noexcept override {
        return message_.c_str();
    }

    explicit CustomException(const std::string& message) : message_(message) {}

private:
    std::string message_;
};

class NFAPI_CRC_INDICATION_PDU_T {
public:
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
};

unsigned int deserialize_and_allocate_crc_indications(const std::string& input, unsigned int N, bool use_md5) {
    unsigned int retries = 0;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> indications;
    std::map<uint32_t, bool> rnti_used;

    while (true) {
        try {
            if (use_md5) {
                if (input.length() < 16) { // Minimum length for MD5 is 16 bytes
                    throw CustomException("Input string too short for MD5 hashing");
                }
            } else if (input.length() < 32) { // Minimum length for SHA-256 is 32 bytes
                throw CustomException("Input string too short for SHA-256 hashing");
            }

            // Deserialize the input byte array into an object of a specific class using Java serialization techniques
            // (Assuming you have implemented this part)

            if (!rnti_used.empty()) {
                auto it = rnti_used.begin();
                while (it != rnti_used.end()) {
                    if (it->second == true && indications.back().rnti == it->first) {
                        it = rnti_used.erase(it);
                        retries++;
                        continue;
                    }
                    ++it;
                }
            }

            if (rnti_used.size() < N) {
                indications.push_back(*it);
                rnti_used[indications.back().rnti] = true;
                break;
            }
        } catch (const std::exception& e) {
            ++retries;
            std::cerr << "Error: " << e.what() << "\n";
        }
    }

    if (retries > 0) {
        BOOST_LOG_TRIVIAL(info) << "Retried " << retries << " times to achieve unique RNTI values.";
    }

    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[]> indications_array(new NFAPI_CRC_INDICATION_PDU_T[indications.size()]);
    std::copy(indications.begin(), indications.end(), indications_array.get());

    return indications_array;
}
