NFAPI_CRC_INDICATION_PDU_T* create_pdu(RX_UE_INFORMATION_TAG rx_ue_information_tag, uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu) {
        log_info("Error: Failed to allocate memory for PDU.");
        return NULL;
    }

    pdu->rx_ue_information_tag = rx_ue_information_tag;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag.crcflag = (rand() % 2) ? 1 : 0; // randomly set CRCFLAG

    log_info("Created PDU with RX_UE_INFORMATION_TAG:");
