    log_info(" and RNTI:", pdu->rnti);
    log_info(" with CRC_INDICATION_REL8_TAG.crcflag:", pdu->crc_indication_rel8_tag.crcflag);

    return pdu;
}

void populate_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t n, RX_UE_INFORMATION_TAG start_uei) {
    if (n <= 0 || !list) {
        log_info("Error: Invalid input values.");
        return;
    }

    for (size_t i = 0; i < n; ++i) {
        RX_UE_INFORMATION_TAG uei = start_uei + i;
        *list++ = create_pdu(uei, i);

        if (!*list) {
            log_info("Error: Failed to allocate memory for a PDU in the list.");
            break;
        }
    }
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) {
        free(pdu);
    }
}

void free_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t n) {
    if (!list || !n) return;

    for (size_t i = 0; i < n; ++i) {
        free_pdu(*list++);
    }
}
