    uint16_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

struct thread_data {
    Node** head;
    int max_list_size;
    pthread_mutex_t mutex;
};

void create_and_populate_list(Node** head, int max_list_size) {
    *head = malloc(max_list_size * sizeof(Node));
    if (!*head) {
        perror("Memory allocation failed");
        exit(1);
    }

    for (int i = 0; i < max_list_size; ++i) {
        (*head)[i].data.RX_UE_INFORMATION_TAG = rand();
        (*head)[i].data.RNTI = rand() % 65536;
        (*head)[i].data.CRC_INDICATION_REL8_TAG = rand() % 2;
        (*head)[i].next = (i + 1 < max_list_size) ? &((*head)[i+1]) : NULL;
    }
}

void enqueue(Node** head, Node* node) {
    pthread_mutex_lock(&((struct thread_data*)(*head))->mutex);
    if (!*head) {
        *head = malloc(sizeof(Node));
        if (!*head) {
            perror("Memory allocation failed");
            exit(1);
        }
        (*head)->data = node->data;
        (*head)->next = NULL;
    } else {
        Node* temp = *head;
        while (temp->next) {
            temp = temp->next;
        }
        temp->next = node;
    }
    pthread_mutex_unlock(&((struct thread_data*)(*head))->mutex);
}

Node* dequeue(Node** head) {
    if (!*head) return NULL;

    Node* result = (*head);
    if ((*head)->next == NULL) {
        *head = NULL;
    } else {
        *head = &((*head)->next[0]);
    }

    return result;
}

