    int pdsch_mapping_info;
    int crc_indication_rel15_tag;
} LTE_PHY_RX_FRAME_PDU_T;

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Assuming an XML file with a root element "configuration" and child elements for settings.
// Each LTE_PHY_RX_FRAME_PDU_T structure is represented by an "lte_structure" tag, and each NFAPI_CRC_INDICATION_PDU_T structure is represented by an "nfapi_structure" tag.
int xml2struct(const char* xml_file_path, LTE_PHY_RX_FRAME_PDU_T** lte_list, NFAPI_CRC_INDICATION_PDU_T** nfapi_list) {
    // Load XML file and parse it using libxml2 library.
    lua_State *L = luaL_newstate();
    luaL_openlibs(L);
    int parser_result;
    lua_XML_Parser *parser;

    luaL_loadfile(L, xml_file_path);
    if (lua_pcall(L, 0, 0, 0) != 0) {
        fprintf(stderr, "Error loading XML file: %s\n", lua_tostring(L, -1));
        return 0;
    }
    parser = lua_XML_newParser(L, lua_gettop(L) - 1);

    // Iterate through each "lte_structure" and "nfapi_structure" element in the XML file.
    LTE_PHY_RX_FRAME_PDU_T *lte_ptr = NULL;
    NFAPI_CRC_INDICATION_PDU_T *nfapi_ptr = NULL;
    int n_lte = 0, n_nfapi = 0;

    while ((parser_result = lua_XML_nextNode(parser)) != LUA_XML_ERROR && parser_result != LUA_XML_DONE) {
        // Create a new LTE or NFAPI structure and populate it with data read from the XML element.
        if (strcmp((char *)lua_XML_getTagName(parser), "lte_structure") == 0) {
            lte_ptr = realloc(lte_ptr, sizeof(LTE_PHY_RX_FRAME_PDU_T) * (n_lte + 1));
            lte_ptr[n_lte].ue_id = /* read UE_ID from XML element */;
            lte_ptr[n_lte].pdsch_mapping_info = /* read PDSCH_MAPPING_INFO from XML element */;
            lte_ptr[n_lte].crc_indication_rel15_tag = rand() % 2; // Set CRC flag randomly.
            n_lte++;
        } else if (strcmp((char *)lua_XML_getTagName(parser), "nfapi_structure") == 0) {
            nfapi_ptr = realloc(nfapi_ptr, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (n_nfapi + 1));
            nfapi_ptr[n_nfapi].rx_ue_information_tag = /* read RX_UE_INFORMATION_TAG from XML element */;
            nfapi_ptr[n_nfapi].rnti = /* read RNTI from XML element */;
            nfapi_ptr[n_nfapi].crc_indication_rel8_tag = rand() % 2; // Set CRC flag randomly.
            n_nfapi++;
        }
    }

    lua_XML_freeParser(parser);
    lua_close(L);

    *lte_list = lte_ptr;
    *nfapi_list = nfapi_ptr;

    return n_lte + n_nfapi; // Number of successfully populated structures.
}
