typedef struct {
    time_t timestamp;
    enum { INFO, WARNING, ERROR, CRITICAL } severity;
    enum { NETWORK, SYSTEM, APPLICATION } event_type;
    size_t body_len;
    char *body;
    size_t meta_len;
    char *meta;
} LogEntry;

#define MAX_LOGS 10000
static LogEntry logs[MAX_LOGS];
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t num_logs = 0;
static char *logfile = NULL;

void init_logger(const char *filename) {
    logfile = filename;
}

LogEntry* new_log_entry() {
    if (num_logs >= MAX_LOGS) return NULL;
    LogEntry *entry = &logs[num_logs++];
    entry->body = malloc(0);
    entry->meta = malloc(0);
    return entry;
}

void free_log_entry(LogEntry *entry) {
    if (!entry) return;
    free(entry->body);
    free(entry->meta);
}

void add_log_entry(LogEntry *entry) {
    pthread_mutex_lock(&log_mutex);
    free_log_entry(logs + num_logs - 1);
    memcpy(logs + num_logs - 1, entry, sizeof(LogEntry));
    pthread_mutex_unlock(&log_mutex);
}

void log_event(time_t timestamp, enum { INFO, WARNING, ERROR, CRITICAL } severity,
               enum { NETWORK, SYSTEM, APPLICATION } event_type, const char *body, size_t body_len,
               const char *meta, size_t meta_len) {
    LogEntry *entry = new_log_entry();
    if (!entry) return;

    entry->timestamp = timestamp;
    entry->severity = severity;
    entry->event_type = event_type;
    entry->body_len = body_len;
    entry->meta_len = meta_len;
    entry->body = malloc(entry->body_len);
    memcpy(entry->body, body, entry->body_len);
    entry->meta = malloc(entry->meta_len);
    memcpy(entry->meta, meta, entry->meta_len);

    add_log_entry(entry);
}

void filter_logs(time_t start, time_t end, enum { INFO, WARNING, ERROR, CRITICAL } severity,
                 enum { NETWORK, SYSTEM, APPLICATION } event_type) {
    pthread_mutex_lock(&log_mutex);
    for (size_t i = 0; i < num_logs; ++i) {
        if ((logs[i].timestamp >= start && logs[i].timestamp <= end) &&
            ((severity == -1) || (logs[i].severity == severity)) &&
            ((event_type == -1) || (logs[i].event_type == event_type))) {
            // Process log entry as needed
        }
    }
    pthread_mutex_unlock(&log_mutex);
}

void summary_report() {
    pthread_mutex_lock(&log_mutex);
    int counts[4][3] = {{0}};
    for (size_t i = 0; i < num_logs; ++i) {
        counts[logs[i].severity][logs[i].event_type]++;
    }
    pthread_mutex_unlock(&log_mutex);

    printf("Summary Report:\n");
    for (int s = 0; s < 4; ++s) {
        for (int e = 0; e < 3; ++e) {
            if (!counts[s][e]) continue;
            printf("\nEvent Type: %s\nSeverity Level: %s",
                (e == NETWORK) ? "Network" :
                (e == SYSTEM) ? "System" :
                (e == APPLICATION) ? "Application": "",
                (s == INFO) ? "Info" :
                (s == WARNING) ? "Warning" :
                (s == ERROR) ? "Error" :
                (s == CRITICAL) ? "Critical" : "");
            printf("\nOccurrences: %d", counts[s][e]);
        }
    }
}

void export_logs() {
    // Implement exporting log entries to a file in the specified format
}
