#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <json-c/json.h>
#include <ml/crceprediction.h> // Assuming you have a machine learning library

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    pthread_mutex_t mutex;
} CRCIndication;

typedef struct {
    CRCIndication* buffer;
    size_t head, tail, size;
    pthread_mutex_t queue_mutex;
    pthread_cond_t not_empty;
} Queue;

Queue* create_queue(size_t size) {
    Queue* q = malloc(sizeof(Queue));
    if (!q) return NULL;
    q->buffer = calloc(size, sizeof(CRCIndication));
    if (!q->buffer) {
        free(q);
        return NULL;
    }
    q->head = q->tail = 0;
    q->size = size;
    pthread_mutex_init(&q->queue_mutex, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    return q;
}

void enqueue(Queue* q, CRCIndication data) {
    pthread_mutex_lock(&q->queue_mutex);
    if ((q->tail + 1) % q->size == q->head) {
        pthread_mutex_unlock(&q->queue_mutex);
        return; // Queue is full, ignore the data
    }
    memcpy(q->buffer + q->tail, &data, sizeof(CRCIndication));
    q->tail = (q->tail + 1) % q->size;
    if (q->head == q->tail) { // Queue is empty now
        pthread_cond_signal(&q->not_empty);
    }
    pthread_mutex_unlock(&q->queue_mutex);
}

CRCIndication dequeue(Queue* q) {
    CRCIndication data;
    pthread_mutex_lock(&q->queue_mutex);
    if (q->head == q->tail) { // Queue is empty, return an empty structure
        data.data = {};
        pthread_mutex_unlock(&q->queue_mutex);
        return data;
    }
    memcpy(&data, q->buffer + q->head, sizeof(CRCIndication));
    q->head = (q->head + 1) % q->size;
    pthread_mutex_unlock(&q->queue_mutex);
    return data;
}

CRCIndication* create_structures(json_object* config) {
    size_t n = json_object_get(config, "N");
    CRCIndication* structures = malloc(n * sizeof(CRCIndication));
    if (!structures) return NULL;

    for (size_t i = 0; i < n; ++i) {
        structures[i].data.RX_UE_INFORMATION_TAG = json_object_get(config, json_new_string("RX_UE_INFORMATION_TAG"));
        structures[i].data.RNTI = json_object_get(config, json_new_string("RNTI"));
        structures[i].data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    return structures;
}

void log_info(json_object* config, CRCIndication data) {
    FILE* file = fopen(json_object_get_string(config, "logfile"), "a");
    if (!file) return; // Logging failed, no action required

    fprintf(file, "[%lu] [RX_UE_INFORMATION_TAG=%s RNTI=%s CRCFLAG=%d]\n", time(NULL), data.data.RX_UE_INFORMATION_TAG, data.data.RNTI, data.data.CRC_INDICATION_REL8_TAG.CRCFLAG);
    fclose(file);
}

void* process_structures(void* arg) {
    Queue* queue = arg;
    json_object* config = get_config(); // Assuming a global configuration is available

    while (1) {
        CRCIndication data = dequeue(queue);
        if (data.data.RX_UE_INFORMATION_TAG == NULL || data.data.RNTI == NULL) continue; // Ignore invalid structures

        log_info(config, data);

        // Process the structure based on the specific communication protocol
        process_protocol(&data.data);

        free_structure(&data.data); // Free the dynamically allocated memory
    }
}

CRCIndication* create_list(json_object* config) {
    Queue* queue = create_queue(json_object_get(config, "queue_size"));
    if (!queue) return NULL;

    CRCIndication* structures = create_structures(config);
    if (!structures) {
        free(queue);
        return NULL;
    }

    for (size_t i = 0; i < json_object_get(config, "N"); ++i) {
        pthread_mutex_init(&structures[i].mutex, NULL);
        enqueue(queue, structures[i]);
    }

    pthread_t threads[json_object_get(config, "N")];
    for (size_t i = 0; i < json_object_get(config, "N"); ++i) {
        if (pthread_create(&threads[i], NULL, process_structures, queue)) {
            fprintf(stderr, "Failed to create thread\n");
            exit(1);
        }
    }

    // Process remaining structures when shutting down
    for (size_t i = 0; i < json_object_get(config, "N"); ++i) pthread_join(threads[i], NULL);

    free(structures);
    free(queue->buffer);
    free(queue);

    return NULL; // Indicating success
}
