// Logging macro with verbosity control
#define LOG(level, ...) \
    if (g_log_level <= level) { \
        printf("[Level " #level "] " __VA_ARGS__); \
    }

// Global variables for logging and thread safety
volatile int g_log_level = 3; // Level 0: Error, Level 1: Warning, Level 2: Info, Level 3: Debug
pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random RNTI within the given range
unsigned int gen_rnti(unsigned int min, unsigned int max) {
    return rand() % (max - min + 1) + min;
}

// Function for initializing and managing array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* init_pdu_array(unsigned int n, unsigned int min_signal_strength) {
    pthread_t tid;
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        LOG(Error, "Failed to allocate memory for PDUs array.");
        return NULL;
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&pdus[0].data.mutex, &attr);
    pthread_mutexattr_destroy(&attr);

    for (unsigned int i = 0; i < n; ++i) {
        pdus[i].rnti = gen_rnti(1, UINT16_MAX);
        // Ensure no two consecutive structures share the same RNTI value
        if (i > 0 && (pdus[i].rnti == pdus[i - 1].rnti + 1)) {
            pdus[i].rnti = gen_rnti(1, UINT16_MAX);
        }

        // Set the CRCFLAG randomly for each PDU
        pdus[i].crc_indication.crcflag = rand() % 2;

        // Filter PDUs based on signal strength threshold (if provided)
        if (min_signal_strength > 0 && pdus[i].rx_ue_info.signalStrength < min_signal_strength) {
            continue;
        }
    }

    return pdus;
}

// Cleanup function for releasing resources when done with the PDU array
void cleanup_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdus, unsigned int n) {
    free(pdus);
}
