typedef struct node {
    NFAPI_CRCI_INDICATION_PDU_T* data;
    struct node *next;
} Node;

static Node* head = NULL;
static int num_elements = 0;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static double min_signal_strength = -1.0; // default value indicates no filtering
static double signal_strength_tolerance = 0.0;

void log(const char* message, int verbosity) {
    // Implement logging with various verbosity levels based on user-defined verbosity level
}

void create_and_insert_pdu(NFAPI_CRCI_INDICATION_PDU_T* pdu) {
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        log("Error: Memory allocation failed.", 1);
        return;
    }

    pthread_mutex_lock(&list_mutex);
    while (head != NULL && head->data->rnti == pdu->rnti) {
        Node* current = head;
        head = head->next;
        free(current);
    }

    newNode->data = pdu;
    newNode->next = head;
    head = newNode;
    num_elements++;
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRCI_INDICATION_PDU_T* find_pdu_by_rnti(RNTI rnti) {
    pthread_mutex_lock(&list_mutex);
    Node* current = head;
    while (current != NULL) {
        if (current->data->rnti == rnti) {
            NFAPI_CRCI_INDICATION_PDU_T* result = current->data;
            pthread_mutex_unlock(&list_mutex);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
    return NULL;
}

void set_filtering(double min_signal_strength, double signal_strength_tolerance) {
    if (min_signal_strength < -1.0 || min_signal_strength > 1.0 || signal_strength_tolerance <= 0.0) {
        log("Error: Invalid filtering parameters.", 1);
        return;
    }

    this->min_signal_strength = min_signal_strength;
    this->signal_strength_tolerance = signal_strength_tolerance;
}
