#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct _state {
    int id;
    struct _state *next;
} State;

typedef struct _fsa {
    int num_states;
    struct _transition **transitions;
    State *current;
} FSA;

State* create_linked_list(int *states, int num_states, FSA *fsa) {
    State *head = NULL, *tail = NULL, *temp;

    if (num_states <= 0 || fsa->num_states <= 0)
        return NULL;

    bool visited[fsa->num_states] = {false};

    for (int i = 0; i < num_states; ++i) {
        if (!visited[states[i]]) {
            visited[states[i]] = true;
            temp = malloc(sizeof(State));
            if (!temp) {
                fprintf(stderr, "Out of memory\n");
                return NULL;
            }
            temp->id = states[i];
            temp->next = head;
            head = temp;
            tail = temp;

            dfs(fsa, states[i], visited);
        }
    }

    fsa->current = head;
    return head;
}

void dfs(FSA *fsa, int state, bool *visited) {
    struct _transition *transition;

    visited[state] = true;

    for (int i = 0; i < fsa->num_states; ++i) {
        transition = fsa->transitions[state + i*fsa->num_states];
        if (transition && !visited[transition->to]) {
            tail->next = malloc(sizeof(State));
            if (!tail->next) {
                fprintf(stderr, "Out of memory\n");
                return;
            }
            tail = tail->next;
            tail->id = transition->to;
            tail->next = NULL;
            dfs(fsa, transition->to, visited);
        }
    }
}
```

