    NFAPI_CRC_INDICATION_PDU data;
    struct list_node *next;
} list_node_t;

// Initialize a doubly-linked list using a sentinel node
static list_node_t *head = NULL;
static list_node_t *tail = NULL;

// Mutex for thread safety
pthread_mutex_t mutex;

// Function to initialize the dynamic list with a given number of users
void init_list(size_t num_users) {
    // Acquire the mutex before making any changes to the list
    pthread_mutex_lock(&mutex);

    size_t node_size = sizeof(list_node_t);
    head = (list_node_t*) malloc((num_users + 2) * node_size);

    // Set up the sentinel nodes
    head->data = (NFAPI_CRC_INDICATION_PDU){ .crc_indication.crcflag = false };
    tail = head + num_users + 1;
    tail->next = head;

    // Initialize each user node with default values
    for (size_t i = 0; i < num_users; ++i) {
        list_node_t *current = head + i + 1;
        current->data.rx_ue_information = (RX_UE_INFORMATION_TAG){ .tag = i };
        current->data.rnti = (RNTI){ .value = i };
        current->data.crc_indication.crcflag = false;
        current->next = tail;
    }

    // Release the mutex after making changes
    pthread_mutex_unlock(&mutex);
}

// Function to insert a new user into the dynamic list
void add_user(NFAPI_CRC_INDICATION_PDU user) {
    pthread_mutex_lock(&mutex);

    // Allocate a new node and set its data to the given user
    list_node_t *new_node = (list_node_t*) malloc(sizeof(list_node_t));
    new_node->data = user;

    // Insert the new node at the tail of the doubly-linked list
    new_node->next = head;
    tail->next = new_node;
    tail = new_node;

    // Release the mutex after making changes
    pthread_mutex_unlock(&mutex);
}

// Function to remove a user from the dynamic list based on their RNTI value
void remove_user(RNTI rnti) {
    pthread_mutex_lock(&mutex);

    // Iterate through the doubly-linked list to find the node with the given RNTI
    list_node_t *current = head;
    while (current->next != head && current->next->data.rnti.value != rnti.value) {
        current = current->next;
    }

    // If the node with the given RNTI was found, remove it from the list
    if (current->next != head) {
        list_node_t *to_remove = current->next;
        current->next = to_remove->next;

        // Ensure that the removed node is freed and not left dangling in memory
        free(to_remove);
    }

    // Release the mutex after making changes
    pthread_mutex_unlock(&mutex);
}

// Function to simulate probabilistic packet loss conditions by randomly setting the CRCFLAG for each node
void update_crcflag() {
    pthread_mutex_lock(&mutex);

    list_node_t *current = head;
    while (current->next != head) {
        // Use a random number generator to determine whether to set the CRCFLAG for this node
        if (rand() / (float) RAND_MAX < 0.05) {
            current->data.crc_indication.crcflag = true;
        }

        current = current->next;
    }

    // Release the mutex after making changes
    pthread_mutex_unlock(&mutex);
}
