    return user;
}

// Function to manage the dynamic list of users
void update_list(int action, int ue_tag, RNTI rnti) {
    pthread_mutex_lock(&list_lock);

    // Determine the index of the user based on the specified action and configuration policy
    size_t index = 0;
    if (action == ADD_USER && num_users < max_users) {
        void* new_user = create_user(ue_tag, rnti);
        memcpy((char*)user_memory + index * sizeof(NFAPI_CRC_INDICATION_PDU), new_user, sizeof(NFAPI_CRC_INDICATION_PDU));
        num_users++;
    } else if (action == REMOVE_USER && num_users > 0) {
        size_t min_gap = num_users;
        for (size_t i = 1; i < num_users; ++i) {
            if ((char*)user_memory + i * sizeof(NFAPI_CRC_INDICATION_PDU) - (char*)user_memory >= min_gap) {
                min_gap = (char*)user_memory + i * sizeof(NFAPI_CRC_INDICATION_PDU) - (char*)user_memory;
                index = i;
            }
        }
        if (allocation_policy == ALLOCATION_POLICY_BEST_FIT) {
            // Shift the remaining users to fill the gap and free the memory for the removed user
            void* moved_users = memcpy((char*)user_memory + index * sizeof(NFAPI_CRC_INDICATION_PDU),
                                      (char*)user_memory, num_users * sizeof(NFAPI_CRC_INDICATION_PDU) - index * sizeof(NFAPI_CRC_INDICATION_PDU));
            free(moved_users + num_users * sizeof(NFAPI_CRC_INDICATION_PDU) - index * sizeof(NFAPI_CRC_INDICATION_PDU));
        } else { // Allocation policy is ALLOCATION_POLICY_WORST_FIT
            void* removed_user = user_memory + index * sizeof(NFAPI_CRC_INDICATION_PDU);
            memcpy((char*)removed_user, (char*)user_memory + (index + 1) * sizeof(NFAPI_CRC_INDICATION_PDU), num_users - index - 1
                   * sizeof(NFAPI_CRC_INDICATION_PDU));
        }
        num_users--;
    }

    pthread_mutex_unlock(&list_lock);
}

// Function to initialize the memory for the dynamic list of users
void init_list(size_t max_users) {
    if (user_memory != NULL) free(user_memory);
    user_memory = malloc(max_users * sizeof(NFAPI_CRC_INDICATION_PDU));
    this->num_users = 0;
    this->max_users = max_users;
}
