#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>
#include <sys/mman.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

struct list {
    int size;
    int capacity;
    Node** nodes;
    pthread_mutex_t lock;
    sem_t alloc_sem, free_sem;
};

void* best_fit(struct list* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    int i = 0;
    for (i = 0; i < list->size; ++i) {
        if (!list->nodes[i]) {
            break;
        }
        if (list->nodes[i]->next == NULL) {
            return &list->nodes[i];
        }
    }
    return NULL;
}

void* worst_fit(struct list* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    int best_index = -1;
    int min_size = INT_MAX;

    for (int i = 0; i < list->size; ++i) {
        if (!list->nodes[i]) {
            continue;
        }
        if (list->nodes[i]->next == NULL && list->nodes[i]->data.crc_ind_tag.crcflag == 0) { // Empty node with no packet loss
            min_size = list->nodes[i]->data.crc_ind_tag.payload_length;
            best_index = i;
        }
        if (list->nodes[i]->next != NULL && list->nodes[i]->data.crc_ind_tag.crcflag == 0) { // Non-empty node with no packet loss
            int size = list->nodes[i]->data.crc_ind_tag.payload_length + list->nodes[i]->next->data.crc_ind_tag.payload_length;
            if (size < min_size) {
                min_size = size;
                best_index = i;
            }
        }
    }

    return &list->nodes[best_index];
}

void init_list(struct list* list, int capacity) {
    list->capacity = capacity;
    list->size = 0;
    list->nodes = mmap(NULL, capacity * sizeof(Node*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (list->nodes == MAP_FAILED) {
        // Handle memory allocation failure without crashing the system
        fprintf(stderr, "Memory allocation failed\n");
        exit(-1);
    }

    list->lock = PTHREAD_MUTEX_INITIALIZER;
    sem_init(&list->alloc_sem, 0, capacity);
    sem_init(&list->free_sem, 0, 0);
}

Node* get_node(struct list* list, AllocationPolicy policy) {
    pthread_mutex_lock(&list->lock);

    if (policy == BEST_FIT) {
        Node* node = best_fit(list, NULL);
        if (node) {
            sem_wait(&list->free_sem);
            sem_post(&list->alloc_sem);
            return node;
        }
    } else if (policy == WORST_FIT) {
        Node* node = worst_fit(list, NULL);
        if (node) {
            sem_wait(&list->free_sem);
            sem_post(&list->alloc_sem);
            return node;
        }
    }

    if (list->capacity == list->size) { // Resize list if full
        list->capacity *= 2;
        Node** new_nodes = mremap(list->nodes, list->capacity * sizeof(Node*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

        if (new_nodes == MAP_FAILED) {
            // Handle memory allocation failure without crashing the system
            fprintf(stderr, "Memory allocation failed\n");
            exit(-1);
        }

        list->nodes = new_nodes;
    }

    Node* node = &list->nodes[list->size++];
    // Set initial state for the new node (e.g., crcflag based on probabilistic algorithm)
    node->data.crc_ind_tag.crcflag = rand() % 10 > 5;
    return node;

    pthread_mutex_unlock(&list->lock);
}

void free_node(struct list* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    sem_wait(&list->alloc_sem);
    sem_post(&list->free_sem);
    pthread_mutex_unlock(&list->lock);
}
