        free(rec->key);
        free(rec->data);
        free(rec);
        pthread_mutex_unlock(&queue_mutex);
        return;
    }

    new_node->record = rec;
    new_node->next = NULL;

    if (!head) {
        head = new_node;
        tail = head;
    } else {
        tail->next = new_node;
        tail = tail->next;
    }

    pthread_mutex_unlock(&queue_mutex);
}

// Function to dequeue a record from the queue and return it.
record_t* dequeue() {
    pthread_mutex_lock(&queue_mutex);

    node_t* temp = head;
    if (!head) {
        pthread_mutex_unlock(&queue_mutex);
        return NULL;
    }

    head = head->next;
    record_t* rec = temp->record;

    free(temp);
    pthread_mutex_unlock(&queue_mutex);

    return rec;
}
