['```c
#include <pthread.h>
#include <semaphore.h>
#include <sys/time.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tcp_packet_capture.h"

struct tcp_record {
    struct timeval timestamp;
    unsigned short src_ip;
    unsigned short dest_ip;
    uint16_t protocol;
    uint32_t payload_size;
    char payload[BUFFER_SIZE];
};

typedef struct monitoring_system {
    void* handle;
    void (*init)(void*);
    void (*deinit)(void*);
    void (*process)(struct tcp_record*);
} MonitoringSystem;

struct config {
    uint32_t sampling_rate;
    size_t buffer_size_constraints;
    int log_level;
    MonitoringSystem** systems;
    unsigned num_systems;
};

struct tcp_capture {
    struct tcp_record* buffer;
    size_t capacity;
    size_t head, tail;
    pthread_mutex_t lock;
    sem_t full, empty;
    struct config cfg;
};

void tcpcap_init(struct tcp_capture* self, const struct config* cfg) {
    memset(self, 0, sizeof(*self));
    self->cfg = *cfg;
    pthread_mutex_init(&self->lock, NULL);
    sem_init(&self->full, 0, self->capacity);
    sem_init(&self->empty, 0, self->capacity);
}

void tcpcap_deinit(struct tcp_capture* self) {
    pthread_mutex_destroy(&self->lock);
    sem_destroy(&self->full);
    sem_destroy(&self->empty);
}

void tcpcap_add_record(struct tcp_capture* self, const struct tcp_record* record) {
    pthread_mutex_lock(&self->lock);
    while (sem_trywait(&self->full)) {} // block until buffer is not full
    memcpy(&self->buffer[self->head], record, sizeof(*record));
    self->head = (self->head + 1) % self->capacity;
    sem_post(&self->empty);
    pthread_mutex_unlock(&self->lock);
}

void* tcpcap_process(void* arg) {
    struct tcp_capture* self = arg;
    struct tcp_record record;

    while (1) {
        // wait for buffer to have data
        pthread_mutex_lock(&self->lock);
        while (sem_trywait(&self->empty)) {} // block until buffer is not empty
        memcpy(&record, &self->buffer[self->tail], sizeof(record));
        self->tail = (self->tail + 1) % self->capacity;
        pthread_mutex_unlock(&self->lock);

        for (unsigned i = 0; i < self->cfg.num_systems; ++i) {
            self->cfg.systems[i]->process(&record);
        }
    }

    return NULL;
}
```

This code provides a basic framework for managing TCP packet capture records and integrating with multiple network monitoring systems. The `tcp_capture` struct represents the core data structure, and the `config` struct contains configuration parameters that can be customized for different use cases. The `tcpcap_init()` function initializes the object, while `tcpcap_deinit()` frees up any allocated resources.

The `tcpcap_add_record()` function adds a new record to the buffer, ensuring thread safety by locking the buffer with a mutex before writing and unlocking it afterwards. The `tcpcap_process()` function processes records from the buffer in a separate thread, iterating through all connected monitoring systems and calling their respective `process()` functions for each record.

The code demonstrates some engineering trade-offs by using semaphores for synchronization between threads and a mutex to lock access to the buffer. This approach can potentially introduce contention and overhead but ensures data integrity and thread safety. The implementation is flexible enough to accommodate various network monitoring systems, each with its own specific configuration and integration methods.']

