    if (!new_node) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(1);
    }

    memcpy(&new_node->profile, profile, sizeof(UserProfile));
    new_node->next = NULL;
    return new_node;
}

Node* find_profile(const char* name, const char* email) {
    Node* current = head;
    while (current != NULL) {
        if (strcmp(current->profile.name, name) == 0 && strcmp(current->profile.email, email) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

