        fprintf(stderr, "Error: Could not open log file\n");
        exit(1);
    }
}

void manage_list(int operation, const char* name, const char* email, const char* phone) {
    validate(name, "Name");
    validate(email, "Email");
    if (!email_valid(email)) return;
    validate(phone, "Phone Number");
    if (!phone_valid(phone)) return;

    Node* new_node = create_node((UserProfile*)malloc(sizeof(UserProfile)));
    strcpy(new_node->profile.name, name);
    strcpy(new_node->profile.email, email);
    strcpy(new_node->profile.phone, phone);

    if (operation == ADD) {
        if (!head) {
            head = new_node;
            return;
        }

        Node* current = head;
        while (current->next != NULL) current = current->next;
        current->next = new_node;
    } else {
        Node* existing = find_profile(name, email);
        if (!existing) return;

        strcpy(existing->profile.phone, phone);
    }

    add_log_entry(ADD, name, email);
}

void search(const char* query) {
    Node* current = head;
    while (current != NULL) {
        if (strstr(current->profile.name, query) || strstr(current->profile.email, query)) {
            printf("Name: %s\nEmail: %s\nPhone: %s\n", current->profile.name, current->profile.email, current->profile.phone);
        }
        current = current->next;
    }
}
