struct event_queue_node {
    MAC_EVENT_INSTANCE *event;
    struct event_queue_node *next;
};

struct event_queue {
    struct event_queue_node *head;
    size_t batch_size;
    sem_t batch_full;
    sem_t batch_not_empty;
};

