    // Write asynchronous logging mechanism here, e.g., using a separate thread or callback to the existing network monitoring library
}

void event_queue_init(struct event_queue *queue, size_t batch_size) {
    queue->batch_size = batch_size;
    sem_init(&queue->batch_full, 0, 0);
    sem_init(&queue->batch_not_empty, 0, 0);
}

void enqueue(struct event_queue *queue, MAC_EVENT_INSTANCE *event) {
    struct event_queue_node *node = malloc(sizeof(struct event_queue_node));
    if (!node) {
        // Handle out-of-memory error here
        return;
    }
    node->event = event;
    node->next = NULL;

    sem_wait(&queue->batch_not_empty);
    struct event_queue_node *current = queue->head;
    if (current) {
        while (current->next != NULL && queue->batch_size > 1) {
            current = current->next;
        }
        node->next = current->next;
        current->next = node;
    } else {
        queue->head = node;
    }

    sem_post(&queue->batch_full);
}

MAC_EVENT_INSTANCE *dequeue(struct event_queue *queue) {
    MAC_EVENT_INSTANCE *event = NULL;
    if (queue->head != NULL) {
        struct event_queue_node *current = queue->head;
        queue->head = current->next;
        event = current->event;
        free(current);
        sem_post(&queue->batch_not_empty);
    }
    return event;
}

MAC_EVENT_INSTANCE *alloc_mac_event(const char *payload, size_t payload_length, enum MAC_EVENT_TYPE_TYPE event_type) {
    MAC_EVENT_INSTANCE *event = malloc(sizeof(MAC_EVENT_INSTANCE));
    if (!event) {
        // Handle out-of-memory error here
        return NULL;
    }
    event->timestamp = time(NULL);
    event->type = event_type;
    event->length = payload_length;
    event->payload = malloc(payload_length);
    if (!event->payload) {
        // Handle out-of-memory error here
        free(event);
        return NULL;
    }
    memcpy(event->payload, payload, payload_length);
    log_event(event);
    return event;
}

void free_mac_event(MAC_EVENT_INSTANCE *event) {
    free(event->payload);
    free(event);
    log_event(event);
}
