    }
    config->FRAME_TIMESTAMP = rand() / (double)RAND_MAX * TIMESTAMP_RESOLUTION + ((double)clock() / CLOCKS_PER_SEC) * TIMESTAMP_RESOLUTION;
}

void validate(const LTE_PHY_RX_FRAME_INFO_T* buf, size_t buf_size, const LTE_PHY_RX_FRAME_INFO_T* expected) {
