        if (buf[i].tag != expected[i].tag || buf[i].RF_CHANNEL_FREQUENCY != expected[i].RF_CHANNEL_FREQUENCY || fabs(buf[i].FRAME_TIMESTAMP - expected[i].FRAME_TIMESTAMP) > 1e-6) {
