}

unsigned int calculate_checksum(const LTE_PHY_RX_FRAME_INFO_T* buf, size_t buf_size) {
    unsigned long long checksum = 0;
    for (size_t i = 0; i < buf_size; ++i) {
        checksum ^= ((unsigned long long)buf[i].tag << 32) | buf[i].RF_CHANNEL_FREQUENCY | *(unsigned int*)&buf[i].FRAME_TIMESTAMP;
    }
    return (unsigned int)(checksum & 0xFFFFFFFF);
}

