    node->rnti = (RNTI)(rand() % 0xffffffff);
    node->crc_indication.crcflag = (CRCFLAG)(rand() % 2);
    node->prev = manager->tail ? manager->tail->prev : NULL;
    node->next = manager->tail;

    if (manager->tail) {
        manager->tail->prev = node;
        manager->tail = node;
    }

    pthread_mutex_unlock(&manager->mutex);

    // Performance monitoring
    printf("Allocation at index %u\n", manager->size - 1);

    return (unsigned int)(manager->size - 1);
