void destroy_crc_indication_pdu(CRC_MANAGER_T *manager, unsigned int idx) {
    pthread_mutex_lock(&manager->mutex);

    NFAPI_CRC_INDICATION_PDU_T *node = &manager->head[idx];

    if (node->prev)
        node->prev->next = node->next;
    else
        manager->head = node->next;

    if (node->next)
        node->next->prev = node->prev;
    else
        manager->tail = node->prev;

    custom_free(node);

    pthread_mutex_unlock(&manager->mutex);

    // Performance monitoring
    printf("Deallocation at index %u\n", idx);
}

