class DynamicList {
public:
    explicit DynamicList(size_t capacity) : elements_(capacity), rntiMap_{} {}

    void pushBack(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        if (elements_.size() >= capacity) resize();
        elements_.push_back(pdu);
        rntiMap_[pdu.rnti] = &elements_.back();
    }

    size_t size() const { return elements_.size(); }

    NFAPI_CRC_INDICATION_PDU_T& operator[](size_t index) { return elements_[index]; }

    const RX_UE_INFORMATION_TAG* findRNTI(uint32_t rnti) const {
        auto it = rntiMap_.find(rnti);
        return it == rntiMap_.end() ? nullptr : it->second;
    }

private:
    void resize() {
        std::vector<NFAPI_CRC_INDICATION_PDU_T> newElements(elements_.size() * 2);
        std::copy(elements_.begin(), elements_.end(), newElements.begin());
        elements_.swap(newElements);
    }

    std::vector<NFAPI_CRC_INDICATION_PDU_T> elements_;
    std::unordered_map<uint32_t, const RX_UE_INFORMATION_TAG*> rntiMap_;
};

void generatePDU(DynamicList& list) {
    std::mt19937 generator(std::random_device{}());
    std::uniform_int_distribution<> distribution(0, 0xFFFFFFFF);

    for (size_t i = 0; i < 10000; ++i) {
        RX_UE_INFORMATION_TAG tag{};
        if (rntiMap.find(tag.value) != rntiMap.end()) {
            tag.value = ++tag.value & ((1ULL << 64) - 1);
        }
        tag.isUnique = true;

        list.pushBack({tag, i + 1, {distribution(generator), !distribution(generator)}});
    }
}
