import json
import random
import requests
from collections import defaultdict
import time
import ssl
import os
import hashlib
from urllib.parse import urlparse

class CustomAuthException(Exception):
    pass

def get_config(auth_request):
    if not auth_request or 'directory' not in auth_request:
        raise CustomAuthException("Invalid authentication request")

    config_file = os.path.join(auth_request['directory'], 'config.json')
    if not os.path.isfile(config_file):
        raise CustomAuthException("Config file not found")

    with open(config_file, 'r') as f:
        config = json.load(f)
    return config

def request_to_remote_service(url, headers=None, params=None, data=None):
    timeout = 5
    response = requests.request(method='GET', url=url, headers=headers, params=params, data=data, timeout=timeout)

    if response.status_code != 200:
        raise CustomAuthException("Remote service returned unexpected status code")

    try:
        response_json = response.json()
    except json.JSONDecodeError as e:
        raise CustomAuthException(f"Received malformed data from remote service: {e}")

    if not response_json or 'error' in response_json:
        raise CustomAuthException("Remote service returned an error")

    return response_json

class DirectedGraph:
    def __init__(self):
        self.vertices = defaultdict(lambda: {'edges': [], 'timestamp': time.time()})

    def add_vertex(self, vertex, weight=1):
        if vertex not in self.vertices:
            self.vertices[vertex] = {'timestamp': time.time()}
        self.vertices[vertex]['weight'] += weight

    def add_edge(self, source, target, weight=None):
        if weight is None:
            weight = random.uniform(0, 1) + self.vertices[source]['timestamp']
        self.vertices[source]['edges'].append((target, weight))

def create_graph(auth_request, graph, max_vertices=10000, max_edges=50000):
    config = get_config(auth_request)

    api_key = hashlib.sha256((auth_request['api_key'] + config['secret_key']).encode()).hexdigest()

    headers = {'Authorization': f'API-Key {api_key}'}
    url = config['endpoint']

    try:
        vertices = request_to_remote_service(url, headers=headers)
    except CustomAuthException as e:
        print(e)
        return

    if not isinstance(vertices, list):
        raise CustomAuthException("Unexpected data format from remote service")

    for vertex in vertices[:max_vertices]:
        try:
            self.add_vertex(vertex)
        except Exception as e:
            print(f"Error adding vertex {vertex}: {e}")

    edges = request_to_remote_service(url + '/edges', headers=headers)
    for edge in edges[:max_edges]:
        try:
            source, target, weight = map(str, edge)
            self.add_edge(source, target, weight)
        except Exception as e:
            print(f"Error adding edge between {source} and {target}: {e}")
