NFAPI_CRC_INDICATION_PDU_T* create_doubly_linked_list(size_t size) {
    if (!size) return NULL;
    NFAPI_CRC_INDICATION_PDU_T *head = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!head) return NULL;
    head->prev = NULL;
    head->next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (size - 1));
    if (!head->next) {
        free(head);
        return NULL;
    }
    NFAPI_CRUC_INDICATION_PDU_T *current = head->next;
    for (size_t i = 0; i < size - 1; ++i) {
        current[i].prev = head++;
        current[i].next = &current[i + 1];
        memset(&current[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    current->next = head;
    head->prev = &current[size - 1];
    return head;
}

void destroy_doubly_linked_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head->next, *temp;
    while (current != head) {
        temp = current;
        current = current->next;
        free(temp);
    }
}

