        memcpy(buffer + totalOut, packet.data, packet.size);
        totalOut += packet.size;
        gzwrite(compression_context, buffer + totalOut - packet.size, packet.size);
    }

    free(buffer);
    avcodec_free_context();
    avformat_close_input(&avformat_context);
}

