typedef struct CircularBuffer {
    struct Frame* buffer;
    size_t capacity;
    size_t head;
    size_t tail;
    sem_t mutex;
    sem_t notFull;
    sem_t notEmpty;
} CircularBuffer;

CircularBuffer* create_circular_buffer(size_t capacity) {
    CircularBuffer* cb = malloc(sizeof(CircularBuffer));
    cb->capacity = capacity;
    cb->head = 0;
    cb->tail = 0;
    cb->buffer = calloc(capacity, sizeof(struct Frame));
    sem_init(&cb->mutex, 0, 1);
    sem_init(&cb->notFull, 0, capacity);
    sem_init(&cb->notEmpty, 0, 0);
    return cb;
}

void push_frame(CircularBuffer* cb, const struct Frame* frame) {
    sem_wait(&cb->notFull);
    sem_wait(&cb->mutex);
    cb->buffer[(cb->head + 1) % cb->capacity] = *frame;
    cb->head = (cb->head + 1) % cb->capacity;
    if ((cb->head - cb->tail) == cb->capacity - 1)
        sem_post(&cb->notEmpty);
    sem_post(&cb->mutex);
}

const struct Frame* pop_frame(CircularBuffer* cb) {
    sem_wait(&cb->notEmpty);
    sem_wait(&cb->mutex);
    const struct Frame* frame = &cb->buffer[cb->tail];
    cb->tail = (cb->tail + 1) % cb->capacity;
    if ((cb->head - cb->tail) == 1)
        sem_post(&cb->notFull);
    sem_post(&cb->mutex);
    return frame;
}

void rolling_average(CircularBuffer* cb, float* avg) {
    sem_wait(&cb->mutex);
    size_t count = 0;
    for (size_t i = cb->tail; count < 20 && i != cb->head; ++i) {
        if (cb->buffer[i].quality_metric >= 0.f)
            count++;
    }
    if (count > 0) {
        float sum = 0.f;
        for (size_t i = cb->tail; count != 0 && i != cb->head; ++i) {
            if (cb->buffer[i].quality_metric >= 0.f) {
                sum += cb->buffer[i].quality_metric;
                --count;
            }
        }
        *avg = sum / count;
    } else
        *avg = -1.f;
    sem_post(&cb->mutex);
}

// External logging and configuration management APIs should be integrated here

void iterate_frames(CircularBuffer* cb, void(*func)(const struct Frame*), bool forward) {
    size_t index = (forward ? cb->head : cb->tail);
    sem_wait(&cb->mutex);
    while ((!forward && index != cb->tail) || (forward && index != cb->head)) {
        const struct Frame* frame = &cb->buffer[index];
        func(*frame);
        index = (forward ? (index + 1) % cb->capacity : (index - 1 < 0 ? cb->capacity - 1 : index - 1));
    }
    sem_post(&cb->mutex);
}
