```python
import os
import glob
import sys
import io
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed

def md5(file):
    h = hashlib.md5()
    with open(file, 'rb') as f:
        while True:
            data = f.read(8192)
            if not data:
                break
            h.update(data)
    return h.hexdigest()

def process_files(directory):
    file_paths = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            if os.path.islink(file_path):
                real_path = os.readlink(file_path)
                file_paths.append((real_path, file_path))
            else:
                file_paths.append((file_path, None))
    return file_paths

def read_lines(file_path, delimiter=None):
    with open(file_path) as f:
        lines = []
        for line in f:
            if delimiter:
                lines.append(line.split(delimiter))
            else:
                lines.append(line)
        return lines

def main(directories, delimiter=None, log=True):
    file_count = 0
    line_count = 0
    checksums = {}

    executor = ThreadPoolExecutor(max_workers=os.cpu_count())

    def process_file(file_path, real_file_path):
        nonlocal file_count, line_count, checksums
        if real_file_path:
            real_file_path.parent.mkdir(parents=True, exist_ok=True)

        with executor.submit(read_lines, file_path, delimiter):
            lines = as_completed().result()
            file_count += 1
            line_count += len(lines)

            if real_file_path:
                checksum = md5(file_path)
                if checksum in checksums:
                    print(f"Potential File Corruption detected for {file_path}")
                else:
                    checksums[checksum] = file_path

            if log:
                print(f"Processed File: {file_path} with {len(lines)} lines")

    for directory in directories:
        file_paths = process_files(directory)
        executor.map(process_file, file_paths)

        if log:
            print("\n")

if __name__ == "__main__":
    main([sys.argv[1], sys.argv[2]], sys.argv[3])
```

