namespace rng {
class RandomNumberGenerator {
public:
    std::mt19937 engine;

    explicit RandomNumberGenerator() : engine(std::random_device{}()) {}
    ~RandomNumberGenerator() = default;
};
}  // namespace rng

namespace po = boost::program_options;

void printUsage(const char* programName) {
    std::cerr << "Usage: " << programName << " [options]\n"
              << "\nOptions:\n"
              << "-h, --help             Print this help message.\n"
              << "--manpage              Display detailed usage information.\n"
              << "-i input_file           Specify the input file to process.\n"
              << "-o output_file          Redirect output to a specified file.\n"
              << "-cs                    Count only non-empty lines (default: count all lines).\n";
}

void printDetailedUsage(const char* programName) {
    std::cout << "Simple Random Number Generator using Mersenne Twister algorithm.\n\n";
    printUsage(programName);
}

std::string getAbsolutePath(const char* path) {
    if (realpath(path, nullptr) == nullptr) {
        throw std::runtime_error("Invalid absolute path.");
    }
    return std::string(realpath(path, nullptr));
}

void readFile(std::ifstream& file, size_t* lineCount, bool countNonEmptyOnly) {
    std::string line;
    while (std::getline(file, line)) {
        if (!countNonEmptyOnly || !line.empty()) {
            ++(*lineCount);
        }
    }
}

int main(int argc, char* argv[]) {
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help,h", "Print help message")
        ("manpage", "Display detailed usage information")
        ("input-file,i", po::value<std::string>()->required(), "Specify the input file to process")
        ("output-file,o", po::value<std::string>(), "Redirect output to a specified file")
        ("count-nonempty,cs", "Count only non-empty lines (default: count all lines)");

    po::variables_map vm;
    try {
        po::store(po::parse_command_line(argc, argv, desc), vm);
        po::notify(vm);

        if (vm.count("help")) {
            printUsage(argv[0]);
            return 0;
        } else if (vm.count("manpage")) {
            printDetailedUsage(argv[0]);
            return 0;
        }

        const std::string inputFilePath = getAbsolutePath(vm["input-file"].as<std::string>());
        bool countNonEmptyLines = vm.count("count-nonempty") > 0;

        std::ifstream inputFile(inputFilePath);
        if (!inputFile) {
            throw std::runtime_error("Could not open the specified file.");
        }

        size_t lineCount = 0;
        readFile(inputFile, &lineCount, countNonEmptyLines);

        rng::RandomNumberGenerator rng;
        size_t randomLineIndex = rng.engine() % lineCount;

        std::ofstream outputFile;
        if (!vm["output-file"].as<std::string>().empty()) {
            const std::string outputFilePath = getAbsolutePath(vm["output-file"].as<std::string>());
            outputFile.open(outputFilePath);

            if (!outputFile) {
                throw std::runtime_error("Could not open the specified output file for writing.");
            }
        } else {
            outputFile.rdbuf(stdout);
        }

        size_t lineNumber = 1;
        std::string line;
        inputFile.seekg(0, std::ios::beg);

        while (std::getline(inputFile, line)) {
            if (!countNonEmptyLines || !line.empty()) {
                if (lineNumber == randomLineIndex + 1) {
                    outputFile << line;
                    break;
                }
                ++lineNumber;
            }
        }

        if (outputFile) {
            outputFile.close();
        }

        std::cout << "Number of lines in the file: " << lineCount << "\n";
        std::cout << "Randomly selected line number: " << randomLineIndex + 1 << '\n';
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
        return 1;
    }
}
