#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <sys/mman.h>
#include <unistd.h>
#include <semaphore.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t mutex;
} CRCI_POOL;

CRCI_POOL* crc_pool_init(size_t max_elements) {
    CRCI_POOL *pool = mmap(NULL, sizeof(CRCI_POOL), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool == MAP_FAILED) {
        perror("mmap failed");
        return NULL;
    }

    pthread_mutex_init(&pool->mutex, NULL);
    pool->capacity = max_elements;
    pool->size = 0;
    pool->data = calloc(max_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        perror("calloc failed");
        munmap(pool, sizeof(CRCI_POOL));
        return NULL;
    }

    for (size_t i = 0; i < max_elements; ++i) {
        pthread_mutex_init(&((NFAPI_CRC_INDICATION_PDU_T*)pool->data + i)->mutex, NULL);
    }

    return pool;
}

size_t crc_pool_push(CRCI_POOL *pool, RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size >= pool->capacity) {
        pthread_mutex_unlock(&pool->mutex);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool->data[pool->size];
    pdu->rx_ue_information_tag = rx_ue_information_tag;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag.crcflag = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG to either 1 or 0

    pool->size++;
    printf("Successfully created PDU #%ld\n", pool->size);
    fflush(stdout);

    pthread_mutex_unlock(&pool->mutex);
    return pool->size - 1;
}

void crc_pool_free(CRCI_POOL *pool) {
    if (!pool) return;

    free(pool->data);
    munmap(pool, sizeof(CRCI_POOL));
}
