struct lock_free_list {
    struct node volatile *head;
    pthread_mutex_t mutex; // Fallback mechanism
};

void init_lock_free_list(struct lock_free_list* list) {
    new(&list->head) struct node;
    list->head->next = list->head;
    pthread_mutex_init(&list->mutex, NULL);
}

int enqueue(struct lock_free_list* list, NFAPI_CRC_INDICATION_PDU_T* data) {
