    struct node** tail = &list->head;
    while (true) {
        struct node* next = vol_head->next;
        if (__sync_val_compare_and_swap(vol_head->next, next, node)) break;
        else if (next == vol_head) pthread_mutex_lock(&list->mutex); // Fallback mechanism
    }

    *tail = node;
    tail = &node->next;
    return 1;
}

int dequeue(struct lock_free_list* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    struct node* vol_head = list->head;
    while (true) {
        struct node* next = vol_head->next;
        if (__sync_val_compare_and_swap(vol_head, vol_head, next)) break;
    }

    if (vol_head == list->head) return -1; // List is empty

    struct node* temp = vol_head->next;
    *data = temp->data;

    while (true) {
        struct node* next = temp->next;
        if (__sync_val_compare_and_swap(vol_head, temp, next)) break;
        else if (next == vol_head) pthread_mutex_lock(&list->mutex); // Fallback mechanism
    }

    free(temp);
    return 1;
}

