static NFAPI_CRC_INDICATION_PDU_T *head = NULL;
static pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
static size_t nodeCount = 0;

void addNode(NFAPI_CRC_INDICATION_PDU_T *newNode) {
    pthread_mutex_lock(&listMutex);
    newNode->next = head;
    head = newNode;
    nodeCount++;
    uint16_t rollingChecksum = 0;
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        rollingChecksum += current->crcIndication.crcValue;
        current = current->next;
    }
    newNode->crcFlag = (rollingChecksum & 0x0001) == 0x0001 ? true : false;
    pthread_mutex_unlock(&listMutex);
}

NFAPI_CRC_INDICATION_PDU_T* removeHead() {
    NFAPI_CRC_INDICATION_PDU_T *tempNode = head;
    if (head != NULL) {
        head = head->next;
        nodeCount--;
    }
    return tempNode;
}

