UE_CONTEXT_BUFFER_T* create_ue_context_buffer(size_t capacity, void (*reclaim)(void*, size_t)) {
    UE_CONTEXT_BUFFER_T* buffer = malloc(sizeof(UE_CONTEXT_BUFFER_T));
    if (!buffer) return NULL;

    pthread_rwlock_init(&buffer->lock, NULL);
    buffer->capacity = capacity;
    buffer->used = 0;
    buffer->fragmentation = 0;
    buffer->reclaim = reclaim;
    buffer->buffer = malloc(sizeof(LTE_UE_CONTEXT_T) * capacity);
    if (!buffer->buffer) {
        free(buffer);
        return NULL;
    }

    return buffer;
}

LTE_UE_CONTEXT_T* allocate_ue_context(UE_CONTEXT_BUFFER_T* buffer, size_t* out_index) {
