// Lock-free ring buffer for UE Contexts and NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    void** data;
    size_t capacity;
    size_t head;
    size_t tail;
} lf_ringbuffer_t;

void init_lf_ringbuffer(lf_ringbuffer_t* buf, size_t capacity) {
    buf->capacity = capacity;
    buf->data = malloc(sizeof(void*) * capacity);
    buf->head = buf->tail = 0;
}

bool push_lf_ringbuffer(lf_ringbuffer_t* buf, void* data) {
    if ((buf->head + 1) % buf->capacity == buf->tail) return false; // Buffer full
    buf->data[(buf->head)] = data;
    buf->head = (buf->head + 1) % buf->capacity;
    return true;
}

void* pop_lf_ringbuffer(lf_ringbuffer_t* buf) {
    if (buf->tail == buf->head) return NULL; // Buffer empty
    void* data = buf->data[(buf->tail)];
    buf->tail = (buf->tail + 1) % buf->capacity;
    return data;
}

typedef struct ue_context {
    uint32_t uecid;
    uint16_t bwp; // Randomized within limits
    // ... other UE Context members
} ue_context_t;

