    ctx->bwp = rand() % (MAX_BWP - MIN_BWP + 1) + MIN_BWP; // Randomize BWP within specified limits
    // ... initialize other UE Context members
}

typedef struct ue_config {
    uint32_t max_memory;
    double crc_flag_probability;
    size_t buffer_size_constraints;
} ue_config_t;

int init_ue_list(void** list_buf, size_t N, const ue_config_t* config) {
    lf_ringbuffer_t ue_list = {0};
    init_lf_ringbuffer(&ue_list, N);
    void* buffer = calloc(N, sizeof(ue_context_t));
    if (!buffer || !buffer_within_mem_constraints(config, N * sizeof(ue_context_t))) { // Check memory constraint
        free(buffer);
        return -1;
    }

    ue_context_t* ctx = (ue_context_t*) buffer;
    for (size_t i = 0; i < N; ++i) {
        init_ue_context(&ctx[i], i); // Initialize UE Contexts
        if (!push_lf_ringbuffer(&ue_list, &ctx[i])) { // Add to lock-free ring buffer
            for (size_t j = 0; j < i; ++j) free(ctx + j); // Free allocated but not added contexts
            free(buffer);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* crc_indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications || !buffer_within_mem_constraints(config, N * sizeof(NFAPI_CRC_INDICATION_PDU_T))) { // Check memory constraint
        free(buffer);
        free(crc_indications);
        return -1;
    }

    // Generate and initialize CRC_INDICATION_PDU_T structures here...

    *list_buf = buffer;
    void** data = pop_lf_ringbuffer(&ue_list); // Get the first UE context from lock-free ring buffer
    while (data) {
        ctx = (ue_context_t*) data;
        // Attach CRC_INDICATION_PDU_T structures to UE Context here...
        data = pop_lf_ringbuffer(&ue_list);
    }

    free(crc_indications); // Free unused memory
    return N;
}

bool buffer_within_mem_constraints(const ue_config_t* config, size_t bytes) {
    return (bytes <= config->max_memory && bytes <= config->buffer_size_constraints);
}
