#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <limits.h>

// Lock-free queue structure for efficient thread-safe access
typedef struct lock_free_queue {
    void** buffer;
    size_t head;
    size_t tail;
    size_t capacity;
} lock_free_queue;

void lock_free_enqueue(lock_free_queue* queue, void* data) {
    size_t index = (queue->head + 1) % queue->capacity;

    while (index != queue->tail) {
        if (__sync_val_compare_and_swap(&queue->buffer[queue->head], NULL, data))
            break;
        index = (index + 1) % queue->capacity;
    }

    if (index == queue->tail)
        queue->tail = index;
}

void* lock_free_dequeue(lock_free_queue* queue) {
    size_t head = queue->head;

    while (true) {
        void* data = queue->buffer[head];

        if (!data)
            break;

        if (__sync_val_compare_and_swap(&queue->buffer[head], data, NULL))
            return data;

        head = (head + 1) % queue->capacity;
    }

    return NULL;
}

lock_free_queue* create_lock_free_queue(size_t capacity) {
    lock_free_queue* queue = malloc(sizeof(lock_free_queue));
    queue->buffer = calloc(capacity, sizeof(void*));
    queue->head = 0;
    queue->tail = 0;
    queue->capacity = capacity;
    return queue;
}

// Function to initialize UE contexts and NFAPI structures
size_t init_ue_contexts(size_t num, void* buffer, const void* config) {
    lock_free_queue* q = create_lock_free_queue(num);

    // Initialize UE contexts
    for (size_t i = 0; i < num; ++i) {
        uint32_t uecid = i;
        // Randomize BWP settings within specified limits
        int bwp = rand() % MAX_BWP;

        // Create UE context structure with unique UECID and randomized BWP
