        ctx->uecid = uecid;
        ctx->ucd.bwp = bwp;
        // ... fill remaining parameters of UE_CONTEXT_T structure

        // Enqueue the UE context in the lock-free queue for later processing
        lock_free_enqueue(q, ctx);
    }

    size_t processed = 0;
    while (processed < num && q->head != q->tail) {
        UE_CONTEXT_T* ctx = lock_free_dequeue(q);

        // Create NFAPI structure with associated UE context and other parameters
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        pdu->rnti = rand() % MAX_RNTI;
        pdu->crc_indication_rel8_tag.crcflag = (rand() < *(uint32_t*)config) ? 1 : 0;
        // ... fill remaining parameters of NFAPI_CRC_INDICATION_PDU_T structure, associating with the UE context

        // Copy the UE context into the provided buffer at the appropriate index
        memcpy(buffer + processed * sizeof(NFAPI_CRC_INDICATION_PDU_T), pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        ++processed;
    }

    free(q);

    if (processed == num)
        return num;
    else
        return -1;
}
