```java
import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.logging.Level;
import java.util.logging.Logger;

public class HashUtil {
    private static final Logger LOGGER = Logger.getLogger(HashUtil.class.getName());

    public static byte[] hash(String input, String algorithm) throws NoSuchAlgorithmException {
        MessageDigest md;
        if (algorithm.equalsIgnoreCase("MD5")) {
            md = MessageDigest.getInstance("MD5");
        } else if (algorithm.equalsIgnoreCase("SHA-256")) {
            md = MessageDigest.getInstance("SHA-256");
        } else {
            throw new IllegalArgumentException("Unsupported algorithm: " + algorithm);
        }

        byte[] bytesOfMessage = input.getBytes("UTF-8");
        byte[] digest = md.digest(bytesOfMessage);
        return digest;
    }

    public static String getHexDigest(byte[] hash) {
        BigInteger number = new BigInteger(1, hash);
        StringBuilder sb = new StringBuilder();
        sb.append(number.toString(16));
        while (sb.length() < 32) {
            sb.insert(0, '0');
        }
        return sb.toString();
    }

    public static String hashString(String input, boolean useMD5) throws NoSuchAlgorithmException {
        byte[] hash = hash(input, useMD5 ? "MD5" : "SHA-256");
        if (hash.length < 32) {
            throw new IllegalArgumentException("Input length too short for SHA-256 algorithm.");
        }
        return getHexDigest(hash);
    }
}
```

