#include <mutex>
#include <memory>
#include <functional>
#include <string>
#include <iostream>
#include <map>
#include <vector>
#include <thread>
#include <stdexcept>
#include <condition_variable>

struct SessionRecord {
    std::string sessionID;
    std::tm lastActivity; // Represented as a C standard time_t tm structure.
    std::string state;
    std::string loginIP;
    std::string userAgent;
};

typedef std::shared_ptr<SessionRecord> SessionPtr;
std::atomic_shared_ptr<std::deque<SessionPtr>> sessions; // Thread-safe dynamic list of session records.

void manageSessions(const SessionPtr& sessionToManage, std::function<void()> action) {
    std::unique_lock<std::mutex> lck(g_mtx);
    g_cv.wait(lck, [&](){ return sessions->empty() || (*sessions).back().get()->state == "active"; });

    // Add new session to the list.
    auto newSession = std::make_shared<SessionRecord>();
    *newSession = *sessionToManage;
    sessions->push_back(newSession);

    lck.unlock(); // Unlock to allow other threads to continue processing.

    action();

    std::unique_lock<std::mutex> lck2(g_mtx);
    g_cv.notify_one(); // Signal that a new session is processed and can be cleaned up.
}

void cleanupSessions() {
    std::unique_lock<std::mutex> lck(g_mtx);
    auto now = std::chrono::system_clock::now().time_since_epoch().count();

    while (!sessions->empty()) {
        auto session = sessions->front();
        auto sessionTime = std::chrono::system_clock::from_time_t(std::mktime(&session.get()->lastActivity));
        auto elapsedSeconds = std::chrono::duration_cast<std::chrono::seconds>(now - sessionTime).count();

        if (elapsedSeconds > 60) { // Expired sessions get cleaned up after one minute of inactivity.
            sessions->pop_front();
        } else {
            break; // If the session is active, wait until it becomes expired to clean it up.
        }
    }
}

void logErrorsAndAnomalies(const std::string& errorMessage) {
    // Implement logging functionality here.
}

// Function to add a new session with given metadata and state.
SessionPtr createSession(const std::string& sessionID, const std::tm& lastActivity, const std::string& state,
                         const std::string& loginIP, const std::string& userAgent) {
    auto session = std::make_shared<SessionRecord>();
    *session = {sessionID, lastActivity, state, loginIP, userAgent};
    manageSessions(session, [session](){ sessions->push_back(session); }); // Add the new session to the list concurrently.
    return session;
}

// Function to query the dynamic list based on given criteria.
std::vector<SessionPtr> filterSessions(const std::string& sessionID, const std::string& state,
                                      const std::tm& startTime, const std::tm& endTime) {
    std::unique_lock<std::mutex> lck(g_mtx);
    std::vector<SessionPtr> result;

    for (auto session : *sessions) {
        if ((session->sessionID == sessionID || sessionID.empty()) &&
            (session->state == state || state.empty()) &&
            (std::mktime(&session->lastActivity) >= std::mktime(&startTime) &&
             std::mktime(&session->lastActivity) <= std::mktime(&endTime))) {
            result.push_back(session);
        }
    }
    return result;
}

// Global mutex and condition variable for synchronizing thread access to the dynamic list.
std::mutex g_mtx;
std::condition_variable g_cv;
```

