class LTEUEContext {
public:
    uint64_t UECID;
    NFAPI_CRC_INDICATION_PDU_T UCD;

    LTEUEContext(uint64_t id) : UECID(id), UCD() {}
};

std::vector<LTEUEContext*> initializeUEContexts(size_t N, cppcms3::utility::logger& log) {
    std::vector<LTEUEContext*> contexts;
    std::map<uint64_t, bool> RNTIsUsed;
    std::default_random_engine generator(time(0));
    std::uniform_int_distribution<> distribution(0, BWP_MAX - BWP_MIN + 1);

    for (size_t i = 0; i < N; ++i) {
        uint64_t id = i;
        LTEUEContext* context = new LTEUEContext(id);
        contexts.push_back(context);
        RNTIsUsed[id] = false;

        context->UCD.RX_UE_INFORMATION_TAG = static_cast<uint16_t>(rand() | 0x8000);
        context->UCD.RNTI = id;
        context->UCD.CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() < CRCFLAG_PROBABILITY) ? 1 : 0;

        if (RNTIsUsed[id]) {
            delete context;
            log("Error: Duplicate RNTI encountered. Reallocating with a new UECID.");
            id = generateUniqueUECID(contexts, RNTIsUsed);
            context->UCD.RNTI = id;
        }

        RNTIsUsed[id] = true;

        // Randomize bandwidth part (BWP) settings within specified limits
        context->UCD.BWP.startingFrequency_Hz = BWP_MIN + distribution(generator);
        context->UCD.BWP.bandwidth_kHz = BWP_KHZ + distribution(generator);
        context->UCD.BWP.numOfBWPs = static_cast<uint8_t>(1 + (rand() % NUM_OF_BWP));

        // Add other configuration parameters as needed
    }

    return contexts;
}

uint64_t generateUniqueUECID(std::vector<LTEUEContext*>& contexts, std::map<uint64_t, bool>& RNTIsUsed) {
    uint64_t id = 0;
    do {
        ++id;
    } while (RNTIsUsed[id]);

    return id;
}

