    for (size_t i = 0; i < N; ++i) {
        RX_UE_INFORMATION_TAG tag;
        while (1) {
            tag = (RX_UE_INFORMATION_TAG)i;
            size_t unique = 1;
            for (size_t j = 0; j < i; ++j) {
                if (pdus[j].tag == tag) {
                    unique = 0;
                    break;
                }
            }
            if (unique) {
                break;
