#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <time.h>

typedef struct {
    char ip[INET6_ADDRSTRLEN];
    in_port_t port;
    time_t last_activity;
} Connection;

typedef struct connection_map {
    pthread_mutex_t lock;
    Connection **connections;
    size_t capacity, count;
} ConnectionMap;

ConnectionMap *connection_map_new(size_t initial_capacity) {
    ConnectionMap *map = malloc(sizeof(*map));
    map->connections = calloc(initial_capacity, sizeof(Connection*));
    map->capacity = initial_capacity;
    map->count = 0;
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

void connection_map_resize(ConnectionMap *map) {
    Connection **old_connections = map->connections;
    size_t new_capacity = map->capacity * 2;
    map->connections = realloc(old_connections, new_capacity * sizeof(Connection*));
    memset(&map->connections[map->capacity], 0, (new_capacity - map->capacity) * sizeof(Connection*));
    map->capacity = new_capacity;
}

void connection_map_insert(ConnectionMap *map, Connection *connection) {
    pthread_mutex_lock(&map->lock);
    if (map->count >= map->capacity) connection_map_resize(map);
    size_t index = map->count % map->capacity;
    map->connections[index] = connection;
    ++map->count;
    pthread_mutex_unlock(&map->lock);
}

Connection *connection_map_find_by_ip(const ConnectionMap *map, const char *ip) {
    pthread_mutex_lock(&map->lock);
    for (size_t i = 0; i < map->count; ++i) {
        if (!strcmp(map->connections[i]->ip, ip)) {
            Connection *connection = map->connections[i];
            pthread_mutex_unlock(&map->lock);
            return connection;
        }
    }
    pthread_mutex_unlock(&map->lock);
    return NULL;
}

Connection *connection_map_find_by_port(const ConnectionMap *map, in_port_t port) {
    pthread_mutex_lock(&map->lock);
    for (size_t i = 0; i < map->count; ++i) {
        if (map->connections[i]->port == port) {
            Connection *connection = map->connections[i];
            pthread_mutex_unlock(&map->lock);
            return connection;
        }
    }
    pthread_mutex_unlock(&map->lock);
    return NULL;
}
