} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    int max_structures;
    int current_structures;
    int dynamic_param;
} ConfigData;

void* set_dynamic_param(void* data) {
    ConfigData* config = (ConfigData*)data;
    pthread_mutex_lock(&config->lock);
    if (config->dynamic_param < 0) {
        printf("Invalid dynamic parameter value.\n");
        pthread_mutex_unlock(&config->lock);
        return NULL;
    }
    config->max_structures = config->dynamic_param;
    pthread_mutex_unlock(&config->lock);
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* create_populated_array(int n) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Memory allocation failure.\n");
        return NULL;
    }

    ConfigData config = { .lock = PTHREAD_MUTEX_INITIALIZER, .max_structures = n };
    pthread_t thread;
    if (pthread_create(&thread, NULL, set_dynamic_param, &config) != 0) {
        fprintf(stderr, "Thread creation failure.\n");
        free(pdu);
        return NULL;
    }
    pthread_join(thread, NULL);

    for (int i = 0; i < config.max_structures; ++i) {
        pdu[i].rx_ue_information_tag = (RX_UE_INFORMATION_TAG)i;
        pdu[i].rnti = (RNTI)(i % 256);
        pdu[i].crc_indication_rel8_tag.crcflag = rand() % 2;
    }

    return pdu;
}
