#include <stdio.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <time.h>
#include <stdlib.h>
#include <sys/socket.h>

typedef struct Connection {
    sockaddr_in addr;
    time_t last_active;
    pthread_mutex_t lock;
} Connection;

typedef struct ConnectionList {
    Connection *connections;
    size_t size;
    size_t capacity;
    size_t head;
    size_t tail;
    time_t timeout;
    size_t max_size;
    pthread_mutex_t list_lock;
} ConnectionList;

ConnectionList *conn_list_init(time_t timeout, size_t max_size) {
    ConnectionList *list = malloc(sizeof(ConnectionList));
    if (!list) return NULL;
    list->connections = NULL;
    list->size = 0;
    list->capacity = 0;
    list->head = 0;
    list->tail = 0;
    list->timeout = timeout;
    list->max_size = max_size;
    pthread_mutex_init(&list->list_lock, NULL);
    return list;
}

void conn_list_destroy(ConnectionList *list) {
    if (!list) return;
    for (size_t i = list->head; i != list->tail; i = (i + 1) % list->capacity) {
        Connection *conn = &list->connections[i];
        pthread_mutex_destroy(&conn->lock);
    }
    free(list->connections);
    free(list);
}

Connection* conn_get_by_ip(ConnectionList *list, const char *ip) {
    if (!list || !ip) return NULL;
    pthread_mutex_lock(&list->list_lock);
    for (size_t i = list->head; i != list->tail; i = (i + 1) % list->capacity) {
        Connection *conn = &list->connections[i];
        if (inet_pton(AF_INET, ip, &conn->addr.sin_addr) == 1) {
            pthread_mutex_unlock(&list->list_lock);
            return conn;
        }
    }
    pthread_mutex_unlock(&list->list_lock);
    return NULL;
}

Connection* conn_get_by_port(ConnectionList *list, socklen_t size, const sa_family_t *address, in_port_t port) {
    if (!list || !address || !size) return NULL;
    pthread_mutex_lock(&list->list_lock);
    for (size_t i = list->head; i != list->tail; i = (i + 1) % list->capacity) {
        Connection *conn = &list->connections[i];
        if (size == sizeof(sockaddr_in)) {
            if (*(const sockaddr_in *)address == conn->addr && port == ntohs(conn->addr.sin_port)) {
                pthread_mutex_unlock(&list->list_lock);
                return conn;
            }
        }
    }
    pthread_mutex_unlock(&list->list_lock);
    return NULL;
}

void conn_add(ConnectionList *list, const char *ip, socklen_t size, const sa_family_t *address, in_port_t port) {
    if (!list || !ip || !size || !address) return;
    Connection *new_conn = malloc(sizeof(Connection));
    if (!new_conn) return;
    memcpy(&new_conn->addr, address, size);
    new_conn->last_active = time(NULL);
    pthread_mutex_init(&new_conn->lock, NULL);

    pthread_mutex_lock(&list->list_lock);
    if (list->size == list->capacity) {
        if (list->head == 0) list->head = list->capacity - 1;
        list->tail = (list->head + 1) % list->capacity;
    }
    list->connections[list->head] = *new_conn;
    list->size++;
    if (list->size > list->max_size) {
        size_t oldest_idx = (list->head + (time(NULL) - list->timeout) / list->timeout) % list->capacity;
        Connection oldest = list->connections[oldest_idx];
        pthread_mutex_destroy(&oldest.lock);
        free(oldest.addr.sin_addr.s_addr); // Free IP address if necessary
        free(oldest.addr.sin_port); // Free port number if necessary
        free(oldest);
        list->size--;
    }
    pthread_mutex_unlock(&list->list_lock);
}

void conn_update(ConnectionList *list, const char *ip, socklen_t size, const sa_family_t *address, in_port_t port) {
    Connection* conn = conn_get_by_ip(list, ip);
    if (!conn || !conn->addr.sin_addr.s_addr) return; // IP address not found or invalid
    pthread_mutex_lock(&list->list_lock);
    for (size_t i = list->head; i != list->tail; i = (i + 1) % list->capacity) {
        Connection *c = &list->connections[i];
        if (inet_pton(AF_INET, ip, &c->addr.sin_addr) == 1 && c->addr.sin_port == port) {
            c->last_active = time(NULL);
            pthread_mutex_unlock(&list->list_lock);
            pthread_mutex_unlock(&c->lock);
            return;
        }
    }
    pthread_mutex_unlock(&list->list_lock);
}

void conn_garbage_collection(ConnectionList *list) {
    if (!list || list->size == 0) return;
    pthread_mutex_lock(&list->list_lock);
    size_t oldest_idx = (list->head + (time(NULL) - list->timeout) / list->timeout) % list->capacity;
    Connection oldest = list->connections[oldest_idx];
    pthread_mutex_destroy(&oldest.lock);
    free(oldest.addr.sin_addr.s_addr); // Free IP address if necessary
    free(oldest.addr.sin_port); // Free port number if necessary
    free(oldest);
    list->size--;
    pthread_mutex_unlock(&list->list_lock);
}
```

