#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
    pthread_mutex_t lock;
} Node;

static size_t num_successful_allocations = 0;
static size_t num_unsuccessful_allocations = 0;
static pthread_mutex_t stats_lock = PTHREAD_MUTEX_INITIALIZER;

Node* list = NULL;
pthread_mutex_t head_lock = PTHREAD_MUTEX_INITIALIZER;

void init_list() {
    pthread_mutex_init(&head_lock, NULL);
}

void destroy_list() {
    Node *current = list;
    Node *next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&head_lock);
}

Node* acquire_node() {
    Node *new_node = malloc(sizeof(Node));

    if (!new_node) {
        pthread_mutex_lock(&stats_lock);
        num_unsuccessful_allocations++;
        pthread_mutex_unlock(&stats_lock);
        return NULL;
    }

    new_node->data.crc_indication_rel8_tag.crcflag = rand() % 2;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    pthread_mutex_lock(&head_lock);
    new_node->next = list;
    list = new_node;
    pthread_mutex_unlock(&head_lock);

    pthread_mutex_lock(&stats_lock);
    num_successful_allocations++;
    pthread_mutex_unlock(&stats_lock);

    return new_node;
}

void free_node(Node *node) {
    if (!node) return;

    pthread_mutex_lock(&head_lock);

    if (list == node)
        list = node->next;
    else {
        Node *current = list;

        while (current->next != node)
            current = current->next;

        current->next = node->next;
    }

    pthread_mutex_unlock(&head_lock);

    free(node);
}
```

This code defines a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures, ensuring efficient memory allocation and deallocation through `acquire_node()` and `free_node()` functions. The list is thread-safe using mutex locks for concurrent access from multiple threads. It also keeps statistics on the number of successful allocations and reallocations performed, as well as logs errors if any allocation fails.']

