void grow_list(size_t new_capacity) {
    if (new_capacity <= capacity) return;

    PHY_STATS_RECORD_T *tmp = realloc(list, sizeof(PHY_STATS_RECORD_T) * new_capacity);
    if (!tmp) {
        fprintf(stderr, "Failed to reallocate memory for the list\n");
        num_failures++;
        return;
