    if (num_elements == capacity) grow_list(capacity * 2);
    ++num_elements;
    memset(result, 0, sizeof(*result));
    return result;
}

void log_error() {
    fprintf(stderr, "Number of allocation failures: %zu\n", num_failures);
    if (num_failures > 1) {
        fprintf(stderr, "Multiple allocation errors occurred!\n");
    }
}

void list_init(size_t initial_capacity) {
    list = malloc(sizeof(PHY_STATS_RECORD_T) * initial_capacity);
    if (!list) log_error();

    capacity = initial_capacity;
    num_elements = 0;
}

