typedef struct LockFreeListNode {
    struct LockFreeListNode *next;
    NFAPI_CRC_INDICATION_PDU_T data;
    pthread_spinlock_t lock;
} LockFreeListNode_T;

LockFreeListNode_T* lockfree_list_init(size_t size) {
    if (size == 0) return NULL;

    LockFreeListNode_T *head = malloc(sizeof(LockFreeListNode_T));
    if (!head) return NULL;

    head->next = NULL;
    head->lock.pthread_attr_init(&head->lock.attr);
    pthread_spin_init(&head->lock, PTHREAD_PROCESS_PRIVATE);

    for (size_t i = 1; i < size; ++i) {
        LockFreeListNode_T *node = malloc(sizeof(LockFreeListNode_T));
        if (!node) {
            free(head);
            return NULL;
        }
        node->next = head;
        pthread_spin_init(&node->lock, PTHREAD_PROCESS_PRIVATE);
        node->data.crc_indication.CRCFLAG = rand() % 100 < config.crccapability; // 1% chance of CRC error
        node->next = head;
        head = node;
    }

    return head;
}

UE_Context_T* create_ue_context(uint32_t UECID, UE_Configuration config) {
    UE_Context_T *context = malloc(sizeof(UE_Context_T));
