    if (!N || !list_buffer) return 0;

    *list_buffer = malloc(N * sizeof(UE_Context_T));
    if (!*list_buffer) return 0;

    LockFreeListNode_T *head = lockfree_list_init(N);
    if (!head) {
        free(*list_buffer);
        return 0;
    }

    size_t count = 0;
    for (LockFreeListNode_T* node = head; node; node = node->next, ++count) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &node->data.crc_indication.value.pdu;
        UE_Context_T *context = create_ue_context(node->data.tag.UE_ID, config);

