    struct _NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _list_t {
    size_t max_size;
    size_t num_elements;
    size_t failed_allocs;
    size_t integrity_check_fails;
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
    pthread_mutex_t mutex;
} list_t;

list_t* create_list(size_t max_size) {
    list_t *list = malloc(sizeof(list_t));
    if (!list) return NULL;

    list->max_size = max_size;
    list->num_elements = 0;
    list->failed_allocs = 0;
    list->integrity_check_fails = 0;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

NFAPI_CRC_INDICATION_PDU_T* create_node() {
    NFAPI_CRC_INDICATION_PDU_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;

    node->tag = (RX_UE_INFORMATION_TAG)random();
    node->rnti = random();
    node->crc_indication = malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (!node->crc_indication) {
        free(node);
        return NULL;
    }
    node->crc_indication->crcflag = (uint16_t)(random() & ((1 << 15) - 1));
    node->prev = node->next = NULL;
    return node;
}

void insert(list_t* list, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list->mutex);
    if (list->num_elements >= list->max_size) {
        free(node->crc_indication);
        free(node);
        list->integrity_check_fails++;
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->next = list->head;
        list->head->prev = node;
        list->head = node;
    }
    list->num_elements++;
    pthread_mutex_unlock(&list->mutex);
}

void dump(const list_t* list) {
    printf("Linked List:\n");
    for (NFAPI_CRC_INDICATION_PDU_T *current = list->head; current != NULL; current = current->next) {
        printf("\ttag: 0x%x\n", current->tag);
        printf "\trnti: %u\n", current->rnti);
        printf("\tcrcflag: 0x%x\n", current->crc_indication->crcflag);
    }
}
