const uint32_t MAX_MEMORY = 1000000; // Maximum memory usage limit (bytes)
const int CRC_FLAG_PROBABILITY = 50; // CRC flag probability (%)
const int BUFFER_SIZE_CONSTRAINT = 1024; // Buffer size constraint (bytes)

struct UEContext {
    uint32_t UECID;
    struct UEConfigurationData UCD;
};

