std::vector<UEContext> createUEContexts(size_t N, void* buffer, const UEConfigurationData* config) {
    std::vector<UEContext> ueContexts;
    ueContexts.reserve(N); // Reserve space to avoid frequent reallocations

    auto it = ueContexts.begin();
    for (size_t i = 0; i < N && ((uint64_t)ueContexts.size() + sizeof(UEContext) * i) <= MAX_MEMORY; ++i, ++it) {
        void* contextPtr = (char*)buffer + sizeof(UEContext) * i;
        new (contextPtr) UEContext{ static_cast<uint32_t>(i), config[i] }; // Construct UEContext at specified memory location

        if (ueContexts.size() == i && ((uint64_t)it - ueContexts.cbegin()) >= N) {
            it = ueContexts.end();
            break;
        }
    }

    if (it != ueContexts.end()) { // If we didn't reach the end of 'buffer' before the memory limit was reached, create remaining contexts in a new block
        size_t remaining = N - ueContexts.size();
        auto newBufferPtr = std::allocator_traits<std::allocator<UEContext>>::allocate(ueContexts.get_allocator(), remaining);
        std::copy(it, ueContexts.end(), newBufferPtr); // Copy existing contexts to the new block
        ueContexts.resize(N, UEContext()); // Resize the vector to reserve space for all allocated contexts
        it = ueContexts.begin();

        for (size_t i = 0; i < remaining; ++i, ++it) {
            new (it) UEContext{ static_cast<uint32_t>(ueContexts.size() + i), config[i] }; // Construct UEContext at specified memory location
        }
    }

    std::vector<NFAPI_CRC_INDICATION_PDU_T> crcIndications;
    crcIndications.reserve(ueContexts.size());

    for (auto& context : ueContexts) {
        uint8_t crcFlag = static_cast<uint8_t>(std::rand() % 100 < CRC_FLAG_PROBABILITY);
        NFAPI_CRC_INDICATION_PDU_T crcIndication{ context.tag, context.UEID, { .crcFlag = crcFlag } };
        crcIndications.push_back(crcIndication);
    }

    return ueContexts;
}
