static unsigned int update_count = 0;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void reset_rate_limit() {
    last_reset = time(NULL);
    update_count = 0;
}

char* stringToMD5WithAdvancedOptions(const char *input, size_t size_limit, bool trim, bool log, int rate_limit) {
    Options opts = { (char*)input, size_limit, trim, log, rate_limit };
    reset_rate_limit();

    sem_wait(&rate_limiter);
    char *hash = SHA1((unsigned char*)input, strlen(input), NULL);
    if (!sem_trywait(&rate_limiter)) {
        free(hash);
        return NULL;
    }

    size_t current_size = strlen(input);
    if (current_size <= size_limit) {
        char *result = malloc(current_size + 32 + 10); // MD5 length + trailing slash + custom log message + timestamp
        if (!result) {
            free(hash);
            return NULL;
        }

        strcpy(result, hash);
        sprintf(&result[32], "/%s %llu", ctime(&time(NULL)), (unsigned long long)update_count);

        if (log) {
            pthread_mutex_lock(&log_mutex);
            printf("%s: [%lld] Processed %d hash updates with string length %zu and hash value %s\n", ctime(&time(NULL)), (long long)current_size, update_count, current_size, hash);
            pthread_mutex_unlock(&log_mutex);
        }

        if (trim && current_size > size_limit) {
            result[size_limit] = '\0';
            strncat(result, "\037", size_limit - current_size + 1);
        }
        return result;
    } else if (trim) {
        char *truncated_input = malloc(size_limit);
        strncpy(truncated_input, input, size_limit);
        truncated_input[size_limit] = '\0';

        char *result = malloc(strlen(SHA1((unsigned char*)truncated_input, strlen(truncated_input), NULL)) + 32 + 10);
        if (!result) {
            free(truncated_input);
            free(hash);
            return NULL;
        }

        strcpy(result, SHA1((unsigned char*)truncated_input, strlen(truncated_input), NULL));
        sprintf(&result[32], "/%s %llu", ctime(&time(NULL)), (unsigned long long)update_count);

        if (log) {
            pthread_mutex_lock(&log_mutex);
            printf("%s: [%lld] Processed %d hash updates with string length %zu before truncation to %zu and hash value %s\n", ctime(&time(NULL)), (long long)current_size, update_count, current_size, strlen(truncated_input), result);
            pthread_mutex_unlock(&log_mutex);
        }

        free(truncated_input);
        return result;
    } else {
        if (log) {
            pthread_mutex_lock(&log_mutex);
            printf("%s: [%lld] String exceeds size limit (%zu), refusing to generate hash\n", ctime(&time(NULL)), (long long)current_size, current_size);
            pthread_mutex_unlock(&log_mutex);
        }
        free(hash);
        return NULL;
    }
}

void init_rate_limit() {
    sem_init(&rate_limiter, 0, rate_limit);
}
```

