template<typename T>
class ConcurrentList {
private:
    std::vector<std::unique_ptr<T>> list;
    std::mutex mtx;
    size_t capacity;
    size_t read_index, write_index;
    boost::circular_buffer<T> buffer; // Buffer for high-frequency updates
public:
