    void push(T* data) {
        std::unique_lock<std::mutex> lock(mtx);
        if (list.size() >= capacity) {
            // Handle out of capacity and log error
        }
        list.push_back(data);
        buffer.push_back(*data); // Store a copy for high-frequency updates
    }
    T* pop() {
        std::unique_lock<std::mutex> lock(mtx);
        if (list.empty()) {
            // Handle underflow and log error
        }
        auto result = list[read_index].get();
        list.erase(list.begin());
        read_index = (read_index + 1) % capacity;
        return result;
    }
};
