['```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <cstdlib>
#include <csignal>
#include <numeric>
#include <random>
#include <sys/stat.h>
#include <unistd.h>
#include <sys/types.h>

class RandomNumberGenerator {
public:
    explicit RandomNumberGenerator(int argc, char* argv[]) {
        initialize(argc, argv);
    }

    ~RandomNumberGenerator() {
        if (_line_reader) _line_reader.reset();
        if (_output_file) delete[] _output_file;
    }

    void run();

private:
    void initialize(int argc, char* argv[]);
    std::ifstream _line_reader;
    std::ofstream _output_file;
    std::string* _output_file;
    bool count_empty_lines = false;
    int line_count = 0;
    std::random_device _rd;
    std::mt19937 _gen;

    static void signal_handler(int signum) {
        if (signum == SIGINT || signum == SIGTERM) {
            std::cout << "\nExiting gracefully..." << std::endl;
            exit(0);
        }
    }
};

void RandomNumberGenerator::initialize(int argc, char* argv[]) {
    signal(SIGINT, &signal_handler);
    signal(SIGTERM, &signal_handler);

    if (argc < 2) {
        print_usage();
        exit(1);
    }

    std::string input_file;
    std::string output_file = "";
    bool help = false;

    for (int i = 1; i < argc; ++i) {
        if (argv[i][0] == '-') {
            switch (argv[i][1]) {
                case 'h':
                case 'H':
                    help = true;
                    break;
                case 'c':
                    count_empty_lines = true;
                    break;
                case 'o':
                    if (++i == argc) {
                        print_usage();
                        exit(1);
                    }
                    output_file = argv[i];
                    break;
                default:
                    print_usage();
                    exit(1);
            }
        } else {
            input_file = argv[i];
        }
    }

    if (help) {
        print_usage();
        return;
    }

    if (!input_file.empty()) {
        _line_reader.open(input_file);
        if (!_line_reader.is_open()) {
            std::cerr << "Error opening file: " << input_file << std::endl;
            exit(1);
        }
    } else {
        print_usage();
        exit(1);
    }

    if (!output_file.empty()) {
        _output_file = new char[output_file.size() + 1];
        std::copy(output_file.begin(), output_file.end(), _output_file);
        _output_file[_output_file->size()] = '\0';
    }
}

void RandomNumberGenerator::run() {
    int lines = count_lines();
    _gen.seed(_rd());
    std::uniform_int_distribution<> dist(0, RAND_MAX);

    if (_output_file) {
        _output_file->open("w");
        if (!_output_file->is_open()) {
            std::cerr << "Error opening output file: " << *_output_file << std::endl;
            exit(1);
        }
    }

    while (_line_reader) {
        std::string line;
        std::getline(_line_reader, line);
        if (!_line_reader.eof()) {
            if (std::streamsize(_line_reader.gcount()) == 0) {
                if (!count_empty_lines) ++line_count;
                continue;
            } else if (_output_file) _output_file << line << std::endl;
        }
        if (_output_file && !_line_reader.eof()) {
            _output_file->flush();
        }
        ++line_count;
    }

    if (_output_file) {
        _output_file->close();
    }

    int random_number = dist(_gen);
    std::cout << "Total lines: " << line_count << ", Generated number: " << random_number << std::endl;
}

void RandomNumberGenerator::print_usage() {
    std::cout << "Usage: [input_file] [options]\n"
              << "\t-h, --help:\tdisplay this help and exit\n"
              << "\t-c:\tcount only non-empty lines\n"
              << "\t-o output_file:\tredirect output to a specified file" << std::endl;
}

void count_lines() {
    int line_count = 0;
    std::string line;
    while (std::getline(_line_reader, line)) {
        if (!_line_reader.eof()) ++line_count;
    }
    return line_count;
}

int main(int argc, char* argv[]) {
    RandomNumberGenerator rng(argc, argv);
    rng.run();
    return 0;
}
```

