import os
import sys
import time
import threading
import asyncio
from collections import defaultdict
import psutil
from functools import lru_cache
import logging
import gc
import zlib
import pickle

import dfs
import nfapi

class BufferReader:
    def __init__(self, file):
        self.file = file
        self.buf = b''
        self.position = 0

    async def read(self, size):
        while len(self.buf) < size:
            chunk = await self.file.read_chunk()
            self.buf += chunk

        result = self.buf[self.position:self.position + size]
        self.position += len(result)
        return result

    async def readline(self):
        line = b''
        while True:
            chunk = await self.read(1)
            if not chunk or chunk == b'\n':
                break
            line += chunk
        return line

class DynamicDfs:
    def __init__(self, root_path, max_workers=psutil.cpu_count(), **kwargs):
        self.root_path = os.path.abspath(os.path.expanduser(root_path))
        self.max_workers = max_workers
        self.queue = asyncio.Queue()
        self.results = defaultdict(list)
        self.workers = [Worker(self.queue, self.results) for _ in range(self.max_workers)]
        self.log = logging.getLogger(__name__)
        self._setup_logging()

    @lru_cache(maxsize=None)
    def get_file(self, path):
        return dfs.open(path, 'rb') if os.path.isfile(os.path.abspath(path)) else None

    async def process(self, path, delimiter='\n'):
        file = self.get_file(path)
        if not file:
            return []

        reader = BufferReader(file)
        lines = await asyncio.gather(*[reader.readline() for _ in range(1024)])
        data = [line.decode().strip() for line in lines]
        return [data for data in zip(*[iter(data)] * len(delimiter)) if delimiter.join(data) == ''.join(delimiter)]

    async def _run_worker(self, queue, results):
        while True:
            path = await queue.get()
            if not path:
                break

            try:
                data = await self.process(path)
                results[os.path.relpath(path, self.root_path)] += data
                gc.collect()
            except Exception as e:
                self.log.error(f'Error processing {path}: {e}', exc_info=True)

    def _setup_logging(self):
        logging.basicConfig(format='%(asctime)s %(levelname)s [%(name)s] - %(message)s', level=logging.INFO)
        self.log.info('Initializing DynamicDfs')

    async def run(self):
        for worker in self.workers:
            worker.start()

        tasks = []
        stack = [(self.root_path, None)]
        while stack:
            path, parent = stack[-1]
            if parent:
                children = [os.path.join(parent, name) for name in os.listdir(parent) if not name.startswith('.')]
            else:
                children = [file for file in dfs.list(self.root_path) if not file.is_directory()]

            for child in children:
                full_child = os.path.join(path, child)
                stack.append((full_child, path))
                if os.path.isfile(os.path.abspath(full_child)):
                    tasks.append(self.queue.put(full_child))

        await asyncio.gather(*tasks)

        for worker in self.workers:
            worker.join()

        return self.results

class Worker(threading.Thread):
    def __init__(self, queue, results):
        super().__init__()
        self.queue = queue
        self.results = results

    def run(self):
        while True:
            path = self.queue.get()
            if not path:
                break

            try:
                data = DynamicDfs._run_worker(path)
                gc.collect()
            except Exception as e:
                self.log.error(f'Error processing {path}: {e}', exc_info=True)

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rx_ue_information_tag, rnti, crc_indication_rel8_tag):
        self.rx_ue_information_tag = rx_ue_information_tag
        self.rnti = rnti
        self.crc_indication_rel8_tag = crc_indication_rel8_tag

    def set_crcflag(self, probability):
        if random.uniform(0, 1) < probability:
            self.crc_indication_rel8_tag.crcflag = True

class TaskRunner:
    def __init__(self, max_workers=psutil.cpu_count(), **kwargs):
        self.max_workers = max_workers
        self._tasks = []

    async def add_task(self, task, *args, **kwargs):
        self._tasks.append((task, args, kwargs))

    async def run(self):
        tasks = self._tasks[:]
        results = []

        for worker in range(self.max_workers):
            worker_results = []
            asyncio.create_task(self._worker(worker, worker_results))

        while tasks:
            task, args, kwargs = tasks.pop(0)
            results.append(await self._run_single_task(task, *args, **kwargs))

            for worker in range(self.max_workers):
                if len(tasks) > 0 and not worker_results:
                    tasks.append((task, args, kwargs))
                    break
                elif worker_results:
                    task, args, kwargs = worker_results.pop(0)
            if len(tasks) == 0 and all([len(res) == 0 for res in results]):
                break

        return results

    async def _worker(self, worker_id, results):
        while True:
            task, args, kwargs = await self.queue.get()
            if not task:
                break

            try:
                result = await self._run_single_task(task, *args, **kwargs)
                results.append((task, result))
            except Exception as e:
                self.log.error(f'Error running task {task}: {e}', exc_info=True)

    async def _run_single_task(self, task, *args, **kwargs):
        start = time.time()
        result = task(*args, **kwargs)
        end = time.time()

        log_entry = {'start': start, 'end': end}
        if kwargs:
            for k, v in kwargs.items():
                log_entry[k] = v

        self.log.info(f'Task {task.__name__}: {log_entry}', extra={'task': task})

        return result

@NFAPI.register_pdus(PDU_TYPES.CRCINDIC)
def create_crcindic_pdu(rx_ue_information_tag, rnti, crc_indication_rel8_tag, probability=0.5):
    pdu = NFAPI_CRC_INDICATION_PDU_T(rx_ue_information_tag, rnti, crc_indication_rel8_tag)
    pdu.set_crcflag(probability)
    return pdu

if __name__ == '__main__':
    import random

    dfs = DynamicDfs('path/to/distributed/filesystem', max_workers=2)
    nfapi_pdu_factory = create_crcindic_pdu
    probability = 0.1
    max_entries = 50000

    task_runner = TaskRunner(max_workers=dfs.max_workers)

    for entry in range(max_entries):
        rx_ue_information_tag, rnti, crc_indication_rel8_tag = entry % 16, entry // 16, None
        task_runner.add_task(nfapi_pdu_factory, rx_ue_information_tag, rnti, crc_indication_rel8_tag, probability)

    pdus = await task_runner.run()

    for pdu in pdus:
        print(pdu)
