import logging
from functools import lru_cache
from threading import Lock
from queue import LifoQueue

class ConfigManager:
    def __init__(self, config_path):
        self.config_path = config_path
        self.cache = {}
        self.lock = Lock()
        self.queue = LifoQueue()

    @lru_cache(maxsize=128)
    def _parse_file(self, format):
        with open(self.config_path, 'r') as file:
            if format == 'json':
                return json.load(file)
            elif format == 'yaml':
                return yaml.safe_load(file)
            elif format == 'ini':
                cfg = configparser.ConfigParser()
                cfg.read_file(file)
                return dict(cfg.items('DEFAULT'))

    def get_config(self, format=None):
        if format not in ['json', 'yaml', 'ini']:
            logging.warning(f"Unsupported config file format: {format}")
            self._load_default()
            return self.cache

        try:
            self.cache = self._parse_file(format)
        except Exception as e:
            logging.error(f"Error parsing config file: {e}")
            self._load_default()

        return self.cache

    def _load_default(self):
        default_config = {}  # Add your default configuration here
        self.cache = default_config

    def update(self, new_config, format=None):
        with self.lock:
            if format not in ['json', 'yaml', 'ini']:
                logging.warning(f"Unsupported config file format: {format}")
                return

            try:
                updated_config = self._parse_file(format, new_config)
                self.cache.update(updated_config)
                self.queue.put((format, updated_config))
            except Exception as e:
                logging.error(f"Error updating config file: {e}")

    def poll(self):
        if not self.queue.empty():
            format, updated_config = self.queue.get()
            self.cache = updated_config

class Application:
