    app1 = Application('App1', ['key1', 'key2'])
    app2 = Application('App2', ['key3', 'key4'])

    while True:
        config = config_manager.get_config()
        config_manager.poll()

        if all(key in config for key in app1.required_config_keys):
            app1.run(**config)

        if all(key in config for key in app2.required_config_keys):
            app2.run(**config)

