#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <time.h>

typedef struct Log {
    char ip[INET6_ADDRSTRLEN];
    char method[10];
    char uri[256];
    char version[10];
    int status;
    time_t timestamp;
} Log;

struct LogManager {
    size_t capacity;
    size_t count;
    size_t max_age; // in seconds
    size_t max_size; // number of logs to keep
    Log* data;
    pthread_mutex_t lock;
    condition_t not_full, not_empty;
};

struct LogManager* create_log_manager(size_t initial_capacity, size_t max_age, size_t max_size) {
    struct LogManager* manager = malloc(sizeof(struct LogManager));
    if (!manager) return NULL;

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->max_age = max_age;
    manager->max_size = max_size;
    manager->data = malloc(initial_capacity * sizeof(Log));
    if (!manager->data) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->not_full, NULL);
    pthread_cond_init(&manager->not_empty, NULL);

    return manager;
}

void destroy_log_manager(struct LogManager* manager) {
    if (manager) {
        free(manager->data);
        pthread_mutex_destroy(&manager->lock);
        pthread_cond_destroy(&manager->not_full);
        pthread_cond_destroy(&manager->not_empty);
        free(manager);
    }
}

// Add a new log entry, handle edge cases and return 0 if successful or error code otherwise
int add_log(struct LogManager* manager, const char* ip, const char* method, const char* uri, const char* version, int status, time_t timestamp) {
    // Validation for IP address, etc. can be done here
    if (strlen(ip) > INET6_ADDRSTRLEN || strlen(method) >= 10 || strlen(uri) >= 256) return -1;

    pthread_mutex_lock(&manager->lock);

    // Check for capacity and purge old logs as needed
    if (manager->count == manager->capacity && manager->count > manager->max_size) {
        size_t to_remove = manager->count - manager->max_size;
        if (to_remove >= manager->capacity / 2) {
            // Purge a large number of logs and resize the array
            manager->capacity *= 2;
            Log* new_data = realloc(manager->data, manager->capacity * sizeof(Log));
            if (!new_data) {
                pthread_mutex_unlock(&manager->lock);
                return -1;
            }
            manager->data = new_data;
        }

        for (size_t i = 0; i < to_remove; ++i) {
            free( &(manager->data[i]) );
        }

        manager->count -= to_remove;
    }

    // Insert the new log into the array and signal if the manager is not empty
    memcpy(&(manager->data[manager->count]), &{Log}{ .ip = ip, .method = method, .uri = uri, .version = version, .status = status, .timestamp = timestamp }, sizeof(Log));
    ++manager->count;
    pthread_cond_signal(&manager->not_empty);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Update an existing log entry based on IP address, handle edge cases and return 0 if successful or error code otherwise
int update_log(struct LogManager* manager, const char* ip, const char* method, const char* uri, const char* version, int status, time_t timestamp) {
    // Find the log with the given IP address
    size_t i;
    for (i = 0; i < manager->count; ++i) {
        if (!strcmp(manager->data[i].ip, ip)) break;
    }

    if (i == manager->count) return -1; // Not found

    // Update the log and signal if the manager is not full
    manager->data[i].method = method;
    strcpy(manager->data[i].uri, uri);
    strcpy(manager->data[i].version, version);
    manager->data[i].status = status;
    manager->data[i].timestamp = timestamp;

    pthread_mutex_lock(&manager->lock);
    pthread_cond_signal(&manager->not_full);
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

// Search for logs based on various criteria, handle edge cases and return a pointer to the first matching log or NULL if no matches found
Log* search_logs(struct LogManager* manager, const char* client_ip, const char* request_method, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&manager->lock);

    // Iterate through the logs and apply filters as needed
    for (size_t i = 0; i < manager->count; ++i) {
        if (!strcmp(client_ip, manager->data[i].ip)) {
            if ((start_time == 0 || start_time <= manager->data[i].timestamp) &&
                (end_time == 0 || end_time > manager->data[i].timestamp)) {
                    pthread_mutex_unlock(&manager->lock);
                    return &(manager->data[i]);
                }
            }
        }

        pthread_mutex_unlock(&manager->lock);
        return NULL;
}

// Manually trigger garbage collection to immediately free up resources if needed
void garbage_collect(struct LogManager* manager) {
    if (manager->count > manager->max_size) {
        size_t to_remove = manager->count - manager->max_size;
        pthread_mutex_lock(&manager->lock);

        for (size_t i = 0; i < to_remove; ++i) {
            free( &(manager->data[i]) );
        }

        manager->count -= to_remove;
        pthread_cond_signal(&manager->not_full);
        pthread_mutex_unlock(&manager->lock);
    }
}
```

