// Define the log structure
typedef struct Log {
    char ip[INET6_ADDRSTRLEN];
    char method[16];
    char uri[256];
    char http_version[16];
    int status_code;
    time_t timestamp;
} Log;

// Define a thread-safe linked list for the logs
typedef struct Node {
    Log log;
    struct Node *next;
    pthread_mutex_t lock;
} Node;

// Global variables to manage retention and storage limit
const time_t RETENTION = 86400; // 1 day in seconds
size_t STORAGE_LIMIT = 1000000; // Maximum number of logs allowed
size_t current_size = 0;

Node *head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a log to the list
void add_log(Log log) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    memcpy(&new_node->log, &log, sizeof(Log));
    pthread_mutex_init(&new_node->lock, NULL);
    new_node->next = head;
    head = new_node;

    current_size++;
    purge_old_logs();
}

// Function to update an existing log based on client IP
void update_log(const char *ip, Log new_log) {
    Node *current = head;
    Node *prev = NULL;

    pthread_mutex_lock(&list_lock);

    while (current != NULL && strcmp(current->log.ip, ip)) {
        prev = current;
        current = current->next;
    }

    if (current != NULL) {
        memcpy(&current->log, &new_log, sizeof(Log));
        pthread_mutex_unlock(&list_lock);
    } else {
        pthread_mutex_unlock(&list_lock);
    }
}

// Function to search for logs based on various criteria (not implemented here)
Node* find_logs(/* criteria */);

// Function to purge old logs older than the retention period and ensure storage limit is not exceeded
void purge_old_logs() {
    time_t now = time(NULL);
    size_t count = 0;

    Node *current = head;
    Node *temp;

    pthread_mutex_lock(&list_lock);

    while (current != NULL) {
        if ((now - current->log.timestamp) > RETENTION) {
            temp = current;
            current = current->next;

            free(temp);
            count++;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list_lock);

    if (current_size - count > STORAGE_LIMIT)
        purge_old_logs(); // Recursively call to keep purging logs until the limit is reached
}

// Garbage collection function to free up resources immediately
void gc() {
    Node *current = head;
    Node *temp;

    pthread_mutex_lock(&list_lock);

    while (current != NULL) {
        temp = current;
        current = current->next;

        free(temp);
    }

    head = NULL;
    current_size = 0;
    pthread_mutex_unlock(&list_lock);
}
```

