    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->size = 0;
    list->capacity = capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

Node* create_node() {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;

    node->data.RNTI = (uint32_t)(rand() % RNTI_MAX);
    node->data.RX_UE_INFORMATION_TAG = (uint8_t)(rand() % MAX_TAG);
    node->data.CRCFLAG = rand() & 1;
    node->prev = node->next = NULL;

    return node;
}

void insert(DList* list, Node* node) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity && !--list->integrity_checks) {
        list_cleanup(list);
    }

    if (!list->head) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }

    ++list->size;
    pthread_mutex_unlock(&list->lock);
}

void list_cleanup(DList* list) {
    if (list->size == 0) return;

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = list->tail = NULL;
    list->size = 0;
}

void stats_dump(DList* list) {
    printf("Successful inserts: %llu\n", list->successful_inserts);
    printf("Failed allocations: %llu\n", list->failed_allocations);
    printf("Integrity checks: %llu\n", list->integrity_checks);
}
