    for (int i = 0; i < buffer_size && log_entries[i]; ++i) {
        if (log_entries[i]->severity >= log_level_indicator) {
            LOG_MESSAGE_T* log_message = malloc(sizeof(LOG_MESSAGE_T));
            if (!log_message) {
                for (int j = message_count - 1; j >= 0; --j) {
                    free(log_messages[j]);
                }
                free(log_entries);
                custom_mempool_free(log_buffer, mempool);
                custom_mempool_destroy(mempool);
                return NULL;
            }

            log_message->level = log_entries[i]->severity;
            log_message->message_id = i;
            memset(log_message->log_flag, '\0', MAX_LOG_FLAG_LENGTH);

            if (enable_logging && log_message->level >= LOG_LEVEL_DEBUG) {
                printf("[%d] Log message created for level %u\n", i, log_message->level);
            }

            log_messages[message_count++] = log_message;
        }
    }

    free(log_entries);

    int buffer_position = 0;
    for (int i = 0; i < message_count && buffer_position + strlen(log_messages[i]->log_flag) + 1 <= buffer_size; ++i) {
        snprintf(log_buffer + buffer_position, buffer_size - buffer_position, "[%llu] [%u] %s\n", log_entries[log_messages[i]->message_id]->timestamp, log_messages[i]->level, log_messages[i]->log_flag);
        buffer_position += strlen(log_buffer + buffer_position) + 1;
    }

    if (truncate && buffer_position > buffer_size) {
        log_buffer[buffer_size - 1] = '\0';
    } else if (!truncate && buffer_position >= buffer_size) {
        custom_mempool_free(log_buffer, mempool);
        for (int i = 0; i < message_count; ++i) {
            free(log_messages[i]);
        }
        free(log_messages);
        custom_mempool_destroy(mempool);
        return NULL;
    }

    // SHA-256 hashing and appending to the log buffer
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, log_buffer, buffer_position);
    unsigned char sha256[SHA256_DIGEST_LENGTH];
    SHA256_Final(sha256, &ctx);
    snprintf(log_buffer + buffer_position, buffer_size - buffer_position, "%s\n", base64_encode(sha256));

    if (enable_logging && log_message->level >= LOG_LEVEL_DEBUG) {
        printf("[%d] Log buffer prepared with SHA-256: %s\n", i, base64_encode(sha256));
    }

    return realloc(log_buffer, buffer_position + 1);
}
