#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <arpa/inet.h>

typedef struct NetworkFlowStats {
    sockaddr_in addr;
    uint32_t packet_count;
    uint64_t byte_count;
    uint16_t protocol_type;
} NetworkFlowStats;

struct network_flow_stats_manager {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    NetworkFlowStats* data;
};

NetworkFlowStatsManager* create_network_flow_stats_manager(size_t capacity) {
    NetworkFlowStatsManager* manager = malloc(sizeof(NetworkFlowStatsManager));
    manager->lock = PTHREAD_MUTEX_INITIALIZER;
    manager->capacity = capacity;
    manager->size = 0;
    manager->data = calloc(manager->capacity, sizeof(NetworkFlowStats));
    return manager;
}

void destroy_network_flow_stats_manager(NetworkFlowStatsManager* manager) {
    free(manager->data);
    free(manager);
}

size_t find_free_index(const NetworkFlowStatsManager* manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (!manager->data[i].addr.sin_port || !manager->data[i].addr.sin_addr.s_addr) {
            return i;
        }
    }
    return manager->size;
}

void add_network_flow_stat(NetworkFlowStatsManager* manager, const sockaddr* addr) {
    pthread_mutex_lock(&manager->lock);
    size_t index = find_free_index(manager);
    if (index >= manager->size) {
        if (manager->size == manager->capacity) {
            NetworkFlowStats* new_data = realloc(manager->data, sizeof(NetworkFlowStats) * manager->capacity * 2);
            manager->capacity *= 2;
            manager->data = new_data;
        }
    }
    inet_pton(AF_INET, inet_ntoa(((sockaddr_in*)addr)->sin_addr), &manager->data[index].addr.sin_addr);
    manager->data[index].addr.sin_port = ((sockaddr_in*)addr)->sin_port;
    manager->data[index].packet_count = 1;
    manager->data[index].byte_count = 0;
    manager->data[index].protocol_type = (((sockaddr_in*)addr)->sin_protocol) & 0xFF;
    manager->size++;
    pthread_mutex_unlock(&manager->lock);
}

void update_network_flow_stat(NetworkFlowStatsManager* manager, const sockaddr* addr, uint32_t packet_count, uint64_t byte_count) {
    pthread_mutex_lock(&manager->lock);
    size_t index = find_index(manager, addr);
    if (index != NUM_ELEMENTS(manager->data)) {
        manager->data[index].packet_count += packet_count;
        manager->data[index].byte_count += byte_count;
    }
    pthread_mutex_unlock(&manager->lock);
}

uint64_t total_traffic(const NetworkFlowStatsManager* manager) {
    uint64_t total = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        total += manager->data[i].byte_count;
    }
    pthread_mutex_unlock(&manager->lock);
    return total;
}
```

