};

class CryptoLibrary {
public:
    // Initialize OpenSSL and register cryptographic primitives
    static void init(const Config& config);

    // Multi-threaded function to perform encryption/decryption or digest calculation
    static EVP_CIPHER_CTX* encryptDecrypt(EVP_CIPHER_ctx_st* cipher, const uint8_t* in, size_t length, uint8_t* out);
