    static std::vector<const EVP_CIPHER*>& getCipherAlgorithms();
};

// Implement the initialization function
void CryptoLibrary::init(const Config& config) {
    // Register AES, Camellia, MD5, SHA, and RSA with SHA1 cryptographic primitives
    for (auto cipher : getCipherAlgorithms()) {
        if (!config.aes && strcmp("AES", cipher->type) == 0 ||
            !config.camellia && strcmp("CAMELLIA", cipher->type) == 0)
            continue;
        EVP_add_cipher(cipher);
    }

    for (auto digest : getDigestAlgorithms()) {
        if (!config.md5 && strcmp("md5", digest->type) == 0 ||
            !config.sha && strcmp("sha1", digest->type) == 0)
            continue;
        EVP_add_digest(digest);
    }

    // Register RSA with SHA1 alias if required
    if (config.rsa_sha1) {
        EVP_MD_CTX* ctx = EVP_MD_CTX_create();
        EVP_DigestInit_ex(ctx, EVP_sha1(), nullptr);
        EVP_add_digest_alias("RSA_SHA1", ctx, 0);
    }

    // Error handling and resource management
    ERR_load_crypto_strings();
    OpenSSL_add_all_algorithms((config.rsa_sha1 ? ALL : NID_ssl3_methods));
}

