    if (!email || strlen(email) > 255) return -1; // Check for empty or excessively long emails

    sscanf(email, "%[^@]@%15s", local, domain);
    len = strlen(local);
    if (len >= 64 || strlen(domain) > 10) return -2; // Check for malformatted email addresses

    iconv_t icd = iconv_open("US-ASCII", NULL);
    char input[256];
    strncpy(input, domain, sizeof(input));
    size_t cdlen = iconv(icd, &pw, &ps, &input, sizeof(input));
    iconv_close(icd, &icd);

    if (cdlen > 10) return -3; // Handle errors related to internationalized domain names

    sprintf(domain, "%.*s", 10, input);
    time_t timestamp = time(NULL);
    struct tm *tm = localtime(&timestamp);
    char timestamp_str[19];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y%m%d%H%M%S", tm);

    email[0] = (local[0] < 'a' || local[0] > 'z') ? local[0] + 32 : local[0]; // Ensure the first letter is lowercase
    sprintf(email + 1, "%.*s%s", len + strlen(domain) + strlen(timestamp_str), domain, timestamp_str);

    return 0;
}

