static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static char *library_path;
static EVP_LIBRARY library;

void log(const char *message) {
    fprintf(stderr, "[%s] %s\n", __TIME__, message);
}

void load_primitive(const char *name) {
    void *handle = dlopen(library_path, RTLD_LAZY);
    if (!handle) {
        log("Failed to open library");
        return;
    }

    const char *symbol = (char *)dlsym(handle, name);
    if (!symbol) {
        log("Failed to load symbol");
        dlclose(handle);
        return;
    }

    typedef int (*load_func)(EVP_LIBRARY, const char *, EVP_ID *);
    load_func load = (load_func)dlsym(handle, "EVP_add_cipher"); // Replace with the correct symbol name for other primitives

    EVP_ID id;
    if (!load(library, symbol, &id)) {
        log("Failed to add primitive");
        dlclose(handle);
        return;
    }

    log(symbol);
}

void initialize_library() {
    time_t grace_period = 3600; // Grace period in seconds
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += grace_period;

    library_path = getenv("CRYPTO_LIBRARY_PATH");
    if (!library_path) {
        log("Environment variable CRYPTO_LIBRARY_PATH not set.");
        return;
    }

    pthread_mutex_lock(&mutex);
    EVP_cleanup(); // Ensure a clean start
    pthread_mutex_unlock(&mutex);

    char *primitive_names[] = {
        "EVP_aes_128_cbc",   // AES-128-CBC
        "EVP_camellia_192_cbc",  // Camellia-192-CBC
        "EVP_md5",           // MD5 digest
        "EVP_sha1",          // SHA-1 digest
        "EVP_sha256",        // SHA-256 digest
        "EVP_RSA_sign_SHA1"  // RSA with SHA-1 signature
    };

    for (size_t i = 0; i < sizeof(primitive_names) / sizeof(char *); ++i) {
        load_primitive(primitive_names[i]);
        // Grace period check and deactivation of weak algorithms goes here.
    }
}

void register_library() {
    library = EVP_get_dynamic();
}
