#define NUM_ELEMENTS 10000

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

bool validate_tag(uint32_t tag) {
    return (tag >= 1 && tag <= 0xFFFFFFFD);
}

bool validate_rnti(uint64_t rnti) {
    return (rnti >= 1 && rnti <= UINT64_MAX - 1);
}

void* create_crcflag(void *arg) {
    uint64_t *rnti = (uint64_t *) arg;
    uint32_t tag = (rand() % 0xFFFFFFFD) + 1;
    return ((*rnti << 5) ^ tag);
}

void populate_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size) {
    *list = malloc(*size * sizeof(**list));
    if (*list == NULL) {
        perror("Error: Memory allocation failed.");
        exit(1);
    }

    pthread_t threads[NUM_ELEMENTS];
    uint64_t rntis[NUM_ELEMENTS];

    for (size_t i = 0; i < NUM_ELEMENTS; ++i) {
        rntis[i] = (uint64_t)(rand() + 1);
    }

    for (size_t i = 0; i < NUM_ELEMENTS; ++i) {
        if (!validate_tag((*list)[i].RX_UE_INFORMATION_TAG) || !validate_rnti(rntis[i])) {
            fprintf(stderr, "Error: Invalid RX_UE_INFORMATION_TAG or RNTI.\n");
            exit(1);
        }

        (*list)[i].RX_UE_INFORMATION_TAG = i;
        (*list)[i].RNTI = rntis[i];

        pthread_create(&threads[i], NULL, create_crcflag, &rntis[i]);
        pthread_join(threads[i], (void *)&(*list)[i].CRC_INDICATION_REL8_TAG);
