} TransactionRecord;

struct TransactionList {
    size_t length;
    size_t capacity;
    TransactionRecord* transactions;
    pthread_mutex_t mutex;
};

TransactionList* create_transaction_list() {
    TransactionList* list = malloc(sizeof(TransactionList));
    if (!list) {
        perror("Failed to allocate memory for transaction list");
        return NULL;
    }
    list->length = 0;
    list->capacity = 4;
    list->transactions = malloc(list->capacity * sizeof(TransactionRecord));
    if (!list->transactions) {
        perror("Failed to allocate memory for transaction records");
        free(list);
        return NULL;
    }
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
    return list;
}

void resize_transaction_list(TransactionList* list) {
    TransactionRecord* new_transactions = realloc(list->transactions, (list->capacity * 2) * sizeof(TransactionRecord));
    if (!new_transactions) {
        perror("Failed to reallocate memory for transaction records");
        return;
    }
    list->transactions = new_transactions;
    list->capacity *= 2;
}

long generate_transaction_id(TransactionRecord* record) {
    long transaction_id = record->account_number ^ ((long)record->transaction_amount * time((time_t*)NULL));
    while (search_transaction_by_id(list, transaction_id)) {
        transaction_id++;
    }
    return transaction_id;
}

int is_valid_amount(double amount) {
    // Implement your bank's validating logic here
    return amount > 0 && amount <= 100000.0;
}

void add_transaction(TransactionList* list, TransactionRecord* record) {
    pthread_mutex_lock(&list->mutex);
    if (list->length == list->capacity) {
        resize_transaction_list(list);
    }

    record->transaction_id = generate_transaction_id(record);
    memcpy(&list->transactions[list->length], record, sizeof(TransactionRecord));
    list->length++;
    pthread_mutex_unlock(&list->mutex);
}

int search_transaction_by_id(TransactionList* list, long id) {
    for (size_t i = 0; i < list->length; ++i) {
        if (list->transactions[i].transaction_id == id) {
            return 1;
        }
    }
    return 0;
}

void serialize_transaction_list(TransactionList* list, FILE* csv_file) {
    pthread_mutex_lock(&list->mutex);
    fprintf(csv_file, "Transaction ID,Account Number,Transaction Amount,Timestamp\n");
    for (size_t i = 0; i < list->length; ++i) {
        struct tm* timeinfo = localtime(&list->transactions[i].timestamp);
        char time_str[26];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(csv_file, "%ld,\"%ld\",%.2f,\"%s\"\n", list->transactions[i].transaction_id,
                list->transactions[i].account_number, list->transactions[i].transaction_amount,
                time_str);
    }
    pthread_mutex_unlock(&list->mutex);
}

void destroy_transaction_list(TransactionList* list) {
    if (!list) return;
    free(list->transactions);
    free(list);
}
