static void* custom_malloc(size_t size) {
    static size_t total_allocated = 0;
    static char *heap = NULL;

    if (!heap) {
        int fd = open("/dev/zero", O_RDWR);
        mmap(&heap, sysconf(_SC_PAGE_SIZE), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, fd, 0);
        close(fd);
    }

    if (size + total_allocated > sysconf(_SC_PAGE_SIZE)) {
        madvise(heap + total_allocated, size, MADV_DONTNEED);
        total_allocated -= (char*)heap - heap;
        heap = custom_malloc(sysconf(_SC_PAGE_SIZE));
    }

    char *ptr = heap + total_allocated;
    total_allocated += size;
    return ptr;
}

static void custom_free(void* ptr) {
    total_allocated -= (char*)ptr - (char*)heap;
}

static long find_next_offset(long *array, size_t len, long start, size_t max) {
    if (len <= max) return start + 1;

    int i = start + 1;
    while (i < len && array[i] == start) ++i;
    return i;
}

