// Custom hash function for the hash table
unsigned long long hash(char *key) {
    unsigned long long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % HASH_TABLE_SIZE;
}

// Allocate memory for an array of float values with a size determined by a user-provided max_values parameter, ensuring the total memory usage does not exceed 5 MB.
