void populate_hash_table(FILE *file) {
    char key[64], value[32];
    float *value_ptr;
    size_t i;

    while (fscanf(file, "%s %s\n", key, value) == 2) {
        // Allocate memory for the value and update its timestamp
        if (!(value_ptr = malloc(sizeof(float)))) break;
        scanf("%f", value_ptr);

        // Hash the key and insert the entry into the hash table
        cache_entry *entry = &hash_table[hash(key)];
        for (i = 0; i < HASH_TABLE_SIZE && entry->value != NULL; ++i, ++entry);
        strcpy(entry->key, key);
        entry->value = value_ptr;
        entry->timestamp = time(NULL);
    }
}

// Function to retrieve a float value associated with a given key from the hash table, updating the timestamp of the accessed entry to ensure cache locality.
float get_hash_table_value(char *key) {
    unsigned long long hash_index = hash(key);
    size_t i;
    cache_entry *entry;

    for (i = 0, entry = &hash_table[hash_index]; i < HASH_TABLE_SIZE && entry->value != NULL; ++i, ++entry) {
        if (!strncmp(entry->key, key, sizeof(entry->key))) {
            // Update the timestamp of the accessed entry
            entry->timestamp = time(NULL);
            return *entry->value;
        }
    }

    return 0.0f;
}

// After initializing the data structures, implement a mechanism to periodically clean up least recently used entries from the hash table to maintain performance and avoid memory leaks.
void cleanup_hash_table() {
    size_t i, j, smallest_index = HASH_TABLE_SIZE;
    cache_entry *entries[HASH_TABLE_SIZE], *temp_entry;

    for (i = 0; i < HASH_TABLE_SIZE; ++i)
        if (hash_table[i].value != NULL && hash_table[i].timestamp < smallest_index) {
            smallest_index = hash_table[i].timestamp;
            entries[0] = &hash_table[i];
        }

    for (i = 1; i < HASH_TABLE_SIZE; ++i)
        if (hash_table[entries[i - 1]->timestamp].value != NULL &&
            hash_table[entries[i - 1]->timestamp].timestamp < smallest_index)
            entries[i] = &hash_table[entries[i - 1]->timestamp];

    for (i = HASH_TABLE_SIZE; i--; ) {
        temp_entry = entries[i];
        if (temp_entry->value != NULL) {
            free(temp_entry->value);
            temp_entry->value = NULL;
        }
    }
}
