    int key;
    long offset;
} tile;

void* allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void **ptr) {
    free(*ptr);
    *ptr = NULL;
}

size_t custom_hash(char* key, size_t table_size) {
    size_t hash = 0;
    for (int i = 0; key[i]; ++i) {
        hash = (hash * 31 + key[i]) % table_size;
    }
    return hash;
}

void populate_hash_table(char* filename, size_t table_size, cache_entry** entries, size_t* num_entries) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file %s\n", filename);
        exit(EXIT_FAILURE);
    }

    char line[1024];
    size_t num_lines = 0;
    while (fgets(line, sizeof(line), file)) {
        ++num_lines;
    }

    rewind(file);
    cache_entry *table = allocate_memory(sizeof(cache_entry) * table_size);
    *num_entries = 0;

    while (fgets(line, sizeof(line), file)) {
        char* key = strtok(line, " \t\n");
        float value = atof(strtok(NULL, "\n"));
        size_t hash = custom_hash(key, table_size);
        cache_entry *entry = &table[hash];

        // Hash table is full or entry already exists
        if (*num_entries == table_size || entry->key) {
            continue;
        }

        entry->key = strdup(key);
        entry->value = allocate_memory(sizeof(float));
        *entry->value = value;
        entry->timestamp = time(NULL);
        ++(*num_entries);
    }

    free_memory((void**)&table);
}

