#define MAX_OFFSETS 1024 * 1024 / sizeof(long) // Max offsets to fit 10MB
#define MAX_RECORDS (100000 < MAX_OFFSETS ? 100000 : MAX_OFFSETS)
#define HASH_TABLE_SIZE 31

typedef struct {
    int value;
    long offset;
    time_t timestamp;
} record;

// Offset cache (LRU eviction policy)
struct offcache {
    long *data;
    size_t len, cap, head, tail;
};

void init_offcache(struct offcache *oc) {
    oc->len = 0;
    oc->cap = MAX_OFFSETS;
    oc->head = oc->tail = 0;
    oc->data = malloc(sizeof(long) * oc->cap);
}

void grow_offcache(struct offcache *oc) {
    if (++oc->len >= oc->cap) {
        oc->cap *= 2;
        oc->data = realloc(oc->data, sizeof(long) * oc->cap);
    }
}

void push_offcache(struct offcache *oc, long data) {
    if (oc->len == oc->cap) grow_offcache(oc);
    if (oc->head == oc->tail) oc->tail = (oc->tail + 1) % oc->cap;
    memmove(oc->data + oc->head, oc->data + oc->tail, sizeof(long) * ((oc->cap - oc->tail) % oc->cap));
    oc->data[oc->head] = data;
    oc->head = (oc->head + 1) % oc->cap;
    oc->len++;
}

long pop_offcache(struct offcache *oc) {
    if (!oc->len) return -1;
    long ret = oc->data[oc->tail];
    oc->len--;
    if (++oc->tail >= oc->cap) oc->tail = 0;
    return ret;
}

// Hash table using open addressing with linear probing
struct hashtable {
    size_t len, cap;
    int *data;
    record **records;
};

void init_hashtable(struct hashtable *ht) {
    ht->len = 0;
    ht->cap = HASH_TABLE_SIZE;
    ht->data = malloc(sizeof(int) * ht->cap);
    memset(ht->data, -1, sizeof(int) * ht->cap);
    ht->records = calloc(ht->cap, sizeof(record*));
}

void resize_hashtable(struct hashtable *ht) {
    int *newdata = malloc(sizeof(int) * (ht->cap *= 2));
    memcpy(newdata, ht->data, sizeof(int) * ht->cap);
    free(ht->data);
    ht->data = newdata;
}

size_t hash(int key) {
    return key % HASH_TABLE_SIZE;
}

void insert_hashtable(struct hashtable *ht, int key, record *rec) {
    size_t idx = hash(key);
    size_t i = idx;
    for (; ht->data[i] != -1; i = (i + 1) % ht->cap) {
        if (ht->records[i]->offset == rec->offset) return; // Avoid duplicates
        if (!ht->records[i]) {
            ht->records[i] = rec;
            ht->len++;
            return;
        }
    }

    if (ht->len >= ht->cap * 0.75) resize_hashtable(ht);
    ht->records[i] = rec;
    ht->data[i] = key;
    ht->len++;
}

record* find_hashtable(struct hashtable *ht, int key) {
    size_t idx = hash(key);
    size_t i = idx;
    for (; ht->data[i] != key && ht->data[i] != -1; i = (i + 1) % ht->cap) {
        if (!ht->records[i]) continue;
        if (ht->records[i]->offset == -1) continue; // Ignore expired records
        return ht->records[i];
    }

    return NULL;
}

