class MemoryBlock {
public:
    void* data;
    size_t size;
    sem_t lock;

    MemoryBlock(size_t _size) : size(_size), data(nullptr), lock(Sem_INITIALIZE_NP) {}

    bool allocate(void** ptr) {
        *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (*ptr == MAP_FAILED) {
            cerr << "Memory allocation failed. Size: " << size << endl;
            return false;
        }
        data = *ptr;
        return true;
    }

    void release() {
        munmap(data, size);
    }

    void lock() const {
        sem_wait(&lock);
    }

    void unlock() const {
        sem_post(&lock);
    }
};

