typedef struct {
    uint8_t priority;
    int qos_params[4]; // QoS parameters array
    struct in6_addr ipv6_address;
    time_t creation_time;
    time_t last_access_time;
} SM_CM_Context;

typedef struct SM_CM_Pool {
    SM_CM_Context* contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond_not_full, cond_not_empty;
} SM_CM_Pool;

SM_CM_Pool* sm_cm_pool_create(size_t max_contexts) {
    SM_CM_Pool* pool = malloc(sizeof(SM_CM_Pool));
    if (!pool) return NULL;

    pool->capacity = max_contexts;
    pool->count = 0;

    pool->contexts = calloc(max_contexts, sizeof(SM_CM_Context));
    if (!pool->contexts) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond_not_full, NULL);
    pthread_cond_init(&pool->cond_not_empty, NULL);

    return pool;
}

void sm_cm_pool_destroy(SM_CM_Pool* pool) {
    if (!pool) return;

    free(pool->contexts);
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond_not_full);
    pthread_cond_destroy(&pool->cond_not_empty);
    free(pool);
}

SM_CM_Context* sm_cm_pool_add(SM_CM_Pool* pool, const struct in6_addr ipv6_address, uint8_t priority, int qos_params[4]) {
    SM_CM_Context* context = NULL;

    pthread_mutex_lock(&pool->mutex);
    if (pool->count < pool->capacity) {
        context = &pool->contexts[pool->count];
        memcpy(context, calloc(1, sizeof(SM_CM_Context)), sizeof(SM_CM_Context));
        if (!context) {
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
        context->ipv6_address = ipv6_address;
        context->priority = priority;
        memcpy(context->qos_params, qos_params, sizeof(int) * 4);
        pool->count++;
    }
    pthread_mutex_unlock(&pool->mutex);

    return context;
}

void sm_cm_pool_remove(SM_CM_Pool* pool, SM_CM_Context* context) {
    pthread_mutex_lock(&pool->mutex);
    size_t index = (size_t)(context - pool->contexts);
    if (index < pool->count) {
        memmove(pool->contexts + index, pool->contexts + index + 1, (pool->count - index - 1) * sizeof(SM_CM_Context));
        pool->count--;
    }
    pthread_mutex_unlock(&pool->mutex);
}

SM_CM_Context* sm_cm_pool_find(const SM_CM_Pool* pool, const struct in6_addr ipv6_address) {
    for (size_t i = 0; i < pool->count; ++i) {
        if (!memcmp(&pool->contexts[i].ipv6_address, &ipv6_address, sizeof(struct in6_addr))) {
            return &pool->contexts[i];
        }
    }
    return NULL;
}

void sm_cm_pool_age_check(SM_CM_Pool* pool) {
    time_t now = time(NULL);
    for (size_t i = 0; i < pool->count; ++i) {
        if ((now - pool->contexts[i].last_access_time) > MAX_AGE) {
            SM_CM_Context* context = &pool->contexts[i];
            // log expiration event, update statistics, and free resources
        }
    }
}
