#include <pthread.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    NFAPI_UE_INFORMATION_TAG RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG *CRC_INDICATION_REL8_TAG;
    time_t creation_time;
    bool valid;
} NFAPI_CRC_INDICATION_PDU;

struct list_node {
    NFAPI_CRC_INDICATION_PDU *data;
    struct list_node *prev, *next;
};

struct list {
    struct list_node *head, *tail;
    int size;
    pthread_mutex_t mutex;
    int max_size;
    time_t age_threshold;
};

void list_init(struct list *list, int max_size, time_t age_threshold) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->max_size = max_size;
    list->age_threshold = age_threshold;
    pthread_mutex_init(&list->mutex, NULL);
}

void list_destroy(struct list *list) {
    struct list_node *current, *temp;
    pthread_mutex_lock(&list->mutex);
    current = list->head;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp->data);
        free(temp);
    }
    pthread_mutex_unlock(&list->mutex);
}

void list_insert(struct list *list, NFAPI_CRC_INDICATION_PDU *data) {
    struct list_node *new_node;

    if ((new_node = malloc(sizeof(struct list_node))) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);

    // Check integrity and update CRCFLAG if necessary
    validate(new_node->data);
}

void validate(NFAPI_CRC_INDICATION_PDU *data) {
    uint8_t expected[MD5_DIGEST_LENGTH];
    uint8_t received[MD5_DIGEST_LENGTH];

    // Generate expected hash
    stringToMD5WithAdvancedOptions(
        (char *) &data->RX_UE_INFORMATION_TAG,
        sizeof(NFAPI_UE_INFORMATION_TAG),
        true, // Trim if necessary
        false); // No logging
    md5_hash((const uint8_t *) expected, MD5_DIGEST_LENGTH, (uint8_t *) received);

    // Check received hash against expected hash
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        if (received[i] != expected[i]) {
            data->valid = false;
            break;
        }
    }
}

void clean_background(struct list *list) {
    struct list_node *current, *temp;
    time_t current_time = time(NULL);

    pthread_mutex_lock(&list->mutex);
    current = list->head;
    while (current != NULL) {
        if (!current->data->valid || current_time - current->data->creation_time > list->age_threshold) {
            temp = current;
            current = current->next;
            free(temp->data);
            free(temp);
            list->size--;
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void *cleanup_thread(void *arg) {
    struct list *list = arg;
    while (true) {
        clean_background(list);
        sleep(10); // Adjust sleep time as needed for desired clean-up frequency
    }
}

