    {
        _random = new Random();
        Floats = new List<(float, float)>();
        Ints = new List<(int, int)>();
        LoadConfig("config.json");
    }

    private void LoadConfig(string fileName)
    {
        try
        {
            using (StreamReader reader = new StreamReader(fileName))
            {
                string json = reader.ReadToEnd();
                _config = JObject.Parse(json);
            }
            ValidateConfiguration();
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error loading configuration file: {ex.Message}");
        }
    }

    private void ValidateConfiguration()
    {
        if (_config == null) throw new InvalidOperationException("Invalid configuration.");

        foreach (JProperty property in _config.Properties())
        {
            JToken token = property.Value;
            string name = property.Name;

            if (!(token is JObject)) continue;

            var configObj = token as JObject;

            switch (name)
            {
                case "Floats":
                    foreach (JProperty floatProp in configObj.Properties())
                        ValidateFloatConfig(floatProp);
                    break;
                case "Ints":
                    foreach (JProperty intProp in configObj.Properties())
                        ValidateIntConfig(intProp);
                    break;
            }
        }
    }

    private void ValidateFloatConfig(JProperty floatProp)
    {
        if (!floatProp.Value.TryGetValue("Min", out JToken minVal) || !floatProp.Value.TryGetValue("Max", out JToken maxVal))
            throw new InvalidOperationException($"Invalid configuration for Floats: missing 'Min' or 'Max' property.");

        if (!minVal.Type.Equals(JTokenType.Float) || !maxVal.Type.Equals(JTokenType.Float))
            throw new InvalidOperationException($"Invalid configuration for Floats: invalid types for 'Min' or 'Max' property.");
    }

    private void ValidateIntConfig(JProperty intProp)
    {
        if (!intProp.Value.TryGetValue("Min", out JToken minVal) || !intProp.Value.TryGetValue("Max", out JToken maxVal))
            throw new InvalidOperationException($"Invalid configuration for Ints: missing 'Min' or 'Max' property.");

        if (!minVal.Type.Equals(JTokenType.Integer) || !maxVal.Type.Equals(JTokenType.Integer))
            throw new InvalidOperationException($"Invalid configuration for Ints: invalid types for 'Min' or 'Max' property.");
    }

    private void AddRange(List<(float, float)> rangeList, JProperty configProp)
    {
        if (configProp.Value is not JArray array) throw new InvalidOperationException($"Invalid configuration: expected array for '{configProp.Name}'.");

        foreach (JToken token in array.Children())
        {
            if (!token.Type.Equals(JTokenType.Float)) continue;

            float value = (float)token;
            rangeList.Add((float.MinValue, value));
        }
    }

    private void AddRange(List<(int, int)> rangeList, JProperty configProp)
    {
        if (configProp.Value is not JArray array) throw new InvalidOperationException($"Invalid configuration: expected array for '{configProp.Name}'.");

        foreach (JToken token in array.Children())
        {
            if (!token.Type.Equals(JTokenType.Integer)) continue;

            int value = (int)token;
            rangeList.Add((int.MinValue, value));
        }
    }

    private float GenerateRandomFloat([IterParam(Name = "range")] (float min, float max) range, bool inclusive = true)
    {
        if (range.min == range.max) throw new InvalidOperationException("Invalid range: min and max values are the same.");

        double value;
        if (inclusive)
            value = _random.NextDouble() * (range.max - range.min) + range.min;
        else
            value = (_random.NextDouble() * (range.max - range.min)) + range.min;

        return (float)value;
    }

    private int GenerateRandomInt([IterParam(Name = "range")] (int min, int max) range, bool inclusive = true)
    {
        if (range.min == range.max) throw new InvalidOperationException("Invalid range: min and max values are the same.");

        int value;
        if (inclusive)
            value = _random.Next(range.min, range.max + 1);
        else
            value = _random.Next(Math.Max(range.min, 0), range.max);

        return value;
    }

    public float GenerateRandomFloatInclusive([IterParam(Name = "floatRange")] (float min, float max) floatRange) => GenerateRandomFloat(floatRange, true);
    public float GenerateRandomFloatExclusive([IterParam(Name = "floatRange")] (float min, float max) floatRange) => GenerateRandomFloat(floatRange, false);

    public int GenerateRandomIntInclusive([IterParam(Name = "intRange")] (int min, int max) intRange) => GenerateRandomInt(intRange, true);
    public int GenerateRandomIntExclusive([IterParam(Name = "intRange")] (int min, int max) intRange) => GenerateRandomInt(intRange, false);

    public void Reset()
    {
        lock (_lock)
        {
            _random.Next(); // advance the seed to a new value
            LoadConfig("config.json");
        }
    }

    public override string ToString() => $"{{Seed = {_random.Next()}, Floats = {{{String.Join(", ", Floats.Select(x => $"[{x.Min, 4}, {x.Max, 4}]"))}}, Ints = {{...}}}}";
}
```
