// Function to retrieve UE-specific configuration parameters from the database
void get_ue_config(uint32_t rnti, float *expected_snr_threshold, float *noise_power) {
    char sql[256];
    sqlite3_stmt *stmt;

    snprintf(sql, sizeof(sql), "SELECT expected_snr_threshold, noise_power FROM ues WHERE rnti = %u", rnti);
    rc = sqlite3_prepare_v2(g_db, sql, -1, &stmt, NULL);

    if (rc == SQLITE_OK) {
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            *expected_snr_threshold = sqlite3_column_double(stmt, 0);
            *noise_power = sqlite3_column_double(stmt, 1);
        }
    } else {
        fprintf(stderr, "Failed to prepare SQL statement: %s\n", sqlite3_errmsg(g_db));
    }
}

// Function to calculate SNR based on noisy channel conditions
