    long long total_bytes;
    long long packets;
} traffic_report;

void validate(const char* str, const char* message) {
    if (strlen(str) < 100) {
        log_error(message);
        exit(EXIT_FAILURE);
    }
}

traffic_report* network_traffic_monitor(const char** interface_names, const char* traffic_type, const char* report_mode) {
    validate(interface_names, "Invalid interface names");
    validate(traffic_type, "Invalid traffic type");

    traffic_report* report = malloc(sizeof(traffic_report));
    report->interfaces = NULL;
    report->num_interfaces = 0;
    report->capacity = 16;
    report->total_bytes = 0;
    report->packets = 0;
    pthread_mutex_init(&report->lock, NULL);

    network_interface** interfaces = calloc(report->capacity, sizeof(network_interface*));
    if (!interfaces) {
        log_error("Memory allocation failed");
        free(report);
        exit(EXIT_FAILURE);
    }
    report->interfaces = interfaces;

    for (size_t i = 0; i < report->capacity; ++i) {
        report->interfaces[i] = malloc(sizeof(network_interface));
        if (!report->interfaces[i]) {
            log_error("Memory allocation failed");
            free_traffic_report(report);
            exit(EXIT_FAILURE);
        }
    }

    size_t num_interfaces = 0;
    for (size_t i = 0, len = sizeof(interface_names)/sizeof(char*); i < len; ++i) {
        network_interface* interface = report->interfaces[num_interfaces];
        validate(interface_names[i], "Invalid interface name");
        interface->interface_name = strdup(interface_names[i]);
        if (!interface->interface_name) {
            log_error("Memory allocation failed");
            free_traffic_report(report);
            exit(EXIT_FAILURE);
        }
        interface->total_bytes = 0;
        interface->packets = 0;
        pthread_mutex_init(&interface->lock, NULL);

        if (!is_interface_available(interface->interface_name)) {
            log_error("Network interface not available");
            free_network_interface(interface);
            continue;
        }

        num_interfaces++;
        if (num_interfaces == report->capacity) {
            resize_traffic_report(report);
        }
    }
    report->num_interfaces = num_interfaces;

    for (size_t i = 0, len = sizeof(interface_names)/sizeof(char*); i < len; ++i) {
        if (!strcasecmp(traffic_type, interface_names[i])) {
            log_error("Duplicate traffic type provided");
            free_traffic_report(report);
            exit(EXIT_FAILURE);
        }
    }

    start_monitoring(report, report_mode);

    return report;
}

void resize_traffic_report(traffic_report* report) {
    network_interface** interfaces = realloc(report->interfaces, (report->capacity * 2) * sizeof(network_interface*));
    if (!interfaces) {
        log_error("Memory allocation failed");
        free_traffic_report(report);
        exit(EXIT_FAILURE);
    }
    report->interfaces = interfaces;
    report->capacity *= 2;
}

void free_network_interface(network_interface* interface) {
    free(interface->interface_name);
    pthread_mutex_destroy(&interface->lock);
    free(interface);
}

void free_traffic_report(traffic_report* report) {
    for (size_t i = 0; i < report->num_interfaces; ++i) {
        free_network_interface(report->interfaces[i]);
    }
    free(report->interfaces);
    pthread_mutex_destroy(&report->lock);
    free(report);
}

