#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

typedef struct DataTransferPacket {
    int session_id;
    int seq_num;
    size_t payload_len;
    void* payload;
} DataTransferPacket;

typedef struct Node {
    DataTransferPacket dt_packet;
    struct Node* next;
} Node;

Node** create_hashmap(int capacity) {
    Node **table = malloc(capacity * sizeof(Node*));
    for (int i = 0; i < capacity; ++i)
        table[i] = NULL;
    return table;
}

void insert(Node** table, DataTransferPacket dt_packet) {
    int hash = abs((uint32_t)&dt_packet.session_id % table[0]->next->session_id);
    Node *node = malloc(sizeof(Node));
    node->dt_packet = dt_packet;
    node->next = table[hash];
    table[hash] = node;
}

DataTransferPacket* find(Node** table, int session_id) {
    int hash = abs((uint32_t)&session_id % table[0]->next->session_id);
    Node *current = table[hash];
    while (current != NULL && current->dt_packet.session_id != session_id)
        current = current->next;
    return current == NULL ? NULL : &current->dt_packet;
}

void delete(Node** table, int session_id) {
    int hash = abs((uint32_t)&session_id % table[0]->next->session_id);
    Node **prev = table + hash;
    Node *current = table[hash];
    while (current != NULL && current->dt_packet.session_id != session_id) {
        prev = &current->next;
        current = current->next;
    }

    if (current == NULL) return;

    (*prev)->next = current->next;
    free(current);
}
