#include <stdio.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>
#include <malloc.h>
#include <stdlib.h>
#include <tshashmap/tshashmap.h>

typedef struct UserSession {
    int user_id;
    time_t last_login;
    time_t expiration_time;
    struct list_head endpoints;
};

struct hashmap *sessions;
pthread_mutex_t sessions_lock = PTHREAD_MUTEX_INITIALIZER;

void update_session(int user_id, time_t last_login, time_t expiration_time) {
    struct UserSession *session = tshashmap_get(sessions, &user_id);
    if (!session) {
        session = malloc(sizeof(struct UserSession));
        memset(session, 0, sizeof(struct UserSession));
        session->user_id = user_id;
        tshashmap_insert(sessions, &user_id, session);
    }
    session->last_login = last_login;
    session->expiration_time = expiration_time;
}

void remove_session(int user_id) {
    pthread_mutex_lock(&sessions_lock);
    tshashmap_remove(sessions, &user_id);
    pthread_mutex_unlock(&sessions_lock);
}

struct UserSession *get_session(int user_id) {
    return tshashmap_get(sessions, &user_id);
}

void check_expired_sessions() {
    pthread_mutex_lock(&sessions_lock);
    struct hash_entry *it;
    TSITER(sessions, it);
    while (TSNEXT(it)) {
        struct UserSession *session = TSDATA(it->key);
        if (time(NULL) > session->expiration_time) {
            remove_session(session->user_id);
        }
    }
    pthread_mutex_unlock(&sessions_lock);
}
```

This code uses a hash map provided by the tshashmap library for efficient insertion, deletion, and retrieval. The `update_session`, `remove_session`, and `get_session` functions perform their respective operations while managing concurrent access with a mutex lock (`sessions_lock`). The `check_expired_sessions` function iterates through the sessions hash map and invalidates any sessions that have expired.']

