    xmlDocPtr doc = xmlReadFile("configuration.xml", NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "Failed to parse XML file\n");
        exit(1);
    }

    xmlNodeSetPtr nodeSet = xmlFindNodeSet(doc, NULL, BAD_CAST "world");
    if (nodeSet->nodeNr != 1) {
        fprintf(stderr, "Invalid XML structure: Expected exactly one 'world' tag\n");
        exit(1);
    }

    xmlNodePtr worldNode = nodeSet->nodeTab[0];
    *worldWidth = strtol(xmlGetProp(worldNode, (xmlChar*)"width"), NULL, 10);
    *worldHeight = strtol(xmlGetProp(worldNode, (xmlChar*)"height"), NULL, 10);

    xmlNodePtr cameraNode = xmlFindSubElement(worldNode, (xmlChar*)"camera");
    if (cameraNode == NULL) {
        fprintf(stderr, "Invalid XML structure: Expected a 'camera' tag under the 'world' tag\n");
        exit(1);
    }

    *cameraSpeed = strtof(xmlGetProp(cameraNode, (xmlChar*)"speed"), NULL);

    xmlNodePtr tileNode = xmlFindSubElement(worldNode, (xmlChar*)"tileSize");
    if (tileNode == NULL) {
        fprintf(stderr, "Invalid XML structure: Expected a 'tileSize' tag under the 'world' tag\n");
        exit(1);
    }

    int tileSize = strtol(xmlNodeGetContent(tileNode), NULL, 10);
    *config = calloc(*worldHeight, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int y = 0; y < *worldHeight; ++y) {
        for (int x = 0; x < *worldWidth; ++x) {
            (*config)[y][x].RX_UE_INFORMATION_TAG.value = (uint8_t)(x >> 3);
            (*config)[y][x].RNTI.value = (uint16_t)(y << 4) | (uint16_t)x;
            (*config)[y][x].CRC_INDICATION_REL8_TAG.value = rand() % 2;
        }
    }
}
