typedef struct {
    int id;
    char ip[INET6_ADDRSTRLEN];
    uint16_t port;
    char* data_types; // comma-separated list of sensor data types
} SensorNodeConfig;

#define MAX_NODES 1024
SensorNodeConfig nodes[MAX_NODES];
int num_nodes = 0;

pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

struct sockaddr_in central_addr, sensor_addr;
UDPSocket central_sock, *sensor_sockets;

void read_config(const char* filename) {
    json_object* root;
    json_object* node;
    json_array* array;
    size_t i;

    FILE* fp = fopen(filename, "r");
    if (!fp) err(1, "\042%s\042: \042cannot open file\042", filename);

    root = json_tokener_parse(fp);
    array = json_object_get_array(root);

    pthread_mutex_lock(&config_lock);
    num_nodes = 0;
    for (i = 0; i < json_array_length(array); ++i) {
        node = json_array_get_idx(array, i);

        nodes[num_nodes].id = json_object_get_int(json_object_object_get(node, "id"));
        strncpy(nodes[num_nodes].ip, json_object_get_string(json_object_object_get(node, "ip")), INET6_ADDRSTRLEN);
        nodes[num_nodes].port = json_object_get_int(json_object_object_get(node, "port"));

        // Extract sensor data types from the comma-separated string
        char* str = strdup(json_object_get_string(json_object_object_get(node, "data_types")));
        char* token = strtok(str, ",");
        nodes[num_nodes].data_types = token;
        while (token != NULL) {
            token = strtok(NULL, ",");
            if (token != NULL) {
                nodes[num_nodes].data_types = realloc(nodes[num_nodes].data_types, strlen(nodes[num_nodes].data_types) + strlen(token) + 2);
                strcat(nodes[num_nodes].data_types, ", ");
                strcat(nodes[num_nodes].data_types, token);
            }
        }

        ++num_nodes;
    }
    pthread_mutex_unlock(&config_lock);
}

int main() {
    read_config("config.json");

    // Initialize central control node
    memset(&central_addr, 0, sizeof(struct sockaddr_in));
    central_addr.sin_family = AF_INET;
    central_addr.sin_port = htons(CENTRAL_PORT);
    if (inet_pton(AF_INET, "127.0.0.1", &central_addr.sin_addr) <= 0) err(1, "Invalid IP address");

    central_sock = udp_socket(AF_INET, SOCK_DGRAM);

    // Initialize and connect to each sensor node
    sensor_sockets = malloc(num_nodes * sizeof(UDPSocket));
    for (int i = 0; i < num_nodes; ++i) {
        memset(&sensor_addr, 0, sizeof(struct sockaddr_in));
        sensor_addr.sin_family = AF_INET;
        inet_pton(AF_INET, nodes[i].ip, &sensor_addr.sin_addr);
        sensor_addr.sin_port = htons(nodes[i].port);

        sensor_sockets[i] = udp_socket(AF_INIT, SOCK_DGRAM);
        if (connect(sensor_sockets[i], (struct sockaddr*)&sensor_addr, sizeof(sensor_addr)) < 0) {
            warn("Failed to connect to sensor node %d", nodes[i].id);
        }
    }

    // Implement your periodic querying, data aggregation, and logging mechanism here...

    return 0;
}
