#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t creation_timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t total_structures = 0;
static NFAPI_CRC_INDICATION_PDU_T *list = NULL;

enum { SUCCESS, MEMORY_ERROR, DUPLICATE_RNTI };

void log_creation(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("Created structure at %s\n", ctime(&pdu->creation_timestamp));
}

int create_and_add_structure(NFAPI_CRC_INDICATION_PDU_T **out, RX_UE_INFORMATION_TAG *rx_ue_information, RNTI *rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_pdu;
    size_t i;

    new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        return MEMORY_ERROR;
    }

    pthread_mutex_lock(&list_mutex);
    while (total_structures > 0 && list[total_structures - 1].rnti == *rnti) {
        total_structures--;
    }
    if (total_structures > 0 && list[total_structures - 1].rnti == *rnti) {
        pthread_mutex_unlock(&list_mutex);
        free(new_pdu);
        return DUPLICATE_RNTI;
    }

    total_structures++;
    new_pdu->rx_ue_information = *rx_ue_information;
    new_pdu->rnti = *rnti;
    new_pdu->crc_indication.crcFlag = (rand() % 2) ? 1 : 0;
    log_creation(new_pdu);
    memcpy(&list[total_structures - 1], new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&list_mutex);

    *out = &list[total_structures - 1];
    return SUCCESS;
}

int verify_crc_flags() {
    size_t i;
    for (i = 0; i < total_structures; i++) {
        if (list[i].crc_indication.crcFlag != 1) { // Assuming 1 indicates set CRCFLAG
            return FALSE;
        }
    }
    return TRUE;
}

size_t get_total_structures() {
    return total_structures;
}
