#include <pthread.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>
#include <semaphore.h>
#include <log4cxx/logger.h>
#include <log4cxx/basicconfigurator.h>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
};

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

static Node* head = NULL;
static size_t capacity = 0;
static size_t count = 0;
static sem_t mutex;
static sem_t notFull;
static sem_t notEmpty;
static log4cxx::LoggerPtr logger = log4cxx::Logger::getLogger("NFAPI_CRC_INDICATION_PDU_LIST");

void initialize(size_t initialCapacity) {
    capacity = initialCapacity;
    head = malloc(initialCapacity * sizeof(Node));
    if (!head) {
        log4cxx::LoggerPtr logger = log4cxx::Logger::getLogger("NFAPI_CRC_INDICATION_PDU_LIST");
        logger->error("Memory allocation failure");
        exit(-1);
    }
    memset(head, 0, initialCapacity * sizeof(Node));
    for (size_t i = 0; i < initialCapacity - 1; ++i) {
        head[i].next = &head[i + 1];
    }
    head[initialCapacity - 1].next = NULL;

    sem_init(&mutex, 0, 1);
    sem_init(&notFull, 0, initialCapacity);
    sem_init(&notEmpty, 0, 0);
}

void push(const NFAPI_CRC_INDICATION_PDU_T& data) {
    Node* current = head;
    Node* newNode = NULL;

    sem_wait(&notFull);

    sem_wait(&mutex);
    if (count == capacity) {
        capacity *= 2;
        void* resizedHead = mmap(NULL, capacity * sizeof(Node), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (resizedHead == MAP_FAILED) {
            log4cxx::LoggerPtr logger = log4cxx::Logger::getLogger("NFAPI_CRC_INDICATION_PDU_LIST");
            logger->error("Memory mapping failure");
            sem_post(&mutex);
            exit(-1);
        }
        memmove(resizedHead, head, count * sizeof(Node));
        free(head);
        head = static_cast<Node*>(resizedHead);
    }

    newNode = &head[count];
    newNode->data = data;
    newNode->next = current->next;
    current->next = newNode;

    count++;

    sem_post(&mutex);
    sem_post(&notEmpty);
}

const NFAPI_CRC_INDICATION_PDU_T* pop() {
    Node* current = head;

    sem_wait(&notEmpty);
    sem_wait(&mutex);

    if (current->next == NULL) {
        sem_post(&mutex);
        return NULL;
    }

    Node* toReturn = current->next;
    current->next = toReturn->next;

    count--;
    sem_post(&mutex);
    sem_post(&notFull);

    return &toReturn->data;
}

bool verifyCRC(const NFAPI_CRC_INDICATION_PDU_T& data) {
    // Implement your CRC verification logic here
}

void logCreationMetadata(const NFAPI_CRC_INDICATION_PDU_T& data) {
    time_t now;
    struct tm *tm;

    char buffer[256];

    time(&now);
    tm = localtime(&now);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm);

    log4cxx::LoggerPtr logger = log4cxx::Logger::getLogger("NFAPI_CRC_INDICATION_PDU_LIST");
    logger->info(std::string("Created structure with RNTI: ") + std::to_string(data.rnti) + ", CRCFLAG: " + (data.crc_indication.crcflag ? "true" : "false") + ", at " + buffer);
}
