typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
    pthread_mutex_t lock;
} Node;

Node *head = NULL;
size_t count = 0;
size_t max_elements = 50000;
pthread_mutex_t list_lock;

static void log_error(const char* message) {
    fprintf(stderr, "%s\n", message);
}

static int is_unique(uint32_t rnti) {
    Node *current = head;
    for (size_t i = 0; i < count; ++i) {
        if (current->data.RNTI == rnti) {
            log_error("Warning: Duplicate RNTI encountered.");
            return 0;
        }
        current = current->next;
    }
    return 1;
}

static void perform_operation(Node **list, Node **current, NFAPI_CRC_INDICATION_PDU_T *new_data) {
    pthread_mutex_lock(&(*list)->lock);
    if (*current == NULL) {
        *current = malloc(sizeof(Node));
        if (*current == NULL) {
            log_error("Error: Memory allocation failure.");
            return;
        }
        (*current)->data = *new_data;
        (*current)->next = NULL;
        (*current)->lock = PTHREAD_MUTEX_INITIALIZER;
        count++;
    } else {
        *current = (*current)->next;
        if (*current == NULL) {
            *current = malloc(sizeof(Node));
            if (*current == NULL) {
                log_error("Error: Memory allocation failure.");
                return;
            }
            (*current)->data = *new_data;
            (*current)->next = NULL;
            (*current)->lock = PTHREAD_MUTEX_INITIALIZER;
        } else {
            perform_operation(list, current, new_data);
        }
    }
    pthread_mutex_unlock(&(*list)->lock);
}

static void init_list() {
    if (pthread_mutex_init(&list_lock, NULL) != 0) {
        log_error("Error: Mutex initialization failed.");
    }
}

void populate_list(int N) {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    if (N > max_elements) {
        log_error("Error: Number of elements exceeds the maximum capacity.");
        return;
    }

    init_list();

    for (int i = 0; i < N; ++i) {
        Node *new_data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            log_error("Error: Memory allocation failure.");
            return;
        }

        new_data->RNTI = rand() % 100000 + 1;
        while (!is_unique(new_data->RNTI)) {
            new_data->RNTI = rand() % 100000 + 1;
        }

        new_data->RX_UE_INFORMATION_TAG = rand();
        new_data->CRC_INDICATION.CRCFLAG = (rand() % 2) == 0 ? 1 : 0;

        pthread_mutex_lock(&list_lock);
        Node *current = head;
        perform_operation(&head, &current, new_data);
        pthread_mutex_unlock(&list_lock);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    double elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1_000_000_000;
    printf("Total time taken to populate the list: %.6fs\n", elapsed_time);
}
