```cpp
#include <iostream>
#include <chrono>
#include <random>
#include <unordered_map>
#include <boost/circular_buffer.hpp>

using namespace std::chrono;
using namespace boost;

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
    high_resolution_clock::time_point timestamp;
};

class NFAPIDynamicList {
private:
    std::unordered_map<uint32_t, NFAPI_CRC_INDICATION_PDU_T> data;
    circular_buffer<NFAPI_CRC_INDICATION_PDU_T> buffer;
    int max_offset = 10 * 1024 * 1024 / sizeof(long); // Limit memory usage to 10 MB
    int max_keys = 100000;
    long* offsets;
    int* keys;
    std::mt19937 randEngine;

public:
    NFAPIDynamicList(int max_offset, int max_keys) {
        this->max_offset = max_offset;
        this->max_keys = max_keys;
        offsets = new long[max_offset];
        keys = new int[max_keys];
        std::fill(offsets, offsets + max_offset, -1); // Initialize as unallocated
        std::fill(keys, keys + max_keys, 0);          // Initialize all keys to 0 (not allocated)
        randEngine = std::mt19937(std::random_device{}());
    }

    ~NFAPIDynamicList() {
        delete[] offsets;
        delete[] keys;
    }

    void add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        auto now = high_resolution_clock::now();
        while (data.count(pdu.rnti)) { // Ensure RNTI uniqueness within the list
            pdu.rnti += 1;
        }
        pdu.crcflag = randEngine() % 2 == 0; // Randomly set CRCFLAG
        data[pdu.rnti] = pdu;
        offsets[data.size()] = now.time_since_epoch().count(); // Record creation timestamp

        if (buffer.capacity() > buffer.size()) {
            buffer.push_back(pdu);
        } else {
            auto lru_it = buffer.get_lru(); // Get least-recently-used item
            if (lru_it != buffer.end()) {
                data.erase(lru_it->rnti);
                keys[*offsets[buffer.size()] + lru_it - buffer.begin()] = 0; // Mark evicted item as unallocated
            }
        }
    }
};
```

