    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

struct buffer {
    struct node* head;
    struct node* tail;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
};

void buffer_init(struct buffer* buf, size_t capacity) {
    if (capacity > 10000) {
        fprintf(stderr, "Buffer capacity exceeds the limit of 10000\n");
        exit(EXIT_FAILURE);
    }

    buf->head = buf->tail = NULL;
    buf->capacity = capacity;
    buf->count = 0;
    pthread_mutex_init(&buf->lock, NULL);
}

struct node* buffer_alloc() {
    struct node* node = malloc(sizeof(struct node));
    if (!node) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    node->next = NULL;
    return node;
}

void buffer_push(struct buffer* buf, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&buf->lock);
    if (buf->count == buf->capacity) {
        struct node* old_tail = buf->tail;
        struct node* new_tail = buffer_alloc();
        memcpy(&new_tail->data, &old_tail->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        buf->tail = new_tail;
    }
    struct node* current = buf->head;
    if (!current) {
        buf->head = buf->tail = buffer_alloc();
        memcpy(&buf->head->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        return;
    }
    while (current->next) {
        current = current->next;
    }
    struct node* new_node = buffer_alloc();
    memcpy(&new_node->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    current->next = new_node;
    buf->tail = new_node;
    pthread_mutex_unlock(&buf->lock);
}

void buffer_compact(struct buffer* buf) {
    pthread_mutex_lock(&buf->lock);
    struct node* current = buf->head;
    while (current != NULL) {
        struct node* next = current->next;
        free(current);
        current = next;
    }
    buf->head = buf->tail = buffer_alloc();
    struct node* iterator = buf->head;
    while ((iterator = buf->head)->next) {
        memcpy(iterator, iterator->next, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(iterator->next);
        iterator->next = NULL;
    }
    pthread_mutex_unlock(&buf->lock);
}

void* create_list(int N) {
    struct buffer list_buffer;
    buffer_init(&list_buffer, 10000);

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        // Initialize the data structure with valid RX_UE_INFORMATION_TAG, RNTI, and randomly generated CRCFLAG
        // ...
        buffer_push(&list_buffer, data);
    }

    buffer_compact(&list_buffer);

    return &list_buffer;
}

