import os
import sys
import re
import linecache
import argparse
import time
import gzip
from concurrent.futures import ThreadPoolExecutor
from urllib.parse import urlparse

def is_textfile(path):
    return path.endswig with ('.txt', '.text')

def walk_files(root_dir, visit_func, recursive=True):
    for root, dirs, files in os.walk(root_dir):
        for file in files:
            file_path = os.path.join(root, file)
            if os.path.islink(file_path):
                target = os.readlink(file_path)
                if urlparse(target).scheme or is_textfile(target):
                    visit_func(target)
            elif is_textfile(file_path):
                visit_func(file_path)

def count_lines(file, delimiter='\n', field=-1):
    lines = 0
    with open(file, 'r') as f:
        for line in iter(f.readline, b''):
            lines += 1 if not delimiter else lines += len(line.split(delimiter))
    return lines

def process_files(directory, delimiter='\n', field=-1, regex=None, compress=False, log=False, chunk_size=1024):
    results = {}
    start_time = time.time()

    if not os.access(directory, os.R_OK):
        print(f"Error: Cannot read directory '{directory}'")
        return

    with ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
        walk_files(directory, lambda path: executor.submit(process_file, path, delimiter, field, regex, compress, log), False)

    end_time = time.time()
    processed_lines = sum([results[file] for file in results])

    if log:
        with open('log.txt', 'a') as log_file:
            log_file.write(f"{start_time} - {end_time}: Processed {processed_lines} lines from {len(results)} files\n")
            for file, count in results.items():
                if regex and not re.search(regex, file):
                    continue
                log_file.write(f"{file}: {count}\n")

def process_file(file, delimiter='\n', field=-1, regex=None, compress=False, log=False, chunk_size=1024):
    if not os.access(file, os.R_OK):
        print(f"Error: Cannot read file '{file}'")
        return 0

    lines = count_lines(file, delimiter, field)
    results[file] = lines

    if regex and re.search(regex, file) is None:
        return lines

    if compress:
        with gzip.open(f"{file}.gz", "wb") as output_file:
            with open(file, 'r') as input_file:
                for chunk in iter(lambda: input_file.read(chunk_size), b''):
                    output_file.write(chunk)
        os.remove(file)
        results[os.path.splitext(file)[0] + '.gz'] = lines

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--help', action='store_true')
    parser.add_argument('-d', '--delimiter', type=str)
    parser.add_argument('-f', '--field', type=int)
    parser.add_argument('-r', '--regex', type=str)
    parser.add_argument('-c', '--compress', action='store_true')
    parser.add_argument('-l', '--log', action='store_true')
    parser.add_argument("directories", nargs="*")

    args = parser.parse_args()

    if args.help:
        parser.print_help()
        return

    process_files(args.directories[0], delimiter=args.delimiter, field=args.field, regex=args.regex, compress=args.compress, log=args.log)

if __name__ == "__main__":
    main()
```

