        for file in files:
            if file.endswith('.conf'):
                filepath = os.path.join(root, file)
                logger.info(f'Processing {filepath}')
                with open(filepath, 'r') as f:
                    content = f.read()
                    for placeholder, value in params.items():
                        content = content.replace(placeholder, value)
                password = encrypt_password('your-secret-password')
                new_content = content + '\nENC_PASSWORD=' + password
                with open(filepath, 'w') as f:
                    f.write(new_content)
                logger.info(f'Updated {filepath}')
                # Use sed command to ensure the placeholders are replaced correctly in the file before updating it
                try:
                    subprocess.run(['sed', '-i', f'/{|placeholder}|{value}/g', filepath])
                except subprocess.CalledProcessError as e:
                    logger.error(f'Failed to replace placeholders in {filepath}: {e}')
                    raise e

def main():
    params = {'placeholder1': 'value1', 'placeholder2': 'value2'}
    for directory in ['/path/to/dir1', '/path/to/dir2']:
        try:
            process_dir(directory, params)
        except Exception as e:
            logging.exception('Error processing configuration files')
            sys.exit(1)

if __name__ == '__main__':
