typedef struct {
    size_t current_size;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T* elements;
} NFAPI_CRC_INDICATION_PDU_ARRAY_T;

void nfapi_crc_indication_pdu_array_init(NFAPI_CRC_INDICATION_PDU_ARRAY_T* array) {
    array->current_size = 0;
    array->capacity = 0;
    array->elements = NULL;
}

void nfapi_crc_indication_pdu_array_resize(NFAPI_CRC_INDICATION_PDU_ARRAY_T* array, size_t new_capacity) {
    if (new_capacity <= array->current_size) return;

    clock_t start = clock();

    NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(array->elements, new_capacity * TAG_SIZE);
    if (!temp_array) {
        fprintf(stderr, "Error: Out of memory.\n");
        exit(EXIT_FAILURE);
    }

    array->elements = temp_array;
    array->capacity = new_capacity;

    printf("Resized array in %.3fs\n", (double)(clock() - start) / CLOCKS_PER_SEC);
}

void nfapi_crc_indication_pdu_array_push(NFAPI_CRC_INDICATION_PDU_ARRAY_T* array, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (array->capacity == array->current_size) nfapi_crc_indication_pdu_array_resize(array, array->capacity ? (array->capacity * 2) : MAX_ELEMENTS);

    memcpy(&array->elements[array->current_size], pdu, TAG_SIZE);
    array->current_size++;
}

void nfapi_crc_indication_pdu_array_destroy(NFAPI_CRC_INDICATION_PDU_ARRAY_T* array) {
    free(array->elements);
    array->elements = NULL;
    array->current_size = 0;
    array->capacity = 0;
}
