import org.apache.commons.io.FileUtils;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import com.google.common.cache.LoadingCache;
import com.google.common.cache.RemovalListener;
import com.google.common.cache.RemovalNotification;

public class MD5Hasher {
    private static final int CACHE_SIZE = 10000;
    private static final long EXPIRATION_DURATION = TimeUnit.MINUTES.toMillis(5);
    private static final LoadingCache<String, String> cache = LoadingCache.newBuilder()
            .expireAfterAccess(EXPIRATION_DURATION, TimeUnit.MILLISECONDS)
            .maximumSize(CACHE_SIZE)
            .removalListener((RemovalNotification<String, String> notif) -> logger.log(Level.INFO, "Cache eviction: {0}", notif.getValue()))
            .build(this::hash);

    private static Logger logger; // Initialize this with your preferred logging framework

    public String hash(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hashedBytes = digest.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashedBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public String hashFile(Path file) throws IOException, NoSuchAlgorithmException {
        return cache.get(file.toUri().toString());
    }
}
