    array->capacity = initial_size;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    log("Initializing array", initial_size, 1);
    memory_stress_test(array, initial_size); // Run a memory stress test on the initialized array

    return array;
}

// Function to resize the CRC_INDICATOR_ARRAY and handle any errors
CRC_INDICATOR_ARRAY *resize_array(CRC_INDICATOR_ARRAY *array, size_t new_capacity) {
    if (new_capacity > 10000 || new_capacity == array->capacity) return array;

    NFAPI_CRC_INDICATION_PDU_T *temp = (NFAPI_CRC_INDICATION_PDU_T *)custom_realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        perror("Error: realloc failed");
        log("Resizing array", 0, 0);
        return NULL;
    }

    array->data = temp;
    array->capacity = new_capacity;

    log("Resizing array", new_capacity, 1);
    memory_stress_test(array, 10); // Run a memory stress test on the resized array

    return array;
}

// Function to deinitialize CRC_INDICATOR_ARRAY and perform cleanup
void deinit_array(CRC_INDICATOR_ARRAY *array) {
    if (array == NULL) return;

    pthread_mutex_destroy(&array->lock);
    custom_free(array->data);
