    file_operation* operation = malloc(sizeof(file_operation));
    if (!operation) return 2;

    operation->file_path = strdup(file_path);
    operation->operation = operation;

    // Initialize other data structures...

    pthread_mutex_init(&operation->lock, NULL);

    pthread_t thread;
    int err = pthread_create(&thread, NULL, process_file, operation);
    if (err) {
        free(operation->file_path);
        free(operation);
        return 3;
    }

    // Wait for the thread to finish execution...

