```javascript
const express = require('express');
const multer = require('multer');
const uuidv4 = require('uuid/v4');
const Template = require('../models/template');
const { ErrorResponse, SuccessResponse } = require('../utils/response');

const router = express.Router();

// Initialize Multer storage configuration
const upload = multer({ dest: 'uploads/' });

router.get('/', async (req, res) => {
  try {
    const limit = parseInt(req.headers['x-limit']) || 10;
    const page = parseInt(req.query.page) || 1;
    const templates = await Template.find()
      .sort({ id: 1 })
      .skip((page - 1) * limit)
      .limit(limit);

    SuccessResponse(res, templates);
  } catch (error) {
    ErrorResponse(res, error);
  }
});

router.post('/', upload.single('template'), async (req, res) => {
  try {
    if (!req.file || req.file.size > 10485760) { // 10MB size limit
      return ErrorResponse(res, new Error('Invalid template file'));
    }

    const newTemplate = new Template({ id: uuidv4(), data: req.file.buffer });
    await newTemplate.save();

    SuccessResponse(res, newTemplate);
  } catch (error) {
    ErrorResponse(res, error);
  }
});

router.put('/:id', upload.single('template'), async (req, res) => {
  try {
    const templateId = req.params.id;
    const updatedTemplateData = req.file ? req.file.buffer : Buffer.from(req.body.data);
    const options = { new: true };

    if (!updatedTemplateData || updatedTemplateData.size > 10485760) { // 10MB size limit
      return ErrorResponse(res, new Error('Invalid template file'));
    }

    await Template.findByIdAndUpdate(templateId, { data: updatedTemplateData }, options);
    const updatedTemplate = await Template.findById(templateId);

    SuccessResponse(res, updatedTemplate);
  } catch (error) {
    ErrorResponse(res, error);
  }
});

router.delete('/:id', async (req, res) => {
  try {
    const templateId = req.params.id;
    await Template.findByIdAndRemove(templateId);

    SuccessResponse(res, { message: 'Template deleted successfully' });
  } catch (error) {
    ErrorResponse(res, error);
  }
});

module.exports = router;
```

Finally, create a new folder called `utils`, and inside it, create another file called `response.js`:

```javascript
const { Response, errorHandler } = require('express-async-handler');

// Custom ErrorResponse function with status code, message, and error details (if any)
function ErrorResponse(res, error, statusCode = 500) {
  const response = new Response({ success: false });
  response.statusCode = statusCode;
  response.message = error.message || 'An error occurred';
  response.errorDetails = error.stack ? error.stack : error;
  res.status(statusCode).json(response);
}

// Custom SuccessResponse function with status code, data (if any), and message (if necessary)
function SuccessResponse(res, data, statusCode = 200, message = '') {
  const response = new Response({ success: true });
  response.statusCode = statusCode;
  response.data = data || {};
  response.message = message;
  res.status(statusCode).json(response);
}

module.exports = { SuccessResponse, ErrorResponse };
```

