    public class Program
    {
        private static ObjectCache _cache = MemoryCache.Default;
        private const string CacheKeyPrefix = "XmlElements_";

        public static void Main(string[] args)
        {
            if (!ParseArgs(args)) return;

            var watch = Stopwatch.StartNew();
            var results = ParseXmlFile(args[0]);
            watch.Stop();

            Console.WriteLine($"Time elapsed: {watch.ElapsedMilliseconds}ms");
            OutputResults(results);
        }

        private static bool ParseArgs(string[] args)
        {
            if (args.Length < 1 || args[0] == "-h" || args[0] == "--help")
            {
                ShowHelp();
                return false;
            }

            // Implement command-line argument parsing here

            return true;
        }

        private static void ShowHelp()
        {
            Console.WriteLine("Usage: XmlElementParser [XML_FILE] [--element=ELEMENT_NAME] [-o OUTPUT_FILE]");
            // Add more help information here
        }

        private static List<XmlNode> ParseXmlFile(string filePath)
        {
            if (_cache.Get(CacheKeyPrefix + filePath) is XmlDocument document) return document.SelectNodes("/").Cast<XmlNode>().ToList();

            lock (this)
            {
                using var reader = XmlReader.Create(filePath);
                document = new XmlDocument();
                document.Load(reader);
                _cache.Insert(CacheKeyPrefix + filePath, document, null, null, DateTimeOffset.MaxValue, CacheItemPolicy.AbsoluteExpiration(TimeSpan.FromHours(1)));
            }

            return document.SelectNodes("/").Cast<XmlNode>().ToList();
        }

        private static void OutputResults(List<XmlNode> results)
        {
            if (results.Count == 0) Console.WriteLine("No matching elements found.");
            else ResultsSortingAlgorithm.Sort(results);

            foreach (var node in results)
            {
                Console.WriteLine(node.OuterXml);
            }
        }
    }

    public static class ResultsSortingAlgorithm
    {
        // Implement sorting algorithms here, for example:
        public static void Sort(List<XmlNode> nodes) => nodes.Sort((x, y) => string.CompareOrdinal(x.TextContent, y.TextContent));
    }
}
