        $stmt = $db->prepare("DELETE FROM users WHERE id=?");
        $stmt->execute([$request['id']]);

        // Remove user data from cache to prevent further access to deleted user accounts.
        unset($caching->cache["user_{$request['id']}"]);
    }

    return json_encode($responseData);
}
