typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

Node* head = NULL;
unsigned int capacity = 0, size = 0;
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;

int create_structs(void) {
    if (size >= 1000)
        return size;

    NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data)
        return -1;

    data->rx_ue_info.tag = RX_UE_INFORMATION_TAG_VALID;
    data->rnti = (RNTI)rand();
    data->crc_indication.tag = CRC_INDICATION_REL8_TAG_VALID;
    data->crc_indication.crcflag = (CRCFLAG)rand() % 2;

    pthread_mutex_init(&data->lock, NULL);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        free(data);
        return -1;
    }

    new_node->data = *data;
    new_node->next = head;
    head = new_node;

    ++size;
    return 1;
}

void destroy_structs(NFAPI_CRC_INDICATION_PDU_T* data) {
    if (data == NULL)
        return;

    pthread_mutex_destroy(&data->lock);
    free(data);
}

void remove_node(Node** head_ref, Node* node) {
    if (*head_ref == node) {
        *head_ref = node->next;
        free(node);
        return;
    }

    Node* current = *head_ref;
    while (current && current->next != node) {
        current = current->next;
    }

    if (current == NULL)
        return;

    current->next = node->next;
    free(node);
}

int manage_structs(void) {
    int created_count = 0;
    pthread_mutex_lock(&queue_lock);

    if (size < capacity) {
        for (Node* current = head; current; current = current->next) {
            if (!current->data.rx_ue_info.tag || !current->data.rnti || !current->data.crc_indication.tag) {
                pthread_mutex_unlock(&queue_lock);
                return created_count;
            }

            if (pthread_trylock(&current->data.lock) != 0) {
                continue;
            }

            destroy_structs(&current->data);
            remove_node(head, current);
            --size;
            created_count += create_structs();
            pthread_mutex_unlock(&queue_lock);
            break;
        }
    }

    pthread_mutex_unlock(&queue_lock);

    if (created_count == 0) {
        Node* last = NULL;
        for (Node* current = head; current && size >= capacity; current = current->next) {
            if (!current->data.rx_ue_info.tag || !current->data.rnti || !current->data.crc_indication.tag) {
                continue;
            }

            if (pthread_trylock(&current->data.lock) != 0) {
                last = current;
                continue;
            }

            Node* temp = current->next;
            destroy_structs(&current->data);
            remove_node(head, current);
            --size;
            last = current;
            current = temp;
            created_count += create_structs();
        }
    }

    return created_count;
}
