    connection->timeout = time(NULL) + 60; // Set initial timeout to 60 seconds
    connection->is_active = false;

    return connection;
}

DatabaseConnection* find_available_connection() {
    for (int i = 0; i < config.max_connections; ++i) {
        if (!connection_pool[i].is_active) return &connection_pool[i];
    }

    // If no idle connections found, create a new one
    DatabaseConnection* new_connection = create_connection();
    if (new_connection) {
        connection_pool[num_active_connections++] = *new_connection;
    }

    return new_connection;
}

void return_connection(DatabaseConnection* connection) {
    sem_wait(&connection->lock);
    connection->is_active = false;
    sem_post(&connection->lock);

    num_active_connections--;
}

DatabaseConnection* initializeDatabaseConnectionPool(char* config_path, const struct Config* cfg) {
    if (load_config(config_path, &config)) return NULL;

    if (!validate_config(&config)) return NULL;

    init_connection_pool();

    connection_pool = mmap(NULL, sizeof(DatabaseConnection) * config.max_connections, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (connection_pool == MAP_FAILED) return NULL;

    for (int i = 0; i < config.max_connections; ++i) {
        connection_pool[i].connection_handle = calloc(1, sizeof(void*));
        if (!connection_pool[i].connection_handle) {
            int retries = cfg->retries;
            while (--retries > 0 && !initializeDatabaseConnectionPool(config_path, cfg)) {}

            if (retries <= 0) {
                munmap(connection_pool, sizeof(DatabaseConnection) * config.max_connections);
                return NULL;
            }
        }
    }

    sem_init(&connection_pool_mutex, 0, 1);
    pthread_mutex_init(&log_mutex, NULL);

    return connection_pool;
}
