    // Initialize traffic configuration
    num_simulations = json_array_size(json_object_get(root, "simulations"));
    traffic_configs = malloc(num_simulations * sizeof(TrafficFlowConfig*));

    for (size_t i = 0; i < num_simulations; ++i) {
        TrafficFlowConfig* configs = calloc(CONFIG_MAX_FLOWS, sizeof(TrafficFlowConfig));
        if (!configs) {
            free(traffic_configs);
            fclose(web_config);
            return NULL;
        }

        for (size_t j = 0; j < CONFIG_MAX_FLOWS; ++j) {
            // Generate unique FlowID, IP addresses, and CRCFLAG
            uint32_t flow_id = rand() % UINT32_MAX;
            char source_ip[64], dest_ip[64];
            generate_random_ip(source_ip);
            generate_random_ip(dest_ip);
