            for (size_t k = 0; k < j; ++k) {
                if (configs[k].FlowID == flow_id ||
                    strcmp(configs[k].SourceIP, source_ip) == 0 ||
                    strcmp(configs[k].DestinationIP, dest_ip) == 0) {
                    is_duplicate = true;
                    break;
                }
            }

            if (is_duplicate) continue;

            configs[j].FlowID = flow_id;
            snprintf(configs[j].SourceIP, sizeof(configs[j].SourceIP), "%s/%s", source_ip, source_ip_length_exceeded(source_ip) ? "/" : "");
            snprintf(configs[j].DestinationIP, sizeof(configs[j].DestinationIP), "%s", dest_ip);

            pthread_mutex_lock(&config_mutex);
            traffic_configs[i] = configs;
            pthread_mutex_unlock(&config_mutex);
        }
    }

    fclose(web_config);
    return 1;
}

