typedef struct _list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _list_node* next;
} list_node_t;

static list_node_t* head = NULL;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random CRCFLAG value
uint8_t gen_random_crcflag() {
    return rand() % 2;
}

void init_list() {
    if (head != NULL) {
        free_list();
        head = NULL;
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_node(RX_UE_INFORMATION_TAG tag, uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication.crcflag = gen_random_crcflag();
    return new_node;
}

void add_node(NFAPI_CRC_INDICATION_PDU_T* node) {
    pthread_mutex_lock(&list_lock);
    list_node_t** current = &head;
    while (*current != NULL) {
        current = &(*current)->next;
    }
    *current = node;
    pthread_mutex_unlock(&list_lock);
}

NFAPI_CRC_INDICATION_PDU_T* remove_node(uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* to_remove = NULL;
    pthread_mutex_lock(&list_lock);
    list_node_t** current = &head;

    while (*current != NULL) {
        if ((*current)->rnti == rnti) {
            to_remove = (*current);
            *current = (*current)->next;
            break;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list_lock);
    return to_remove;
}

void free_node(NFAPI_CRC_INDICATION_PDU_T* node) {
    if (node != NULL) {
        free(node);
        node = NULL;
    }
}

void free_list() {
    pthread_mutex_lock(&list_lock);
    list_node_t* current, * temp;
    current = head;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free_node(temp);
    }

    head = NULL;
    pthread_mutex_unlock(&list_lock);
}
