typedef struct _bundle {
    char *keyvalue;
    struct _bundle *next;
} BundleNode;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t list_size;
    size_t list_capacity;
    BundleNode **bundles;
    size_t num_bundles;
    size_t max_bundles;
} DynamicCollection;

void manage_dynamic_collections(const char *const *file_paths, const char *bundle_type) {
    // Initialize dynamic collection
    DynamicCollection *dc = malloc(sizeof(DynamicCollection));
    pthread_mutex_init(&dc->lock, NULL);
    dc->list = NULL;
    dc->list_size = 0;
    dc->list_capacity = 0;
    dc->bundles = calloc(1, sizeof(BundleNode*) * MAX_BUNDLES);
    dc->num_bundles = 0;
    dc->max_bundles = MAX_BUNDLES;

    // Process files and bundles (thread-safe)
    for (size_t i = 0; file_paths[i] != NULL; ++i) {
        BundleNode **bundle_ptr = &dc->bundles[dc->num_bundles];
        char *bundle_content = load_file(file_paths[i]);

        if (bundle_content == NULL) {
            continue;
        }

        // Check if duplicate bundle type, keep only the most recent one
        for (size_t j = 0; j < dc->num_bundles; ++j) {
            if (strcmp(bundle_type, get_bundle_type(dc->bundles[j])) == 0) {
                free(bundle_content);
                break;
            }
        }

        // Add bundle to the dynamic collection and process its content
        *bundle_ptr = parse_bundle(bundle_content, bundle_type);
        dc->num_bundles++;

        if (dc->num_bundles >= dc->max_bundles) {
            dc->max_bundles *= 2;
            dc->bundles = realloc(dc->bundles, sizeof(BundleNode*) * dc->max_bundles);
        }
    }

    // Cleanup and free memory
    for (size_t i = 0; i < dc->num_bundles; ++i) {
        BundleNode *current = dc->bundles[i];
        while (current != NULL) {
            BundleNode *temp = current;
            current = current->next;
            free(temp->keyvalue);
            free(temp);
        }
    }
    free(dc->bundles);
    pthread_mutex_destroy(&dc->lock);
    free(dc);
}
