['```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

struct list {
    unsigned int size;
    unsigned long memory_usage;
    node_t** nodes;
    pthread_mutex_t mutex;
};

void init_list(struct list* list, unsigned int capacity) {
    if (!list) return;
    list->size = 0;
    list->memory_usage = 0;
    list->nodes = calloc(capacity, sizeof(node_t*));
}

void destroy_list(struct list* list) {
    if (!list) return;
    for (unsigned int i = 0; i < list->size; ++i) {
        free(list->nodes[i]);
    }
    free(list->nodes);
}

unsigned long get_memory_usage(const struct list* list) {
    if (!list) return 0;
    unsigned long memory = sizeof(struct list);
    for (unsigned int i = 0; i < list->size; ++i) {
        memory += sizeof(node_t); // Assume node_t is 8 bytes
        node_t* node = list->nodes[i];
        if (node) memory += node->data.crc_indication.byte_length;
    }
    return memory;
}

void lock_list(struct list* list) {
    if (!list) return;
    pthread_mutex_lock(&(list->mutex));
}

void unlock_list(struct list* list) {
    if (!list) return;
    pthread_mutex_unlock(&(list->mutex));
}

unsigned int find_rnti(const struct list* list, uint32_t rnti) {
    unsigned int index = 0;
    node_t *current = list->nodes[index];
    while (current && current->data.rnti < rnti) {
        index++;
        if (index >= list->size) return -1; // Not found
        current = list->nodes[index];
    }
    if (!current || current->data.rnti > rnti) return index; // Not found
    else return index + 1; // Found at the current position or later
}

void insert_node(struct list* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !pdu) return;

    lock_list(list);

    unsigned int index = find_rnti(list, pdu->rnti);
    node_t *current = list->nodes[index];

    // Allocate new node
    node_t* newNode = malloc(sizeof(node_t));
    if (!newNode) {
        unlock_list(list);
        return; // Failed to allocate memory
    }

    newNode->data = *pdu;
    newNode->next = NULL;

    if (index < list->size) {
        // Move existing nodes after the insertion point
        for (unsigned int i = index + 1; i < list->size; ++i) {
            node_t* temp = list->nodes[i];
            list->nodes[i] = newNode;
            newNode = temp;
        }
    } else {
        // Append the new node to the end of the list
        list->nodes[list->size++] = newNode;
    }

    unlock_list(list);
}

void remove_node(struct list* list, uint32_t rnti) {
    if (!list) return;

    lock_list(list);

    unsigned int index = find_rnti(list, rnti);
    node_t *current = list->nodes[index];

    // Case 1: Current node is empty or not found
    if (!current || current->data.rnti != rnti) {
        unlock_list(list);
        return;
    }

    // Case 2: Only one element in the list
    if (list->size == 1) {
        free(current);
        list->nodes[0] = NULL;
        list->size--;
    } else {
        // Move all nodes after the removed node to fill the gap
        for (unsigned int i = index + 1; i < list->size; ++i) {
            list->nodes[i - 1] = list->nodes[i];
        }
        free(current);
        list->nodes[--list->size] = NULL;
    }

    unlock_list(list);
}

const NFAPI_CRC_INDICATION_PDU_T* find_node(const struct list* list, uint32_t rnti) {
    if (!list) return NULL;

    lock_list(list);

    unsigned int index = find_rnti(list, rnti);

    node_t *current = list->nodes[index];
    unlock_list(list);

    return current && current->data.rnti == rnti ? &current->data : NULL;
}
