#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <semaphore.h>
#include <sys/mman.h>

// Define the Packet Header Information structure
typedef struct _packet_header {
    uint32_t ip_header; // IP header data (e.g., source and destination addresses, protocol)
    uint32_t pid;        // Unique packet identifier
} packet_header;

// Define a macro for the alignment of packet_header structures in memory
#define ALIGNED_PACKET_HEADER __attribute__((aligned(64)))

// Custom allocator for aligned memory blocks and structs
ALIGNED_PACKET_HEADER* custom_malloc(size_t size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Custom free function for the custom allocator
void custom_free(void* ptr) {
    if (munmap(ptr, sizeof(*ptr)) == -1) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }
}

typedef struct _packet_list {
    packet_header** data;  // Array of pointers to packet_header structures
    size_t capacity;        // Maximum number of elements the list can hold
    size_t size;            // Current number of elements in the list
    pthread_mutex_t mutex;   // Mutex for thread synchronization
    semaphore_t semaphore;  // Semaphore to control concurrent access
} packet_list;

// Initialize a new packet_list with the given capacity
void packet_list_init(packet_list* list, size_t capacity) {
    list->data = custom_malloc(capacity * sizeof(packet_header*));
    list->capacity = capacity;
    list->size = 0;
    pthread_mutex_init(&(list->mutex), NULL);
    sem_init(&(list->semaphore), 0, capacity);
}

// Insert a new packet_header into the list with the given PID. Return true if successful or false otherwise.
bool packet_list_insert(packet_list* list, const packet_header* header) {
    // Wait for access to the list data
    pthread_mutex_lock(&(list->mutex));
    sem_wait(&(list->semaphore));

    if (list->size >= list->capacity) {
        pthread_mutex_unlock(&(list->mutex));
        sem_post(&(list->semaphore));
        return false;
    }

    list->data[list->size] = custom_malloc(sizeof(packet_header));
    *list->data[list->size] = *header;
    ++list->size;

    // Signal that the list data is available for other threads to access
    pthread_mutex_unlock(&(list->mutex));
    sem_post(&(list->semaphore));

    return true;
}

// Retrieve a packet_header from the list by its PID. Return NULL if not found or an error occurred.
const packet_header* packet_list_get(const packet_list* list, uint32_t pid) {
    pthread_mutex_lock(&(list->mutex));
    sem_wait(&(list->semaphore));

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i]->pid == pid) {
            // Signal that the packet has been accessed and make it available to other threads
            pthread_mutex_unlock(&(list->mutex));
            sem_post(&(list->semaphore));
            return list->data[i];
        }
    }

    pthread_mutex_unlock(&(list->mutex));
    sem_post(&(list->semaphore));
    return NULL;
}

// Delete a packet_header from the list by its PID. Return true if successful or false otherwise.
bool packet_list_delete(packet_list* list, uint32_t pid) {
    pthread_mutex_lock(&(list->mutex));
    sem_wait(&(list->semaphore));

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i]->pid == pid) {
            custom_free(list->data[i]);
            memmove(list->data + i, list->data + i + 1, (list->size - i - 1) * sizeof(packet_header*));
            --list->size;
            // Signal that the packet has been deleted and make it available for other threads to access
            pthread_mutex_unlock(&(list->mutex));
            sem_post(&(list->semaphore));
            return true;
        }
    }

    pthread_mutex_unlock(&(list->mutex));
    sem_post(&(list->semaphore));
    return false;
}
```

