    int rx_quality_metrics;
    int phy_layer_events;
} NFAPI_NETWORK_STATISTICS_PDU_T;

#define MAX_STRUCTURES 5000
static NFAPI_NETWORK_STATISTICS_PDU_T *network_stats = NULL;
static size_t structures_capacity = 0;
static size_t structures_count = 0;
static sem_t mutex;

void init_mutex() {
    sem_init(&mutex, 0, 1);
}

void destroy_mutex() {
    sem_destroy(&mutex);
}

void resize_array() {
    if (structures_capacity >= MAX_STRUCTURES) return;

    NFAPI_NETWORK_STATISTICS_PDU_T *new_array = realloc(network_stats, sizeof(NFAPI_NETWORK_STATISTICS_PDU_T) * (structures_capacity + 1024));
    if (!new_array) {
        fprintf(stderr, "Failed to resize array\n");
        return;
    }

    network_stats = new_array;
    structures_capacity++;
}

bool process_network_stats(const char *json_data) {
    json_t *root, *tx_power, *rx_quality, *phy_events;
    int tx_power_values[MAX_STRUCTURES], rx_quality_values[MAX_STRUCTURES], phy_events_values[MAX_STRUCTURES];
    size_t i = 0;

