        perror("Failed to parse JSON");
        return false;
    }

    tx_power = json_object_get(root, "TX_POWER_LEVELS");
    rx_quality = json_object_get(root, "RX_QUALITY_METRICS");
    phy_events = json_object_get(root, "PHY_LAYER_EVENTS");

    if (!tx_power || !rx_quality || !phy_events) {
        fprintf(stderr, "Missing required field: TX_POWER_LEVELS, RX_QUALITY_METRICS, or PHY_LAYER_EVENTS\n");
