        json_decref(root);
        return false;
    }

    sem_wait(&mutex);
    if (structures_count >= structures_capacity) resize_array();
    sem_post(&mutex);

    for (i = 0; i < json_array_size(tx_power); ++i) {
        tx_power_values[i] = json_integer_value(json_array_get(tx_power, i));
        rx_quality_values[i] = json_integer_value(json_array_get(rx_quality, i));
        phy_events_values[i] = json_integer_value(json_array_get(phy_events, i));
