        network_stats[i].tx_power_levels = tx_power_values[i];
        network_stats[i].rx_quality_metrics = rx_quality_values[i];
        network_stats[i].phy_layer_events = phy_events_values[i];
    }

    structures_count += json_array_size(tx_power);

