This function utilizes external API to get the list of Old Testament books and performs text analysis using regular expressions for optimized performance.

Note: This is a simplified implementation; you may need to adjust it according to your project's requirements.

```javascript
const BibleBooksAPI = 'https://api.example.com/bible-books'; // Replace with the API URL
const BooksCache = {}; // In-memory cache for book names and counts

function analyzeText(text) {
  let bookCounts = Object.assign({}, BooksCache[text] || {});

  if (bookCounts.length > 0) {
    return bookCounts;
  }

  fetch(BibleBooksAPI)
    .then(response => response.json())
    .then(books => {
      const regexPatterns = books.map(book => new RegExp(`\\b(${book}\\w+)\\b`, 'gi'));
      let matches;

      while ((matches = regexPatterns.reduce((acc, pattern) => acc || pattern.exec(text), null))) {
        const bookName = matches[0].toLowerCase();
        if (!bookCounts[bookName]) {
          bookCounts[bookName] = 1;
        } else {
          bookCounts[bookName]++;
        }
      }

      BooksCache[text] = bookCounts; // Cache the result for future use
      return bookCounts;
    });
}
