typedef struct {
    NFAPI_L1_STATS_PDU_T *data;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
} stats_list_t;

void init_stats_list(stats_list_t *list) {
    list->data = mmap(NULL, MAX_LIST_SIZE * ALIGNMENT, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (list->data == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    list->capacity = MAX_LIST_SIZE;
    list->length = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

bool add_stats(stats_list_t *list, const NFAPI_L1_STATS_PDU_T *entry) {
    if (list->length >= list->capacity) return false;
    NFAPI_L1_STATS_PDU_T *pos = (NFAPI_L1_STATS_PDU_T *)((uintptr_t)list->data + (list->length * ALIGNMENT));
    if (entry->L1_INSTANCE_ID < 0 || entry->L1_INSTANCE_ID > UINT16_MAX ||
        entry->TX_POWER_LEVELS < -128 || entry->TX_POWER_LEVELS > 127 ||
        entry->BER < 0.0f || entry->BER > 1.0f ||
        entry->RSSI < -128 || entry->RSSI > 127) return false;
    *pos = *entry;
    pthread_mutex_lock(&list->mutex);
    list->length++;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

NFAPI_L1_STATS_PDU_T* get_stats_by_id(const stats_list_t *list, uint16_t id) {
    if (list->length == 0) return NULL;
    NFAPI_L1_STATS_PDU_T *pos = list->data;
    for (size_t i = 0; i < list->length; ++i, pos += ALIGNMENT) {
        if (pos->L1_INSTANCE_ID == id) return pos;
    }
    return NULL;
}
