['```javascript
const { PromisifyFunction } = require('util');

function copyBufferChunks(chunks, byteCount, callback) {
  if (!Array.isArray(chunks) || chunks.length === 0 || typeof byteCount !== 'number' || byteCount < 0) {
    return callback(new Error("Invalid input: chunks must be an array, byteCount must be a positive number"));
  }

  let offset = 0;
  const resultBufferLength = Math.min(chunks.reduce((sum, chunk) => sum + chunk.length, 0) - byteCount, byteCount);
  if (resultBufferLength === 0) return callback(null, Buffer.from([]));

  let resultBuffer;
  if (resultBufferLength > 1e6) { // Performance-critical section: large buffers use allocateUnsafe
    resultBuffer = Buffer.allocUnsafe(resultBufferLength);
    for (const chunk of chunks) {
      const end = Math.min(offset + byteCount, chunk.length);
      if (end - offset < byteCount) byteCount -= (end - offset); // Update byteCount to avoid out-of-bound access
      offset += end - offset >= byteCount ? byteCount : chunk.length;
      if (offset >= byteCount) break;
      chunk.copy(resultBuffer, offset - byteCount, offset - byteCount);
    }
  } else { // Performance-critical section: small buffers use concat()
    const slices = chunks.map((chunk, index) => {
      const end = Math.min(offset + byteCount, chunk.length);
      if (end - offset < byteCount) byteCount -= (end - offset);
      offset += end - offset >= byteCount ? byteCount : chunk.length;
      return chunk.slice(offset - byteCount, offset);
    });
    resultBuffer = Buffer.concat(slices);
  }

  callback(null, resultBuffer);
}

const promisifiedCopyBufferChunks = PromisifyFunction(copyBufferChunks);
