class TransactionRecord {
public:
    std::string id;
    time_t timestamp;
    int marketMakerId;
    bool isBuy;
    double volume, price;
};

class HighFrequencyTradingEngine {
private:
    std::unordered_map<std::string, TransactionRecord> transactionRecords;
    boost::circular_buffer<TransactionRecord> buffer(10000); // Adjust the buffer size as needed

public:
    void insertTransactionRecord(const TransactionRecord& record) {
        transactionRecords[record.id] = record;
        buffer.push_back(record);
    }

    TransactionRecord* queryTransactionRecord(const std::string& id) {
        auto iter = transactionRecords.find(id);
        if (iter != transactionRecords.end()) {
            return &(*iter);
        }
        // Return an empty buffer element if the record is not found
        return &buffer.front();
    }
};
