// Sliding window data structures
pthread_mutex_t transactions_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t ws_mutex = PTHREAD_MUTEX_INITIALIZER;
int ws_head, ws_tail;
Transaction *ws[WINDOW_SIZE];

