void add_transaction(Transaction);
Transaction* process_transactions();
FSA* create_state_list(int*, int, FSA*, int);

// Main function
Transaction* manage_transactions(FSA*, Transaction*) {
    Transaction* current = *transaction;
    if (current != NULL) {
        add_transaction(*current);
        free(current);
    }
    return process_transactions();
}

void add_transaction(Transaction transaction) {
    pthread_mutex_lock(&transactions_mutex);
    time_t now = time(NULL);

    if ((now - transaction.timestamp) > 7) {
        // Ignore old transactions
        return;
    }

    if (ws_head + 1 == ws_tail || (now - ws[ws_tail]->timestamp) > 15) {
        // Add to sliding window
        ws[(ws_tail+1)%WINDOW_SIZE] = transaction;
        ws_tail = (ws_tail + 1) % WINDOW_SIZE;
    } else {
        // Replace the oldest transaction in the window
        ws[ws_head] = transaction;
        ws_head = (ws_head+1)%WINDOW_SIZE;
    }

    pthread_mutex_unlock(&transactions_mutex);
}

Transaction* process_transactions() {
    pthread_mutex_lock(&ws_mutex);
    int count = 0, last7_count = 0, total_sum = 0.0;
    Transaction* max_transaction = NULL, *current;
    float max_sum = -1.0;

    for (int i = ws_head, j = 0; i != ws_tail || j < WINDOW_SIZE; i = (i+1)%WINDOW_SIZE, j++) {
        current = &ws[i];

        if ((current->timestamp - time(NULL)) <= 7) {
            last7_count++;
