        auto elapsed = now - last_strategy_activation;

        if (elapsed >= cooldown_duration) {
            std::ofstream logfile("network_service_log.txt", std::ios_base::app);
            logfile << "Activated strategy: " << strategy << ", at: "
                    << std::put_time(std::gmtime(&now.time_since_epoch().count()), "%Y-%m-%d %H:%M:%S") << std::endl;
        }

        last_strategy_activation = now;
    }
}

void defensive_strategy() {
    auto now = std::chrono::steady_clock::now();
    auto elapsed = now - last_strategy_activation;

    if (elapsed >= cooldown_duration) {
        std::mt19937 rng(now.time_since_epoch().count());
        std::uniform_int_distribution<> distribution(0, strategy_weights.size() - 1);

        int strategy_index = distribution(rng);
        log_strategy(strategy_weights.begin()->first);

        strategy_weights[strategy_weights.begin()->first] -= 0.05; // Adjust strategy weights dynamically based on historical attack data
    }
