async function processPipeline(filePaths, initialState, transformations) {
  let currentState = initialState;
  let promises = [];

  for (const filePath of filePaths) {
    const promise = new Promise((resolve, reject) => {
      const transformation = transformations.find(t => t.handleType === typeof filePath);

      if (!transformation) {
        return reject(new Error(`No transformation found for type: ${typeof filePath}`));
      }

      transformation.fn(currentState, filePath).then(updatedState => {
        currentState = updatedState;
        promises.push(Promise.resolve()); // Resolve internal promise to mark processing of this file as done
      }).catch(error => {
        return reject(new Error(`Error while transforming file ${filePath}: ${error.message}`));
      });
    });

    promises.push(promise);
  }

  await Promise.all(promises); // Wait for all promises to resolve before returning the final state
  return currentState;
}

// Sample transformations
const transformation1 = { handleType: String, fn: (state, filePath) => new Promise((resolve, reject) => {
  // Process the file content and update the state as needed...
  // For this example, we simply double the value of a property in the state.
  fs.readFile(filePath, 'utf8', (err, data) => {
    if (err) return reject(err);
    const number = parseInt(data, 10) * 2;
    resolve({...state, someProperty: number});
  });
}) };

const transformation2 = { handleType: Function, fn: (state, filePath) => new Promise((resolve, reject) => {
  // Process the function and update the state as needed...
  // For this example, we simply increment a property in the state.
  functionToCall(state, (result) => resolve({...state, anotherProperty: result + 1}));
}) };

// Usage
processPipeline(['file1.txt', functionToCall], {someProperty: 5, anotherProperty: 3}, [transformation1, transformation2])
  .then(finalState => console.log(finalState))
  .catch(error => console.error(error.message));
```"]

