['```java
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Stream;

public class Main {
    public static void main(String[] args) {
        if (args.length < 2) {
            System.err.println("Usage: java Main inputFile command");
            return;
        }

        Path inputPath = Paths.get(args[0]);
        String command = args[1];

        try {
            if (Files.exists(inputPath))
                Files.deleteIfExists(inputPath);

            List<String> lines = readLinesSorted(inputPath);
            int sequenceNumber = Integer.parseInt(lines.get(lines.size() - 1));

            Process process = Runtime.getRuntime().exec(command, null, null);
            BufferedReader inputStream = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader errorStream = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            Thread inputThread = new Thread(() -> {
                try {
                    String line;
                    while ((line = inputStream.readLine()) != null) {
                        System.out.println("InputStream: " + line);
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                }
            });
            Thread errorThread = new Thread(() -> {
                try {
                    String line;
                    while ((line = errorStream.readLine()) != null) {
                        System.err.println("Error Stream: " + line);
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                }
            });

            inputThread.start();
            errorThread.start();

            process.waitFor();

            int exitValue = process.exitValue();
            System.out.println("Command exited with value: " + exitValue);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    private static List<String> readLinesSorted(Path path) throws IOException {
        try (Stream<String> lines = Files.lines(path)) {
            return lines.sorted().toList();
        }
    }
}
