        const struct csv_row *row = parser.data->rows + lines_read;

        int i;
        for (i = 0; i < arraylen(required_columns); ++i) {
            if (!csv_row_has_column(row, required_columns[i])) {
                fprintf(stderr, "Missing mandatory column: %s\n", csv_column_name(required_columns[i]));
                valid = false;
                break;
            }
        }

        if (!valid) break;

        // Validate each column based on the JSON schema and its rules here

        ++lines_read;
    }

    fclose(csv);

    jsmn_parser_free(&json_parser);
