    public Map<String, ImageUploadStatus> optimizeImages(List<ImageFile> inputFiles, int maxThreads) {
        // Create and start a specified number of worker threads for image processing
        List<WorkerThread> workerThreads = new ArrayList<>();
        for (int i = 0; i < maxThreads; i++) {
            WorkerThread worker = new WorkerThread(this);
            workerThreads.add(worker);
            worker.start();
        }

        // Add input files to the queue for processing
        for (ImageFile image : inputFiles) {
            queue.enqueue(image);
        }

        // Wait for all worker threads to finish processing
        for (WorkerThread worker : workerThreads) {
            try {
                worker.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        // Return the upload status, resolution, and size of each processed image
        return queue.getResults();
    }
