public async Task<ProcessResult> SecureProcessAndStreamFile(string base64EncodedMessage, string inputFilePath, string outputFilePath, string transformationRules, Config config)
{
    var aes = Aes.Create();
    var decryptedMessage = DecryptStringFromBytes_Aes(Convert.FromBase64String(base64EncodedMessage), aes.Key, aes.IV);

    var inputFileStream = new FileStream(inputFilePath, FileMode.Open);
    var outputFileStream = new FileStream(outputFilePath, FileMode.Create);
    var hashSHA256 = SHA256.Create();

    long bufferSize = 1024 * 64;
    byte[] buffer = new byte[bufferSize];

    TimeSpan elapsedTime = default;
    Stopwatch sw = Stopwatch.StartNew();

    var logs = new StringBuilder();

    try
    {
        while (true)
        {
            int read = await inputFileStream.ReadAsync(buffer, 0, buffer.Length);

            if (read <= 0) break;

            var chunkHashSHA256 = hashSHA256.ComputeHash(buffer);
            await SendHashToServer(chunkHashSHA256, config);

            Array.Copy(buffer, 0, buffer, 0, read);
            inputFileStream.Position += read;

            // Parse and transform the data based on provided transformation rules
            var transformedBuffer = TransformData(buffer, transformationRules);

            await outputFileStream.WriteAsync(transformedBuffer, 0, transformedBuffer.Length);
        }
    }
    catch (Exception ex)
    {
        logs.AppendLine($"Error during file processing: {ex.Message}");
    }

    elapsedTime = sw.Elapsed;
    inputFileStream.Dispose();
    outputFileStream.Dispose();

    var processResult = new ProcessResult()
    {
        Success = !logs.ToString().Contains("Error"),
        DecryptedMessage = decryptedMessage,
        TransformedContent = Convert.ToBase64String(outputFileStream.Length > 0 ? File.ReadAllBytes(outputFilePath) : Array.Empty<byte>()),
        Logs = logs.ToString(),
        ElapsedTime = elapsedTime
    };

    if (processResult.Success)
    {
        var receivedChecksum = await ValidateOutputFileIntegrity(outputFilePath, config);
        if (receivedChecksum != null && !ReceivedChecksumMatches(receivedChecksum, outputFilePath))
        {
            processResult.Logs += "Output file integrity validation failed.";
            processResult.Success = false;
        }
    }

    return processResult;
}

