private async Task SendHashToServer(byte[] hashSHA256, Config config)
{
    var httpClient = new HttpClient();

    for (int i = 0; i < config.RetryAttempts; i++)
    {
        try
        {
            var requestContent = new ByteArrayContent(hashSHA256);
            var response = await httpClient.PostAsync(config.LoggingServerUri, requestContent);
            if (response.IsSuccessStatusCode) break;
        }
        catch (Exception ex)
        {
