            Console.WriteLine($"Error sending hash to server: {ex.Message}");
            await Task.Delay(config.RetryInterval);
        }
    }
}

private static string DecryptStringFromBytes_Aes(byte[] encrypted, byte[] Key, byte[] IV)
{
    // Implement AES decryption logic
    using (var aes = Aes.Create())
    {
        using (var msDecrypt = new MemoryStream(encrypted))
        {
            aes.Key = Key;
            aes.IV = IV;
            var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
            {
                using (var sr = new StreamReader(csDecrypt))
                {
                    return sr.ReadToEnd();
                }
            }
        }
    }
}
