    DistributedCache(const std::string& host, int port) : redis_(host, port) {}

    // Retrieve or update cache entry with given key
    void getOrUpdate(const std::string& key, const std::string& value) {
        auto callback = [this, key](const redis::redisReplyPtr& reply) {
            if (reply->getType() == redis::RedisReplyType::Error) {
                // Handle error
            } else if (reply->getType() == redis::RedisReplyType::String) {
                // Cache hit, return existing value
                std::cout << "Cache Hit: " << reply->str() << std::endl;
            } else {
                // Cache miss, set new value with expiration and eviction policy
                redis_.set(key, value).expire(60).expiresWhenIdle(30).onExpire([this](const redis::redisReplyPtr&) {
                    this->evictLeastRecentlyUsed();
                });
            }
        };

        // Check if key exists in cache first, then update it if not found
        redis_.get(key).async_apply(callback);
    }

