class CRCIndicationsGenerator {
public:
    void generate(size_t num_pdus) {
        std::vector<std::shared_ptr<CRC_INDICATION_PDU_T>> pdus;

        pdus.resize(num_pdus);
        pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
        std::random_device rd;
        std::mt19937 gen(rd());
        static constexpr uint32_t max_rnti = 0xffffffff;
        for (size_t i = 0; i < num_pdus; ++i) {
            boost::thread::scoped_lock lock(mutex);
            pdus[i] = std::make_shared<CRC_INDICATION_PDU_T>();
            pdus[i]->rx_ue_information_tag.value = i;
            pdus[i]->rnti.value = rd() % max_rnti + 1; // Generate unique RNTI values
            pdus[i]->crc_indication_rel8_tag.crcflag = rand() % 2;
        }
    }
};
