fn initialize_app_data_dir() -> Result<String, Error> {
    let base_path = Path::new(BASE_PATH);
    if !base_path.is_dir() {
        return Err(Error::IOError(std::io::Error::last_os_error()));
    }

    let app_data_dir_env = "APP_DATA_DIR";
    match env::var(app_data_dir_env) {
        Ok(_) => (),
        Err(_) => {
            let temp_dir = TempDir::new_in(base_path).unwrap();
            set_env("APP_DATA_DIR", &temp_dir.path().to_str().unwrap());
        }
    }

    // Atomicity and consistency check for the created directory.
    let app_data_dir = Path::new(env::var("APP_DATA_DIR").unwrap());
    if !app_data_dir.is_dir() {
        walkdir::WalkDir::new(app_data_dir)
            .into_iter()
            .for_each(|entry| match entry {
                Ok(ref entry) => {
                    if entry.path().is_symlink() {
                        if let Some(target) = entry.file_name().to_str() {
                            std::fs::remove_file(Path::new(&format!("{}/{}", app_data_dir, target)))
                                .expect("Failed to remove symlink");
                        }
                    }
                }
                Err(_) => {}
            });
        thread::scoped(|| {
            for _ in 0..MAX_RETRIES {
                if std::fs::create_dir_all(app_data_dir).is_ok() {
                    return Ok(());
                }

                thread::sleep(std::time::Duration::from_millis(RETRY_SLEEP_TIME_MS));
            }
        })
        .unwrap()
        .join().expect("Failed to create directory");
    }

    Ok(env::var("APP_DATA_DIR").unwrap())
}

fn set_env(key: &str, value: &str) {
    use std::os::unix::prelude::*;
    use std::os::windows::prelude::*;

    match uname().is_unix() {
        true => unsafe {
            let ptr = CString::new(value).unwrap().as_ptr();
            libc::putenv(ptr);
        },
        false => std::env::set_var(key, value),
    }
}

fn create_thread_pool() -> Arc<Mutex<Vec<thread::JoinHandle<()>>>> {
    let pool = Vec::with_capacity(THREAD_POOL_SIZE);
    Arc::new(Mutex::new(pool))
}

