#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct LTE_PHY_RX_FRAME_INFO {
    int symbol_count;
    double signal_strength;
    float interference_level;
    int symbol_rate;
    uint64_t frame_timestamp;
    enum modulation_type modulation;
    struct demodulation_result demodulated_data;
    struct channel_state_info channel_conditions;
    struct synchronization_data sync_info;
} frame;

struct memory_pool {
    size_t capacity;
    frame* frames;
    pthread_mutex_t lock;
};

void init_memory_pool(struct memory_pool* pool, size_t initial_capacity) {
    pool->capacity = initial_capacity;
    pool->frames = malloc(initial_capacity * sizeof(frame));
    if (!pool->frames) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memset(pool->frames, 0, initial_capacity * sizeof(frame));
    pthread_mutex_init(&pool->lock, NULL);
}

struct memory_pool* expand_memory_pool(struct memory_pool* pool, size_t new_capacity) {
    if (new_capacity <= pool->capacity) return pool;

    frame* temp = realloc(pool->frames, new_capacity * sizeof(frame));
    if (!temp) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memset(&temp[pool->capacity], 0, (new_capacity - pool->capacity) * sizeof(frame));
    pool->frames = temp;
    pool->capacity = new_capacity;

    return pool;
}

frame* acquire_frame(struct memory_pool* pool) {
    pthread_mutex_lock(&pool->lock);

    size_t index = (pool->read + 1) % pool->capacity;
    frame* frame_ptr = &pool->frames[index];

    if (frame_ptr->symbol_count >= INT_MAX / 2 || pool->write - index < pool->capacity / 4) {
        pool = expand_memory_pool(pool, pool->capacity * 2);
        frame_ptr = &pool->frames[index];
    }

    frame_ptr->symbol_count = rand() % MAX_SYMBOLS + MIN_SYMBOLS;
    frame_ptr->frame_timestamp = time(NULL) * 1000; // Timestamp in milliseconds
    frame_ptr->modulation = RAND_MODULATION_TYPE();

    pthread_mutex_unlock(&pool->lock);
    return frame_ptr;
}

int validate_frame(const frame* frame) {
    if (frame->frame_timestamp < time(NULL) * 1000 - FRAME_LIFETIME ||
        frame->symbol_count <= 0 ||
        frame->modulation > MAX_MODULATION_TYPES ||
        !isValidDemodulatedData(frame->demodulated_data)) {
        return 0;
    }

    return 1;
}

int populate_frames(struct memory_pool* pool, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        frame* frame = acquire_frame(pool);
        if (!validate_frame(frame)) return 0;
    }

    // Perform additional processing and calculations on the populated frames...

    return 1;
}
```

