typedef struct TCP_CONNECTION_STATS_T {
    uint32_t CONN_ID;
    inet_addr_t REMOTE_ADDR, LOCAL_ADDR;
    size_t BYTES_SENT, BYTES_RECV;
    time_t CONN_ESTABLISHED_TIME;
    time_t LAST_DATA_TIME;
    enum conn_state CONNECTION_STATE;
    int ERROR_CODE;
    struct session_info SESSION_INFO;
} TCP_CONNECTION_STATS_T;

typedef struct MEM_POOL_T {
    TCP_CONNECTION_STATS_T *connections;
    size_t capacity, size;
    pthread_mutex_t lock;
} MEM_POOL_T;

void* create_connection(void *data) {
    MEM_POOL_T *pool = data;
    TCP_CONNECTION_STATS_T *conn;

    conn = calloc(1, sizeof(*conn));
    if (!conn) {
        perror("calloc");
        return NULL;
    }

    // Initialize connection structure fields here

    pthread_mutex_lock(&pool->lock);
    pool->connections[pool->size] = *conn;
    pool->size++;
    pthread_mutex_unlock(&pool->lock);

    return conn;
}

void resize_pool(MEM_POOL_T *pool, size_t new_capacity) {
    if (new_capacity <= pool->size)
        return;

    TCP_CONNECTION_STATS_T *new_connections = realloc(pool->connections, sizeof(*pool->connections) * new_capacity);
    if (!new_connections) {
        perror("realloc");
        return;
    }

    pool->capacity = new_capacity;
    pool->connections = new_connections;
}

MEM_POOL_T* create_pool(size_t initial_capacity) {
    MEM_POOL_T *pool = malloc(sizeof(*pool));
    if (!pool) {
        perror("malloc");
        return NULL;
    }

    pool->connections = calloc(initial_capacity, sizeof(*pool->connections));
    if (!pool->connections) {
        free(pool);
        perror("calloc");
        return NULL;
    }

    pool->size = 0;
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->lock, NULL);

    pthread_t threads[initial_capacity];
    for (size_t i = 0; i < initial_capacity; ++i)
        pthread_create(&threads[i], NULL, create_connection, pool);

    for (size_t i = 0; i < initial_capacity; ++i)
        pthread_join(threads[i], NULL);

    return pool;
}

TCP_CONNECTION_STATS_T* get_connection(MEM_POOL_T *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size >= pool->capacity)
        resize_pool(pool, pool->capacity + 10);

    TCP_CONNECTION_STATS_T *conn = &pool->connections[pool->size];

    pool->size++;
    pthread_mutex_unlock(&pool->lock);

    return conn;
}

