#include <stdio.h>
#include <string.h>
#include <time.h>
#include <sys/mman.h>
#include <pthread.h>
#include <semaphore.h>

#define MD5_SIZE 16
#define TIMESTAMP_FORMAT "%Y-%m-%dT%H:%M:%S.000Z"

struct HashContext {
    unsigned char digest[MD5_SIZE];
    size_t hash_updates;
    time_t last_reset;
    sem_t rate_limit_sem;
    pthread_mutex_t lock;
};

void md5Init(HashContext *context) {
    memset(context->digest, 0, sizeof(context->digest));
    context->hash_updates = 0;
    time(&(context->last_reset));
    sem_init(&(context->rate_limit_sem), 0, INT_MAX);
    pthread_mutex_init(&(context->lock), NULL);
}

void md5Update(HashContext *context, const char *data, size_t len) {
    sem_wait(&(context->rate_limit_sem));
    pthread_mutex_lock(&(context->lock));
    MD5_CTX ctx;
    char *temp_buffer = NULL;

    if (len + context->hash_updates * MD5_SIZE > context->memory_limit) {
        temp_buffer = mmap(NULL, len, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        memcpy(temp_buffer, data, len);
    } else {
        temp_buffer = (char *)realloc(context->digest + context->hash_updates * MD5_SIZE, len + context->hash_updates * MD5_SIZE);
        memcpy(temp_buffer + context->hash_updates * MD5_SIZE, data, len);
    }

    MD5_Init(&ctx);
    MD5_Update(&ctx, temp_buffer, len);
    memcpy(context->digest, ctx.digest, MD5_SIZE);
    context->hash_updates++;

    pthread_mutex_unlock(&(context->lock));
    sem_post(&(context->rate_limit_sem));

    if (temp_buffer != context->digest + context->hash_updates * MD5_SIZE) {
        free(temp_buffer);
    }
}

void md5Final(HashContext *context, char *result) {
    MD5_Final(context->digest, &ctx);
    sprintf(result, "%02x", context->digest);
    result[MD5_SIZE * 2] = '/';
}

char* stringToMD5WithAdvancedOptions(const char *input, size_t size_limit, bool trim, bool log, unsigned int rate_limit, unsigned int memory_limit) {
    HashContext context;
    md5Init(&context);

    if (strlen(input) > size_limit && trim) {
        size_t len = strlen(input);
        if (len > memory_limit) return NULL;

        char *truncated = malloc(size_limit + 1);
        memcpy(truncated, input, size_limit);
        truncated[size_limit] = '\0';
        md5Update(&context, truncated, strlen(truncated));
        free(truncated);
    } else {
        md5Update(&context, (const char *)input, strlen(input));
    }

    if (md5Update(&context, "", 0) > rate_limit && log) {
        time_t current;
        struct tm *current_tm;
        char timestamp[32];
        char hash_str[MD5_SIZE * 2 + 1];
        md5Final(&context, hash_str);

        time(&current);
        current_tm = localtime(&current);
        strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, current_tm);

        printf("%s: String length: %zu, Hash: %s, Timestamp: %s, Updates: %u\n", trim ? "Truncated string" : "Out of memory", strlen(input) > size_limit ? strlen(input) - size_limit : strlen(input), hash_str, timestamp, context.hash_updates - context.last_reset.tv_sec);
    }

    char *result = malloc(MD5_SIZE * 2 + 1 + (strlen(input) > size_limit ? size_limit : strlen(input)) + 1);
    md5Final(&context, result);

    if (strlen(input) > size_limit && !trim) {
        printf("%s: String length: %zu, Hash: %s, Timestamp: %s, Updates: %u\n", "Out of memory", strlen(input), result, timestamp, context.hash_updates - context.last_reset.tv_sec);
        free(result);
        return NULL;
    }

    strcat(result, input);
    if (strlen(input) > size_limit && trim) {
        result[size_limit] = '\0';
    }
    return result;
}
```

