public class AdvancedValueGenerator
{
    private BigInteger _seed;
    private float _minFloat, _maxFloat;
    private int _minInt, _maxInt;
    private Dictionary<int, float> _weights;
    private object _lockObject = new object();
    private IDictionary<string, object> _state;

    public AdvancedValueGenerator(BigInteger seed, float minFloat, float maxFloat, int minInt, int maxInt, IReadOnlyDictionary<int, float> weights)
    {
        if (seed < 0) throw new ArgumentOutOfRangeException(nameof(seed), "Seed must be non-negative.");
        _seed = seed;
        _minFloat = max(minFloat, 0);
        _maxFloat = min(_maxFloat, _minFloat);
        _minInt = max(minInt, int.MinValue);
        _maxInt = min(_maxInt, _minInt);
        _weights = weights?.ToDictionary(kvp => kvp.Key, kvp => Max(kvp.Value, 0)) ?? new Dictionary<int, float>();

        if (_weights.Sum() > 1) throw new ArgumentOutOfRangeException(nameof(weights), "The sum of the weights must be equal to or less than one.");

        _state = new Dictionary<string, object>
        {
            ["Seed"] = _seed,
            ["MinFloat"] = _minFloat,
            ["MaxFloat"] = _maxFloat,
            ["MinInt"] = _minInt,
            ["MaxInt"] = _maxInt,
            ["Weights"] = _weights
        };
    }

    public void LogError(string format, params object[] args)
    {
        var message = string.Format(format, args);
        Console.Error.WriteLine($"[Error] {message}");
    }

    public override string ToString() => JsonConvert.SerializeObject(_state, Formatting.Indented);

    [MethodImpl(MethodImplOptions.Synchronized)]
    private Random _random = new Random((int)_seed);

    public float GetRandomFloat([CallerMemberName] string methodName = null)
    {
        lock (_lockObject)
        {
            if (_weights.Count == 0) return _random.NextDouble() * (_maxFloat - _minFloat) + _minFloat;

            var totalWeightSum = _weights.Values.Sum();
            var weightedCumulativeSum = new List<float>();
            for (var i = 0; i < _weights.Count; i++)
            {
                weightedCumulativeSum.Add(weightedCumulativeSum.Sum() + (_weights[i] / totalWeightSum));
            }

            var r = _random.NextDouble();
            for (var i = 0; i < weightedCumulativeSum.Count; i++)
            {
                if (r <= weightedCumulativeSum[i])
                    return (_weights.ElementAt(i).Key + _minFloat) * (1 / weightedCumulativeSum[i]);
            }

            throw new Exception($"{methodName} - Weighted random float generation failed.");
        }
    }

    public int GetRandomInt([CallerMemberName] string methodName = null)
    {
        lock (_lockObject)
        {
            if (_weights.Count == 0) return _random.Next(_minInt, _maxInt + 1);

            var maxWeightIndex = _weights.Keys.ToList().Max(index => _weights[index]);
            var indexToChoose = new List<int>();
            for (var i = 0; i < _weights.Count; i++)
            {
                if (_weights[i] == maxWeightIndex) indexToChoose.Add(i);
            }

            return _random.Next(indexToChoose) + _minInt;
        }
    }

    public void ResetGeneratorState() => _state.Clear();

