    const LTE_NAS_Message_T* findByTransactionID(std::uint64_t transactionID) {
        std::unique_lock<std::mutex> lock(m_);

        auto it = std::find_if(messages_.begin(), messages_.end(), [transactionID](const LTE_NAS_Message_T& message) {
            return message.transactionID == transactionID;
        });

        if (it != messages_.end())
            return &*it;

        return nullptr;
    }

