typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define BUFFER_SIZE (1024)

static NFAPI_CRC_INDICATION_PDU_T* buffer = NULL;
static size_t buffer_size = 0;
static size_t count = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;
static pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;

void init(size_t num_users) {
    buffer_size = BUFFER_SIZE > num_users ? BUFFER_SIZE : num_users;
    buffer = malloc(buffer_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!buffer) {
        perror("malloc");
        exit(1);
    }
}

void add(const size_t user_index) {
    pthread_mutex_lock(&mutex);
    while (count == buffer_size) {
        pthread_cond_wait(&not_full, &mutex);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &buffer[user_index];
    pdu->rx_ue.tag = RX_UE_INFORMATION_TAG_INITIALIZER;
    pdu->rnti.rnti = user_index;
    pdu->crc_indication.crcflag = rand() % 2;

    count++;
    if (count < buffer_size) {
        pthread_cond_signal(&not_empty);
    }
    pthread_mutex_unlock(&mutex);
}

void process_batch(void (*callback)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&mutex);
    size_t start = count;
    size_t end = (count + buffer_size - 1) % buffer_size;

    for (size_t i = start; i != end; ++i) {
        callback(&buffer[i]);
    }

    count -= start;

    if (count < buffer_size / 2) {
        size_t to_free = buffer_size - count;
        buffer_size -= to_free;
        buffer = realloc(buffer, buffer_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&not_empty);
}
```

