struct message_queue* create_message_queue(size_t initial_capacity) {
    struct message_queue* queue = malloc(sizeof(struct message_queue));
    if (!queue) return NULL;

    queue->capacity = initial_capacity;
    queue->count = 0;
    queue->messages = calloc(initial_capacity, sizeof(LTE_NAS_Message_T));
    if (!queue->messages) {
        free(queue);
        return NULL;
    }

    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

void destroy_message_queue(struct message_queue* queue) {
    if (queue && queue->messages) {
        free(queue->messages);
        pthread_mutex_destroy(&queue->lock);
        free(queue);
    }
}

bool insert_message(struct message_queue* queue, LTE_NAS_Message_T msg) {
    validate_message(&msg);

    pthread_mutex_lock(&queue->lock);

    if (queue->count == queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        LTE_NAS_Message_T* temp_messages = realloc(queue->messages, new_capacity * sizeof(LTE_NAS_Message_T));
        if (!temp_messages) {
            pthread_mutex_unlock(&queue->lock);
            return false;
        }
        queue->messages = temp_messages;
        queue->capacity = new_capacity;
    }

    queue->messages[queue->count] = msg;
    ++queue->count;

    pthread_mutex_unlock(&queue->lock);

    return true;
}

LTE_NAS_Message_T* get_message(struct message_queue* queue) {
    pthread_mutex_lock(&queue->lock);

    if (queue->count == 0) {
        pthread_mutex_unlock(&queue->lock);
        return NULL;
    }

    LTE_NAS_Message_T* msg = &queue->messages[0];
    memmove(&queue->messages[0], &queue->messages[1], queue->count * sizeof(LTE_NAS_Message_T));
    --queue->count;

    pthread_mutex_unlock(&queue->lock);

    return msg;
}
```

