typedef enum { SUCCESS, ERROR_INVALID_DATA, ERROR_MEMORY_ALLOCATION } LTE_ERROR;

static sem_t lock; // Mutex to ensure thread safety during allocation and validation processes

LTE_ERROR allocate_frame_info(size_t num_frames, LTE_PHY_FRAME_INFO** frame_info) {
    LTE_PHY_FRAME_INFO* frames = NULL;

    sem_init(&lock, 0, 1); // Initialize the mutex

    if ((frames = (LTE_PHY_FRAME_INFO*)calloc(num_frames, sizeof(LTE_PHY_FRAME_INFO))) == NULL) {
        printf("Error: Memory allocation failed.\n");
        sem_destroy(&lock);
        return ERROR_MEMORY_ALLOCATION;
    }

    // Validate each frame metadata within the thread-safe context
    for (size_t i = 0; i < num_frames; ++i) {
        sem_wait(&lock); // Acquire the mutex before modifying shared data

        if ((frames[i].frequency_band >= MIN_FREQUENCY && frames[i].frequency_band <= MAX_FREQUENCY) &&
            (frames[i].time_slot_index >= 0 && frames[i].time_slot_index < valid_time_slots[frames[i].frequency_band])) {
            sem_post(&lock); // Release the mutex after checking data consistency
        } else {
            printf("Error: Invalid frequency band or time slot index detected.\n");
            for (size_t j = 0; j < i; ++j) free(frames + j); // Free allocated resources up to the invalid frame
            sem_destroy(&lock);
            return ERROR_INVALID_DATA;
        }
    }

