#include <time.h>

typedef struct LTE_RRC_CONNECTION_RECONFIGURATION_IND_T {
    int RRC_INSTANCE_ID;
    // TARGETrvine_information
    char target[64];
    // CELL_RECONFIGURATION_COMMAND
    unsigned short COMMAND_FLAG;
    struct LTE_RRC_CONNECTION_RECONFIGURATION_IND_T *prev, *next;
    pthread_mutexattr_t attr;
    pthread_mutex_t lock;
    enum STATUS { PENDING, IN_PROGRESS, COMPLETED, FAILED } status;
} LTE_RRC_CONNECTION_RECONFIGURATION_IND;

typedef struct dllist {
    struct LTE_RRC_CONNECTION_RECONFIGURATION_IND_T head;
    struct LTE_RRC_CONNECTION_RECONFIGURATION_IND_T *tail;
    unsigned int size;
} dl_list;

void init_mutex(pthread_mutex_t *mutex) {
    pthread_mutexattr_init(&mutex->attr);
    pthread_mutexattr_settype(&mutex->attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(mutex, &mutex->attr);
}

dl_list *create_list() {
    dl_list *list = malloc(sizeof(dl_list));
    list->head.prev = NULL;
    list->tail = &list->head;
    list->size = 0;
    init_mutex(&list->head.lock);
    return list;
}

void add_to_list(LTE_RRC_CONNECTION_RECONFIGURATION_IND *node, dl_list *list) {
    init_mutex(&node->lock);

    node->prev = list->tail;
    node->next = NULL;

    pthread_mutex_lock(&list->head.lock);
    if (list->size > 0) {
        list->tail->next = node;
    }
    list->tail = node;
    list->size++;
    pthread_mutex_unlock(&list->head.lock);
}

LTE_RRC_CONNECTION_RECONFIGURATION_IND *remove_from_list(dl_list *list, int id) {
    LTE_RRC_CONNECTION_RECONFIGURATION_IND *node = NULL;
    pthread_mutex_lock(&list->head.lock);
    struct LTE_RRC_CONNECTION_RECONFIGURATION_IND_T *iter = list->head.next;

    if (iter == NULL) {
        pthread_mutex_unlock(&list->head.lock);
        return NULL;
    }

    while (iter != list->tail && iter->RRC_INSTANCE_ID != id) {
        node = iter;
        iter = iter->next;
    }

    if (iter == list->tail && iter->RRC_INSTANCE_ID == id) {
        node = iter;
        list->tail = node->prev;
        if (list->size > 1) {
            node->prev->next = NULL;
        }
    } else if (iter != list->tail && iter->RRC_INSTANCE_ID == id) {
        node->next->prev = iter->prev;
    }

    if (node != NULL) {
        list->size--;
    }

    pthread_mutex_unlock(&list->head.lock);
    return node;
}

void batch_process(dl_list *list, void (*processor)(LTE_RRC_CONNECTION_RECONFIGURATION_IND*)) {
    pthread_mutex_lock(&list->head.lock);
    struct LTE_RRC_CONNECTION_RECONFIGURATION_IND_T *iter = list->head.next;

    while (iter != list->tail) {
        if (iter->status == PENDING) {
            processor(iter);
            iter->status = IN_PROGRESS;
        }
        iter = iter->next;
    }

    pthread_mutex_unlock(&list->head.lock);
}
```

This implementation includes a doubly-linked list to handle dynamic memory allocation, an atomic mutex for thread safety, and a batch processing function that processes pending requests in a queue. The solution considers the constraints and trade-offs mentioned in the problem statement."]

