void initializeLTEUEContexts(int num_contexts, int max_load) {
    LTEUEContext *ue_contexts = malloc(num_contexts * sizeof(LTEUEContext));
    if (!ue_contexts) {
        log(ERROR, "Failed to allocate memory for UE contexts");
        return;
    }

    struct semaphore_t sem_obj;
    sem_init(&sem_obj.sem, 0, max_load);

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    struct timespec time;
    clock_gettime(CLOCK_MONOTONIC, &time);
    double total_time = 0.0;
    int created_contexts = 0;

    for (int i = 0; i < num_contexts; ++i) {
        LTEUEContext *context = ue_contexts + i;
        context->UECID = i;

        // Initialize UCD structure with randomized BWP settings and other parameters
        // ...

        sem_wait(&sem_obj.sem);

        context->thread_id = pthread_create(&context->thread_id, &attr, processEvent, context);
        if (context->thread_id == 0) {
            log(ERROR, "Failed to create a thread for UE context %d", context->UECID);
            sem_post(&sem_obj.sem);
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &time);
        double time_taken = (time.tv_sec - time.tv_sec) + (time.tv_nsec - time.tv_nsec) / 1_000_000_000;
        total_time += time_taken;
        created_contexts++;

        log(INFO, "Created UE context %d in %.9f seconds", context->UECID, time_taken);
        sem_post(&sem_obj.sem);
    }

    if (created_contexts > 0) {
        double avg_time = total_time / created_contexts;
        log(INFO, "Average time to create UE context: %.9f seconds", avg_time);
    }

    // Cleanup and manage resources effectively when required
}

