import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public class HashUtils {
    private static final String HASH_ALGORITHM = "MD5";

    public static byte[] hashStringToBytes(String s) throws Exception {
        return MessageDigest.getInstance(HASH_ALGORITHM).digest(s.getBytes("UTF-8"));
    }

    public static String bytesToHex(byte[] hash) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < hash.length; i++) {
            sb.append(String.format("%02x", hash[i]));
        }
        return sb.toString();
    }

    public static String hashStringMD5(String input) throws Exception {
        byte[] hash = hashStringToBytes(input);
        return bytesToHex(hash);
    }
}
