void* count_lines(void *arg) {
    struct args *args = arg;
    struct line_count *lc = malloc(sizeof(struct line_count));
    lc->lines = 0;
    lc->lock = PTHREAD_MUTEX_INITIALIZER;

    FILE *fp = fopen(args->input_file, "r");
    char buffer[4096];
    size_t read;
    if (!fp) {
        perror("Error opening input file");
        exit(1);
    }

    while ((read = fread(buffer, sizeof(char), sizeof(buffer) - 1, fp)) > 0) {
        buffer[read] = '\0';
        char *line_end = strchr(buffer, '\n');
        if (line_end) {
            pthread_mutex_lock(&lc->lock);
            lc->lines++;
            pthread_mutex_unlock(&lc->lock);
            if (line_end > buffer) *line_end = '\0';
        }
    }

    fclose(fp);
    free(arg);
    free(lc);
    pthread_exit(NULL);
}

