        else if (!strcmp(argv[i], "--manpage")) args.manpage = 1;
        else if (!strcmp(argv[i], "-cs")) args.case_sensitive = 1;
        else if (strlen(argv[i]) > 2 && argv[i][0] == '-' && argv[i][1] == 'o') {
            args.output_file = argv[++i];
        } else if (strlen(argv[i]) > 3 && argv[i][0] == '-' && argv[i][1] == 'l') {
            args.log_file = argv[++i];
        } else {
