    int priority;
    void* context;
} Task;

typedef struct TaskList {
    size_t capacity;
    size_t size;
    Task** tasks;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int max_threads;
    pthread_t* threads;
} TaskList;

void create_task_list(TaskList* list, size_t capacity) {
    // Initialize task list structure
    list->capacity = capacity;
    list->size = 0;
    list->tasks = mmap(NULL, sizeof(Task*) * capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (list->tasks == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
    list->cond = PTHREAD_COND_INITIALIZER;
    // Initialize thread pool
    list->max_threads = 10;
    list->threads = malloc(sizeof(pthread_t) * list->max_threads);
}

