from pathlib import Path

def resolve_path(path):
    if isinstance(path, str):
        try:
            return Path(Path(path).resolve())
        except FileNotFoundError:
            return None
    elif hasattr(path, "resolve"):
        return path.resolve()
    else:
        return path

def is_text_file(path):
    return (path.suffix in {".txt", ".csv", ".tsv"} or
            path.is_file() and path.stat().st_mode & 0x200000 == 0x200000)

def split_line(line, delimiter=-1):
    if delimiter < 0:
        return line.split()
    return [line[i:i+delimiter] for i in range(0, len(line), delimiter)]

def extract_field(line, field_number, delimiter=-1):
    fields = split_line(line, delimiter)
    if len(fields) >= field_number + 1:
        return fields[field_number]
    else:
        raise IndexError(f"Field number {field_number} out of range")

def filter_lines(patterns, lines):
    for pattern in patterns:
        if not re.match(pattern, line):
            yield line

def log_processing(message, level=logging.INFO):
    logging.log(level, message)

def compress_output(output, compression="gzip"):
    if compression == "gzip":
        with gzip.open(f"{output}.gz", "wb") as f:
            with open(output, "rb") as g:
                f.write(g.read())
        output = f"{output}.gz"
    return output

def main():
    import argparse

    parser = argparse.ArgumentParser(description="Process text files from a directory structure.")
    parser.add_argument("-d", "--directory", type=str, required=True, help="The input directory to process.")
    parser.add_argument("--delimiter", type=int, default=-1, help="Custom line delimiter for splitting lines (default: space-separated).")
    parser.add_argument("-f", "--field", type=int, nargs="+", default=[0], help="Specify the field number(s) to extract from each line.")
    parser.add_argument("--filter", nargs="+", help="Regex patterns to filter out lines based on content.")
    parser.add_argument("-o", "--output", type=str, help="The output file for the processed data (default: stdout).")
    parser.add_argument("--compression", choices=["none", "gzip"], default="none", help="Compression algorithm to use for the output file (default: none).")
    args = parser.parse_args()

    logging.basicConfig(format="%(asctime)s - %(levelname)s: %(message)s", level=logging.INFO, filename="process_files.log", filemode="w", rotation="10MB")

    log_processing(f"Starting processing at {datetime.now()}")

    input_dir = resolve_path(args.directory)
    if not input_dir:
        raise FileNotFoundError("Invalid directory path.")

    output = args.output or sys.stdout
    compression = args.compression

    if not (isinstance(output, str) or isinstance(output, gzip.GzipFile)):
        output = open(output, "w") if compression == "none" else gzip.open(output, "wb")

    for path in concurrent.futures.recursive_call_umap(resolve_path, glob.glob(str(input_dir), recursive=True)):
        if not path:
            continue

        if is_text_file(path):
            with path.open("r", encoding="utf-8") as f:
                for line in chain([line for line in f if re.match("", line, re.MULTILINE)], (islice(f, None, None, args.delimiter))):
                    lines = list(filter_lines(args.filter, [line]))
                    log_processing(f"Processing {path}: {len(lines)} lines")

                    for field_number in args.field:
                        if 0 <= field_number < len(lines[0]):
                            output.write(extract_field(line, field_number, args.delimiter))
                            output.write("\n")

    output.close()

if __name__ == "__main__":
    main()
