struct cache* create_cache(size_t max_offset, size_t max_keys) {
    struct cache *cache = malloc(sizeof(struct cache));
    if (!cache) return NULL;
    cache->max_offset = max_offset;
    cache->max_keys = max_keys;
    cache->num_keys = 0;
    pthread_mutex_init(&cache->lock, NULL);
    cache->records = calloc(5 * max_keys, sizeof(record));
    if (!cache->records) {
        free(cache);
        return NULL;
    }
    cache->offsets = malloc(max_offset * sizeof(long));
    if (!cache->offsets) {
        free(cache->records);
        free(cache);
        return NULL;
    }
    cache->keys = malloc(max_keys * sizeof(int));
    if (!cache->keys) {
        free(cache->offsets);
        free(cache->records);
        free(cache);
        return NULL;
    }
    return cache;
}

long get_offset(struct cache* cache, int key) {
    pthread_mutex_lock(&cache->lock);
    size_t i = key % cache->num_keys;
    while (cache->records[i].key == key && i < cache->num_keys) {
        if (cache->records[i].offset > 0 && cache->records[i].timestamp + 60 * 60 * 24 < time(NULL)) {
            // reclaim expired record
            cache->records[i].key = -1;
            cache->records[i].offset = 0;
        }
        i = (i + 1) % cache->num_keys;
    }
    if (cache->records[i].key == -1 || cache->records[i].key != key) {
        if (i < cache->num_keys) cache->records[i] = (record){.key = key, .offset = 0, .timestamp = time(NULL)};
        size_t offset = cache->num_keys < cache->max_offset ? cache->offsets[cache->num_keys++] : find_free_offset(cache);
        if (offset == -1) {
            // handle insufficient memory
            printf("Out of memory\n");
            return -1;
        }
        cache->records[i].key = key;
        cache->records[i].offset = offset;
    }
    long ret = cache->offsets[cache->records[i].offset];
    if (ret == 0 && cache->num_keys < cache->max_keys / 2) rehash(cache); // maintain even distribution
    pthread_mutex_unlock(&cache->lock);
    return ret;
}

long* allocate_pdus(size_t N, struct cache *cache) {
    long *pdus = malloc(N * sizeof(long));
    if (!pdus) return NULL;
    for (size_t i = 0; i < N; ++i) pdus[i] = get_offset(cache, i);
    return pdus;
}

void deallocate_pdus(long *pdus, size_t N, struct cache *cache) {
    for (size_t i = 0; i < N; ++i) {
        long offset = pdus[i];
        if (offset >= 0) {
            cache->records[find_index(cache, offset)].key = -1;
            cache->records[find_index(cache, offset)].offset = 0;
            cache->offsets[offset] = 0;
        }
    }
    free(pdus);
}

// Helper functions for finding a free offset within the specified range
long find_free_offset(struct cache *cache) {
    for (size_t i = 0; i < cache->max_offset; ++i) {
        if (!cache->offsets[i]) return i;
    }
    return -1;
}

size_t find_index(struct cache* cache, long offset) {
    for (size_t i = 0; i < cache->num_keys; ++i) {
        if (cache->records[i].offset == offset) return i;
    }
    return -1;
}

void rehash(struct cache *cache) {
