    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot prepare statement: %s\n", sqlite3_errmsg(db));
        exit(EXIT_FAILURE);
    }

    rc = sqlite3_step(stmt);
    if (rc == SQLITE_ROW) {
        uint32_t id = sqlite3_column_int(stmt, 0);
        return htonl(id + 1);
    } else if (rc != SQLITE_DONE) {
        fprintf(stderr, "Preparation failed: %s\n", sqlite3_errmsg(db));
        exit(EXIT_FAILURE);
    }

    return htonl(0);
}

