        {"concurrent", no_argument, NULL, 'C'},
        {0, 0, 0, 0}
    };

    while ((opt = getopt_long(argc, argv, "hho:a::c::s:C", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                usage();
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'a':
                append = 1;
                break;
            case 'c':
                non_empty_lines = 1;
                break;
            case 's':
                sscanf(optarg, "%d", &size_limit);
                break;
            case 'C':
                concurrent = 1;
                break;
            default:
                usage();
        }
