        if (input_file == NULL)
            print_usage("Error: No input file provided.");
        else
            usage();
    }

    input_file = argv[optind];

    int fd = open(input_file, O_RDONLY);
    if (fd < 0)
        err(1, "open");

    if (fstat(fd, &file_stat) < 0)
        err(1, "fstat");

    mapped_size = file_stat.st_size;
    mmaped_buffer = mmap(NULL, mapped_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (mmaped_buffer == MAP_FAILED)
        err(1, "mmap");

    char *line = calloc(BUFFER_SIZE, sizeof(char));
    int line_count = 0;

    for (off_t i = 0; i < mapped_size; i += BUFFER_SIZE) {
        memmove(line, mmaped_buffer + i, BUFFER_SIZE > (mapped_size - i) ? (mapped_size - i) : BUFFER_SIZE, 0);
        line[BUFFER_SIZE - 1] = '\0';

        char *next_line = strchr(line, '\n');
        if (!next_line) next_line = line + strlen(line);

        int is_nonempty = next_line != line;
        if (is_nonempty && !non_empty_lines) line_count++;

        if (next_line < line + BUFFER_SIZE) {
            memmove(line, next_line + 1, strlen(next_line + 1));
            free(line + strlen(next_line + 1));
        }
    }

    close(fd);
    munmap(mmaped_buffer, mapped_size);

    if (output_file) {
        int ofd = open(output_file, append ? O_WRONLY | O_APPEND : O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IXUSR);
        if (ofd < 0)
            err(1, "open");

        // Implement logging and other features here...

        fprintf(stdout, "Lines in file: %d\n", line_count);
    } else {
        fprintf(stdout, "Lines in file: %d\n", line_count);
    }

    return 0;
}

void usage(const char *message) {
    if (message) printf("%s\n", message);
    printf("Usage: %s [options] input_file\n", argv[0]);
    printf("\t--manpage            Display this help information.\n");
    printf("\t-o output_file       Redirect output to a specified file. Use --append to append data.\n");
