#define MAX_LINE_LENGTH 1024
#define BUFFER_SIZE (MAX_LINE_LENGTH * 16) // 16KB buffer for lines up to 1024 characters each

static int line_count = 0;
static int suppress_line_count = 0;
static char keyword[] = "error";
static int keyword_positions[1024];
static int num_keywords = 0;
static FILE *input_file = stdin;
static char *output_file = NULL;

void die(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

size_t read_line(FILE *stream, char *buffer, size_t buf_size) {
    size_t pos = 0;
    int c;

    while ((c = fgetc(stream)) != EOF && pos < buf_size - 1) {
        buffer[pos++] = (char)c;
        if (c == '\n') break;
    }

    if (pos > 0 && c == EOF) {
        // The input stream was at eof and we read a line. Add a newline character.
        buffer[--pos] = '\n';
        pos++;
    }

    buffer[pos] = '\0';
    return pos;
}

int main(int argc, char **argv) {
    int opt;
    const char *const short_opts = "mho:";
    const struct option long_opts[] = {
        {"manpage", no_argument, NULL, 'm'},
        {"no-count", no_argument, NULL, 'c'},
        {"output", required_argument, NULL, 'o'},
        {0, 0, 0, 0}
    };

    while ((opt = getopt_long(argc, argv, short_opts, long_opts, NULL)) != -1) {
        switch (opt) {
            case 'm':
                fprintf(stdout, "Usage: %s [OPTIONS] input_file\n"
                                "\n"
                                "Parse an input file and perform the following operations:\n"
                                "1. Count the number of lines and print this count.\n"
                                "2. For each line, check if it contains a specific keyword (e.g., 'error') and record its position in the file.\n"
                                "3. Print a summary of these keywords found, including their line numbers and positions within those lines.\n\n"
                                "\n"
                                "-cs : Suppress the display of the total line count.\n"
                                "-o output_file : Redirect the output to a specified file instead of the console.\n", argv[0]);
                return EXIT_SUCCESS;
            case 'c':
                suppress_line_count = 1;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                die("Invalid option");
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "Error: Missing input file\n");
        return EXIT_FAILURE;
    }

    int fd = open(argv[optind], O_RDONLY);
    if (fd == -1) die("Failed to open input file");

    input_file = fdopen(fd, "r");
    if (!input_file) die("Could not create file stream from the opened file");

    char line[MAX_LINE_LENGTH];
    size_t len;

    while ((len = read_line(input_file, line, sizeof(line))) > 0) {
        line_count++;
        if (!suppress_line_count && !line_count % 100000) printf("%d lines processed\n", line_count);

        if (strstr(line, keyword)) {
            int pos = strchr(line, keyword[0]) - line;
            if (pos < num_keywords * sizeof(int)) {
                memcpy(&keyword_positions[num_keywords], &pos, sizeof(int));
            } else {
                keyword_positions[num_keywords++] = pos;
            }
        }
    }

    if (!suppress_line_count) printf("Total lines: %d\n", line_count);

    printf("\nKeywords found:\n");
    for (int i = 0; i < num_keywords; ++i) {
        printf("%2d: %s at position %d\n", i + 1, keyword, keyword_positions[i]);
    }

    if (output_file) {
        FILE *out_file = fopen(output_file, "w");
        if (!out_file) die("Failed to open output file for writing");

        fprintf(out_file, "%s", ""); // Flush the buffer to ensure all output is written.
        fclose(out_file);
    }

    return EXIT_SUCCESS;
}
