public:
    UserListManager(size_t initialCapacity) : m_activeUsers(initialCapacity), m_mutex() {}

    void addUser() {
        if (m_activeUsers.size() >= m_capacity) {
            growCapacity();
        }
        NFAPI_CRC_INDICATION_PDU_T* user = &m_activeUsers.back();
        new(user) NFAPI_CRC_INDICATION_PDU_T();
