        std::unique_lock<std::mutex> lock(m_mutex);
        if (index >= m_activeUsers.size()) {
            throw std::out_of_range("Index out of range");
        }
        auto it = m_activeUsers.begin();
        std::advance(it, index);
        user_deleter{}((NFAPI_CRC_INDICATION_PDU_T*)it);
        m_activeUsers.erase(it);
    }

    const NFAPI_CRC_INDICATION_PDU_T& getUser(size_t index) const {
        std::unique_lock<std::mutex> lock(m_mutex);
        if (index >= m_activeUsers.size()) {
            throw std::out_of_range("Index out of range");
        }
        return m_activeUsers[index];
