public class RandomValueGenerator {
    private readonly Random _random;
    private readonly float _min, _max;
    private int _seed;

    public RandomValueGenerator(float min, float max, int seed) {
        _min = min;
        _max = max;
        _seed = seed;
        _random = new Random(_seed);
    }

    public float NextFloat() => _random.NextDouble() * (_max - _min) + _min;
    public int NextInt(int min, int max, bool inclusive = true) {
        int rangeSize = (inclusive ? max : max - min) + 1;
        return _random.Next(rangeSize) + (min - (rangeSize > 2 ? min % rangeSize : 0));
    }
}
