```c
// Implementation of init_measurement_reports()
MeasurementReports* init_measurement_reports(void) {
    MeasurementReports* reports = malloc(sizeof(MeasurementReports));
    if (!reports) return NULL;

    // Initialize mutex and set default values for capacity, size, head, and next pointers
    pthread_mutex_init(&reports->lock, NULL);
    reports->capacity = 8;
    reports->size = 0;
    reports->head = -1;
    reports->data = calloc(reports->capacity, sizeof(struct MeasurementReport*));
    if (!reports->data) {
        free(reports);
        return NULL;
    }

    return reports;
}

// Implementation of add_measurement_report()
bool add_measurement_report(MeasurementReports* reports, struct MeasurementReport* measurement) {
    if (!reports || !measurement) return false;

    pthread_mutex_lock(&reports->lock);

    if (reports->size == reports->capacity) resize_measurement_reports(reports);

    struct MeasurementReport** current = &reports->data[reports->head];
    while (*current != NULL && (*current)->timestamp < measurement->timestamp) {
        current = &(*current)->next;
    }

    measurement->next = *current;
    *current = measurement;
    if (reports->head == -1) reports->head = 0;
    ++reports->size;

    pthread_mutex_unlock(&reports->lock);

    return true;
}

// Implementation of resize_measurement_reports()
void resize_measurement_reports(MeasurementReports* reports) {
    if (!reports) return;

    pthread_mutex_lock(&reports->lock);

    struct MeasurementReport** new_data = realloc(reports->data, (reports->capacity * 2) * sizeof(struct MeasurementReport*));
    if (!new_data) {
        pthread_mutex_unlock(&reports->lock);
        return;
    }

    reports->capacity *= 2;
    reports->data = new_data;
    pthread_mutex_unlock(&reports->lock);
}
