};

CircularQueue cq = {NULL, NULL, NULL, 0};

pthread_mutex_t memPoolMutex = PTHREAD_MUTEX_INITIALIZER;

NR_FRAGMETN_TNL_PDU_T* allocate_memory(size_t num) {
    void *memPool = mmap(NULL, sizeof(NR_FRAGMETN_TNL_PDU_T) * num, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (memPool == MAP_FAILED) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        return NULL;
    }
    return memPool;
}

void free_memory(void *ptr, size_t num) {
    munmap(ptr, sizeof(NR_FRAGMETN_TNL_PDU_T) * num);
}

void enqueue(CircularQueue *cq, void *data) {
    CircularQueueNode *node = (CircularQueueNode *)malloc(sizeof(CircularQueueNode));
    node->data = data;
    node->next = NULL;

    pthread_mutex_lock(&memPoolMutex);
    if (!cq->front) { // Queue is empty
        cq->front = node;
        cq->rear = node;
        cq->tail = node;
    } else {
        cq->rear->next = node;
        cq->rear = node;
    }
    cq->size++;
    pthread_mutex_unlock(&memPoolMutex);
}

void dequeue(CircularQueue *cq) {
    if (cq->front) {
        CircularQueueNode *temp = cq->front;
        cq->front = cq->front->next;
        free(temp);
        cq->size--;
    }
}

NR_FRAGMETN_TNL_PDU_T* create_struct(uint32_t pdu_session_id, uint32_t sessid, PDU_T tnl_pdu) {
    NR_FRAGMETN_TNL_PDU_T *new_struct = malloc(sizeof(NR_FRAGMETN_TNL_PDU_T));
