NR_FRAGMETN_TNL_PDU_T* get_next_free() {
    pthread_mutex_lock(&memPoolMutex);
    if (cq.front) {
        void *data = cq.front->data;
        CircularQueueNode *temp = cq.front;
        cq.front = cq.front->next;
        cq.size--;
        pthread_mutex_unlock(&memPoolMutex);
        return data;
    } else {
        void *new_memory = allocate_memory(CQ_SIZE);
        if (!new_memory) {
            pthread_mutex_unlock(&memPoolMutex);
            return NULL;
        }
        for (size_t i = 0; i < CQ_SIZE; ++i) {
            NR_FRAGMETN_TNL_PDU_T *new_struct = new_memory + i;
            if (!create_struct(new_struct->PDU_SESSION_ID, i+1, new_struct->TNL_PDU_T)) {
