static pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_instance(size_t index) {
    if (index >= MAX_RATIOS) return;

    instances[index].capacity = INITIAL_CAPACITY;
    instances[index].count = 0;
    instances[index].data = calloc(instances[index].capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!instances[index].data) {
        log_error("Failed to allocate memory for instance %zu", index);
        return;
    }

    pthread_mutex_init(&instances[index].mutex, NULL);
}

Instance* get_instance(size_t index) {
    if (index >= MAX_RATIOS || total_structures + instances[index].capacity > MAX_STRUCTURES) return NULL;

    pthread_mutex_lock(&global_mutex);
    if (!instances[index].count) {
        init_instance(index);
    }
    Instance* instance = &instances[index];
    pthread_mutex_unlock(&global_mutex);

    return instance;
}

void resize_instance(Instance* instance, size_t new_capacity) {
    if (new_capacity <= instance->count || new_capacity > MAX_RESIZE_CAPACITY) return;

    NFAPI_CRC_INDICATION_PDU_T* temp = calloc(new_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        log_error("Failed to reallocate memory for instance");
        return;
    }

    memcpy(temp, instance->data, instance->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(instance->data);

    pthread_mutex_lock(&instance->mutex);
    instance->capacity = new_capacity;
    instance->data = temp;
    pthread_mutex_unlock(&instance->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* add_pdu(Instance* instance) {
    if (!instance) return NULL;

    pthread_mutex_lock(&instance->mutex);
    if (instance->count == instance->capacity) resize_instance(instance, instance->capacity * 2);

    NFAPI_CRC_INDICATION_PDU_T* pdu = &instance->data[instance->count];
    pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG_VALUE;
