    pdu->crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG_VALUE;
    pdu->crcflag = rand() % 2; // Randomly set crcflag

    instance->count++;
    total_structures++;

    pthread_mutex_unlock(&instance->mutex);
    return pdu;
}

void cleanup(Instance* instance) {
    if (!instance) return;

    pthread_mutex_lock(&instance->mutex);
    free(instance->data);
    instance->data = NULL;
    instance->capacity = 0;
    instance->count = 0;
    pthread_mutex_unlock(&instance->mutex);
}

void cleanup_instances() {
    pthread_mutex_lock(&global_mutex);
    for (size_t i = 0; i < MAX_RATIOS; ++i) {
        if (!instances[i].count) continue;

        cleanup(&instances[i]);
    }
    total_structures = 0;
    pthread_mutex_unlock(&global_mutex);
}
