int initializeLTEUEContextsWithCRCIndications(struct userData*, int N, LTEUEContext** contexts, const Configuration* config) {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    pthread_attr_t attr;

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);
    pthread_attr_init(&attr);

    pthread_setconcurrency_max(MAX_RATIOS);

    int instances = 0;
    LTEUEContext** contextsPerInstance = malloc(MAX_RATIOS * sizeof(LTEUEContext*));
    if (!contextsPerInstance) {
        perror("Memory allocation failure");
        return NULL;
    }

    for (int i = 0; i < MAX_RATIOS; ++i) {
        contextsPerInstance[i] = malloc(N * sizeof(LTEUEContext));
        if (!contextsPerInstance[i]) {
            perror("Memory allocation failure");
            for (int j = 0; j < i; ++j)
                free(contextsPerInstance[j]);
            free(contextsPerInstance);
            return NULL;
        }
    }

    BinaryFormatter formatter;
    if (!initializeBinaryFormatter(&formatter, config->binaryFilePath)) {
        perror("Failed to initialize BinaryFormatter");
        for (int i = 0; i < MAX_RATIOS; ++i) {
            free(contextsPerInstance[i]);
        }
        free(contextsPerInstance);
        return NULL;
    }

    int loadedCount = 0;
    LTEUEContext* currentContext = NULL;
    void* deserializedData = malloc(config->maxMemoryUsageLimit * sizeof(LTEUEContext));
    if (!deserializedData) {
        perror("Memory allocation failure");
        destroyBinaryFormatter(&formatter);
        for (int i = 0; i < MAX_RATIOS; ++i) {
            free(contextsPerInstance[i]);
        }
        free(contextsPerInstance);
        return NULL;
    }

    while ((loadedCount < N) && !feof(formatter.file)) {
        void* data = deserialize(&formatter, deserializedData + loadedCount * sizeof(LTEUEContext));
        if (data) {
            currentContext = (LTEUEContext*)((char*)deserializedData + loadedCount * sizeof(LTEUEContext));
            ++loadedCount;

            currentContext->UECID = loadedCount;
            currentContext->UCD.BWP = rand() % config->BWP_limits[1] + config->BWP_limits[0];
            // Fill in other UCD parameters

            int instanceIndex = instances % MAX_RATIOS;
            currentContext->crcIndications = contextsPerInstance[instanceIndex][currentContext->UECID];
            if (!currentContext->crcIndications) {
                currentContext->crcIndications = malloc(config->numberOfCRCStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!currentContext->crcIndications) {
                    perror("Memory allocation failure");
                    free(deserializedData);
                    destroyBinaryFormatter(&formatter);
                    for (int i = 0; i < MAX_RATIOS; ++i) {
                        if (i != instanceIndex)
                            free(contextsPerInstance[i][currentContext->UECID]);
                    }
                    return NULL;
                }
            }

