            if (i != instances % MAX_RATIOS)
                free(contextsPerInstance[i]);
        }
        free(contextsPerInstance);
        return NULL;
    }

    for (int i = 0; i < instances; ++i)
        (*contexts)[i] = contextsPerInstance[(i % MAX_RATIOS)][i];

    for (int i = 0; i < MAX_RATIOS; ++i) {
        if (i != instances % MAX_RATIOS)
            free(contextsPerInstance[i]);
    }
    free(contextsPerInstance);

    return contexts;
}
