    return 0;
}

void tearDownInstance() {
    if (--instance_count == 0) {
        free(resource_pool);
    }
}

RESOURCE_BLOCK* getResource(int priority) {
    RESOURCE_BLOCK* resource = NULL;
    pthread_mutex_lock(&resource_pool_lock);

    // Implement custom authentication mechanism to validate session tokens here

    while (resource_count >= MAX_POOL_SIZE || resource_count > GLOBAL_RESOURCE_CAP) {
        pthread_cond_wait(&resource_available, &resource_pool_lock);
    }

    time_t now = time(NULL);
    for (int i = 0; i < MAX_POOL_SIZE; ++i) {
        if (!resource_pool[i].is_valid && resource_pool[i].priority == priority) {
            resource = &resource_pool[i];
            resource->last_used = now;
            resource->is_valid = true;
            resource_count++;
            break;
        }
    }

    if (resource == NULL) {
        // Resource not found, create a new one with the given priority level
        for (int i = 0; i < MAX_POOL_SIZE; ++i) {
            if (!resource_pool[i].is_valid && resource_pool[i].priority == priority) {
                resource = &resource_pool[i];
                resource->last_used = now;
                resource->is_valid = true;
                resource->bandwidth = 100;
                resource->latency = 10;
                resource->priority = priority;
                resource_count++;
                break;
            }
        }
    }

    pthread_mutex_unlock(&resource_pool_lock);

    // Schedule the resource allocation with the scheduling library here

    return resource;
}

void releaseResource(RESOURCE_BLOCK* resource) {
    pthread_mutex_lock(&resource_pool_lock);

    if (!resource || !resource->is_valid) {
        pthread_mutex_unlock(&resource_pool_lock);
        return;
    }

    resource->is_valid = false;
    resource_count--;

    // Schedule the resource deallocation with the scheduling library here

    if (time(NULL) - resource->last_used > 60 * 5) { // Clean up unused resources after 5 minutes of inactivity
        free(resource);
    } else {
        pthread_cond_signal(&resource_available);
    }

    pthread_mutex_unlock(&resource_pool_lock);
}
