typedef struct MAC_PDU {
    unsigned int LCID;
    uint16_t SEQ_NUMBER;
    uint16_t SDU_LENGTH;
} MAC_PDU;

struct instance {
    MAC_PDU* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
};

struct global {
    struct instance instances[MAX_INSTANCES];
    size_t total_count;
    size_t free_list_head;
    pthread_mutex_t memory_lock;
};

static struct global g_global = {};

void* allocate_memory(size_t size) {
    void* result = malloc(size);
    if (!result) {
        log_error("Memory allocation failure");
        return NULL;
    }
    return result;
}

void deallocate_memory(void** ptr) {
    free(*ptr);
    *ptr = NULL;
}

int is_valid_seq_number(unsigned short seq_number) {
    return (seq_number >= 1 && seq_number <= 0xFFFF);
}

struct instance* get_instance(size_t index) {
    if (index >= MAX_INSTANCES) {
        log_error("Invalid instance index");
        return NULL;
    }
    return &g_global.instances[index];
}

void clean_unused_memory() {
    pthread_mutex_lock(&g_global.memory_lock);
    for (size_t i = 0; i < MAX_INSTANCES; ++i) {
        struct instance* inst = &g_global.instances[i];
        if (inst->count == 0) {
            MAC_PDU* data = inst->data;
            size_t capacity = inst->capacity;
            inst->data = NULL;
            inst->capacity = 0;
            deallocate_memory((void**)&data);
        }
    }
    pthread_mutex_unlock(&g_global.memory_lock);
}

MAC_PDU* create_mac_pdu(unsigned int lcid, unsigned short seq_number) {
    if (!is_valid_seq_number(seq_number)) {
        log_error("Invalid SEQ_NUMBER");
        return NULL;
    }

    MAC_PDU* mac_pdu = (MAC_PDU*)allocate_memory(sizeof(MAC_PDU));
    if (!mac_pdu) {
        log_error("Memory allocation failure for MAC_PDU");
        return NULL;
    }

    mac_pdu->LCID = lcid;
    mac_pdu->SEQ_NUMBER = seq_number;
    mac_pdu->SDU_LENGTH = rand() % 1024 + 1; // Generate a random SDU_LENGTH value within the valid range (1-1024)

    return mac_pdu;
}

void destroy_mac_pdu(MAC_PDU* mac_pdu) {
    deallocate_memory((void**)&mac_pdu);
}

struct instance* create_instance() {
    struct instance* inst = NULL;

    // Find an empty instance or get from the free list
    pthread_mutex_lock(&g_global.memory_lock);
    for (size_t i = 0; i < MAX_INSTANCES; ++i) {
        if (g_global.instances[i].count == 0) {
            inst = &g_global.instances[i];
            break;
        }
    }

    if (!inst) { // No empty instance found, allocate a new one and add to the free list
        inst = get_instance(g_global.free_list_head);
        if (inst->data) {
            size_t capacity = inst->capacity;
            MAC_PDU* data = inst->data;
            inst->count = capacity;
            inst->data = NULL;
            inst->capacity = 0;
            // Add this instance to the free list, wrapping around if necessary
            g_global.free_list_head = (g_global.free_list_head + 1) % MAX_INSTANCES;
        } else { // Allocate a new instance
            inst->data = (MAC_PDU*)allocate_memory(sizeof(MAC_PDU) * INITIAL_CAPACITY);
            if (!inst->data) {
                log_error("Memory allocation failure for instance data");
                pthread_mutex_unlock(&g_global.memory_lock);
                return NULL;
            }
            inst->capacity = INITIAL_CAPACITY;
            inst->count = 0;
            // Add this new instance to the free list, wrapping around if necessary
            g_global.free_list_head = (g_global.free_list_head + 1) % MAX_INSTANCES;
        }
    }

    pthread_mutex_init(&inst->lock, NULL);
    clean_unused_memory();
    return inst;
}

void destroy_instance(struct instance* inst) {
    deallocate_memory((void**)&inst->data);
    inst->capacity = 0;
    inst->count = 0;
    pthread_mutex_destroy(&inst->lock);
}

MAC_PDU* add_to_instance(struct instance* inst, MAC_PDU* mac_pdu) {
    pthread_mutex_lock(&inst->lock);
    if (inst->count >= inst->capacity) { // Resize the array if necessary
        MAC_PDU* new_data = (MAC_PDU*)realloc(inst->data, sizeof(MAC_PDU) * (inst->capacity * 2));
        if (!new_data) {
            log_error("Memory allocation failure while resizing instance data");
            pthread_mutex_unlock(&inst->lock);
            return NULL;
        }
        inst->data = new_data;
        inst->capacity *= 2;
    }
    inst->data[inst->count++] = mac_pdu;
    pthread_mutex_unlock(&inst->lock);
    return mac_pdu;
}
