    resource_pool.count = 0;
    resource_pool.threads = malloc(resource_pool.capacity * sizeof(ThreadData));
    pthread_mutex_init(&resource_lock, NULL);

    int chunk_size = array_size / resource_pool.capacity;
    for (int i = 0; i < resource_pool.capacity; ++i) {
        acquire_resource();
        ThreadData* thread = &resource_pool.threads[i];
        thread->session_token = malloc(sizeof(char));

        int start = chunk_size * i + (i < chunk_size ? 0 : -chunk_size);
        int end = (i < chunk_size) ? start + chunk_size : start + array_size;
        if (pthread_create(&thread->thread_id, NULL, &thread_function, thread)) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }

        if (i < chunk_size) continue;

        int sum = initial_value;
        for (int j = start; j < end; ++j) {
            sum = reduce_callback(sum, array[j]);
        }

        pthread_mutex_lock(&resource_lock);
        release_resource(&resource_pool.threads[i]);
        pthread_mutex_unlock(&resource_lock);
    }

    for (int i = 0; i < resource_pool.capacity; ++i) {
        ThreadData* thread = &resource_pool.threads[i];
        if (pthread_join(thread->thread_id, NULL)) {
            perror("pthread_join");
            exit(EXIT_FAILURE);
        }

        release_resource(thread);
    }

    pthread_mutex_destroy(&resource_lock);
    free(resource_pool.threads);
}
