typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    bool crc_indication_flag;
    uint16_t crc_indication_rel8_tag;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

static sem_t lock;
static int num_ue_ids = 0;
static NFAPI_CRC_INDICATION_PDU_T** ue_pdu_list;
static bool* crc_validity;

void init() {
    sem_init(&lock, 0, 1);
}

void destroy() {
    for (int i = 0; i < num_ue_ids; ++i) {
        free(ue_pdu_list[i]);
    }
    free(ue_pdu_list);
    free(crc_validity);
    sem_destroy(&lock);
}

void append_ue_id(int ue_id, bool* success) {
    if (num_ue_ids >= 10000) {
        *success = false;
        return;
    }

    sem_wait(&lock);

    NFAPI_CRC_INDICATION_PDU_T* new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        *success = false;
        sem_post(&lock);
        return;
    }

    time_t current_time = time(NULL);
    new_pdu->rx_ue_information_tag = ue_id;
    new_pdu->rnti = ue_id * 100 + num_ue_ids;
    new_pdu->crc_indication_flag = rand() % 2 == 0 ? true : false;
    new_pdu->crc_indication_rel8_tag = (new_pdu->rnti << 3) | (new_pdu->crc_indication_flag ? 1 : 0);
    new_pdu->timestamp = current_time;

    ue_pdu_list[num_ue_ids] = new_pdu;
    crc_validity[num_ue_ids] = validate_crc(new_pdu);

    num_ue_ids++;
    sem_post(&lock);
    *success = true;
}

bool validate_crc(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    uint16_t calculated_crc = ((pdu->rnti >> 3) ^ (pdu->timestamp & 0xFFFF)) & 1;
    return pdu->crc_indication_rel8_tag == ((pdu->rnti << 3) | calculated_crc);
}

// Example of using the function in a thread-safe manner.
void generate_pdus(int num_ue_ids, void (*log_error)(char*, ...)) {
    bool* success = malloc(num_ue_ids * sizeof(bool));

    pthread_t threads[num_ue_ids];
    for (int i = 0; i < num_ue_ids; ++i) {
        if (pthread_create(&threads[i], NULL, append_ue_id_wrapper, &i)) {
            log_error("Failed to create thread.");
        }
    }

    for (int i = 0; i < num_ue_ids; ++i) {
        pthread_join(threads[i], NULL);
        if (!success[i]) {
            log_error("Failed to append UE ID %d.", i);
        }
    }

    free(success);
}

void* append_ue_id_wrapper(void* arg) {
    int ue_id = *(int*)arg;
    bool success;

    generate_pdus(1, (void (*)(char*, ...))log_error);

    if (!append_ue_id(ue_id, &success)) {
        log_error("Failed to append UE ID %d.", ue_id);
    }

    return NULL;
}
```

