#include <stdbool.h>

// External API configuration structure
typedef struct {
    const char* api_key;
    const char* log_level;
    size_t max_buffer_size;
    int network_interface_id;
} Config;

// Custom memory pool structure
typedef struct MemoryPool {
    void** elements;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    semaphore_t free_semaphore;
} MemoryPool;

// UE signal structure
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint64_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    time_t timestamp;
    uint32_t seed;
    bool valid; // Validation flag
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a unique seed
uint32_t generate_seed(void) {
    static uint64_t last_seed = 0;
    return (uint32_t)((last_seed++ << 16) | time(NULL));
}

// Thread-safe memory pool functions
MemoryPool* create_memory_pool(size_t capacity) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->elements = malloc(capacity * sizeof(void*));
    if (!pool->elements) goto error;

    pool->capacity = capacity;
    pool->count = 0;
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
    sem_init(&pool->free_semaphore, 0, capacity);

    return pool;
error:
    free(pool);
    return NULL;
}

void* memory_pool_alloc(MemoryPool* pool) {
    void* element = NULL;
    sem_wait(&pool->free_semaphore);

    pthread_mutex_lock(&pool->lock);
    if (pool->count < pool->capacity) {
        element = pool->elements[pool->count++];
    }
    pthread_mutex_unlock(&pool->lock);

    return element;
}

void memory_pool_free(MemoryPool* pool, void* element) {
    pthread_mutex_lock(&pool->lock);
    if (element) {
        pool->elements[--pool->count] = element;
    }
    sem_post(&pool->free_semaphore);
    pthread_mutex_unlock(&pool->lock);
}

// Function to initialize UE signal list
void init_ue_signals(NFAPI_CRC_INDICATION_PDU_T** ue_signals, size_t N, Config* config) {
    MemoryPool* memory_pool = create_memory_pool(config->max_buffer_size);

    for (size_t i = 0; i < N; ++i) {
        void* ue_signal = memory_pool_alloc(memory_pool);
        if (!ue_signal) continue; // Skip if memory allocation fails

        NFAPI_CRC_INDICATION_PDU_T* ue_signal_data = ue_signal;
        *ue_signals = ue_signal_data;

        // Generate unique tags, timestamp, and seed for this UE signal
        ue_signal_data->RX_UE_INFORMATION_TAG = i;
        ue_signal_data->RNTI = generate_seed();
        ue_signal_data->CRC_INDICATION_REL8_TAG = generate_seed();
        ue_signal_data->timestamp = time(NULL);
        ue_signal_data->seed = generate_seed();
    }

    // Free any remaining memory in the pool
    for (size_t i = N; i < memory_pool->capacity; ++i) {
        void* element = memory_pool_alloc(memory_pool);
        if (!element) break; // Stop if memory deallocation fails

        memory_pool_free(memory_pool, element);
    }

    free(memory_pool->elements);
    free(memory_pool);
}
