struct instance {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t length;
};

static struct instance* instances = NULL;
static size_t num_instances = 0;
static size_t max_ratios = 0;
static size_t total_capacity = 0;
static pthread_mutex_t global_lock;

void nfapi_crc_indication_pdu_init() {
    if (instances) return; // Already initialized

    pthread_mutex_init(&global_lock, NULL);
}

void nfapi_crc_indication_pdu_deinit() {
    for (size_t i = 0; i < num_instances; ++i) {
        free(instances[i].data);
    }
    free(instances);

    pthread_mutex_destroy(&global_lock);
}

void* create_instance(size_t ratio) {
    if (num_instances + 1 > max_ratios) return NULL; // No more instances allowed

    struct instance* new_instance = calloc(ratio, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_instance) return NULL;

    pthread_mutex_init(&new_instance->lock, NULL);

    total_capacity += ratio;
    instances = realloc(instances, (num_instances + 1) * sizeof(struct instance));
    if (!instances) {
        free(new_instance);
        return NULL;
    }
    instances[num_instances++] = new_instance;

    return new_instance;
}

NFAPI_CRC_INDICATION_PDU_T* get_ue_crc_indication_pdu(struct instance* instance, RNTI rnti) {
