    ue_crc_indication->crcflag = rand() % 256; // CRC Flag must be less than 256
    ue_crc_indication->timestamp = time(NULL);

    instance->length++;

    pthread_mutex_unlock(&instance->lock);
    return ue_crc_indication;
}

void check_and_cleanup() {
    pthread_mutex_lock(&global_lock);

    for (size_t i = 0; i < num_instances; ++i) {
        if (instances[i]->length == 0 && !instances[i]->capacity) {
            free(instances[i]);
            instances[i] = instances + --num_instances;
        }
    }

    pthread_mutex_unlock(&global_lock);
}

