void initMemoryPool(size_t capacity) {
    timerMemPool.freeList = calloc(capacity, sizeof(LTEPHYTIMER));
    if (!timerMemPool.freeList) {
        fprintf(stderr, "Failed to allocate memory for timer pool\n");
        exit(EXIT_FAILURE);
    }

    timerMemPool.capacity = capacity;
    timerMemPool.used = 0;
}

LTEPHYTIMER* getTimerFromPool() {
    pthread_mutex_lock(&memPoolMutex);
    LTEPHYTIMER *timer = (LTEPHYTIMER*) timerMemPool.freeList;
    if (timer) {
        timerMemPool.freeList = *(LTEPHYTIMER**) ((char*) timer + sizeof(LTEPHYTIMER));
        --timerMemPool.used;
    }
    pthread_mutex_unlock(&memPoolMutex);
    return timer;
}

void freeTimerToPool(LTEPHYTIMER *timer) {
    pthread_mutex_lock(&memPoolMutex);
    *(LTEPHYTIMER**) ((char*) timer + sizeof(LTEPHYTIMER)) = &timerMemPool.freeList;
    timerMemPool.used++;
    if (timerMemPool.used >= timerMemPool.capacity / 2) {
        // Reallocate memory to prevent memory fragmentation when the pool is nearly full
        void *newFreeList = realloc(timerMemPool.freeList, timerMemPool.capacity * 2 * sizeof(LTEPHYTIMER));
        if (!newFreeList) {
            fprintf(stderr, "Failed to reallocate memory for timer pool\n");
            exit(EXIT_FAILURE);
        }
        timerMemPool.freeList = newFreeList;
    }
    pthread_mutex_unlock(&memPoolMutex);
}

