}

void initLteTimers(size_t numTimers, void (*timerCallback)(LTEPHYTIMER*)) {
    pthread_mutex_init(&memPoolMutex, NULL);
    initMemoryPool(NUM_TIMERS);

    LTEPHYTIMER *timers = malloc(numTimers * sizeof(LTEPHYTIMER));
    if (!timers) {
        fprintf(stderr, "Failed to allocate memory for timers\n");
        exit(EXIT_FAILURE);
    }

    size_t timerIndex = 0;
    for (size_t i = 0; i < numTimers; ++i) {
        LTEPHYTIMER *timer = getTimerFromPool();
        if (!timer) {
            fprintf(stderr, "Out of memory for timers\n");
            exit(EXIT_FAILURE);
        }

        timer->UE_ID = i % MAX_UE_ID;
        timer->SFN_S = (i / PHICH_SETS) * PHICH_SETS + PHICH; // Adjust as necessary based on LTE protocol specifications
        timer->PHICH = i % PHICH_SETS;

        if (!validateParams(timer->UE_ID, timer->SFN_S, timer->PHICH)) {
            freeTimerToPool(timer);
            continue;
        }

        if (timerCallback)
            timerCallback(timer);

        timers[timerIndex++] = timer;
    }

    // Perform any necessary asynchronous operations here

    free(timerMemPool.freeList); // Free the original memory pool when done
    pthread_mutex_destroy(&memPoolMutex);
}
