#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    uint32_t ue_id;
    char s_tmsi[16];
    bool status; // active, inactive, or error
    void *pdu_data;
} PDU_session;

void init_network(PDU_session **sessions, size_t capacity) {
    *sessions = malloc(capacity * sizeof(PDU_session));
    if (*sessions == NULL) {
        perror("Memory allocation failed");
        exit(1);
    }

    for (size_t i = 0; i < capacity; ++i) {
        (*sessions + i)->ue_id = 0;
        memset((*sessions + i)->s_tmsi, 0, sizeof((*sessions + i)->s_tmsi));
        (*sessions + i)->status = false; // inactive by default
        (*sessions + i)->pdu_data = NULL;
    }
}

PDU_session* add_pdu(PDU_session *sessions, size_t capacity, uint32_t ue_id, const char *s_tmsi) {
    for (size_t i = 0; i < capacity; ++i) {
        if (!sessions[i].status && sessions[i].ue_id == 0) {
            sessions[i].ue_id = ue_id;
            memcpy(sessions[i].s_tmsi, s_tmsi, sizeof(sessions[i].s_tmsi));
            sessions[i].status = true; // active
            return &sessions[i];
        }
    }

    PDU_session *new_pdu = realloc(*sessions, (capacity + 1) * sizeof(PDU_session));
    if (new_pdu == NULL) {
        perror("Memory allocation failed");
        exit(1);
    }

    new_pdu[capacity].ue_id = ue_id;
    memcpy(new_pdu[capacity].s_tmsi, s_tmsi, sizeof(new_pdu[capacity].s_tmsi));
    new_pdu[capacity].status = true; // active

    *sessions = new_pdu;
    return &new_pdu[capacity];
}

void remove_pdu(PDU_session *sessions, size_t capacity, PDU_session *pdu) {
    if (pdu >= sessions + capacity || !pdu->status) {
        fprintf(stderr, "Invalid PDU session\n");
        return;
    }

    pdu->ue_id = 0;
    memset(pdu->s_tmsi, 0, sizeof(pdu->s_tmsi));
    pdu->status = false; // inactive

    if (capacity > 1) {
        size_t i;
        for (i = pdu - sessions; i < capacity; ++i) {
            if (!i->status && i->ue_id == 0) {
                memmove(i, i + 1, (sessions + capacity - i - 1) * sizeof(PDU_session));
                break;
            }
        }

        if (i < capacity) {
            free(sessions + i); // deallocate the removed PDU session
        } else {
            size_t new_capacity = capacity - 1;
            PDU_session *new_sessions = realloc(*sessions, new_capacity * sizeof(PDU_session));
            if (new_sessions == NULL) {
                perror("Memory allocation failed");
                exit(1);
            }
            *sessions = new_sessions;
        }
    }
}

void free_network(PDU_session *sessions, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        if (sessions[i].pdu_data != NULL) {
            free(sessions[i].pdu_data);
        }
    }
    free(sessions);
}

bool is_pdu_active(const PDU_session *pdu) {
    return pdu->status;
}
