NETWORK_INTERFACE *init_network_interface(int port) {
    NETWORK_INTERFACE *ni = malloc(sizeof(NETWORK_INTERFACE));
    ni->socket_fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (ni->socket_fd == -1) {
        perror("socket");
        free(ni);
        return NULL;
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(port);
    serv_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(ni->socket_fd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) == -1) {
        perror("bind");
        close(ni->socket_fd);
        free(ni);
        return NULL;
    }

    if (listen(ni->socket_fd, SOMAXCONN) == -1) {
        perror("listen");
        close(ni->socket_fd);
        free(ni);
        return NULL;
    }

    ni->stats_file = fopen("network_stats.csv", "a+");
    if (!ni->stats_file) {
        perror("fopen");
        close(ni->socket_fd);
        free(ni);
        return NULL;
    }

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_create(&ni->stats_thread_id, &attr, stats_thread, ni);
    pthread_attr_destroy(&attr);

    return ni;
