2. Java Method (Hash Computation)

```java
import java.math.BigInteger;
import java.security.MessageDigest;
import java.util.Objects;

public class HashUtil {

    public static String computeHash(String input, boolean md5) throws Exception {
        if (Objects.isNull(input)) throw new IllegalArgumentException("Input string cannot be null.");
        if (input.isEmpty()) throw new IllegalArgumentException("Input string cannot be empty.");
        if (input.length() < 1) throw new CustomException("Invalid input length");

        MessageDigest md;
        if (md5) {
            md = MessageDigest.getInstance("MD5");
        } else {
            md = MessageDigest.getInstance("SHA-256");
        }
        byte[] digest = md.digest(input.getBytes());

        if (md5) {
            BigInteger bigInt = new BigInteger(1, digest);
            return String.format("%0" + 32 + "X", bigInt);
        } else {
            return bytesToHex(digest);
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02X", b));
        }
        return sb.toString();
    }
}
```

