```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>

typedef struct {
    size_t count;
    size_t* lines;
    size_t* positions;
} KeywordResult;

KeywordResult search(const char* filename, const char* keyword) {
    KeywordResult result = {0};
    FILE *file = fopen(filename, "r");
    if (!file) return result;

    size_t line_number = 0;
    size_t position_in_line = 0;
    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), file)) {
        ++line_number;
        size_t found_position = strcspn(buffer, keyword);
        if (!found_position) continue;

        result.count++;
        result.lines = realloc(result.lines, (line_number + 1) * sizeof(size_t));
        result.positions = realloc(result.positions, (line_number + 1) * sizeof(size_t));
        result.lines[line_number - 1] = position_in_line;
        result.positions[line_number - 1] = found_position;

        position_in_line += found_position + strlen(keyword);
    }

    fclose(file);
    return result;
}

void print_usage() {
    printf("Usage: keyword_search [options]\n");
    printf("\nOptions:\n");
    printf("  --help               Display this help message.\n");
    printf("  --manpage            Display a detailed usage information.\n");
    printf("  -q                   Suppress all output except errors.\n");
    printf("  -o <output_file>     Redirect standard output to the specified file.\n");
    printf("  -n                   Disable line counting.\n");
}

int main(int argc, char** argv) {
    const char* keyword = "error";
    bool quiet = false;
    bool count_lines = true;
    FILE* output_file = NULL;
    size_t opt;
    while ((opt = getopt(argc, argv, "h?mno:q")) != -1) {
        switch (opt) {
            case 'h': print_usage(); return 0;
            case 'm': print_manpage(); return 0;
            case 'n': count_lines = false; break;
            case 'o': output_file = fopen(optarg, "w"); break;
            case 'q': quiet = true; break;
            default: print_usage(); return 1;
        }
    }

    if (argc - optind < 1) {
        print_usage();
        return 1;
    }

    KeywordResult result = search(argv[optind], keyword);
    if (!quiet) {
        if (count_lines) printf("Line number\tPosition\n");
        for (size_t i = 0; i < result.count; ++i) {
            printf("%zu\t%zu\n", result.lines[i], result.positions[i]);
        }
    }

    if (!quiet && output_file) {
        fprintf(output_file, "Number of occurrences: %zu\n", result.count);
        for (size_t i = 0; i < result.count; ++i) {
            fprintf(output_file, "%zu\t%zu\n", result.lines[i], result.positions[i]);
        }
        fclose(output_file);
    }

    free(result.lines);
    free(result.positions);
    return 0;
}
